function openMtgImportAttendeesModal(meetingId) {
  modal({
    title: 'Import Attendees from Teams CSV',
    size: 'large',
    body: `
      <p style="font-size:13px;color:var(--gray-600);margin-bottom:12px;">
        Paste your Microsoft Teams attendance report CSV below.<br>
        Supported columns: <strong>Full Name</strong> or <strong>Name</strong>. Email detected automatically if present.
      </p>
      <textarea class="form-input" id="mtg-csv-input" rows="10"
        style="font-family:monospace;font-size:12px;" placeholder="Paste Teams attendance CSV here…"></textarea>
      <div id="mtg-csv-preview" style="margin-top:12px;font-size:13px;"></div>`,
    footer: `
      <button class="form-secondary" onclick="_mtgPreviewCSV()">Preview</button>
      <button class="form-secondary" onclick="closeModal()">Cancel</button>
      <button class="form-submit" onclick="_mtgImportCSV('${meetingId}')">Import</button>`,
  });
}

function _mtgPreviewCSV() {
  const text   = document.getElementById('mtg-csv-input')?.value || '';
  const parsed = _mtgParseTeamsCSV(text);
  const el     = document.getElementById('mtg-csv-preview');
  if (!el) return;
  if (!parsed.length) { el.innerHTML = '<p style="color:var(--bad);">No attendees found — check CSV format.</p>'; return; }
  el.innerHTML = `<p style="margin-bottom:8px;"><strong>${parsed.length}</strong> attendees detected:</p>
    <div style="max-height:180px;overflow-y:auto;background:var(--gray-50);border:1px solid var(--gray-200);border-radius:4px;padding:8px;">
      ${parsed.map(a => `<div style="padding:2px 0;">${escapeHtml(a.name)}${a.email ? ` <span style="color:var(--gray-400);font-size:11px;">${escapeHtml(a.email)}</span>` : ''}</div>`).join('')}
    </div>`;
}

function _mtgParseTeamsCSV(text) {
  const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
  if (lines.length < 2) return [];
  const headers  = lines[0].split(',').map(h => h.replace(/^"|"$/g, '').trim().toLowerCase());
  const nameCol  = headers.findIndex(h => h.includes('full name') || h === 'name' || h.includes('participant'));
  const emailCol = headers.findIndex(h => h.includes('email') || h.includes('upn') || h.includes('principal'));
  if (nameCol < 0) return [];
  const seen = new Set(), result = [];
  for (let i = 1; i < lines.length; i++) {
    const cols = _mtgCSVLine(lines[i]);
    const name = (cols[nameCol] || '').trim();
    if (!name || seen.has(name.toLowerCase()) || name.toLowerCase() === 'name') continue;
    seen.add(name.toLowerCase());
    result.push({ name, email: emailCol >= 0 ? (cols[emailCol] || '').trim() || null : null });
  }
  return result;
}

function _mtgCSVLine(line) {
  const r = []; let cur = '', q = false;
  for (const c of line) {
    if (c === '"') { q = !q; continue; }
    if (c === ',' && !q) { r.push(cur); cur = ''; continue; }
    cur += c;
  }
  r.push(cur);
  return r;
}

async function _mtgImportCSV(meetingId) {
  const text   = document.getElementById('mtg-csv-input')?.value || '';
  const parsed = _mtgParseTeamsCSV(text);
  if (!parsed.length) { toast('No attendees found in CSV', 'error'); return; }
  try {
    const existing = new Set((_mtgDetail?.attendees||[]).map(a => a.name.toLowerCase()));
    const toInsert = parsed
      .filter(a => !existing.has(a.name.toLowerCase()))
      .map(a => ({ meeting_id: meetingId, name: a.name, email: a.email || null, attended: true, created_at: new Date().toISOString() }));
    if (toInsert.length > 0) {
      const inserted = await _dbInsert('meeting_attendees', toInsert);
      if (_mtgDetail) _mtgDetail.attendees.push(...(inserted || []));
    }
    closeModal();
    toast(`Imported ${toInsert.length} attendee(s) (${parsed.length - toInsert.length} already present)`, 'success');
    await renderMeetings();
  } catch(e) { toast('Error: ' + e.message, 'error'); }
}

// ─── CONVERT TO MINUTES ──────────────────────────────────────
async function convertToMinutesMode(meetingId) {
  if (!confirm('Convert to Minutes Mode? This enables per-item notes recording for the meeting.')) return;
  try {
    await _dbUpdate('meetings', { status: 'Minutes', updated_at: new Date().toISOString() }, { id: meetingId });
    const m = MEETINGS.find(x => x.id === meetingId);
    if (m) m.status = 'Minutes';
    if (_mtgDetail?.meeting) _mtgDetail.meeting.status = 'Minutes';
    toast('Meeting is now in Minutes Mode', 'success');
    await renderMeetings();
  } catch(e) { toast('Error: ' + e.message, 'error'); }
}

// ─── FOLLOW-UP MEETING ────────────────────────────────────────
async function createFollowUpMtg(meetingId) {
  if (!confirm('Create a follow-up meeting? This will clone the full agenda and carry forward all open action items.')) return;
  const src = _mtgDetail?.meeting || MEETINGS.find(m => m.id === meetingId);
  if (!src) { toast('Source meeting not found', 'error'); return; }
  try {
    const [newMtg] = await _dbInsert('meetings', [{
      title: src.title, series: src.series, location: src.location,
      meeting_link: src.meeting_link, timezone: src.timezone || 'America/Los_Angeles',
      is_private: src.is_private, is_draft: src.is_draft, overview: src.overview,
      status: 'Agenda', parent_meeting_id: meetingId,
      created_by: currentRoleUser?.name || null,
      created_at: new Date().toISOString(), updated_at: new Date().toISOString(),
    }]);
    MEETINGS.unshift(newMtg);

    const srcCats  = _mtgDetail?.categories || [];
    const srcItems = _mtgDetail?.items       || [];
    const srcAI    = _mtgDetail?.actionItems || [];

    for (const cat of srcCats) {
      const [newCat] = await _dbInsert('meeting_categories', [{
        meeting_id: newMtg.id, title: cat.title, sort_order: cat.sort_order || 0,
      }]);
      for (const item of srcItems.filter(i => i.category_id === cat.id)) {
        const [newItem] = await _dbInsert('meeting_items', [{
          meeting_id: newMtg.id, category_id: newCat.id,
          title: item.title, description: item.description,
          assignee: item.assignee, due_date: item.due_date,
          status: 'Open', priority: item.priority,
          sort_order: item.sort_order || 0,
          meeting_origin_id: item.meeting_origin_id || meetingId,
          created_at: new Date().toISOString(), updated_at: new Date().toISOString(),
        }]);
        for (const ai of srcAI.filter(a => a.meeting_item_id === item.id && a.status !== 'Closed')) {
          await _dbInsert('meeting_action_items', [{
            meeting_id: newMtg.id, meeting_item_id: newItem.id,
            description: ai.description, assignee: ai.assignee,
            due_date: ai.due_date, status: ai.status,
            created_at: new Date().toISOString(), updated_at: new Date().toISOString(),
          }]);
        }
      }
    }

    toast('Follow-up meeting created!', 'success');
    _mtgDetailId = newMtg.id;
    _mtgItemOpen = {};
    await renderMeetings();
  } catch(e) { toast('Error creating follow-up: ' + e.message, 'error'); }
}

// ─── PDF EXPORT ──────────────────────────────────────────────
async function _mtgPrintPDF(meetingId) {
  if (!_mtgDetail || _mtgDetail.meeting?.id !== meetingId) {
    toast('Loading meeting data…', 'success');
    await _mtgLoadDetail(meetingId);
  }
  const { meeting: m, categories, items, attendees, actionItems } = _mtgDetail;
  const inMinutes = m.status === 'Minutes';

  const agendaHTML = categories.map((cat, ci) => {
    const catItems = items.filter(i => i.category_id === cat.id);
    return `
      <div style="margin-bottom:18px;">
        <div style="font-size:13px;font-weight:700;background:#f4f4f4;padding:7px 10px;border-left:4px solid #C8001A;margin-bottom:8px;">${escapeHtml(cat.title)}</div>
        ${catItems.map((item, ii) => {
          const itemAI = actionItems.filter(a => a.meeting_item_id === item.id);
          return `
            <div style="margin-bottom:10px;padding:9px 10px;border:1px solid #e5e7eb;border-radius:3px;">
              <div style="font-weight:600;font-size:12px;margin-bottom:4px;">${ci+1}.${ii+1} ${escapeHtml(item.title)}</div>
              ${item.description ? `<div style="font-size:11px;color:#555;margin-bottom:5px;">${escapeHtml(item.description)}</div>` : ''}
              <div style="font-size:10px;color:#888;margin-bottom:5px;">${[
                item.assignee ? `Assignee: ${item.assignee}` : '',
                item.due_date ? `Due: ${item.due_date}` : '',
                `Status: ${item.status||'Open'}`,
              ].filter(Boolean).join(' · ')}</div>
              ${inMinutes && item.minutes_notes ? `<div style="margin-top:7px;padding:7px;background:#fefefe;border:1px solid #eee;border-radius:3px;font-size:11px;"><strong style="color:#C8001A;">Minutes:</strong> ${item.minutes_notes}</div>` : ''}
              ${itemAI.length ? `<div style="margin-top:7px;">
                <div style="font-size:10px;font-weight:700;color:#666;margin-bottom:3px;">Action Items:</div>
                ${itemAI.map(ai => `<div style="font-size:10px;padding:3px 7px;background:#fff8f0;border-left:3px solid #E67E22;margin-bottom:2px;">
                  ${escapeHtml(ai.description)}${ai.assignee ? ` — ${escapeHtml(ai.assignee)}` : ''}${ai.due_date ? ` (Due: ${ai.due_date})` : ''} [${escapeHtml(ai.status||'Open')}]
                </div>`).join('')}
              </div>` : ''}
            </div>`;
        }).join('')}
      </div>`;
  }).join('');

  const w = window.open('', '_blank', 'width=900,height=700');
  w.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8">
    <title>${inMinutes ? 'Meeting Minutes — ' : ''}${escapeHtml(m.title||'')}</title>
    <style>
      *{box-sizing:border-box;margin:0;padding:0;}
      body{font-family:Arial,sans-serif;color:#111;background:#fff;padding:32px;}
      @media print{body{padding:16px;}}
    </style>
  </head><body>
    <div style="display:flex;justify-content:space-between;padding-bottom:14px;border-bottom:3px solid #C8001A;margin-bottom:20px;">
      <div>
        <div style="font-size:15px;font-weight:700;color:#C8001A;">Hitachi Rail STS</div>
        <div style="font-size:11px;color:#666;">BART CBTC T&amp;C Portal</div>
      </div>
      <div style="text-align:right;font-size:11px;color:#666;">
        <div style="font-weight:700;font-size:13px;">Meeting #${m.meeting_number||''}</div>
        <div>${m.meeting_date||''}</div>
      </div>
    </div>
    <h1 style="font-size:17px;font-weight:700;margin-bottom:14px;">
      ${inMinutes ? 'Meeting Minutes for ' : ''}${escapeHtml(m.title||'')}
    </h1>
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:16px;font-size:11px;">
      ${[['Date',m.meeting_date],['Start Time',m.start_time],['End Time',m.end_time],['Location',m.location]]
        .filter(([,v]) => v)
        .map(([l,v]) => `<div><div style="font-weight:700;color:#C8001A;text-transform:uppercase;font-size:9px;">${l}</div><div>${escapeHtml(v)}</div></div>`)
        .join('')}
    </div>
    ${m.overview ? `<div style="margin-bottom:14px;font-size:12px;color:#444;font-style:italic;">${escapeHtml(m.overview)}</div>` : ''}
    ${attendees.length ? `
      <div style="margin-bottom:16px;">
        <div style="font-size:11px;font-weight:700;color:#C8001A;text-transform:uppercase;margin-bottom:6px;">Attendees</div>
        <div style="display:flex;flex-wrap:wrap;gap:5px;">
          ${attendees.map(a => `<span style="font-size:11px;background:#f5f5f5;padding:2px 9px;border-radius:10px;">${escapeHtml(a.name)}${a.company ? ` (${escapeHtml(a.company)})` : ''}</span>`).join('')}
        </div>
      </div>` : ''}
    <div style="font-size:11px;font-weight:700;color:#C8001A;text-transform:uppercase;border-bottom:1px solid #eee;padding-bottom:6px;margin-bottom:12px;">Agenda</div>
    ${agendaHTML}
    <div style="margin-top:30px;padding-top:10px;border-top:1px solid #eee;display:flex;justify-content:space-between;font-size:9px;color:#aaa;">
      <span>Hitachi Rail STS — BART CBTC T&amp;C Portal</span>
      <span>Printed: ${new Date().toLocaleString('en-US',{dateStyle:'long',timeStyle:'short'})}</span>
    </div>
  </body></html>`);
  w.document.close();
  w.focus();
  setTimeout(() => w.print(), 600);
}

// ─── TEMPLATES ────────────────────────────────────────────────
function openMtgTemplatesModal() {
  modal({
    title: 'Meeting Templates',
    size: 'large',
    body: `
      <div id="mtg-tpl-list">
        ${MTG_TEMPLATES.length === 0
          ? '<p style="color:var(--gray-400);font-size:13px;">No templates yet. Create one to pre-populate agenda categories and items when creating a new meeting.</p>'
          : MTG_TEMPLATES.map(t => `
              <div style="display:flex;justify-content:space-between;align-items:center;padding:11px 14px;border:1px solid var(--gray-200);border-radius:6px;margin-bottom:8px;">
                <div>
                  <div style="font-weight:600;font-size:14px;">${escapeHtml(t.name)}</div>
                  ${t.description ? `<div style="font-size:12px;color:var(--gray-500);">${escapeHtml(t.description)}</div>` : ''}
                </div>
                <div style="display:flex;gap:6px;">
                  <button class="form-secondary" style="padding:3px 12px;font-size:12px;" onclick="openMtgTemplateEditModal('${t.id}')">Edit</button>
                  <button class="form-secondary" style="padding:3px 12px;font-size:12px;color:var(--bad);" onclick="deleteMtgTemplate('${t.id}')">Delete</button>
                </div>
              </div>`).join('')}
      </div>
      <button class="form-secondary" style="margin-top:12px;" onclick="openMtgTemplateEditModal(null)">+ New Template</button>`,
    footer: `<button class="form-secondary" onclick="closeModal()">Close</button>`,
  });
}

function openMtgTemplateEditModal(editId) {
  const t = editId ? (MTG_TEMPLATES.find(x => x.id === editId) || {}) : {};
  modal({
    title: editId ? 'Edit Template' : 'New Template',
    size: 'large',
    body: `
      <div style="display:grid;gap:18px;">
        <div>
          <label class="form-label" style="font-size:13px;font-weight:600;color:#444;margin-bottom:6px;display:block;">Template Name *</label>
          <input class="form-input" id="mtg-tpl-name" value="${escapeHtml(t.name||'')}"
            placeholder="e.g. Weekly T&C Review"
            style="font-size:15px;padding:12px 14px;border-radius:6px;">
        </div>
        <div>
          <label class="form-label" style="font-size:13px;font-weight:600;color:#444;margin-bottom:6px;display:block;">Description</label>
          <textarea class="form-input" id="mtg-tpl-desc" rows="3"
            placeholder="What is this template used for?"
            style="font-size:14px;padding:12px 14px;border-radius:6px;resize:vertical;">${escapeHtml(t.description||'')}</textarea>
        </div>
      </div>`,
    footer: `
      <button class="form-secondary" onclick="openMtgTemplatesModal()">← Back</button>
      <button class="form-submit" onclick="saveMtgTemplate('${editId||''}')">${editId ? 'Save Changes' : 'Create Template'}</button>`,
  });
  setTimeout(() => document.getElementById('mtg-tpl-name')?.focus(), 100);
}

async function saveMtgTemplate(editId) {
  const name = document.getElementById('mtg-tpl-name')?.value?.trim();
  if (!name) { toast('Name required', 'error'); return; }
  const payload = {
    name,
    description: document.getElementById('mtg-tpl-desc')?.value?.trim() || null,
    updated_at:  new Date().toISOString(),
  };
  try {
    if (editId) {
      await _dbUpdate('meeting_templates', payload, { id: editId });
      const t = MTG_TEMPLATES.find(x => x.id === editId);
      if (t) Object.assign(t, payload);
    } else {
      payload.created_at = new Date().toISOString();
      payload.created_by = currentRoleUser?.name || null;
      const [t] = await _dbInsert('meeting_templates', [payload]);
      MTG_TEMPLATES.push(t);
    }
    toast('Template saved', 'success');
    openMtgTemplatesModal();
  } catch(e) { toast('Error: ' + e.message, 'error'); }
}

async function deleteMtgTemplate(id) {
  if (!confirm('Delete this template?')) return;
  try {
    await _dbDelete('meeting_templates', { id });
    MTG_TEMPLATES = MTG_TEMPLATES.filter(t => t.id !== id);
    toast('Template deleted', 'success');
    openMtgTemplatesModal();
  } catch(e) { toast('Error: ' + e.message, 'error'); }
}

// ============================================================
// LOOKAHEAD / PLANNING MODULE — Batch 1 Foundation
// ============================================================
//
// Tables:
//   planning_resources, pto_requests, planning_import_batches,
//   planning_activities, planning_events, planning_event_resources,
//   planning_conflicts
//
// Cell color → shift mapping (used in Batch 3 importer):
//   Yellow = day_shift   (default 0700–1500)
//   Blue   = night_shift (default 2000–0700)
//   Black  = blanket_shift (all-day)
//   Red    = cancelled (admin must add cancellation_reason)

// ── Global state ─────────────────────────────────────────────
let PLANNING_RESOURCES        = [];   // planning_resources rows
let PLANNING_EVENTS           = [];   // planning_events rows
let PLANNING_ACTIVITIES       = [];   // planning_activities rows
let PLANNING_BATCHES          = [];   // planning_import_batches rows
let PLANNING_EVENT_RES        = [];   // planning_event_resources join rows
let PLANNING_ACTIVITY_RES     = [];   // planning_activity_resources join rows (activity-level assignments)
let PLANNING_CONFLICTS        = [];   // planning_conflicts rows
let PTO_REQUESTS              = [];   // pto_requests rows
let DELAY_LOG                 = [];   // delay_log rows (for Delays & Cancellations report)
let PLANNING_TEST_RESULTS     = [];   // test_results in lookahead window (for per-cell badges)

let _lookaheadTab        = 'lookahead';                 // calendar | lookahead | resources | pto
let _adminPlanningTab    = 'upload';                   // upload | review | conflicts | resources | history
let _planningLoadedAt    = 0;                          // cache flag

// Calendar / timeline state
let _planningCalView     = 'week';                     // day | week | month
let _planningCalDate     = new Date();                 // anchor date for current view
let _calZoom             = 1.0;                        // 0.6 – 1.4 zoom multiplier for calendar shell
let _planningCalInstance = null;                       // legacy — no longer used (kept for cleanup safety)
let _planningTLInstance  = null;                       // vis-timeline instance for lookahead/gantt/resources
let _planningCalNowTimer = null;                       // setInterval handle for the "now" line
let _laTimelineGroupBy   = 'activity';                 // activity | resource | subsystem | location
let _laTimelineWindow    = 28;                         // 14 / 21 / 28 / 60 / 90 days
let _laCollapsedGroups   = {};                         // { tc: true, ... } — collapsed activity_group bands
let _laActivitySubGroup  = 'none';                     // 'none' | 'phase' | 'location' | 'phase_location'
let _laResCompanyFilter  = 'all';                      // 'all' | 'BART' | 'Hitachi' (Resource view)

// ── Edit drawer state (Phase 2 — Master Schedule revamp) ─────
// The right-side persistent drawer replaces modal-per-action for cell &
// activity editing. One of three modes is active at a time:
//   closed    — nothing open
//   cell      — single event_id loaded; targetId = event_id
//   activity  — single planning_activity_id loaded; targetId = activity_id
//   multi     — N selected cells; targetId = null, reads _laSelectedCellKeys
let _laDrawer = {
  mode:        'closed',
  targetId:    null,
  snapshot:    null,
  dirty:       false,
  baseVersion: null,   // for optimistic-concurrency check on save
};
let _laCreateSel = [];      // [{actId, iso, el}] empty cells staged for bulk create
let _laCreateResState = []; // [{resourceId, qty, isBart, label}] temp for create modal
let _planningShowP6      = false;                      // Calendar/Timeline P6 overlay toggle
let _conflictFilter      = 'all';                      // all | pto | double | p6 | hours | unmatched
let _laAssignMode        = false;                      // Assign Resources drag-and-drop mode
let _laCurrentDragRes    = null;                       // resourceId(s) being dragged — now an array
let _laSelectedResIds    = new Set();                  // multi-selected resource card IDs
let _laSelectedCellKeys  = new Set();                  // multi-selected event IDs for bulk remove / copy
let _laClipboard         = null;                       // { mode:'copy'|'cut', items:[{event,resources,dayOffset,sameActivityAsAnchor}], anchorActId, anchorDate }
let _laPasteTarget       = null;                       // { activityId, date } — anchor for paste
let _laRowSearch         = '';                         // live filter for the lookahead grid (activity name/id)
let _laPendingUndo       = null;                        // { fn } — most recent undoable destructive action

// Shift visual styles — used across calendar, timeline, badges
const _SHIFT_VISUAL = {
  day_shift:     { bg: '#FFEB3B', text: '#1f2937', label: 'Day',     icon: '☀' },
  night_shift:   { bg: '#2196F3', text: '#ffffff', label: 'Night',   icon: '☾' },
  blanket_shift: { bg: '#1f2937', text: '#ffffff', label: 'Blanket', icon: '■' },
  swing_shift:   { bg: '#FF9800', text: '#1f2937', label: 'Swing',   icon: '↔' },
  custom:        { bg: '#6b7280', text: '#ffffff', label: 'Custom',  icon: '◆' },
};
const _CANCEL_VISUAL   = { bg: '#b91c1c', text: '#ffffff', label: 'Cancelled', icon: '✕' };
const _PTO_VISUAL      = { bg: '#fef3c7', text: '#92400e', label: 'PTO',       icon: '🌴' };

// ── Data loaders ─────────────────────────────────────────────
async function loadPlanningData(force = false) {
  // Cache for 30s to avoid hammering on tab switches
  if (!force && Date.now() - _planningLoadedAt < 30_000) return;
  try {
    // Pull test_results from ~60 days back to today+60 — covers the lookahead window
    // plus recent history needed for "did this get executed" badges.
    const tResultsFrom = dayjs().subtract(60, 'day').format('YYYY-MM-DD');
    const tResultsTo   = dayjs().add(60, 'day').format('YYYY-MM-DD');
    const [resources, events, activities, batches, eventRes, activityRes, conflicts, pto, delayLog, testResults, shiftTpls] = await Promise.all([
      _fetchAnon('planning_resources?select=*&order=display_name.asc'),
      _fetchAnon('planning_events?select=*&order=event_date.asc'),
      _fetchAnon('planning_activities?select=*&order=created_at.desc'),
      _fetchAnon('planning_import_batches?select=*&order=uploaded_at.desc'),
      _fetchAnon('planning_event_resources?select=*'),
      _fetchAnon('planning_activity_resources?select=*'),
      _fetchAnon('planning_conflicts?select=*&order=created_at.desc'),
      _fetchAnon('pto_requests?select=*&order=start_date.desc'),
      _fetchAnon('delay_log?select=*&delay_occurred=eq.Yes&order=log_date.desc'),
      _fetchAnon(`test_results?select=test_id,activity,date_tested,result&date_tested=gte.${tResultsFrom}&date_tested=lte.${tResultsTo}`),
      _fetchAnon('shift_templates?select=*&order=sort_order.asc').catch(() => []),
    ]);
    PLANNING_RESOURCES    = resources    || [];
    PLANNING_EVENTS       = events       || [];
    PLANNING_ACTIVITIES   = activities   || [];
    PLANNING_BATCHES      = batches      || [];
    PLANNING_EVENT_RES    = eventRes     || [];
    PLANNING_ACTIVITY_RES = activityRes  || [];
    PLANNING_CONFLICTS    = conflicts    || [];
    PTO_REQUESTS          = pto          || [];
    DELAY_LOG             = delayLog     || [];
    PLANNING_TEST_RESULTS = testResults  || [];
    window.SHIFT_TEMPLATES = shiftTpls   || [];   // Phase 2: data-driven shift definitions
    _planningLoadedAt   = Date.now();
    // First-time bootstrap: seed planning_resources from portal users
    if (PLANNING_RESOURCES.length === 0) await _planningBootstrapResources();
  } catch (err) {
    console.warn('Planning data load failed:', err.message);
    toast('Planning data load failed: ' + err.message, 'error');
  }
}

// ── Test Register Activity stats (for per-cell badges) ─────────
// Returns the execution stats for a given Test Register Activity name,
// either for a specific date (per-cell) or over the entire activity (row totals).
function _planningTestActivityStats(activityName, date = null) {
  if (!activityName) return null;
  const tiInActivity = TI.filter(t => (t.Activity || '').trim() === activityName.trim());
  const totalInActivity = tiInActivity.length;
  const completeInActivity = tiInActivity.filter(t => t.Status === 'Complete' || t.Status === 'Pass' || t.Status === 'Passed').length;

  if (!date) {
    // Row-level totals (overall progress on the linked Activity)
    return { totalInActivity, completeInActivity, executedToday: 0, passed: 0, failed: 0, blocked: 0 };
  }

  // Per-cell: results for this activity on this date
  const dayResults = (PLANNING_TEST_RESULTS || []).filter(r =>
    (r.activity || '').trim() === activityName.trim() &&
    r.date_tested === date
  );
  const uniqueTests = new Set(dayResults.map(r => r.test_id));
  const passed  = dayResults.filter(r => r.result === 'Pass').length;
  const failed  = dayResults.filter(r => r.result === 'Fail').length;
  const blocked = dayResults.filter(r => r.result === 'Blocked').length;
  return {
    totalInActivity,
    completeInActivity,
    executedToday: uniqueTests.size,
    passed, failed, blocked,
  };
}

// Cell badge HTML — context-aware:
//   FUTURE date: show "N left" (remaining = total − complete) — useful for planning
//   TODAY:       show "X done · N left" — live status
//   PAST date:   show ✓ executed result, or ✗ if planned but nothing recorded
// Returns '' for unlinked rows (no Test Register link = pure overhead, no signal).
function _planningCellBadge(linkedActivity, date) {
  if (!linkedActivity) return '';
  const s = _planningTestActivityStats(linkedActivity, date);
  if (!s || s.totalInActivity === 0) return '';
  const today = new Date().toISOString().slice(0, 10);
  const remaining = Math.max(0, s.totalInActivity - s.completeInActivity);

  // PAST date — accountability view
  if (date < today) {
    if (s.executedToday === 0) {
      return `<span class="tlg-cell-badge tlg-cell-badge-none" title="${escapeHtml(linkedActivity)} on ${date} — planned but no test results recorded">✗ 0 done</span>`;
    }
    const hasIssue = s.failed > 0 || s.blocked > 0;
    const cls = hasIssue ? 'tlg-cell-badge-warn' : 'tlg-cell-badge-ok';
    const icon = hasIssue ? '⚠' : '✓';
    const issueText = hasIssue ? ` · ${s.failed ? s.failed+' fail' : ''}${s.failed && s.blocked ? ', ' : ''}${s.blocked ? s.blocked+' blk' : ''}` : '';
    return `<span class="tlg-cell-badge ${cls}" title="${escapeHtml(linkedActivity)} on ${date}: ${s.executedToday} test${s.executedToday>1?'s':''} executed${issueText}">${icon} ${s.executedToday} done</span>`;
  }

  // TODAY — live mix of done so far + remaining
  if (date === today) {
    if (s.executedToday > 0) {
      const hasIssue = s.failed > 0 || s.blocked > 0;
      const cls = hasIssue ? 'tlg-cell-badge-warn' : 'tlg-cell-badge-today';
      return `<span class="tlg-cell-badge ${cls}" title="Today: ${s.executedToday} executed · ${remaining} remaining in ${escapeHtml(linkedActivity)}">${s.executedToday}✓ · ${remaining}↻</span>`;
    }
    return `<span class="tlg-cell-badge tlg-cell-badge-today" title="${remaining} tests remaining in ${escapeHtml(linkedActivity)}">${remaining}↻</span>`;
  }

  // FUTURE — workload preview
  if (remaining === 0) {
    return `<span class="tlg-cell-badge tlg-cell-badge-ok" title="All ${s.totalInActivity} tests in ${escapeHtml(linkedActivity)} already complete">✓ done</span>`;
  }
  return `<span class="tlg-cell-badge tlg-cell-badge-future" title="${remaining} of ${s.totalInActivity} tests remaining in ${escapeHtml(linkedActivity)}">${remaining} left</span>`;
}

// Row-level summary chip (shown on the activity label)
function _planningRowProgressChip(linkedActivity) {
  if (!linkedActivity) return '';
  const s = _planningTestActivityStats(linkedActivity);
  if (!s || s.totalInActivity === 0) return '';
  const pct = Math.round((s.completeInActivity / s.totalInActivity) * 100);
  const color = pct >= 100 ? '#16a34a' : pct >= 50 ? '#0891b2' : '#6b7280';
  return `<span class="tlg-row-prog" style="background:${color};" title="${s.completeInActivity} of ${s.totalInActivity} tests Complete in ${escapeHtml(linkedActivity)}">${s.completeInActivity}/${s.totalInActivity}</span>`;
}

function _planningDeriveInitials(name) {
  if (!name) return '';
  return name.split(/\s+/).map(w => w[0] || '').join('').slice(0, 4).toUpperCase();
}

async function _planningBootstrapResources() {
  // Pull active portal users (profiles) and create matching planning_resources rows.
  // Resource type derived from profile role.
  try {
    const profs = await _fetchAnon('profiles?select=id,full_name,role,email,subsystem&is_active=eq.true');
    if (!profs || !profs.length) return;
    const seed = profs.filter(p => p.full_name).map(p => ({
      user_id:       p.id,
      display_name:  p.full_name,
      initials:      _planningDeriveInitials(p.full_name),
      resource_type: (p.role === 'admin' ? 'admin'
                    : p.role === 'field_engineer' ? 'field_engineer'
                    : 'manual'),
      email:         p.email || null,
      subsystem:     p.subsystem || null,
      is_active:     true,
    }));
    if (!seed.length) return;
    await _dbInsert('planning_resources', seed);
    PLANNING_RESOURCES = await _fetchAnon('planning_resources?select=*&order=display_name.asc');
    toast(`Seeded ${seed.length} resources from portal users`, 'success');
  } catch (err) {
    console.warn('Resource bootstrap failed:', err.message);
  }
}

// ── Main Lookahead page render ────────────────────────────────
function renderLookahead() {
  const hero = document.getElementById('lookahead-hero-content');
  const body = document.getElementById('lookahead-content');
  if (!body || !currentRoleUser) return;
  const isAdmin = currentRoleUser?.role === 'admin';

  if (hero) hero.innerHTML = `
    <h1 style="margin:0;font-size:28px;font-weight:700;">Lookahead</h1>
    <p style="margin:6px 0 0;color:var(--gray-500);font-size:14px;">
      Operational planning view — weekly lookahead, resource availability, PTO, and P6 overlay.
    </p>`;

  // Redirect legacy tabs
  if (_lookaheadTab === 'gantt' || _lookaheadTab === 'resources') _lookaheadTab = 'lookahead';
  const tabs = [
    ['calendar',      'Calendar'],
    ['lookahead',     'Lookahead'],
    ['pto',           'PTO'],
    ['cancellations', 'Delays & Cancellations'],
    ['health',        'Lookahead Health'],
  ];

  body.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;border-bottom:2px solid var(--gray-200);padding-bottom:0;">
      <div style="display:flex;gap:0;">
        ${tabs.map(([id, label]) => `
          <button class="admin-tab${_lookaheadTab === id ? ' active' : ''}" data-la-tab="${id}" onclick="_lookaheadSetTab('${id}')">${label}</button>
        `).join('')}
      </div>
      <div style="display:flex;gap:8px;">
        ${isAdmin ? `<button class="form-secondary" onclick="showPage('admin-planning')">⚙ Admin Planning</button>` : ''}
        <button class="form-secondary" onclick="loadPlanningData(true).then(renderLookahead);">↻ Refresh</button>
      </div>
    </div>
    <div id="lookahead-tab-body"></div>
  `;
  _renderLookaheadTabBody();
}

function _lookaheadSetTab(t) {
  _planningCleanupInstances();
  _lookaheadTab = t;
  // Move the dark "active" pill to the clicked tab
  document.querySelectorAll('#lookahead-content [data-la-tab]').forEach(b => {
    b.classList.toggle('active', b.getAttribute('data-la-tab') === t);
  });
  _renderLookaheadTabBody();
}

function _planningCleanupInstances() {
  try { if (_planningCalInstance && typeof _planningCalInstance.destroy === 'function') _planningCalInstance.destroy(); } catch(_) {}
  try { if (_planningTLInstance  && typeof _planningTLInstance.destroy  === 'function') _planningTLInstance.destroy();  } catch(_) {}
  _planningCalInstance = null;
  _planningTLInstance  = null;
  if (_planningCalNowTimer) { clearInterval(_planningCalNowTimer); _planningCalNowTimer = null; }
}

function _renderLookaheadTabBody() {
  const el = document.getElementById('lookahead-tab-body');
  if (!el) return;
  _planningCleanupInstances();
  const tab = _lookaheadTab;
  if (tab === 'calendar')      { el.innerHTML = _laCalendarHTML();         setTimeout(_laMountCalendar,    30); }
  if (tab === 'lookahead')     { el.innerHTML = _laLookaheadHTML();         setTimeout(_laMountLookaheadTL, 30); }
  if (tab === 'pto')           { el.innerHTML = _laPTOStub(); }
  if (tab === 'cancellations') { el.innerHTML = _laCancellationsTabHTML(); }
  if (tab === 'health')        { el.innerHTML = _laHealthTabHTML(); }
}

// ── Stub renderers (replaced in Batch 2+) ────────────────────
function _laStubCard(title, msg, batch) {
  return `
    <div class="data-card" style="padding:32px;text-align:center;">
      <div style="font-size:48px;margin-bottom:12px;">📅</div>
      <h3 style="margin:0 0 8px;font-size:18px;font-weight:600;">${title}</h3>
      <p style="margin:0;color:var(--gray-500);font-size:13px;max-width:520px;margin:0 auto;">${msg}</p>
      <div style="margin-top:14px;font-size:11px;color:var(--gray-400);">Coming in ${batch}</div>
    </div>`;
}

// ── Shared helpers ───────────────────────────────────────────
function _planningEventsForRender() {
  // Returns calendar-style normalized events (lookahead + PTO)
  const events = PLANNING_EVENTS.map(e => {
    const isCancel = e.status === 'cancelled';
    const v = isCancel ? _CANCEL_VISUAL : (_SHIFT_VISUAL[e.shift_type] || _SHIFT_VISUAL.custom);
    return { source: e, visual: v, isCancel };
  });
  const pto = PTO_REQUESTS
    .filter(p => p.status === 'approved')
    .map(p => ({
      source: p,
      visual: _PTO_VISUAL,
      isPTO: true,
    }));
  return { events, pto };
}

function _planningResourceAssignmentsForEvent(eventId) {
  return PLANNING_EVENT_RES
    .filter(er => er.event_id === eventId)
    .map(er => ({
      assignment: er,
      resource:   PLANNING_RESOURCES.find(r => r.id === er.resource_id) || null,
    }));
}

function _planningKPIStrip() {
  const today    = new Date().toISOString().slice(0, 10);
  const outToday = _ptoActiveOnDate(today);
  const pending  = PTO_REQUESTS.filter(p => p.status === 'pending').length;
  const upcoming = PLANNING_EVENTS.filter(e => e.event_date >= today && e.status !== 'cancelled').length;
  const cancelled= PLANNING_EVENTS.filter(e => e.event_date >= today && e.status === 'cancelled').length;
  return `
    <div class="kpi-strip-row">
      <div class="kpi-chip"><div class="kpi-chip-label">Upcoming Events</div><div class="kpi-chip-value">${upcoming}</div></div>
      <div class="kpi-chip"><div class="kpi-chip-label">Resources</div><div class="kpi-chip-value">${PLANNING_RESOURCES.filter(r => r.is_active).length}</div></div>
      <div class="kpi-chip"><div class="kpi-chip-label">Out Today</div><div class="kpi-chip-value" style="color:${outToday.length ? '#92400e' : 'inherit'};">${outToday.length}</div></div>
      <div class="kpi-chip"><div class="kpi-chip-label">PTO Pending</div><div class="kpi-chip-value" style="color:${pending ? 'var(--warn)' : 'inherit'};">${pending}</div></div>
      <div class="kpi-chip"><div class="kpi-chip-label">Cancelled</div><div class="kpi-chip-value" style="color:${cancelled ? 'var(--bad)' : 'inherit'};">${cancelled}</div></div>
    </div>`;
}

function _planningShiftLegend() {
  return `
    <div style="display:flex;gap:14px;flex-wrap:wrap;font-size:12px;color:var(--gray-600);margin-bottom:14px;padding:8px 12px;background:var(--gray-50);border:1px solid var(--gray-200);border-radius:8px;">
      <strong style="color:var(--gray-700);">Legend:</strong>
      <span><span style="display:inline-block;width:12px;height:12px;background:#FFEB3B;border:1px solid #999;vertical-align:middle;margin-right:4px;"></span> Day shift</span>
      <span><span style="display:inline-block;width:12px;height:12px;background:#2196F3;border:1px solid #999;vertical-align:middle;margin-right:4px;"></span> Night shift</span>
      <span><span style="display:inline-block;width:12px;height:12px;background:#1f2937;vertical-align:middle;margin-right:4px;"></span> Blanket</span>
      <span><span style="display:inline-block;width:12px;height:12px;background:#fecaca;border:1px solid #7f1d1d;vertical-align:middle;margin-right:4px;"></span> Cancelled</span>
      <span><span style="display:inline-block;width:12px;height:12px;background:#fef3c7;border:1px solid #92400e;vertical-align:middle;margin-right:4px;"></span> 🌴 PTO</span>
    </div>`;
}

// ── CALENDAR TAB (Teams-style, custom built) ─────────────────
function _laCalendarHTML() {
  const today    = new Date().toISOString().slice(0, 10);
  const outToday = _ptoActiveOnDate(today);

  return `
    ${_planningKPIStrip()}
    ${outToday.length ? `
      <div style="margin-bottom:14px;padding:10px 14px;background:#fef3c7;border:1px solid #fde68a;border-radius:8px;font-size:13px;color:#92400e;">
        🌴 <strong>Out today:</strong> ${outToday.map(x => escapeHtml(x.resource?.display_name || '—')).join(', ')}
      </div>` : ''}

    ${_planningCalendarLegend()}

    <div class="cal-shell" id="cal-shell" style="zoom:${_calZoom}">
      <div class="cal-toolbar">
        <div class="cal-nav">
          <button class="cal-btn cal-btn-primary" onclick="_laNavToday()">Today</button>
          <button class="cal-btn cal-btn-icon" onclick="_laNavPrev()" aria-label="Previous">‹</button>
          <button class="cal-btn cal-btn-icon" onclick="_laNavNext()" aria-label="Next">›</button>
        </div>
        <h2 class="cal-title" id="cal-title">${escapeHtml(_laGetTitle())}</h2>
        <div class="cal-toolbar-right">
          <label class="cal-toggle">
            <input type="checkbox" ${_planningShowP6 ? 'checked' : ''} onchange="_planningTogglePO6Overlay(this.checked)">
            <span>P6 schedule</span>
          </label>
          <div class="cal-zoom-ctrl" style="display:flex;align-items:center;gap:4px;">
            <button class="cal-btn cal-btn-icon" onclick="_laCalZoomOut()" title="Zoom out" aria-label="Zoom out">−</button>
            <span id="cal-zoom-label" style="font-size:11px;color:var(--gray-500);min-width:32px;text-align:center;">${Math.round(_calZoom*100)}%</span>
            <button class="cal-btn cal-btn-icon" onclick="_laCalZoomIn()"  title="Zoom in"  aria-label="Zoom in">+</button>
          </div>
          <div class="cal-view-switch">
            ${[['day','Day'],['week','Week'],['month','Month']].map(([id,label]) => `
              <button class="cal-view-btn${_planningCalView === id ? ' active' : ''}" data-cal-view="${id}" onclick="_planningSetCalView('${id}')">${label}</button>
            `).join('')}
          </div>
        </div>
      </div>
      <div id="cal-body" class="cal-body cal-body-${_planningCalView}"></div>
    </div>`;
}

function _planningSetCalView(v) {
  _planningCalView = v;
  // Move the active pill instantly to the clicked view button
  document.querySelectorAll('#lookahead-tab-body [data-cal-view]').forEach(b => {
    b.classList.toggle('active', b.getAttribute('data-cal-view') === v);
  });
  _renderLookaheadTabBody();
}

// ── Calendar zoom ────────────────────────────────────────────
function _laCalZoomIn() {
  _calZoom = Math.min(1.5, Math.round((_calZoom + 0.1) * 10) / 10);
  _laApplyCalZoom();
}
function _laCalZoomOut() {
  _calZoom = Math.max(0.5, Math.round((_calZoom - 0.1) * 10) / 10);
  _laApplyCalZoom();
}
function _laApplyCalZoom() {
  const shell = document.getElementById('cal-shell');
  const label = document.getElementById('cal-zoom-label');
  if (shell) shell.style.zoom = _calZoom;
  if (label) label.textContent = Math.round(_calZoom * 100) + '%';
}

// ── Calendar navigation ──────────────────────────────────────
function _laNavToday() {
  _planningCalDate = new Date();
  _laRefreshCalendarBody();
}
function _laNavPrev() {
  const d = _planningCalDate;
  if (_planningCalView === 'month')      _planningCalDate = dayjs(d).subtract(1, 'month').toDate();
  else if (_planningCalView === 'week')  _planningCalDate = dayjs(d).subtract(1, 'week').toDate();
  else                                   _planningCalDate = dayjs(d).subtract(1, 'day').toDate();
  _laRefreshCalendarBody();
}
function _laNavNext() {
  const d = _planningCalDate;
  if (_planningCalView === 'month')      _planningCalDate = dayjs(d).add(1, 'month').toDate();
  else if (_planningCalView === 'week')  _planningCalDate = dayjs(d).add(1, 'week').toDate();
  else                                   _planningCalDate = dayjs(d).add(1, 'day').toDate();
  _laRefreshCalendarBody();
}

// Lighter than re-rendering the whole tab — just refreshes the body grid + title
function _laRefreshCalendarBody() {
  if (_planningCalView !== 'day' && _planningCalView !== 'week' && _planningCalView !== 'month') {
    return _renderLookaheadTabBody();
  }
  const titleEl = document.getElementById('cal-title');
  if (titleEl) titleEl.textContent = _laGetTitle();
  const body = document.getElementById('cal-body');
  if (!body) return _renderLookaheadTabBody();
  body.className = `cal-body cal-body-${_planningCalView}`;
  if (_planningCalNowTimer) { clearInterval(_planningCalNowTimer); _planningCalNowTimer = null; }
  _laMountCalendar();
}

// Returns dayjs for the Monday of the week containing `d` (Mon-first weeks).
function _laMondayOf(d) {
  const dj  = dayjs(d);
  const dow = dj.day();              // 0 = Sun, 1 = Mon, ... 6 = Sat
  const offset = dow === 0 ? -6 : 1 - dow;
  return dj.add(offset, 'day').startOf('day');
}

function _laGetTitle() {
  const d = dayjs(_planningCalDate);
  if (_planningCalView === 'month') return d.format('MMMM YYYY');
  if (_planningCalView === 'day')   return d.format('dddd, MMMM D, YYYY');
  // week — "Mon DD – Sun DD, YYYY"
  const monday = _laMondayOf(_planningCalDate);
  const sunday = monday.add(6, 'day');
  if (monday.month() === sunday.month()) return `${monday.format('MMM D')} – ${sunday.format('D, YYYY')}`;
  if (monday.year()  === sunday.year())  return `${monday.format('MMM D')} – ${sunday.format('MMM D, YYYY')}`;
  return `${monday.format('MMM D, YYYY')} – ${sunday.format('MMM D, YYYY')}`;
}

function _planningTogglePO6Overlay(on) {
  _planningShowP6 = !!on;
  if      (_lookaheadTab === 'calendar')  _laMountCalendar();
  else if (_lookaheadTab === 'lookahead') _laMountLookaheadTL();
}

// ── Subsystem colour palette ─────────────────────────────────
const _SUBSYSTEM_COLORS = {
  ATS:  { bg: '#0078D4', fg: '#fff', soft: '#deecf9', border: '#005a9e' },
  CBTC: { bg: '#107C10', fg: '#fff', soft: '#dff6dd', border: '#0b5c0b' },
  DCS:  { bg: '#D83B01', fg: '#fff', soft: '#fed9cc', border: '#a62d00' },
  IXL:  { bg: '#5C2D91', fg: '#fff', soft: '#e8d6f5', border: '#432070' },
  RTU:  { bg: '#008272', fg: '#fff', soft: '#cef2eb', border: '#005f54' },
  TWC:  { bg: '#B4009E', fg: '#fff', soft: '#f4d4ee', border: '#870076' },
  SIG:  { bg: '#CA5010', fg: '#fff', soft: '#fde8d8', border: '#9e3d0c' },
  COM:  { bg: '#004B50', fg: '#fff', soft: '#d0e8ea', border: '#003236' },
};

function _planningSubsystemColor(name) {
  if (!name) return { bg: '#6b7280', fg: '#fff', soft: '#f3f4f6', border: '#4b5563' };
  const key = name.toUpperCase().trim().replace(/[^A-Z0-9]/g, '').slice(0, 4);
  if (_SUBSYSTEM_COLORS[key]) return _SUBSYSTEM_COLORS[key];
  // Derive a stable hue from the string so unknown subsystems get a consistent colour
  let hash = 0;
  for (let i = 0; i < name.length; i++) hash = (hash * 31 + name.charCodeAt(i)) >>> 0;
  const hue = hash % 360;
  return { bg: `hsl(${hue},52%,38%)`, fg: '#fff', soft: `hsl(${hue},60%,95%)`, border: `hsl(${hue},52%,28%)` };
}

// ── Activity-group taxonomy (Phase 2 — Master Schedule revamp) ───
// These mirror the activity_group enum on planning_activities.
const _ACTIVITY_GROUPS = {
  tc:           { label: 'Test & Commissioning', bg: '#fecaca', fg: '#7f1d1d', accent: '#dc2626' },
  construction: { label: 'Construction',         bg: '#fed7aa', fg: '#7c2d12', accent: '#ea580c' },
  design:       { label: 'Design',               bg: '#bfdbfe', fg: '#1e3a8a', accent: '#2563eb' },
  training:     { label: 'Training',             bg: '#bbf7d0', fg: '#14532d', accent: '#16a34a' },
  other:        { label: 'Other',                bg: '#e5e7eb', fg: '#1f2937', accent: '#6b7280' },
};
// Fixed render order — drives the band order in the master grid.
const _GROUP_ORDER = ['tc','construction','design','training','other'];
function _groupMeta(key) { return _ACTIVITY_GROUPS[key] || _ACTIVITY_GROUPS.other; }

// ── Location prefix matching ──────────────────────────────────
// Activity locations can be ad-hoc codes ("W40") that match master
// locations by prefix ("W40 Millbrae Station"). Matching is bidirectional:
// filter="W40" matches item="W40 Millbrae Station" and vice-versa.
function _laMatchesLocation(filterLoc, itemLoc) {
  if (!filterLoc) return true;        // empty filter passes all
  if (!itemLoc)   return false;
  const f = filterLoc.trim().toLowerCase();
  const i = itemLoc.trim().toLowerCase();
  if (f === i) return true;
  // one is a prefix of the other (must be followed by space or dash)
  if (i.startsWith(f + ' ') || i.startsWith(f + '-')) return true;
  if (f.startsWith(i + ' ') || f.startsWith(i + '-')) return true;
  return false;
}

// Resolve an ad-hoc activity location to its master LOCS name.
// Handles four cases in priority order:
//   1. Exact match                          "W40 - Millbrae Station" → itself
//   2. Input is a prefix of a master name  "W40"      → "W40 - Millbrae Station"
//   3. Master name is a prefix of input    "W40 - Millbrae Station X" → "W40 - Millbrae Station"
//   4. Shared station-code (leading 2–4    "W40 TCR"  → "W40 - Millbrae Station"
//      alphanumeric chars before space/-)
function _laResolveLocationPrefix(adHocLoc) {
  if (!adHocLoc) return adHocLoc;
  const loc    = adHocLoc.trim();
  const lower  = loc.toLowerCase();
  const master = LOCS || [];

  // 1. Exact
  const exact = master.find(l => l.name.trim().toLowerCase() === lower);
  if (exact) return exact.name;

  // 2. Master name starts with input (input is prefix of master)
  const fwdPrefix = master.find(l => {
    const n = l.name.trim().toLowerCase();
    return n.startsWith(lower + ' ') || n.startsWith(lower + '-');
  });
  if (fwdPrefix) return fwdPrefix.name;

  // 3. Input starts with master name (master is prefix of input)
  const revPrefix = master.find(l => {
    const n = l.name.trim().toLowerCase();
    return lower.startsWith(n + ' ') || lower.startsWith(n + '-');
  });
  if (revPrefix) return revPrefix.name;

  // 4. Station-code match: leading 2–4 alphanumeric chars before a space or dash.
  //    e.g. "W40 TCR" → code "W40" → matches "W40 - Millbrae Station"
  const codeMatch = loc.match(/^([A-Z0-9]{2,4})(?:\s|-)/i);
  if (codeMatch) {
    const code  = codeMatch[1].toUpperCase();
    const stMaster = master.find(l => {
      const n = l.name.trim().toUpperCase();
      return n.startsWith(code + ' ') || n.startsWith(code + '-') || n === code;
    });
    if (stMaster) return stMaster.name;
  }

  return loc; // no match — return as-is
}

// Auto-infer phase from location hierarchy.
// Level-2 locations have a parent_id pointing to their Level-1 Phase entry.
// Returns the phase name (e.g. "Phase 2") or null if no master match.
function _laInferPhaseFromLocation(adHocLoc) {
  if (!adHocLoc) return null;
  const resolved = _laResolveLocationPrefix(adHocLoc);
  const master = (LOCS || []).find(l => l.name.trim().toLowerCase() === resolved.trim().toLowerCase() && l.level === 2);
  if (!master || !master.parent_id) return null;
  const parent = (LOCS || []).find(l => l.id === master.parent_id);
  return parent?.name || null;
}

function _planningGetSubsystem(ev) {
  // ev = raw planning_event row
  // 1. Direct on event
  if (ev.subsystem) return ev.subsystem;
  // 2. On linked activity
  const act = PLANNING_ACTIVITIES.find(a => a.id === ev.planning_activity_id);
  if (act?.subsystem) return act.subsystem;
  // 3. From first assigned resource's subsystem
  const er = PLANNING_EVENT_RES.find(r => r.event_id === ev.id);
  if (er) {
    const res = PLANNING_RESOURCES.find(r => r.id === er.resource_id);
    if (res?.subsystem) return res.subsystem;
  }
  return null;
}

// Subsystem display helpers — initials badge that doesn't conflict with shift bg colors
function _planningSubsystemInitials(name) {
  if (!name) return '';
  return name.toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 4);
}

function _planningSubsystemBadge(sub) {
  if (!sub) return '';
  const sc = _planningSubsystemColor(sub);
  const init = _planningSubsystemInitials(sub);
  return `<span class="cal-sub-badge" style="background:${sc.bg};color:${sc.fg};border-color:${sc.border};" title="${escapeHtml(sub)}">${escapeHtml(init)}</span>`;
}

// Unified calendar legend — shift colors are the primary visual; subsystems are secondary tags.
function _planningCalendarLegend() {
  const seenSubs = new Set();
  PLANNING_EVENTS.forEach(e => {
    const s = _planningGetSubsystem(e);
    if (s) seenSubs.add(s);
  });

  const shiftItems = `
    <span class="cal-leg-item"><span class="cal-leg-swatch" style="background:#FFEB3B;border-color:#a98e00;"></span>Day shift</span>
    <span class="cal-leg-item"><span class="cal-leg-swatch" style="background:#2196F3;border-color:#0d47a1;"></span>Night shift</span>
    <span class="cal-leg-item"><span class="cal-leg-swatch" style="background:#1f2937;border-color:#000;"></span>Blanket</span>
    <span class="cal-leg-item"><span class="cal-leg-swatch" style="background:#b91c1c;border-color:#7f1d1d;"></span>Cancelled</span>
    <span class="cal-leg-item"><span class="cal-leg-swatch" style="background:#fef3c7;border-color:#92400e;"></span>🌴 PTO</span>
  `;

  const subChips = [...seenSubs].sort().map(s => {
    const c = _planningSubsystemColor(s);
    const init = _planningSubsystemInitials(s);
    return `<span class="cal-sub-leg-chip">
      <span class="cal-sub-leg-stripe" style="background:${c.bg};"></span>
      <span class="cal-sub-badge cal-sub-badge-inline" style="background:${c.bg};color:${c.fg};border-color:${c.border};">${escapeHtml(init)}</span>
      <span class="cal-sub-leg-name">${escapeHtml(s)}</span>
    </span>`;
  }).join('');

  return `
    <div class="cal-legend-bar">
      <div class="cal-legend-row">
        <span class="cal-legend-label">Shift</span>
        <div class="cal-legend-items">${shiftItems}</div>
      </div>
      ${seenSubs.size ? `
        <div class="cal-legend-row">
          <span class="cal-legend-label">Subsystem</span>
          <div class="cal-legend-items cal-legend-subs">${subChips}</div>
        </div>` : ''}
    </div>`;
}

// ── Tooltip HTML builder ─────────────────────────────────────
function _laEventTippy(e, v, assignments) {
  const timeStr = e.all_day
    ? 'All day'
    : `${(e.start_time||'00:00').slice(0,5)} – ${(e.end_time||'23:59').slice(0,5)}`;
  const sub = _planningGetSubsystem(e);
  const res = assignments.map(a => a.resource?.display_name || '—').join(', ') || '—';
  return `
    <div class="cal-tip">
      <div class="cal-tip-title">${escapeHtml(e.title || '(no title)')}</div>
      <div class="cal-tip-row"><span>📅</span> ${escapeHtml(e.event_date)}</div>
      <div class="cal-tip-row"><span>⏰</span> ${escapeHtml(timeStr)}</div>
      ${sub ? `<div class="cal-tip-row"><span>🏷</span> ${escapeHtml(sub)}</div>` : ''}
      ${e.location ? `<div class="cal-tip-row"><span>📍</span> ${escapeHtml(e.location)}</div>` : ''}
      <div class="cal-tip-row"><span>👤</span> ${escapeHtml(res)}</div>
      <div class="cal-tip-row"><span>🔄</span> ${escapeHtml(v.label)}</div>
      ${e.status === 'cancelled' && e.cancellation_reason ? `<div class="cal-tip-row" style="color:#ef4444;"><span>✕</span> ${escapeHtml(e.cancellation_reason)}${e.cancellation_responsible_party ? ` · <strong>${escapeHtml(e.cancellation_responsible_party)}</strong>` : ''}</div>` : ''}
    </div>`.replace(/"/g, '&quot;');
}

// ── _laMountCalendar: dispatches to month / week / day ───────
function _laMountCalendar() {
  const body = document.getElementById('cal-body');
  if (!body) return;
  if (_planningCalView === 'month')     _laRenderMonthView(body);
  else if (_planningCalView === 'week') _laRenderWeekView(body);
  else                                  _laRenderDayView(body);
  // Activate Tippy on newly rendered event chips
  setTimeout(() => {
    if (window.tippy) {
      tippy('[data-cal-tippy]', {
        content(ref) { return ref.getAttribute('data-cal-tippy').replace(/&quot;/g, '"'); },
        allowHTML:   true,
        delay:       [180, 0],
        placement:   'top',
        theme:       'light-border',
        maxWidth:    320,
        interactive: false,
      });
    }
  }, 60);
}

// ── MONTH VIEW ───────────────────────────────────────────────
function _laRenderMonthView(body) {
  const todayISO = new Date().toISOString().slice(0, 10);
  const anchor   = dayjs(_planningCalDate);
  const year     = anchor.year();
  const month    = anchor.month();             // 0-based
  // First cell = Monday on or before the 1st of this month
  const firstDay = dayjs(new Date(year, month, 1));
  const startCell = _laMondayOf(firstDay.toDate());
  // Always 6 rows × 7 cols
  const ROWS = 6, COLS = 7;

  // Gather events for this grid window
  const windowStart = startCell.format('YYYY-MM-DD');
  const windowEnd   = startCell.add(ROWS * COLS - 1, 'day').format('YYYY-MM-DD');
  const { events, pto } = _planningEventsForRender();

  // Group events by date
  const byDate = {};
  events.forEach(({ source: e, visual: v, isCancel }) => {
    if (e.event_date < windowStart || e.event_date > windowEnd) return;
    (byDate[e.event_date] = byDate[e.event_date] || []).push({ kind: 'event', e, v, isCancel });
  });
  pto.forEach(({ source: p }) => {
    // Span across all days of PTO in the window
    let d = dayjs(p.start_date);
    const endD = dayjs(p.end_date);
    while (!d.isAfter(endD)) {
      const iso = d.format('YYYY-MM-DD');
      if (iso >= windowStart && iso <= windowEnd) {
        (byDate[iso] = byDate[iso] || []).push({ kind: 'pto', p });
      }
      d = d.add(1, 'day');
    }
  });
  if (_planningShowP6 && Array.isArray(P6_ACTS)) {
    P6_ACTS.forEach(p6 => {
      if (!p6.start_date || !p6.finish_date) return;
      let d = dayjs(p6.start_date);
      const endD = dayjs(p6.finish_date);
      while (!d.isAfter(endD)) {
        const iso = d.format('YYYY-MM-DD');
        if (iso >= windowStart && iso <= windowEnd) {
          (byDate[iso] = byDate[iso] || []).push({ kind: 'p6', p6 });
        }
        d = d.add(1, 'day');
      }
    });
  }

  const DOW_HEADERS = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
  let html = `<div class="cal-month-grid">`;
  // Header row
  DOW_HEADERS.forEach(h => {
    html += `<div class="cal-month-day-header">${h}</div>`;
  });
  // Day cells
  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS; col++) {
      const cellDay = startCell.add(row * COLS + col, 'day');
      const iso     = cellDay.format('YYYY-MM-DD');
      const isToday = iso === todayISO;
      const isOther = cellDay.month() !== month;
      const items   = byDate[iso] || [];
      const MAX_SHOW = 3;
      const visible  = items.slice(0, MAX_SHOW);
      const overflow = items.length - MAX_SHOW;

      html += `<div class="cal-month-cell${isToday ? ' cal-today' : ''}${isOther ? ' cal-other-month' : ''}">`;
      html += `<div class="cal-day-num${isToday ? ' cal-today-num' : ''}">${cellDay.date()}</div>`;
      html += `<div class="cal-events-stack">`;
      visible.forEach(item => {
        if (item.kind === 'event') {
          const { e, v, isCancel } = item;
          const sub   = _planningGetSubsystem(e);
          const sc    = sub ? _planningSubsystemColor(sub) : null;
          // Shift color is the event background (operational meaning).
          // Subsystem shows as a thin left stripe + small initials badge.
          const bg    = v.bg;
          const fg    = v.text;
          const stripe = sc ? sc.bg : (isCancel ? '#7f1d1d' : '#999');
          const asgns = _planningResourceAssignmentsForEvent(e.id);
          const tip   = _laEventTippy(e, v, asgns);
          html += `<div class="cal-event${isCancel ? ' cal-event-cancelled' : ''}"
            style="background:${bg};color:${fg};border-left:4px solid ${stripe};"
            data-cal-tippy="${tip}"
            onclick="_planningOpenEventDetail('${e.id}')"
          >${_planningSubsystemBadge(sub)}<span class="cal-event-label">${escapeHtml((e.title||'').slice(0,28))}</span></div>`;
        } else if (item.kind === 'pto') {
          html += `<div class="cal-event cal-event-pto"
            onclick="_planningOpenPTODetail(PTO_REQUESTS.find(x=>x.id==='${item.p.id}'))"
          >🌴 <span class="cal-event-label">${escapeHtml(_ptoResourceName(item.p.resource_id))}</span></div>`;
        } else if (item.kind === 'p6') {
          html += `<div class="cal-event cal-event-p6"
            onclick="_planningOpenP6Detail(P6_ACTS.find(x=>x.id==='${item.p6.id}'))"
          >📋 <span class="cal-event-label">${escapeHtml((item.p6.p6_id||'') + ' ' + (item.p6.p6_name||'').slice(0,20))}</span></div>`;
        }
      });
      if (overflow > 0) {
        html += `<div class="cal-event cal-event-more" onclick="_laShowDayOverflow('${iso}')">+${overflow} more</div>`;
      }
      html += `</div></div>`;
    }
  }
  html += `</div>`;
  body.innerHTML = html;
}

// Show all events for a given ISO date in a modal (triggered by "+N more")
function _laShowDayOverflow(iso) {
  const { events, pto } = _planningEventsForRender();
  const items = [];
  events.forEach(({ source: e, visual: v, isCancel }) => {
    if (e.event_date === iso) items.push({ kind: 'event', e, v, isCancel });
  });
  pto.forEach(({ source: p }) => {
    if (iso >= p.start_date && iso <= p.end_date) items.push({ kind: 'pto', p });
  });
  if (_planningShowP6 && Array.isArray(P6_ACTS)) {
    P6_ACTS.forEach(p6 => {
      if (p6.start_date && p6.finish_date && p6.start_date <= iso && p6.finish_date >= iso)
        items.push({ kind: 'p6', p6 });
    });
  }

  const dayLabel = dayjs(iso).format('dddd, MMMM D');
  let bodyHtml = `<div style="display:flex;flex-direction:column;gap:6px;max-height:60vh;overflow-y:auto;padding-right:4px;">`;
  items.forEach(item => {
    if (item.kind === 'event') {
      const { e, v, isCancel } = item;
      const sub  = _planningGetSubsystem(e);
      const sc   = sub ? _planningSubsystemColor(sub) : null;
      const bg   = v.bg;
      const fg   = v.text;
      const bdr  = sc ? sc.bg : (isCancel ? '#7f1d1d' : bg);
      const meta = [e.start_time ? e.start_time.slice(0,5) + (e.end_time ? ' – '+e.end_time.slice(0,5) : '') : '',
                    e.location || ''].filter(Boolean).join(' · ');
      bodyHtml += `<div style="background:${bg};color:${fg};border-left:5px solid ${bdr};padding:7px 10px;border-radius:5px;cursor:pointer;font-size:13px;display:flex;align-items:center;gap:8px;"
        onclick="closeModal();_planningOpenEventDetail('${e.id}')">
        ${_planningSubsystemBadge(sub)}
        <div style="flex:1;">
        <div style="font-weight:600;margin-bottom:2px;">${escapeHtml(e.title||'(no title)')}</div>
        ${meta ? `<div style="font-size:11px;opacity:.8;">${escapeHtml(meta)}</div>` : ''}
        </div>
      </div>`;
    } else if (item.kind === 'pto') {
      bodyHtml += `<div style="background:#fef3c7;color:#92400e;border-left:4px solid #f59e0b;padding:7px 10px;border-radius:5px;cursor:pointer;font-size:13px;"
        onclick="closeModal();_planningOpenPTODetail(PTO_REQUESTS.find(x=>x.id==='${item.p.id}'))">
        🌴 ${escapeHtml(_ptoResourceName(item.p.resource_id))} — PTO
      </div>`;
    } else if (item.kind === 'p6') {
      bodyHtml += `<div style="background:#f0fdf4;color:#166534;border-left:4px solid #22c55e;padding:7px 10px;border-radius:5px;font-size:13px;">
        📋 <strong>${escapeHtml(item.p6.p6_id||'')}</strong> ${escapeHtml((item.p6.p6_name||'').slice(0,60))}
      </div>`;
    }
  });
  bodyHtml += `</div>`;

  modal({
    title: dayLabel,
    sub:   `${items.length} activit${items.length === 1 ? 'y' : 'ies'}`,
    body:  bodyHtml,
    size:  'medium',
    footer:`<button class="form-secondary" onclick="closeModal()">Close</button>`,
  });
}

// ── WEEK VIEW (simple list layout — no time grid) ────────────
function _laRenderWeekView(body) {
  const todayISO = new Date().toISOString().slice(0, 10);
  const monday   = _laMondayOf(_planningCalDate);
  const days     = Array.from({ length: 7 }, (_, i) => monday.add(i, 'day'));
  const isoList  = days.map(d => d.format('YYYY-MM-DD'));

  const { events, pto } = _planningEventsForRender();

  // Group all items by date
  const byDate = {};
  isoList.forEach(iso => { byDate[iso] = []; });

  events.forEach(({ source: e, visual: v, isCancel }) => {
    if (byDate[e.event_date]) byDate[e.event_date].push({ kind: 'event', e, v, isCancel });
  });
  pto.forEach(({ source: p }) => {
    let d = dayjs(p.start_date);
    const endD = dayjs(p.end_date);
    while (!d.isAfter(endD)) {
      const iso = d.format('YYYY-MM-DD');
      if (byDate[iso]) byDate[iso].push({ kind: 'pto', p });
      d = d.add(1, 'day');
    }
  });
  if (_planningShowP6 && Array.isArray(P6_ACTS)) {
    P6_ACTS.forEach(p6 => {
      if (!p6.start_date || !p6.finish_date) return;
      isoList.forEach(iso => {
        if (iso >= p6.start_date && iso <= p6.finish_date && byDate[iso])
          byDate[iso].push({ kind: 'p6', p6 });
      });
    });
  }

  // ── Build HTML: 7-column card grid ──────────────────────────
  let html = `<div class="cal-week-list-grid">`;

  // Header row
  days.forEach((d, i) => {
    const iso     = isoList[i];
    const isToday = iso === todayISO;
    const isWknd  = d.day() === 0 || d.day() === 6;
    html += `<div class="cal-wl-header${isToday ? ' cal-wl-today-hdr' : ''}${isWknd ? ' cal-wl-weekend-hdr' : ''}">
      <span class="cal-wl-dow">${d.format('ddd')}</span>
      <span class="cal-wl-date${isToday ? ' cal-today-num' : ''}">${d.date()}</span>
    </div>`;
  });

  // Content columns
  days.forEach((d, i) => {
    const iso     = isoList[i];
    const isToday = iso === todayISO;
    const isWknd  = d.day() === 0 || d.day() === 6;
    const items   = byDate[iso] || [];

    html += `<div class="cal-wl-col${isToday ? ' cal-wl-today-col' : ''}${isWknd ? ' cal-wl-weekend-col' : ''}">`;
    if (items.length === 0) {
      html += `<div class="cal-wl-empty">—</div>`;
    } else {
      items.forEach(item => {
        if (item.kind === 'event') {
          const { e, v, isCancel } = item;
          const sub   = _planningGetSubsystem(e);
          const sc    = sub ? _planningSubsystemColor(sub) : null;
          const bg    = v.bg;
          const fg    = v.text;
          const bdr   = sc ? sc.bg : (isCancel ? '#7f1d1d' : bg);
          const asgns = _planningResourceAssignmentsForEvent(e.id);
          const tip   = _laEventTippy(e, v, asgns);
          const meta  = [
            e.start_time ? e.start_time.slice(0,5) + (e.end_time ? '–'+e.end_time.slice(0,5) : '') : '',
            e.location || '',
          ].filter(Boolean).join(' · ');
          html += `<div class="cal-wl-chip${isCancel ? ' cal-wl-chip-cancelled' : ''}"
            style="background:${bg};color:${fg};border-left:4px solid ${bdr};"
            data-cal-tippy="${tip}"
            onclick="_planningOpenEventDetail('${e.id}')"
          >
            <div class="cal-wl-chip-title">${_planningSubsystemBadge(sub)}${escapeHtml(e.title || '(no title)')}</div>
            ${meta ? `<div class="cal-wl-chip-meta">${escapeHtml(meta)}</div>` : ''}
          </div>`;
        } else if (item.kind === 'pto') {
          html += `<div class="cal-wl-chip cal-wl-chip-pto"
            onclick="_planningOpenPTODetail(PTO_REQUESTS.find(x=>x.id==='${item.p.id}'))"
          >
            <div class="cal-wl-chip-title">🌴 ${escapeHtml(_ptoResourceName(item.p.resource_id))}</div>
            <div class="cal-wl-chip-meta">PTO</div>
          </div>`;
        } else if (item.kind === 'p6') {
          html += `<div class="cal-wl-chip cal-wl-chip-p6"
            onclick="_planningOpenP6Detail(P6_ACTS.find(x=>x.id==='${item.p6.id}'))"
          >
            <div class="cal-wl-chip-title">📋 ${escapeHtml((item.p6.p6_name || item.p6.p6_id || '').slice(0, 50))}</div>
            <div class="cal-wl-chip-meta">${escapeHtml(item.p6.p6_id || '')}</div>
          </div>`;
        }
      });
    }
    html += `</div>`;
  });

  html += `</div>`;
  body.innerHTML = html;
}

// ── DAY VIEW (list layout — full detail per event) ───────────
function _laRenderDayView(body) {
  const todayISO = new Date().toISOString().slice(0, 10);
  const iso      = dayjs(_planningCalDate).format('YYYY-MM-DD');
  const isToday  = iso === todayISO;
  const dayLabel = dayjs(iso).format('dddd, MMMM D, YYYY');

  const { events, pto } = _planningEventsForRender();
  const items = [];

  events.forEach(({ source: e, visual: v, isCancel }) => {
    if (e.event_date !== iso) return;
    items.push({ kind: 'event', e, v, isCancel });
  });
  pto.forEach(({ source: p }) => {
    if (iso >= p.start_date && iso <= p.end_date) items.push({ kind: 'pto', p });
  });
  if (_planningShowP6 && Array.isArray(P6_ACTS)) {
    P6_ACTS.forEach(p6 => {
      if (p6.start_date && p6.finish_date && iso >= p6.start_date && iso <= p6.finish_date)
        items.push({ kind: 'p6', p6 });
    });
  }

  // Sort events: timed first (by start_time), then all-day, then PTO/P6
  items.sort((a, b) => {
    const rank = x => x.kind === 'pto' ? 2 : x.kind === 'p6' ? 3 : (x.e.all_day || !x.e.start_time ? 1 : 0);
    if (rank(a) !== rank(b)) return rank(a) - rank(b);
    if (a.kind === 'event' && b.kind === 'event') {
      return (a.e.start_time || '00:00').localeCompare(b.e.start_time || '00:00');
    }
    return 0;
  });

  let html = `<div class="cal-day-list-wrap">`;

  // Date header
  html += `<div class="cal-day-list-header${isToday ? ' cal-day-list-today' : ''}">
    <span class="cal-day-list-dow">${dayjs(iso).format('ddd')}</span>
    <span class="cal-day-list-date">${dayjs(iso).date()}</span>
    <span class="cal-day-list-month">${dayjs(iso).format('MMMM YYYY')}</span>
    ${isToday ? '<span class="cal-day-list-todaybadge">Today</span>' : ''}
  </div>`;

  if (items.length === 0) {
    html += `<div class="cal-day-list-empty">No activities scheduled for this day.</div>`;
  } else {
    html += `<div class="cal-day-list-cards">`;
    items.forEach(item => {
      if (item.kind === 'event') {
        const { e, v, isCancel } = item;
        const sub    = _planningGetSubsystem(e);
        const sc     = sub ? _planningSubsystemColor(sub) : null;
        // Shift color = background; subsystem = left stripe + initials badge
        const bg     = v.bg;
        const fg     = v.text;
        const bdr    = sc ? sc.bg : (isCancel ? '#7f1d1d' : bg);
        const asgns  = _planningResourceAssignmentsForEvent(e.id);
        const tip    = _laEventTippy(e, v, asgns);

        const timeStr = e.all_day || !e.start_time
          ? 'All day'
          : `${e.start_time.slice(0,5)}${e.end_time ? ' – ' + e.end_time.slice(0,5) : ''}`;

        const resNames = asgns.map(a => a.resource?.display_name || '').filter(Boolean);
        const resHtml  = resNames.length
          ? `<div class="cal-dl-chip-res">${resNames.map(n => `<span class="cal-dl-res-badge">${escapeHtml(n)}</span>`).join('')}</div>`
          : '';

        const metaParts = [
          timeStr,
          e.location ? `📍 ${e.location}` : '',
        ].filter(Boolean);

        html += `<div class="cal-dl-chip${isCancel ? ' cal-dl-chip-cancelled' : ''}"
          style="border-left:5px solid ${bdr};background:${bg};color:${fg};"
          data-cal-tippy="${tip}"
          onclick="_planningOpenEventDetail('${e.id}')"
        >
          <div class="cal-dl-chip-header">
            <span class="cal-dl-chip-title">${_planningSubsystemBadge(sub)}${escapeHtml(e.title || '(no title)')}</span>
            <span class="cal-dl-chip-badge" style="background:rgba(0,0,0,.25);color:${fg};">${v.icon} ${v.label}</span>
          </div>
          <div class="cal-dl-chip-meta">${metaParts.map(escapeHtml).join(' · ')}</div>
          ${resHtml}
          ${e.notes ? `<div class="cal-dl-chip-notes">${escapeHtml(e.notes.slice(0, 120))}${e.notes.length > 120 ? '…' : ''}</div>` : ''}
        </div>`;

      } else if (item.kind === 'pto') {
        html += `<div class="cal-dl-chip cal-dl-chip-pto"
          onclick="_planningOpenPTODetail(PTO_REQUESTS.find(x=>x.id==='${item.p.id}'))"
        >
          <div class="cal-dl-chip-header">
            <span class="cal-dl-chip-title">🌴 ${escapeHtml(_ptoResourceName(item.p.resource_id))}</span>
            <span class="cal-dl-chip-badge" style="background:#d1fae5;color:#065f46;">PTO</span>
          </div>
          <div class="cal-dl-chip-meta">${escapeHtml(_ptoFmtRange(item.p))}</div>
        </div>`;

      } else if (item.kind === 'p6') {
        html += `<div class="cal-dl-chip cal-dl-chip-p6"
          onclick="_planningOpenP6Detail(P6_ACTS.find(x=>x.id==='${item.p6.id}'))"
        >
          <div class="cal-dl-chip-header">
            <span class="cal-dl-chip-title">📋 ${escapeHtml((item.p6.p6_name || item.p6.p6_id || '').slice(0, 80))}</span>
            <span class="cal-dl-chip-badge" style="background:#e0e7ff;color:#3730a3;">P6</span>
          </div>
          <div class="cal-dl-chip-meta">${escapeHtml(item.p6.p6_id || '')} · ${escapeHtml(item.p6.start_date || '')} – ${escapeHtml(item.p6.finish_date || '')}</div>
        </div>`;
      }
    });
    html += `</div>`;
  }

  html += `</div>`;
  body.innerHTML = html;
}

// ── LOOKAHEAD TIMELINE TAB ───────────────────────────────────
// ── Month colour palette — alternating red / black only ───────
const _TL_MONTH_COLORS = [
  '#e60012', // Hitachi red
  '#2a2a2a', // Hitachi charcoal/black
];

// ── Party to Action — multiselect options + badge colours ─────
// STS = Hitachi Rail (per BART/Hitachi convention).
const _PARTY_TO_ACTION_OPTS = [
  ['STS',  'STS — Hitachi Rail'],
  ['BART', 'BART'],
  ['REI',  'REI'],
];
const _PARTY_BADGE = {
  STS:  { bg: '#e60012', fg: '#fff' }, // Hitachi red
  BART: { bg: '#0072ce', fg: '#fff' }, // BART blue
  REI:  { bg: '#00875a', fg: '#fff' }, // green
};
function _partyBadgesHTML(arr) {
  if (!Array.isArray(arr) || !arr.length) return '';
  return `<span class="tlg-party-wrap">${arr
    .filter(p => _PARTY_BADGE[p])
    .map(p => {
      const c = _PARTY_BADGE[p];
      return `<span class="tlg-party-badge" style="background:${c.bg};color:${c.fg};">${escapeHtml(p)}</span>`;
    }).join('')}</span>`;
}

// ── Derive shift visual from time range (fixes colour mismatches) ──
function _tlgShiftVisual(s) {
  if (s.isCancel) return _CANCEL_VISUAL;
  if (s.all_day || s.shift_type === 'blanket_shift') return _SHIFT_VISUAL.blanket_shift;
  if (s.shift_type && _SHIFT_VISUAL[s.shift_type]) return _SHIFT_VISUAL[s.shift_type];
  if (s.start_time) {
    const h = parseInt(s.start_time.slice(0, 2), 10);
    if (h >= 4  && h < 12) return _SHIFT_VISUAL.day_shift;
    if (h >= 12 && h < 18) return _SHIFT_VISUAL.swing_shift;
    return _SHIFT_VISUAL.night_shift;
  }
  return _SHIFT_VISUAL.custom;
}
// ── Annotate consecutive same-shift runs ─────────────────────────
function _tlgAnnotateRuns(groups, days) {
  groups.forEach(g => {
    if (!g.byDate) return; // skip header/divider rows (no shift data)
    days.forEach((iso, idx) => {
      const shifts = g.byDate[iso] || [];
      // Only merge single-shift days (not split cells)
      if (shifts.length !== 1) { shifts.forEach(s => { s.run = 'solo'; }); return; }
      const s = shifts[0];
      if (s.isCancel || s.is_p6) { s.run = 'solo'; return; }
      const prev = idx > 0 ? (g.byDate[days[idx - 1]] || []) : [];
      const next = idx < days.length - 1 ? (g.byDate[days[idx + 1]] || []) : [];
      const prevSame = prev.length === 1 && !prev[0].isCancel &&
        _tlgShiftVisual(prev[0]).bg === _tlgShiftVisual(s).bg;
      const nextSame = next.length === 1 && !next[0].isCancel &&
        _tlgShiftVisual(next[0]).bg === _tlgShiftVisual(s).bg;
      s.run = prevSame && nextSame ? 'mid' : prevSame ? 'end' : nextSame ? 'start' : 'solo';
    });
  });
}

// ── Tippy tooltip for grid shift blocks ───────────────────────────
function _tlgShiftTip(s, v) {
  const ts = s.all_day ? 'All day'
    : `${(s.start_time||'').slice(0,5)} – ${(s.end_time||'').slice(0,5)}`;
  return (`<div class="cal-tip">
    <div class="cal-tip-title">${escapeHtml(s.title||'(no title)')}</div>
    <div class="cal-tip-row"><span>⏰</span> ${escapeHtml(ts)}</div>
    <div class="cal-tip-row"><span>🔄</span> ${escapeHtml(v.label)}</div>
    ${s.isCancel ? '<div class="cal-tip-row" style="color:#ef4444;"><span>✕</span> Cancelled</div>' : ''}
  </div>`).replace(/"/g, '&quot;');
}

// ── Discipline / Trade / Status helpers for the v-combo swimlane ──
// Discipline + trade come from explicit columns on planning_activities; the
// fallbacks make legacy rows still group correctly until they are tagged.
const _LA_DISCIPLINE_PALETTE = {
  'T&C':    { color: 'var(--disc-tc)',     bg: 'var(--disc-tc-bg)',     label: 'Testing & Commissioning' },
  'CONS':   { color: 'var(--disc-cons)',   bg: 'var(--disc-cons-bg)',   label: 'Construction' },
  'DESIGN': { color: 'var(--disc-design)', bg: 'var(--disc-design-bg)', label: 'Design' },
};
function _laDisciplinePalette(disc) {
  return _LA_DISCIPLINE_PALETTE[disc] || { color: 'var(--disc-default)', bg: 'var(--disc-default-bg)', label: disc || '—' };
}
function _laActDiscipline(a) {
  const explicit = (a?.discipline || '').trim();
  if (explicit) return explicit;
  // Heuristic: activity_group "tc" → T&C, otherwise pick a sensible default
  const grp = (a?.activity_group || '').toLowerCase();
  if (grp === 'tc' || grp === 't&c') return 'T&C';
  if (grp === 'cons' || grp === 'construction') return 'CONS';
  if (grp === 'design') return 'DESIGN';
  return 'T&C';
}
function _laActTrade(a) {
  const explicit = (a?.trade || '').trim();
  if (explicit) return explicit;
  const sub = (a?.subsystem || '').toUpperCase().trim();
  if (['CBTC','SIG','COMMS','POWER','CIVIL','QA'].includes(sub)) return sub;
  return '';
}
const _LA_STATUS_META = {
  ontrack: { label: 'On track', color: 'var(--good)', bg: 'var(--good-light)', bar: 'var(--good)' },
  atrisk:  { label: 'At risk',  color: 'var(--warn)', bg: 'var(--warn-light)', bar: 'var(--warn)' },
  blocked: { label: 'Blocked',  color: 'var(--bad)',  bg: 'var(--bad-light)',  bar: 'var(--bad)'  },
  done:    { label: 'Complete', color: 'var(--info)', bg: 'var(--info-light)', bar: 'var(--info)' },
  plan:    { label: 'Planned',  color: 'var(--gray-700)', bg: 'var(--gray-100)', bar: 'var(--gray-500)' },
};
function _laStatusMeta(s) { return _LA_STATUS_META[s] || _LA_STATUS_META.plan; }
function _laActStatus(a, evs) {
  if (!Array.isArray(evs) || !evs.length) return 'plan';
  if (evs.some(e => e.status === 'cancelled')) return 'blocked';
  const today = new Date().toISOString().slice(0, 10);
  const past  = evs.filter(e => e.event_date < today && e.status !== 'cancelled');
  if (past.length && past.length === evs.length) return 'done';
  return 'ontrack';
}

// Inline icon helper used inside v-combo row labels
function _laIconHTML(name) {
  const paths = {
    pin:   'M12 22s-7-6.5-7-12a7 7 0 0114 0c0 5.5-7 12-7 12zM12 11a2 2 0 100-4 2 2 0 000 4z',
    user:  'M16 7a4 4 0 11-8 0 4 4 0 018 0zM4 21a8 8 0 0116 0',
    clock: 'M12 7v5l3 2M21 12a9 9 0 11-18 0 9 9 0 0118 0z',
    alert: 'M12 9v4m0 4h.01M10.3 3.86l-8.1 14a2 2 0 001.7 3h16.2a2 2 0 001.7-3l-8.1-14a2 2 0 00-3.4 0z',
  };
  return `<svg class="icon-sm" viewBox="0 0 24 24"><path d="${paths[name] || ''}"/></svg>`;
}

// ── Shared grid renderer (Lookahead, Gantt, Resources) ────────
function _laRenderGrid(target, { groups, days, milestones }) {
  if (!target) return;
  if (!days.length) {
    target.innerHTML = `<div style="padding:48px;text-align:center;color:var(--gray-400);font-size:13px;">No data to display. Import a lookahead first.</div>`;
    return;
  }
  const todayISO = new Date().toISOString().slice(0, 10);

  // Build month spans — compare 'YYYY-MM' prefix directly to avoid
  // timezone-induced dayjs mis-classification near month boundaries.
  const monthSpans = [];
  let mi = 0;
  while (mi < days.length) {
    const ym = days[mi].slice(0, 7); // 'YYYY-MM', unambiguous
    const d  = dayjs(days[mi]);
    let j = mi;
    while (j < days.length && days[j].slice(0, 7) === ym) j++;
    monthSpans.push({ label: d.format('MMMM YYYY'), count: j - mi });
    mi = j;
  }

  let html = `<div class="tlg-shell v-combo">`;
  // Sticky header block — milestone strip + month bar + day header
  // stay frozen at the top while the body scrolls vertically.
  html += `<div class="tlg-head">`;

  // ── Milestone strip ──────────────────────────────────────────
  html += `<div class="tlg-row tlg-ms-row"><div class="tlg-label tlg-ms-gutter"></div><div class="tlg-cells">`;
  days.forEach(iso => {
    const isToday = iso === todayISO;
    const marks = milestones.filter(mk => mk.date === iso);
    html += `<div class="tlg-cell tlg-ms-cell">`;
    if (isToday) html += `<div class="tlg-today-marker"><span class="tlg-today-label">Today</span><span class="tlg-today-arr">▼</span></div>`;
    marks.forEach(mk => html += `<div class="tlg-ms-mark" title="${escapeHtml(mk.label)}">${escapeHtml(mk.icon||'◆')}</div>`);
    html += `</div>`;
  });
  html += `</div></div>`;

  // ── Month bar ────────────────────────────────────────────────
  html += `<div class="tlg-row tlg-month-row"><div class="tlg-label tlg-month-gutter"></div><div class="tlg-cells">`;
  monthSpans.forEach((span, si) => {
    const color = _TL_MONTH_COLORS[si % _TL_MONTH_COLORS.length];
    // Lock pill width to exactly span.count day-cells (cell min 46 / max 80px)
    // so the month bar and day header stay aligned even when the grid scrolls.
    html += `<div class="tlg-month-pill" style="flex:${span.count};min-width:${span.count * 46}px;max-width:${span.count * 80}px;background:${color};">${span.label}</div>`;
  });
  html += `</div></div>`;

  // ── Day header ───────────────────────────────────────────────
  html += `<div class="tlg-row tlg-day-hdr-row"><div class="tlg-label tlg-day-gutter"></div><div class="tlg-cells">`;
  days.forEach(iso => {
    const d = dayjs(iso);
    const isToday = iso === todayISO;
    const dow = d.day();
    const isWknd = dow === 0 || dow === 6;
    html += `<div class="tlg-cell tlg-day-hdr${isToday ? ' tlg-today-col' : ''}${isWknd ? ' tlg-weekend' : ''}">
      <div class="tlg-dow">${d.format('dd').slice(0,1)}</div>
      <div class="tlg-date-num${isToday ? ' tlg-today-date' : ''}">${d.date()}</div>
    </div>`;
  });
  html += `</div></div>`;
  html += `</div>`; // close .tlg-head (sticky header block)

  // ── Annotate consecutive runs BEFORE rendering ───────────────
  _tlgAnnotateRuns(groups, days);

  // ── Body rows ────────────────────────────────────────────────
  if (!groups.length) {
    html += `<div style="padding:48px;text-align:center;color:var(--gray-400);font-size:13px;">No activities in this window yet. Import a lookahead or adjust the date range.</div>`;
  }
  groups.forEach(g => {
    // ── Activity-group band header (Phase 2 — Master Schedule) ──
    if (g.isGroupHeader) {
      const caret = g.collapsed ? '▶' : '▼';
      html += `<div class="tlg-row tlg-grp-hdr-row"
          data-group-key="${g.groupKey}"
          style="background:${g.bg};color:${g.fg};border-left:4px solid ${g.accent};"
          onclick="_laToggleGroupCollapse('${g.groupKey}')"
          title="${g.collapsed ? 'Expand' : 'Collapse'} ${escapeHtml(g.label)}">
        <div class="tlg-label tlg-grp-hdr-label">
          <span class="tlg-grp-caret">${caret}</span>
          <span class="tlg-grp-name">${escapeHtml(g.label)}</span>
          <span class="tlg-grp-count">${g.activityCount}</span>
        </div>
        <div class="tlg-cells">${days.map(iso => {
          const isToday = iso === todayISO;
          return `<div class="tlg-cell tlg-grp-hdr-cell${isToday ? ' tlg-today-col' : ''}"></div>`;
        }).join('')}</div>
      </div>`;
      return;
    }

    // ── Phase / Location sub-group header (Activity sub-grouping) ──
    if (g.isSubGroupHeader) {
      const caret = g.collapsed ? '▶' : '▼';
      // Indent the LABEL only — never the row — or the day-cell container
      // shifts and weekend columns stop lining up with the other rows.
      const labelPad = g.indent ? 'padding-left:26px;' : 'padding-left:10px;';
      html += `<div class="tlg-row tlg-subgrp-hdr-row"
          data-subgroup-key="${escapeHtml(g.subGroupKey)}"
          style="background:${g.bg}bb;color:${g.fg};border-left:3px solid ${g.accent}99;"
          onclick="_laToggleGroupCollapse(${JSON.stringify(g.subGroupKey)})"
          title="${g.collapsed ? 'Expand' : 'Collapse'} ${escapeHtml(g.label)}">
        <div class="tlg-label tlg-subgrp-hdr-label" style="${labelPad}">
          <span class="tlg-grp-caret">${caret}</span>
          <span class="tlg-subgrp-icon">${g.icon || ''}</span>
          <span class="tlg-grp-name" style="font-size:11px;">${escapeHtml(g.label)}</span>
          <span class="tlg-grp-count">${g.activityCount}</span>
        </div>
        <div class="tlg-cells">${days.map(iso => {
          const isToday = iso === todayISO;
          return `<div class="tlg-cell tlg-grp-hdr-cell${isToday ? ' tlg-today-col' : ''}"></div>`;
        }).join('')}</div>
      </div>`;
      return;
    }

    // ── Location divider row (kept for Location sort mode) ──────
    if (g.isLocHeader) {
      html += `<div class="tlg-row tlg-loc-hdr-row">
        <div class="tlg-label tlg-loc-hdr-label">📍 ${escapeHtml(g.label)}</div>
        <div class="tlg-cells">${days.map(iso => {
          const isToday = iso === todayISO;
          return `<div class="tlg-cell tlg-loc-hdr-cell${isToday ? ' tlg-today-col' : ''}"></div>`;
        }).join('')}</div>
      </div>`;
      return;
    }

    const actId = g.activityId || '';
    html += `<div class="tlg-row tlg-data-row${_laAssignMode && actId ? ' la-row-droppable' : ''}"${actId ? ` data-activity-id="${actId}"` : ''}>`;

    // Resource chips — shown when assign mode is active
    const assignedChips = (_laAssignMode && g.assignedResources?.length)
      ? `<div class="la-assigned-chips">${g.assignedResources.map(r => {
          const initials = r.initials || r.display_name.split(' ').map(w => w[0]).join('').slice(0, 2).toUpperCase();
          return `<span class="la-assigned-chip" title="${escapeHtml(r.display_name)}">
            ${escapeHtml(initials)}
            <button class="la-chip-remove" title="Remove ${escapeHtml(r.display_name)}"
              onclick="event.stopPropagation();_laRemoveActivityResource('${actId}','${r.id}')">×</button>
          </span>`;
        }).join('')}</div>`
      : '';
    const dropHintHTML = (_laAssignMode && actId && !g.assignedResources?.length)
      ? `<span class="la-drop-hint-text">drop here</span>`
      : '';

    const linkChip = actId ? (g.linkedTestRegActivity
      ? `<span class="tlg-row-link tlg-row-link-set" title="Linked to Test Register Activity: ${escapeHtml(g.linkedTestRegActivity)}">🔗 ${escapeHtml(g.linkedTestRegActivity)}</span>`
      : `<span class="tlg-row-link tlg-row-link-none" title="No Test Register Activity linked — click to link">🔗 unlinked</span>`) : '';
    const progChip = _planningRowProgressChip(g.linkedTestRegActivity);
    // v-combo: discipline color drives the 3px spine; status pill + trade chip
    // sit inline; activity name and meta wrap as needed.
    const discPal  = _laDisciplinePalette(g.actDiscipline);
    const statMeta = _laStatusMeta(g.actStatus || 'plan');
    const tradeCls = g.actTrade ? `trade-${g.actTrade}` : 'trade-default';
    const tradeChip = g.actTrade ? `<span class="la-trade-chip ${tradeCls}">${escapeHtml(g.actTrade)}</span>` : '';
    const codeChip  = g.actCode  ? `<span class="la-combo-code">${escapeHtml(g.actCode)}</span>` : '';
    const statusChip = `<span class="la-combo-status status-${g.actStatus || 'plan'}">
        <span class="la-dot status-${g.actStatus || 'plan'}"></span>${escapeHtml(statMeta.label)}
      </span>`;
    const metaSegs = [];
    if (g.actWorkHours) metaSegs.push(`<span class="la-combo-meta">${_laIconHTML('clock')}${escapeHtml(g.actWorkHours)}</span>`);
    if (g.actSswp)      metaSegs.push(`<span class="la-combo-meta">SSWP ${escapeHtml(g.actSswp)}</span>`);
    html += `<div class="tlg-label tlg-row-label la-combo-label${_laAssignMode && actId ? ' la-drop-label' : ''}"
      ${actId && !_laAssignMode ? `onclick="if(event.target.closest('.tlg-row-del,.tlg-row-link-btn,.dw-party-chip'))return;_laDrawerOpen('activity','${actId}')" title="Click to edit activity"` : ''}
      ${_laAssignMode && actId ? `data-activity-id="${actId}" title="Drop here to assign for the full activity"` : ''}>
      <span class="la-combo-spine" style="background:${discPal.color};"></span>
      <div class="la-combo-content">
        <div class="la-combo-line1">
          <span class="la-combo-loc-icon">${_laIconHTML('pin')}</span>
          <span class="la-combo-location">${escapeHtml(g.actLocation || '—')}</span>
          ${_partyBadgesHTML(g.actParty)}
        </div>
        ${(codeChip || tradeChip) ? `<div class="la-combo-line2">${codeChip}${tradeChip}${statusChip}</div>` : `<div class="la-combo-line2">${statusChip}</div>`}
        <div class="la-combo-line3" title="${escapeHtml(g.label)}">${escapeHtml(g.label)}</div>
        ${metaSegs.length || linkChip ? `<div class="la-combo-line4">
          ${metaSegs.join('')}
          ${linkChip ? `<button class="tlg-row-link-btn" onclick="event.stopPropagation();_laOpenLinkActivityModal('${actId}')">${linkChip}</button>${progChip}` : ''}
        </div>` : ''}
      </div>
      ${assignedChips}${dropHintHTML}
      ${actId ? `<button class="tlg-row-del" onclick="event.stopPropagation();_laDeleteManualActivity('${actId}',event)" title="Delete activity (soft-delete coming in Phase 3)" style="position:absolute;top:6px;right:8px;">🗑</button>` : ''}
    </div>`;
    html += `<div class="tlg-cells">`;
    days.forEach((iso, idx) => {
      const isToday = iso === todayISO;
      const dow = dayjs(iso).day();
      const isWknd = dow === 0 || dow === 6;
      const shifts   = g.byDate[iso] || [];
      const ptoEntry = g.ptoByDate && g.ptoByDate[iso];
      const inP6     = g.p6Range && g.p6Range.has(iso);

      // Run-aware cell classes (hide right border for start/mid runs)
      const singleShift = shifts.length === 1 && !ptoEntry;
      const run = singleShift ? (shifts[0].run || 'solo') : 'solo';
      let cellClass = `tlg-cell tlg-data-cell`;
      if (isToday) cellClass += ' tlg-today-col';
      if (isWknd)  cellClass += ' tlg-weekend';
      if (inP6 && !shifts.length && !ptoEntry) cellClass += ' tlg-p6-bg';
      if (run === 'start' || run === 'mid') cellClass += ' tlg-run-bridge';

      // Assign mode: cells with shifts become individual drop targets
      const isCellDroppable = _laAssignMode && actId && shifts.length > 0 && !ptoEntry;
      if (isCellDroppable) cellClass += ' la-cell-droppable';
      // Always carry activity_id + date so copy/paste can target any cell
      const cellTargetAttrs = actId ? ` data-activity-id="${actId}" data-event-date="${iso}"` : '';
      const isEmptyTarget = actId && !shifts.length && !ptoEntry;
      const emptyClickAttr = isEmptyTarget
        ? ` onclick="_laEmptyCellClick(event,'${actId}','${iso}',this)"`
        : '';
      const isThisPasteTarget = isEmptyTarget && _laPasteTarget &&
        _laPasteTarget.activityId === actId && _laPasteTarget.date === iso;
      if (isThisPasteTarget) cellClass += ' la-paste-target';

      html += `<div class="${cellClass}"${cellTargetAttrs}${emptyClickAttr}>`;

      if (ptoEntry) {
        html += `<div class="tlg-shift-block tlg-shift-pto tlg-run-solo"
          onclick="(function(){const p=PTO_REQUESTS.find(x=>x.id==='${ptoEntry.id}');if(p)_planningOpenPTODetail(p);})()"
          title="PTO"
        >🌴<span class="tlg-shift-time"> PTO</span></div>`;
      } else {
        shifts.forEach(s => {
          const v   = _tlgShiftVisual(s);
          const tip = _tlgShiftTip(s, v);
          const runClass  = `tlg-run-${s.run || 'solo'}`;
          const isCellSel = _laSelectedCellKeys.has(s.event_id);
          const inClip = _laClipboard?.items.some(it => it.event.id === s.event_id);
          const cutClass = (_laClipboard?.mode === 'cut' && inClip) ? ' la-cell-cut' : '';
          const clipClass = inClip ? ' la-cell-clipboard' : '';
          // Per-cell badge: show test execution status from the linked Test Register Activity
          const badgeHtml = _planningCellBadge(g.linkedTestRegActivity, iso);
          html += `<div class="tlg-shift-block ${runClass}${s.isCancel ? ' tlg-shift-cancelled' : ''}${isCellSel ? ' la-cell-selected' : ''}${clipClass}${cutClass}"
            style="background:${v.bg};color:${v.text};"
            data-cell-event-id="${s.event_id}"
            data-activity-id="${actId||''}"
            data-event-date="${iso}"
            onclick="_laCellClick(event,'${s.event_id}','${actId||''}','${iso}',this)"
            oncontextmenu="event.preventDefault();_laCellContextMenu(event,'${s.event_id}','${actId||''}','${iso}',this);return false;"
            data-tlg-tip="${tip}"
          >${s.resChips && s.resChips.length
              ? `<div class="tlg-res-chips" style="--res-fs:${Math.max(8, 15 - s.resChips.length)}px;">${s.resChips.map(ch => `<span class="tlg-res-chip ${ch.isBart?'tlg-res-bart':'tlg-res-hit'}${ch.denied?' tlg-res-denied':''}">${escapeHtml(ch.label)}</span>`).join('')}</div>`
              : s.cellLabel ? `<span class="tlg-cell-location">${escapeHtml(s.cellLabel)}</span>` : ''
            }${badgeHtml}${isCellSel ? `<span class="la-cell-sel-mark">✓</span>` : ''}<span class="tlg-fill-handle" onmousedown="_laFillStart(event,'${s.event_id}','${actId||''}','${iso}',this.parentElement)" title="Drag to fill across days"></span></div>`;
        });
        if (inP6 && !shifts.length) html += `<div class="tlg-p6-hint">P6</div>`;
      }
      html += `</div>`;
    });
    html += `</div></div>`;
  });

  // ── P6 schedule section (Lookahead overlay rows) ─────────────
  if (_planningShowP6 && Array.isArray(P6_ACTS) && P6_ACTS.length) {
    const p6inWindow = P6_ACTS.filter(p6 =>
      p6.start_date && p6.finish_date &&
      days.some(iso => iso >= p6.start_date && iso <= p6.finish_date)
    );
    if (p6inWindow.length) {
      html += `<div class="tlg-p6-section">`;
      html += `<div class="tlg-row tlg-p6-hdr-row"><div class="tlg-label tlg-p6-section-label">📋 P6 Baseline</div><div class="tlg-cells">`;
      days.forEach(() => html += `<div class="tlg-cell"></div>`);
      html += `</div></div>`;
      p6inWindow.forEach(p6 => {
        html += `<div class="tlg-row tlg-data-row">`;
        html += `<div class="tlg-label tlg-row-label tlg-p6-row-label">
          <span class="tlg-label-main" style="font-size:10px;word-break:break-word;">${escapeHtml(p6.p6_name || p6.p6_id || '—')}</span>
          <span class="tlg-label-sub" style="font-family:monospace;font-size:9px;opacity:.7;">${escapeHtml(p6.p6_id||'')}</span>
        </div>`;
        html += `<div class="tlg-cells">`;
        days.forEach(iso => {
          const isToday = iso === todayISO;
          const active  = iso >= p6.start_date && iso <= p6.finish_date;
          html += `<div class="tlg-cell tlg-data-cell${isToday ? ' tlg-today-col' : ''}">`;
          if (active) html += `<div class="tlg-shift-block tlg-shift-p6"
            onclick="(function(){const p=P6_ACTS.find(x=>x.id==='${p6.id}');if(p)_planningOpenP6Detail(p);})()"
            title="${escapeHtml((p6.p6_id||'')+' '+( p6.p6_name||''))}"
          ><span class="tlg-shift-time">${escapeHtml(p6.p6_id||'')}</span></div>`;
          html += `</div>`;
        });
        html += `</div></div>`;
      });
      html += `</div>`;
    }
  }

  html += `</div>`;  // tlg-shell
  target.innerHTML = html;

  // Re-apply persistent UI state after a fresh render
  _laUpdateSelectionChrome();
  if (_laRowSearch) _laApplyRowSearch();

  // Activate Tippy on shift blocks
  setTimeout(() => {
    if (!window.tippy) return;
    tippy('[data-tlg-tip]', {
      content(ref) { return ref.getAttribute('data-tlg-tip').replace(/&quot;/g, '"'); },
      allowHTML: true, delay: [150, 0], placement: 'top',
      theme: 'light-border', maxWidth: 260, interactive: false,
    });
  }, 60);
}

// ── Helper: build shift entries for a date map ─────────────────
function _laBuildByDate(events, days, cellLabelFn) {
  const byDate = {};
  events.forEach(e => {
    if (!days.includes(e.event_date)) return;
    const isCancel = e.status === 'cancelled';
    (byDate[e.event_date] = byDate[e.event_date] || []).push({
      event_id: e.id, shift_type: e.shift_type, start_time: e.start_time,
      end_time: e.end_time, all_day: !!e.all_day, isCancel, title: e.title || '',
      cellLabel: cellLabelFn ? (cellLabelFn(e) || '') : '',
    });
  });
  return byDate;
}

// Returns space-joined initials for all resources on a single event
function _planningEventResourceInitials(eventId) {
  return PLANNING_EVENT_RES
    .filter(er => er.event_id === eventId)
    .map(er => {
      const r = PLANNING_RESOURCES.find(x => x.id === er.resource_id);
      return r?.initials ||
        r?.display_name?.split(/\s+/).map(w => w[0]).join('').slice(0, 2).toUpperCase() || '';
    })
    .filter(Boolean)
    .join(' ');
}

// Returns compact chip objects for BART roles only on a single event.
// Each chip: { label: "TTO×2", denied: bool }
function _planningEventResChips(eventId) {
  return (PLANNING_EVENT_RES || [])
    .filter(er => er.event_id === eventId)
    .map(er => {
      const r = (PLANNING_RESOURCES || []).find(x => x.id === er.resource_id);
      if (!r) return null;
      const initials = r.initials || (r.display_name || '?').split(/\s+/).map(w => w[0]).join('').slice(0, 3).toUpperCase();
      const qty = (er.quantity || 1) > 1 ? '\u00d7' + er.quantity : '';
      return { label: initials + qty, denied: !!er.denied_at, isBart: r.company === 'BART' };
    })
    .filter(Boolean);
}
function _planningEventBartChips(eventId) { return _planningEventResChips(eventId).filter(c => c.isBart); }
// Like _laBuildByDate but attaches BART chips for Activity view cells.
function _laBuildByDateActivity(events, days) {
  const byDate = {};
  events.forEach(e => {
    if (!days.includes(e.event_date)) return;
    const isCancel = e.status === 'cancelled';
    (byDate[e.event_date] = byDate[e.event_date] || []).push({
      event_id: e.id, shift_type: e.shift_type, start_time: e.start_time,
      end_time: e.end_time, all_day: !!e.all_day, isCancel, title: e.title || '',
      cellLabel: '',
      // Activity view: show BART resources only (no Hitachi chips)
      resChips: isCancel ? [] : _planningEventBartChips(e.id),
    });
  });
  return byDate;
}

// ── Helper: build PTO coverage map for a resource ──────────────
function _laBuildPtoByDate(resourceId, days) {
  const map = {};
  PTO_REQUESTS.filter(p => p.status === 'approved' && p.resource_id === resourceId).forEach(p => {
    days.forEach(iso => { if (iso >= p.start_date && iso <= p.end_date) map[iso] = p; });
  });
  return map;
}

function _laLookaheadHTML() {
  return `
    ${_planningKPIStrip()}
    ${_planningShiftLegend()}

    <div style="display:flex;gap:16px;flex-wrap:wrap;align-items:center;margin-bottom:12px;">
      <div style="display:flex;align-items:center;gap:0;">
        <span style="font-size:11px;color:var(--gray-500);margin-right:8px;white-space:nowrap;">View:</span>
        ${[['activity','Activity'],['resource','Resource'],['subsystem','Subsystem'],['location','Location']].map(([v,l]) => `
          <button class="admin-tab${_laTimelineGroupBy === v ? ' active' : ''}"
            style="font-size:12px;padding:6px 14px;"
            onclick="_laSetTimelineGroup('${v}')"
            ${_laAssignMode && v !== 'activity' ? 'disabled title="Exit assign mode to switch view"' : ''}>${l}</button>
        `).join('')}
      </div>
      <div style="display:flex;align-items:center;gap:0;">
        <span style="font-size:11px;color:var(--gray-500);margin-right:8px;white-space:nowrap;">Window:</span>
        ${[['14','2 wks'],['21','3 wks'],['28','4 wks'],['35','5 wks']].map(([v,l]) => `
          <button class="admin-tab${_laTimelineWindow === parseInt(v) ? ' active' : ''}" style="font-size:12px;padding:6px 14px;" onclick="_laSetTimelineWindow(${v})">${l}</button>
        `).join('')}
      </div>
      ${_laTimelineGroupBy === 'activity' ? `
      <div style="display:flex;align-items:center;gap:0;">
        <span style="font-size:11px;color:var(--gray-500);margin-right:8px;white-space:nowrap;">Sub-group:</span>
        ${[['none','None'],['phase','Phase'],['location','Location'],['phase_location','Phase + Loc']].map(([v,l]) => `
          <button class="admin-tab${_laActivitySubGroup === v ? ' active' : ''}"
            style="font-size:12px;padding:6px 14px;"
            onclick="_laSetActivitySubGroup('${v}')">${l}</button>
        `).join('')}
      </div>
      ` : ''}
      ${_laTimelineGroupBy === 'resource' ? `
      <div style="display:flex;align-items:center;gap:0;">
        <span style="font-size:11px;color:var(--gray-500);margin-right:8px;white-space:nowrap;">Resources:</span>
        ${[['all','All'],['Hitachi','Hitachi'],['BART','BART']].map(([v,l]) => `
          <button class="admin-tab${_laResCompanyFilter === v ? ' active' : ''}"
            style="font-size:12px;padding:6px 14px;"
            onclick="_laSetResCompanyFilter('${v}')">${l}</button>
        `).join('')}
      </div>
      ` : ''}
      <label style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--gray-600);cursor:pointer;">
        <input type="checkbox" ${_planningShowP6 ? 'checked' : ''} onchange="_planningTogglePO6Overlay(this.checked)">
        P6 baseline
      </label>
      <div class="la-row-search-wrap" style="display:flex;align-items:center;gap:6px;margin-left:auto;">
        <input id="la-row-search" type="text" placeholder="🔍 Filter activities…"
          value="${escapeHtml(_laRowSearch)}" oninput="_laSetRowSearch(this.value)"
          style="font-size:12px;padding:6px 10px;border:1px solid var(--gray-300);border-radius:6px;width:210px;">
        <button id="la-row-search-clear" onclick="_laSetRowSearch('')" title="Clear filter"
          style="display:${_laRowSearch ? 'inline-flex' : 'none'};font-size:12px;padding:6px 9px;border:1px solid var(--gray-300);background:#fff;border-radius:6px;cursor:pointer;">✕</button>
        <span id="la-row-search-count" style="font-size:11px;color:var(--gray-500);white-space:nowrap;"></span>
      </div>
      <button onclick="_laOpenNewActivityModal()" class="admin-action-btn" title="Add a new activity row to the lookahead">
        + Add Activity
      </button>
      <div style="position:relative;display:inline-block;">
        <button onclick="document.getElementById('la-export-menu').classList.toggle('open');event.stopPropagation();" class="admin-action-btn">
          📤 Export ▾
        </button>
        <div id="la-export-menu" class="la-export-menu">
          <button onclick="_laExportLookahead();document.getElementById('la-export-menu').classList.remove('open');">📅 4-Week Lookahead (.xlsx)</button>
          <button onclick="_laExportBARTResourceMap('xlsx');document.getElementById('la-export-menu').classList.remove('open');">🚧 BART Resource Map (.xlsx)</button>
          <button onclick="_laExportBARTResourceMap('csv');document.getElementById('la-export-menu').classList.remove('open');">📊 BART Resource Map (.csv)</button>
        </div>
      </div>
      <button onclick="_laToggleAssignMode()" class="admin-action-btn${_laAssignMode ? ' la-assign-btn-active' : ''}">
        ${_laAssignMode ? '✓ Done Assigning' : '👤 Assign Resources'}
      </button>
    </div>

    ${_laAssignMode ? `
    <div class="la-assign-banner" style="display:flex;align-items:center;justify-content:space-between;gap:12px;">
      <span>🟥 Drop on the <strong>activity label</strong> to assign for the full activity &nbsp;·&nbsp; 🟩 Drop on a <strong>coloured shift cell</strong> to assign to that specific day only &nbsp;·&nbsp; <strong>Click a colored cell</strong> to select it for bulk remove</span>
    </div>` : ''}

    <!-- Excel-style edit tips bar (always visible) -->
    <div class="la-edit-tips-bar" style="display:flex;align-items:center;gap:14px;padding:6px 12px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;font-size:11px;color:#475569;margin:8px 0;flex-wrap:wrap;">
      <strong style="color:#1e40af;">📋 Excel-style editing:</strong>
      <span><kbd>Ctrl</kbd>+click select</span>
      <span><kbd>Ctrl</kbd>+drag range-select</span>
      <span><kbd>Ctrl</kbd>+<kbd>C</kbd> copy</span>
      <span><kbd>Ctrl</kbd>+<kbd>X</kbd> cut</span>
      <span><kbd>Ctrl</kbd>+<kbd>V</kbd> paste</span>
      <span><kbd>Del</kbd> delete</span>
      <span><kbd>Esc</kbd> clear</span>
      <span style="color:#1e40af;">↔ drag a cell to move it</span>
      <span style="color:#0891b2;">↗ fill-handle to extend days</span>
      <span style="margin-left:auto;color:#64748b;">Right-click for menu</span>
    </div>

    <!-- Floating action banner — populated when cells are selected or clipboard has content -->
    <div id="la-cell-sel-actions" style="margin:6px 0;">${_laCellSelActionsHTML()}</div>

    <div class="la-grid-shell${_laDrawer.mode !== 'closed' ? ' la-drawer-open' : ''}" style="display:flex;gap:12px;align-items:flex-start;">
      ${_laAssignMode ? _laResourcePanelHTML() : ''}
      <div class="la-grid-col" style="flex:1;min-width:0;">
        <div class="data-card" style="padding:0;overflow:hidden;">
          <div id="lookahead-timeline"></div>
        </div>
      </div>
      <aside id="la-drawer" class="la-drawer${_laDrawer.mode === 'closed' ? ' la-drawer-closed' : ''}">
        ${_laDrawerHTML()}
      </aside>
    </div>`;
}

function _laToggleAssignMode() {
  _laAssignMode = !_laAssignMode;
  if (_laAssignMode) {
    // Force activity group-by when entering assign mode
    _laTimelineGroupBy = 'activity';
  } else {
    // Clear all selection state when exiting assign mode
    _laSelectedResIds.clear();
    _laSelectedCellKeys.clear();
  }
  _renderLookaheadTabBody();
}

// ============================================================
// GRID SEARCH — live filter of lookahead activity rows
// ============================================================
function _laSetRowSearch(v) {
  _laRowSearch = (v || '').trim();
  const inp = document.getElementById('la-row-search');
  if (inp && inp.value !== _laRowSearch) inp.value = _laRowSearch;
  const clr = document.getElementById('la-row-search-clear');
  if (clr) clr.style.display = _laRowSearch ? 'inline-flex' : 'none';
  _laApplyRowSearch();
}

// Filters mounted grid rows by activity label/sublabel. Hides non-matching
// data rows and any section header that ends up with no visible rows.
function _laApplyRowSearch() {
  const root = document.getElementById('lookahead-timeline');
  if (!root) return;
  const q = _laRowSearch.toLowerCase();
  const HDR = 'tlg-grp-hdr-row tlg-subgrp-hdr-row tlg-loc-hdr-row tlg-p6-hdr-row'.split(' ');
  const isHdr = el => HDR.some(c => el.classList.contains(c));
  const dataRows = [...root.querySelectorAll('.tlg-row.tlg-data-row')];
  let shown = 0, total = 0;

  dataRows.forEach(row => {
    const lbl = row.querySelector('.tlg-row-label');
    const txt = (lbl ? lbl.textContent : '').toLowerCase();
    total++;
    const match = !q || txt.indexOf(q) !== -1;
    row.style.display = match ? '' : 'none';
    if (match) shown++;
  });

  // Header visibility: a header is shown if any data row before the next
  // header (of equal-or-broader scope) is visible. Two passes keeps the
  // group → sub-group → row hierarchy sane without rebuilding the grid.
  const allRows = [...root.querySelectorAll('.tlg-row')];
  const headerVisible = hdr => {
    const cls = HDR.find(c => hdr.classList.contains(c));
    const broad = cls === 'tlg-grp-hdr-row';
    let i = allRows.indexOf(hdr) + 1;
    for (; i < allRows.length; i++) {
      const r = allRows[i];
      if (isHdr(r)) {
        // Stop at next group header; for sub/loc headers stop at any header
        if (broad ? r.classList.contains('tlg-grp-hdr-row') : true) {
          if (broad && (r.classList.contains('tlg-subgrp-hdr-row') || r.classList.contains('tlg-loc-hdr-row'))) {
            if (r.style.display !== 'none') return true; // group keeps a visible sub-header
            continue;
          }
          break;
        }
      }
      if (r.classList.contains('tlg-data-row') && r.style.display !== 'none') return true;
    }
    return false;
  };
  // Pass 1: sub-group / location / p6 headers
  allRows.filter(r => r.classList.contains('tlg-subgrp-hdr-row') || r.classList.contains('tlg-loc-hdr-row') || r.classList.contains('tlg-p6-hdr-row'))
    .forEach(h => { h.style.display = (!q || headerVisible(h)) ? '' : 'none'; });
  // Pass 2: top-level group headers (after sub-headers resolved)
  allRows.filter(r => r.classList.contains('tlg-grp-hdr-row'))
    .forEach(h => { h.style.display = (!q || headerVisible(h)) ? '' : 'none'; });

  const cnt = document.getElementById('la-row-search-count');
  if (cnt) cnt.textContent = q ? `${shown} of ${total}` : '';
}

// ============================================================
// SELECTION CHROME — dim unselected cells when a selection is active
// ============================================================
function _laUpdateSelectionChrome() {
  const root = document.getElementById('lookahead-timeline');
  if (root) root.classList.toggle('la-has-selection', _laSelectedCellKeys.size > 0);
}

// ============================================================
// UNDO TOAST — actionable toast with an Undo button
// ============================================================
function _laToastUndo(msg, undoFn) {
  _laPendingUndo = { fn: undoFn };
  const el = document.createElement('div');
  el.className = 'toast success la-toast-undo';
  el.innerHTML = `<div class="icon">✓</div><div>${escapeHtml(msg)}</div>` +
    `<button class="la-toast-undo-btn">↩ Undo</button>`;
  el.querySelector('.la-toast-undo-btn').onclick = async () => {
    el.remove();
    const u = _laPendingUndo; _laPendingUndo = null;
    if (u && u.fn) { try { await u.fn(); } catch (e) { toast('Undo failed: ' + e.message, 'error'); } }
  };
  document.body.appendChild(el);
  setTimeout(() => { el.style.opacity = '0'; el.style.transform = 'translateY(20px)'; el.style.transition = 'all 0.3s'; }, 7500);
  setTimeout(() => el.remove(), 8000);
}

async function _laUndoDelete(snap) {
  if (!snap || !snap.events?.length) return;
  await _dbInsert('planning_events', snap.events);
  if (snap.resources?.length) await _dbInsert('planning_event_resources', snap.resources);
  toast(`↩ Restored ${snap.events.length} event${snap.events.length > 1 ? 's' : ''}`, 'success');
  await loadPlanningData(true);
  _renderLookaheadTabBody();
}

// ============================================================
// BULK EDIT — apply shift / location to all selected cells
// ============================================================
async function _laBulkSetShift(code) {
  if (!code) return;
  if (_laSelectedCellKeys.size === 0) { toast('No cells selected.', 'warn'); return; }
  const ids = [..._laSelectedCellKeys];
  const events = PLANNING_EVENTS.filter(e => ids.includes(e.id) && !e.is_locked);
  if (!events.length) { toast('All selected cells are locked.', 'warn'); return; }
  const labels = { day_shift: 'Day', swing_shift: 'Swing', night_shift: 'Night', blanket_shift: 'Blanket' };
  if (!confirm(`Set shift to "${labels[code] || code}" for ${events.length} cell${events.length > 1 ? 's' : ''}?`)) return;
  let n = 0;
  for (const e of events) {
    try {
      await _dbUpdate('planning_events',
        { shift_type: code, version: (e.version || 1) + 1, updated_by: currentProfile?.id || null },
        { id: e.id });
      n++;
    } catch (err) { console.error('[bulk-shift] failed for', e.id, err); }
  }
  toast(`✓ Updated shift on ${n} cell${n > 1 ? 's' : ''}`, 'success');
  await loadPlanningData(true);
  _renderLookaheadTabBody();
}

async function _laBulkSetLocation() {
  if (_laSelectedCellKeys.size === 0) { toast('No cells selected.', 'warn'); return; }
  const inp = document.getElementById('la-bulk-loc');
  const loc = (inp?.value || '').trim();
  if (!loc) { toast('Enter a location first.', 'warn'); return; }
  const ids = [..._laSelectedCellKeys];
  const events = PLANNING_EVENTS.filter(e => ids.includes(e.id) && !e.is_locked);
  if (!events.length) { toast('All selected cells are locked.', 'warn'); return; }
  if (!confirm(`Set location to "${loc}" for ${events.length} cell${events.length > 1 ? 's' : ''}?`)) return;
  let n = 0;
  for (const e of events) {
    try {
      await _dbUpdate('planning_events',
        { location: loc, version: (e.version || 1) + 1, updated_by: currentProfile?.id || null },
        { id: e.id });
      n++;
    } catch (err) { console.error('[bulk-loc] failed for', e.id, err); }
  }
  toast(`✓ Updated location on ${n} cell${n > 1 ? 's' : ''}`, 'success');
  await loadPlanningData(true);
  _renderLookaheadTabBody();
}

async function _laBulkSetHours() {
  if (_laSelectedCellKeys.size === 0) { toast('No cells selected.', 'warn'); return; }
  const inp = document.getElementById('la-bulk-hours');
  const raw = (inp?.value || '').trim();
  if (!raw) { toast('Enter work hours first, e.g. 0700-1500.', 'warn'); return; }
  const { start, end, shift_type } = _laInferShiftFromHours(raw);
  if (!start) { toast('Could not parse hours. Use military format like 0700-1500.', 'warn'); return; }
  const ids = [..._laSelectedCellKeys];
  const events = PLANNING_EVENTS.filter(e => ids.includes(e.id) && !e.is_locked);
  if (!events.length) { toast('All selected cells are locked.', 'warn'); return; }
  if (!confirm(`Set work hours to "${raw}" for ${events.length} cell${events.length > 1 ? 's' : ''}?`)) return;
  let n = 0;
  for (const e of events) {
    try {
      await _dbUpdate('planning_events',
        { start_time: start, end_time: end || null, shift_type,
          all_day: false, version: (e.version || 1) + 1, updated_by: currentProfile?.id || null },
        { id: e.id });
      n++;
    } catch (err) { console.error('[bulk-hours] failed for', e.id, err); }
  }
  toast(`✓ Updated work hours on ${n} cell${n > 1 ? 's' : ''}`, 'success');
  await loadPlanningData(true);
  _renderLookaheadTabBody();
}

// ============================================================
// EDIT DRAWER — Phase 2/3/4 master-schedule editing surface
// ============================================================

function _laDrawerOpen(mode, targetId) {
  if (_laDrawer.dirty && !confirm('Discard unsaved changes?')) return;
  _laDrawer.mode        = mode;
  _laDrawer.targetId    = targetId || null;
  _laDrawer.dirty       = false;
  _laDrawer.snapshot    = null;
  _laDrawer.baseVersion = null;

  // Snapshot the target so save/diff/revert works
  if (mode === 'cell') {
    const ev = PLANNING_EVENTS.find(e => e.id === targetId);
    if (ev) {
      _laDrawer.snapshot    = { ...ev };
      _laDrawer.baseVersion = ev.version || 1;
    }
  } else if (mode === 'activity') {
    const a = PLANNING_ACTIVITIES.find(x => x.id === targetId);
    if (a) _laDrawer.snapshot = { ...a };
  }
  _renderLookaheadTabBody();
}

function _laDrawerClose() {
  if (_laDrawer.dirty && !confirm('Discard unsaved changes?')) return;
  _laDrawer.mode        = 'closed';
  _laDrawer.targetId    = null;
  _laDrawer.snapshot    = null;
  _laDrawer.dirty       = false;
  _laDrawer.baseVersion = null;
  _renderLookaheadTabBody();
}

// Called on location input change: auto-infer phase from master LOCS hierarchy
// and show a hint (or auto-fill if phase field is empty).
function _laDrawerLocationChanged() {
  _laDrawerMarkDirty();
  const locVal   = document.getElementById('dw-act-loc')?.value?.trim() || '';
  const phaseEl  = document.getElementById('dw-act-phase');
  const hintEl   = document.getElementById('dw-loc-phase-hint');
  if (!phaseEl || !hintEl) return;

  const inferred = _laInferPhaseFromLocation(locVal);
  const current  = phaseEl.value.trim();

  if (!inferred) {
    hintEl.innerHTML = locVal
      ? `<span style="color:var(--gray-400);">Ad-hoc location — set phase manually</span>`
      : '';
    return;
  }

  if (!current) {
    // Phase empty → auto-fill silently
    phaseEl.value = inferred;
    _laDrawerMarkDirty();
    hintEl.innerHTML = `<span style="color:var(--good);">✓ Phase auto-set from master location</span>`;
  } else if (current === inferred) {
    hintEl.innerHTML = `<span style="color:var(--good);">✓ Matches master location</span>`;
  } else {
    hintEl.innerHTML = `<span>Master suggests: <strong>${escapeHtml(inferred)}</strong></span>
      <button type="button" class="form-secondary" style="font-size:10px;padding:1px 6px;margin-left:6px;"
        onclick="document.getElementById('dw-act-phase').value=${JSON.stringify(inferred)};_laDrawerMarkDirty();document.getElementById('dw-loc-phase-hint').innerHTML='<span style=\\'color:var(--good);\\'>✓ Accepted<\\/span>';">Use</button>`;
  }
}

function _laDrawerMarkDirty() {
  if (!_laDrawer.dirty) {
    _laDrawer.dirty = true;
    // Just toggle the save button enabled state — don't re-render the whole drawer
    const btn = document.getElementById('la-drawer-save');
    if (btn) { btn.disabled = false; btn.classList.add('la-drawer-save-dirty'); }
    const ind = document.getElementById('la-drawer-dirty-ind');
    if (ind) ind.style.display = 'inline';
  }
}

function _laDrawerHTML() {
  // Routes to the mode-specific renderer. Always wraps in a consistent shell
  // (header bar + close button + footer with save).
  if (_laDrawer.mode === 'closed') return '';
  let title = '', body = '', footer = '';
  if (_laDrawer.mode === 'cell') {
    const ev = PLANNING_EVENTS.find(e => e.id === _laDrawer.targetId);
    if (!ev) { _laDrawer.mode = 'closed'; return ''; }
    title  = '📅 Event details';
    body   = _laDrawerCellHTML(ev);
    footer = _laDrawerCellFooterHTML(ev);
  } else if (_laDrawer.mode === 'activity') {
    const a = PLANNING_ACTIVITIES.find(x => x.id === _laDrawer.targetId);
    if (!a) { _laDrawer.mode = 'closed'; return ''; }
    title  = '📋 Activity details';
    body   = _laDrawerActivityHTML(a);
    footer = _laDrawerActivityFooterHTML(a);
  } else if (_laDrawer.mode === 'multi') {
    const n = _laSelectedCellKeys.size;
    title  = `✏️ Bulk edit (${n} cell${n>1?'s':''})`;
    body   = _laDrawerMultiHTML([..._laSelectedCellKeys]);
    footer = `<button class="form-secondary" onclick="_laDrawerClose()">Close</button>`;
  }

  return `
    <div class="la-drawer-head">
      <div class="la-drawer-title">${title}
        <span id="la-drawer-dirty-ind" style="display:none;color:#dc2626;font-size:11px;font-weight:700;margin-left:8px;">● unsaved</span>
      </div>
      <button class="la-drawer-close" onclick="_laDrawerClose()" title="Close (Esc)">✕</button>
    </div>
    <div class="la-drawer-body">${body}</div>
    <div class="la-drawer-foot">${footer}</div>
  `;
}

// ─── CELL MODE: edit a single event ─────────────────────────
function _laDrawerCellHTML(ev) {
  const act    = PLANNING_ACTIVITIES.find(a => a.id === ev.planning_activity_id);
  const shifts = (window.SHIFT_TEMPLATES || []).filter(s => s.active !== false);
  const isCancel = ev.status === 'cancelled';

  // Resource pickers — split by company
  const allRes      = (PLANNING_RESOURCES || []).filter(r => r.is_active);
  const hitachiRes  = allRes.filter(r => (r.kind === 'person' || !r.kind) && r.company !== 'BART');
  const bartRoles   = allRes.filter(r => r.kind === 'role'   && r.is_requestable);
  const eventResRows = (PLANNING_EVENT_RES || []).filter(er => er.event_id === ev.id);
  const assignedHitachi = eventResRows.filter(er => {
    const r = allRes.find(x => x.id === er.resource_id);
    return r && r.company !== 'BART';
  });
  const requestedBart = eventResRows.filter(er => {
    const r = allRes.find(x => x.id === er.resource_id);
    return r && r.company === 'BART';
  });

  return `
    <div class="la-drawer-section">
      <div class="la-drawer-row">
        <span style="font-size:11px;color:var(--gray-500);text-transform:uppercase;letter-spacing:.04em;">Activity</span>
        <div style="font-size:13px;font-weight:600;color:#111;">${escapeHtml(act?.description || act?.activity_id_text || '—')}</div>
      </div>
    </div>

    <div class="la-drawer-section">
      <label class="la-drawer-label">Title</label>
      <input class="la-drawer-input" id="dw-cell-title" value="${escapeHtml(ev.title || '')}" oninput="_laDrawerMarkDirty()">
    </div>

    <div class="la-drawer-section la-drawer-row-2">
      <div>
        <label class="la-drawer-label">Date</label>
        <input class="la-drawer-input" type="date" id="dw-cell-date" value="${ev.event_date}" onchange="_laDrawerMarkDirty()">
      </div>
      <div>
        <label class="la-drawer-label">Shift</label>
        <select class="la-drawer-input" id="dw-cell-shift" onchange="_laDrawerMarkDirty()">
          <option value="">—</option>
          <option value="day_shift"     ${ev.shift_type==='day_shift'?'selected':''}>\u2600 Day</option>
          <option value="swing_shift"   ${ev.shift_type==='swing_shift'?'selected':''}>\u2194 Swing</option>
          <option value="night_shift"   ${ev.shift_type==='night_shift'?'selected':''}>\u263e Night</option>
          <option value="blanket_shift" ${ev.shift_type==='blanket_shift'?'selected':''}>\u25a0 Blanket</option>
        </select>
      </div>
    </div>

    <div class="la-drawer-section">
      <label class="la-drawer-label">Work hours <span style="font-size:9px;font-weight:400;color:var(--gray-400);">0700-1500 · auto-sets shift</span></label>
      <input class="la-drawer-input" id="dw-cell-hours"
        value="${ev.start_time && ev.end_time ? ev.start_time.replace(':','').slice(0,4)+'-'+ev.end_time.replace(':','').slice(0,4) : ev.start_time ? ev.start_time.replace(':','').slice(0,4) : ''}"
        placeholder="0700-1500" oninput="_laDrawerCellHoursChanged()">
    </div>
    <div class="la-drawer-section la-drawer-row-2">
      <div>
        <label class="la-drawer-label">Start time</label>
        <input class="la-drawer-input" type="time" id="dw-cell-start" value="${ev.start_time || ''}" onchange="_laDrawerMarkDirty()">
      </div>
      <div>
        <label class="la-drawer-label">End time</label>
        <input class="la-drawer-input" type="time" id="dw-cell-end" value="${ev.end_time || ''}" onchange="_laDrawerMarkDirty()">
      </div>
    </div>

    <div class="la-drawer-section">
      <label class="la-drawer-label">Location</label>
      <input class="la-drawer-input" id="dw-cell-loc" value="${escapeHtml(ev.location || '')}" oninput="_laDrawerMarkDirty()">
    </div>

    <div class="la-drawer-section">
      <label class="la-drawer-label">Notes</label>
      <textarea class="la-drawer-input" id="dw-cell-notes" rows="3" oninput="_laDrawerMarkDirty()">${escapeHtml(ev.notes || '')}</textarea>
    </div>

    <div class="la-drawer-section">
      <label class="la-drawer-label">Hitachi resources <span style="font-weight:400;color:var(--gray-400);">(${assignedHitachi.length})</span></label>
      <div class="la-drawer-pills">
        ${assignedHitachi.map(er => {
          const r = allRes.find(x => x.id === er.resource_id);
          return `<span class="la-drawer-pill">${escapeHtml(r?.display_name||'?')}
            <button onclick="_laDrawerRemoveEventResource('${er.id}')" title="Remove">×</button></span>`;
        }).join('') || '<span style="color:var(--gray-400);font-size:12px;">None assigned</span>'}
      </div>
      <select class="la-drawer-input" onchange="if(this.value){_laDrawerAddEventResource('${ev.id}',this.value,1);this.value='';}" style="margin-top:6px;">
        <option value="">+ Add Hitachi person…</option>
        ${hitachiRes
          .filter(r => !assignedHitachi.some(er => er.resource_id === r.id))
          .map(r => `<option value="${r.id}">${escapeHtml(r.display_name)}</option>`).join('')}
      </select>
    </div>

    <div class="la-drawer-section">
      <label class="la-drawer-label">BART requests <span style="font-weight:400;color:var(--gray-400);">(${requestedBart.length})</span></label>
      <div class="la-drawer-pills">
        ${requestedBart.map(er => {
          const r = allRes.find(x => x.id === er.resource_id);
          const denied = !!er.denied_at;
          return `<span class="la-drawer-pill ${denied?'la-drawer-pill-denied':''}">${escapeHtml(r?.display_name||'?')} ×${er.quantity||1}
            ${denied ? `<span title="Denied" style="color:#dc2626;">⚠</span>` : ''}
            <button onclick="_laDrawerRemoveEventResource('${er.id}')" title="Remove">×</button></span>`;
        }).join('') || '<span style="color:var(--gray-400);font-size:12px;">None requested</span>'}
      </div>
      <div style="display:flex;gap:6px;margin-top:6px;">
        <select class="la-drawer-input" id="dw-bart-pick" style="flex:1;">
          <option value="">+ Request BART role…</option>
          ${bartRoles.map(r => `<option value="${r.id}">${escapeHtml(r.display_name)}</option>`).join('')}
        </select>
        <input class="la-drawer-input" type="number" id="dw-bart-qty" value="1" min="1" max="50" style="width:60px;" title="Quantity">
        <button class="form-secondary" style="font-size:11px;" onclick="
          const id=document.getElementById('dw-bart-pick').value;
          const q=parseInt(document.getElementById('dw-bart-qty').value)||1;
          if(id){_laDrawerAddEventResource('${ev.id}',id,q);document.getElementById('dw-bart-pick').value='';}
        ">Add</button>
      </div>
    </div>

    ${isCancel ? `
    <div class="la-drawer-section" style="background:#fef2f2;border-left:3px solid #dc2626;padding:8px 10px;border-radius:4px;">
      <div style="font-size:11px;font-weight:700;color:#7f1d1d;">🚫 CANCELLED</div>
      ${ev.cancellation_category ? `<div style="font-size:12px;margin-top:3px;"><strong>Category:</strong> ${escapeHtml(ev.cancellation_category)}</div>` : ''}
      ${ev.cancellation_reason ? `<div style="font-size:12px;margin-top:3px;"><strong>Reason:</strong> ${escapeHtml(ev.cancellation_reason)}</div>` : ''}
      ${ev.cancellation_responsible_party ? `<div style="font-size:12px;margin-top:3px;"><strong>Responsible:</strong> ${escapeHtml(ev.cancellation_responsible_party)}</div>` : ''}
    </div>` : ''}

    <div style="font-size:10px;color:var(--gray-400);margin-top:14px;padding-top:8px;border-top:1px dashed var(--gray-200);">
      Event v${ev.version || 1} · updated ${ev.updated_at ? dayjs(ev.updated_at).format('YYYY-MM-DD HH:mm') : '—'}
    </div>
  `;
}

function _laDrawerCellFooterHTML(ev) {
  const isCancel = ev.status === 'cancelled';
  return `
    <button class="form-secondary" onclick="_laDrawerClose()">Close</button>
    ${ev.is_locked
      ? `<button class="form-secondary" onclick="_planningToggleLock('${ev.id}')">🔓 Unlock</button>`
      : `<button class="form-secondary" onclick="_planningToggleLock('${ev.id}')">🔒 Lock</button>`}
    ${!isCancel
      ? `<button class="form-secondary" style="color:#dc2626;" onclick="_planningCancelEvent('${ev.id}')">🚫 Cancel</button>`
      : ''}
    <button class="form-submit la-drawer-save" id="la-drawer-save" disabled onclick="_laDrawerSave()">💾 Save</button>
  `;
}

// ─── ACTIVITY MODE: edit a whole activity row ───────────────
function _laDrawerActivityHTML(a) {
  const grp     = a.activity_group || 'other';
  const evs     = (PLANNING_EVENTS || []).filter(e => e.planning_activity_id === a.id);
  const eventCount = evs.length;
  const cancelledCount = evs.filter(e => e.status === 'cancelled').length;

  // Auto-derive phase from master location hierarchy if phase not yet set
  const inferredPhase  = _laInferPhaseFromLocation(a.location);
  const storedPhase    = (a.phase || '').trim();
  const effectivePhase = storedPhase || inferredPhase || '';

  return `
    <div class="la-drawer-section">
      <label class="la-drawer-label">Description</label>
      <textarea class="la-drawer-input" id="dw-act-desc" rows="2" oninput="_laDrawerMarkDirty()">${escapeHtml(a.description || '')}</textarea>
    </div>

    <div class="la-drawer-section la-drawer-row-2">
      <div>
        <label class="la-drawer-label">Activity ID / Ref</label>
        <input class="la-drawer-input" id="dw-act-idtext" value="${escapeHtml(a.activity_id_text || '')}" oninput="_laDrawerMarkDirty()">
      </div>
      <div>
        <label class="la-drawer-label">Group</label>
        <select class="la-drawer-input" id="dw-act-group" onchange="_laDrawerMarkDirty()">
          ${_GROUP_ORDER.map(g => `<option value="${g}" ${grp === g ? 'selected' : ''}>${_groupMeta(g).label}</option>`).join('')}
        </select>
      </div>
    </div>

    <div class="la-drawer-section la-drawer-row-2">
      <div>
        <label class="la-drawer-label">Phase${!storedPhase && inferredPhase ? ' <span style="font-size:9px;color:var(--good);font-weight:400;">(from location)</span>' : ''}</label>
        <input class="la-drawer-input" id="dw-act-phase" value="${escapeHtml(effectivePhase)}" placeholder="e.g. Phase 1" oninput="_laDrawerMarkDirty()" list="dw-act-phase-options">
        <datalist id="dw-act-phase-options">
          ${_fsOptions('lookahead_phase').map(o => `<option value="${escapeHtml(o)}">`).join('')}
        </datalist>
      </div>
      <div>
        <label class="la-drawer-label">SSWP</label>
        <input class="la-drawer-input" id="dw-act-sswp" value="${escapeHtml(a.sswp || '')}" oninput="_laDrawerMarkDirty()">
      </div>
    </div>

    <div class="la-drawer-section la-drawer-row-2">
      <div>
        <label class="la-drawer-label">Discipline <span style="font-size:9px;color:var(--gray-400);font-weight:400;">(grouping)</span></label>
        <input class="la-drawer-input" id="dw-act-discipline" value="${escapeHtml(a.discipline || '')}" placeholder="T&amp;C" oninput="_laDrawerMarkDirty()" list="dw-act-disc-options">
        <datalist id="dw-act-disc-options">
          ${_fsOptions('lookahead_discipline').map(o => `<option value="${escapeHtml(o)}">`).join('')}
        </datalist>
      </div>
      <div>
        <label class="la-drawer-label">Trade <span style="font-size:9px;color:var(--gray-400);font-weight:400;">(chip)</span></label>
        <input class="la-drawer-input" id="dw-act-trade" value="${escapeHtml(a.trade || '')}" placeholder="CBTC" oninput="_laDrawerMarkDirty()" list="dw-act-trade-options">
        <datalist id="dw-act-trade-options">
          ${_fsOptions('lookahead_trade').map(o => `<option value="${escapeHtml(o)}">`).join('')}
        </datalist>
      </div>
    </div>

    <div class="la-drawer-section">
      <label class="la-drawer-label">Location${(() => { const resolved = _laResolveLocationPrefix(a.location); return resolved && resolved !== (a.location||'').trim() ? ` <span style="font-size:10px;color:var(--gray-400);font-weight:400;">→ ${escapeHtml(resolved)}</span>` : ''; })()}</label>
      <input class="la-drawer-input" id="dw-act-loc" value="${escapeHtml(a.location || '')}" placeholder="e.g. W40" oninput="_laDrawerLocationChanged()">
      <div id="dw-loc-phase-hint" style="font-size:10px;margin-top:3px;">${(() => {
        if (!inferredPhase && a.location) return `<span style="color:var(--gray-400);">Ad-hoc location — set phase manually</span>`;
        if (!inferredPhase) return '';
        if (!storedPhase)   return `<span style="color:var(--good);">✓ Phase auto-set from master location</span>`;
        if (storedPhase === inferredPhase) return `<span style="color:var(--good);">✓ Matches master location</span>`;
        return `<span>Master suggests: <strong>${escapeHtml(inferredPhase)}</strong></span>
          <button type="button" class="form-secondary" style="font-size:10px;padding:1px 6px;margin-left:6px;"
            onclick="document.getElementById('dw-act-phase').value=${JSON.stringify(inferredPhase)};_laDrawerMarkDirty();document.getElementById('dw-loc-phase-hint').innerHTML='<span style=\\'color:var(--good);\\'>✓ Accepted<\\/span>';">Use</button>`;
      })()}</div>
    </div>

    <div class="la-drawer-section">
      <label class="la-drawer-label">Work hours / window</label>
      <input class="la-drawer-input" id="dw-act-hours" value="${escapeHtml(a.work_hours_raw || '')}" oninput="_laDrawerMarkDirty()">
    </div>

    <div class="la-drawer-section">
      <label class="la-drawer-label">Party to Action <span style="font-size:9px;color:var(--gray-400);font-weight:400;">(select all that apply)</span></label>
      <div class="dw-party-grid">
        ${_PARTY_TO_ACTION_OPTS.map(([val, lbl]) => {
          const on = Array.isArray(a.party_to_action) && a.party_to_action.includes(val);
          return `<label class="dw-party-chip${on ? ' on' : ''}">
            <input type="checkbox" class="dw-act-party" value="${val}" ${on ? 'checked' : ''}
              onchange="this.closest('.dw-party-chip').classList.toggle('on',this.checked);_laDrawerMarkDirty();">
            <span>${escapeHtml(lbl)}</span>
          </label>`;
        }).join('')}
      </div>
    </div>

    <div class="la-drawer-section">
      <label class="la-drawer-label">Notes</label>
      <textarea class="la-drawer-input" id="dw-act-notes" rows="3" oninput="_laDrawerMarkDirty()">${escapeHtml(a.notes || '')}</textarea>
    </div>

    <div class="la-drawer-section">
      <label class="la-drawer-label">Linked Test Register activity</label>
      <input class="la-drawer-input" id="dw-act-linked-tra" value="${escapeHtml(a.linked_test_register_activity || '')}" oninput="_laDrawerMarkDirty()" list="dw-act-tra-options">
      <datalist id="dw-act-tra-options">
        ${[...new Set((TI || []).map(t => t.Activity).filter(Boolean))].sort().slice(0, 200).map(t => `<option value="${escapeHtml(t)}">`).join('')}
      </datalist>
    </div>

    <div class="la-drawer-section" style="background:#f8fafc;padding:8px 10px;border-radius:4px;">
      <div style="font-size:11px;color:var(--gray-500);">
        ${eventCount} event${eventCount !== 1 ? 's' : ''}${cancelledCount ? ` · ${cancelledCount} cancelled` : ''}
      </div>
    </div>

    <div style="font-size:10px;color:var(--gray-400);margin-top:14px;padding-top:8px;border-top:1px dashed var(--gray-200);">
      Activity · sort_order=${a.sort_order ?? '—'} · created ${a.created_at ? dayjs(a.created_at).format('YYYY-MM-DD') : '—'}
    </div>
  `;
}

function _laDrawerActivityFooterHTML(a) {
  return `
    <button class="form-secondary" onclick="_laDrawerClose()">Close</button>
    <button class="form-secondary" style="color:#dc2626;border-color:#fca5a5;" onclick="_laDrawerSoftDeleteActivity('${a.id}')" title="Soft-delete: hidden from grid but restorable">🗑 Delete</button>
    <button class="form-submit la-drawer-save" id="la-drawer-save" disabled onclick="_laDrawerSave()">💾 Save</button>
  `;
}

// ─── MULTI MODE: bulk-edit the current selection ─────────────
function _laDrawerMultiHTML(eventIds) {
  const events = (PLANNING_EVENTS || []).filter(e => eventIds.includes(e.id));
  const locked = events.filter(e => e.is_locked).length;
  const cancelled = events.filter(e => e.status === 'cancelled').length;
  const editable = events.length - locked - cancelled;
  return `
    <div class="la-drawer-section" style="background:#f8fafc;padding:10px;border-radius:4px;">
      <div style="font-size:13px;font-weight:600;">${events.length} cell${events.length>1?'s':''} selected</div>
      <div style="font-size:11px;color:var(--gray-500);margin-top:3px;">
        ${editable} editable${locked ? ` · ${locked} locked` : ''}${cancelled ? ` · ${cancelled} already cancelled` : ''}
      </div>
    </div>
    <div class="la-drawer-section">
      <div style="font-size:12px;font-weight:600;margin-bottom:6px;">Bulk actions</div>
      <div style="display:flex;flex-direction:column;gap:6px;">
        <button class="form-secondary" onclick="_laBulkCancelCells()">🚫 Cancel all (with reason)</button>
        <button class="form-secondary" onclick="_laDeleteSelection()" style="color:#dc2626;">🗑 Delete all</button>
        <button class="form-secondary" onclick="_laBulkRemoveCellResources()">👥 Remove users only</button>
        <button class="form-secondary" onclick="_laCopySelection('copy')">📋 Copy</button>
        <button class="form-secondary" onclick="_laCopySelection('cut')">✂ Cut</button>
        <button class="form-secondary" onclick="_laClearCellSelection();_laDrawerClose();">✕ Clear selection</button>
      </div>
    </div>
    <div class="la-drawer-section" style="font-size:11px;color:var(--gray-400);">
      Tip: Ctrl+drag to range-select · drag a cell to move it · right-click for more.
    </div>
  `;
}

// ─── Drawer save with optimistic concurrency ────────────────
// Phase 2D: read every editable field from the drawer, build a payload,
// then UPDATE WHERE id=? AND version=? — if 0 rows affected, somebody else
// beat us and we surface a clear "stale" warning instead of silently
// overwriting their change.
async function _laDrawerSave() {
  if (_laDrawer.mode === 'cell') {
    const ev = PLANNING_EVENTS.find(e => e.id === _laDrawer.targetId);
    if (!ev) return;
    const shiftCode = document.getElementById('dw-cell-shift')?.value || '';
    // shift_type is stored directly (day_shift, swing_shift, night_shift, blanket_shift)
    const shiftTypeFromCode = shiftCode || null;

    const payload = {
      title:       document.getElementById('dw-cell-title')?.value?.trim() || '(untitled)',
      event_date:  document.getElementById('dw-cell-date')?.value,
      start_time:  document.getElementById('dw-cell-start')?.value || null,
      end_time:    document.getElementById('dw-cell-end')?.value   || null,
      shift_type:  shiftTypeFromCode,
      location:    document.getElementById('dw-cell-loc')?.value?.trim() || null,
      notes:       document.getElementById('dw-cell-notes')?.value || null,
      version:     (_laDrawer.baseVersion || 1) + 1,
      updated_by:  currentProfile?.id || null,
    };

    try {
      // Optimistic concurrency: WHERE id=? AND version=? — if 0 rows updated,
      // someone else beat us to it. _dbUpdate returns the updated rows.
      const result = await _dbUpdate('planning_events', payload, {
        id:      ev.id,
        version: _laDrawer.baseVersion || 1,
      });
      if (!result || result.length === 0) {
        toast('⚠ Someone else edited this cell. Reloading…', 'error');
        await loadPlanningData(true);
        _laDrawerOpen('cell', ev.id);   // re-open with fresh data
        return;
      }
      _laDrawer.dirty       = false;
      _laDrawer.baseVersion = payload.version;
      toast('✓ Saved', 'success');
      await loadPlanningData(true);
      _renderLookaheadTabBody();
    } catch (err) {
      toast('Save failed: ' + err.message, 'error');
    }
    return;
  }

  if (_laDrawer.mode === 'activity') {
    const a = PLANNING_ACTIVITIES.find(x => x.id === _laDrawer.targetId);
    if (!a) return;
    const discInput  = document.getElementById('dw-act-discipline')?.value?.trim() || null;
    const tradeInput = document.getElementById('dw-act-trade')?.value?.trim() || null;
    const payload = {
      description:                  document.getElementById('dw-act-desc')?.value?.trim() || null,
      activity_id_text:             document.getElementById('dw-act-idtext')?.value?.trim() || null,
      activity_group:               document.getElementById('dw-act-group')?.value || 'other',
      phase:                        document.getElementById('dw-act-phase')?.value?.trim() || null,
      location:                     document.getElementById('dw-act-loc')?.value?.trim() || null,
      sswp:                         document.getElementById('dw-act-sswp')?.value?.trim() || null,
      work_hours_raw:               document.getElementById('dw-act-hours')?.value?.trim() || null,
      party_to_action:              [...document.querySelectorAll('.dw-act-party:checked')].map(c => c.value),
      notes:                        document.getElementById('dw-act-notes')?.value || null,
      linked_test_register_activity: document.getElementById('dw-act-linked-tra')?.value?.trim() || null,
      discipline:                   discInput,
      trade:                        tradeInput,
    };
    try {
      await _dbUpdate('planning_activities', payload, { id: a.id });
      // Auto-grow Field Config vocabularies for newly typed values
      try {
        const promises = [];
        if (discInput)  promises.push(_fscEnsureOptions('lookahead_discipline', [discInput]));
        if (tradeInput) promises.push(_fscEnsureOptions('lookahead_trade',      [tradeInput]));
        const phaseVal = document.getElementById('dw-act-phase')?.value?.trim();
        if (phaseVal)   promises.push(_fscEnsureOptions('lookahead_phase',      [phaseVal]));
        await Promise.all(promises);
      } catch (e) { /* best-effort — don't block the save */ }
      _laDrawer.dirty = false;
      toast('✓ Activity saved', 'success');
      await loadPlanningData(true);
      _renderLookaheadTabBody();
    } catch (err) {
      toast('Save failed: ' + err.message, 'error');
    }
  }
}

// ─── Drawer resource pickers ────────────────────────────────
async function _laDrawerAddEventResource(eventId, resourceId, quantity = 1) {
  const _ev = (PLANNING_EVENTS || []).find(e => e.id === eventId);
  // Real-time conflict gate (PTO + double-booking) before committing
  const _gate = _ev ? await _laConflictGate(resourceId, [_ev]) : { proceed: true, conflicts: [] };
  if (!_gate.proceed) { toast('Assignment cancelled — adjust the allocation.', 'warn'); return; }
  try {
    await _dbInsert('planning_event_resources', [{
      event_id:    eventId,
      resource_id: resourceId,
      role:        'owner',
      quantity:    quantity,
      assignment_source: 'manual',
    }]);
    if (_gate.conflicts.length) {
      await _laLogConflicts(_gate.conflicts);
      toast(`⚠ ${_gate.conflicts.length} conflict${_gate.conflicts.length>1?'s':''} flagged — see Planning Admin → Conflicts`, 'warn');
    }
    await loadPlanningData(true);
    _renderLookaheadTabBody();
  } catch (err) {
    toast('Add failed: ' + err.message, 'error');
  }
}

async function _laDrawerRemoveEventResource(eventResId) {
  try {
    await _dbDelete('planning_event_resources', { id: eventResId });
    await loadPlanningData(true);
    _renderLookaheadTabBody();
  } catch (err) {
    toast('Remove failed: ' + err.message, 'error');
  }
}

// ============================================================
// EXPORTS — Phase 4B & 4C
// ============================================================

// 4-Week Lookahead: activity-row × day-cell visual export.
// Frozen first 2 columns (Group, Activity), one column per day, color-fill
// matches the shift color, cancelled cells get a 🚫 prefix.
function _laExportLookahead() {
  if (typeof XLSX === 'undefined') { toast('Excel library not loaded', 'error'); return; }
  const winStart = dayjs().startOf('day');
  const days = Array.from({ length: _laTimelineWindow }, (_, i) => winStart.add(i, 'day').format('YYYY-MM-DD'));

  // Header: 1 row month strip + 1 row day strip
  const monthRow = ['Group', 'Phase', 'Activity', 'Location'];
  const dayRow   = ['', '', '', ''];
  days.forEach(iso => {
    const d = dayjs(iso);
    monthRow.push(d.format('MMM'));
    dayRow.push(d.format('dd') + ' ' + d.format('D'));
  });
  monthRow.push('Hitachi', 'BART', 'Linked Test Reg', 'Notes');
  dayRow.push('', '', '', '');

  const rows = [monthRow, dayRow];

  // Body: ordered by group + sort_order
  const acts = (PLANNING_ACTIVITIES || []).filter(a => !a.deleted_at);
  const ordered = [];
  [..._GROUP_ORDER, ...new Set(acts.map(a => a.activity_group).filter(g => g && !_GROUP_ORDER.includes(g)))].forEach(gk => {
    acts
      .filter(a => (a.activity_group || 'other') === gk)
      .sort((a, b) => (a.sort_order ?? 999999) - (b.sort_order ?? 999999))
      .forEach(a => ordered.push({ a, gk }));
  });

  ordered.forEach(({ a, gk }) => {
    const meta = _groupMeta(gk);
    const evs = (PLANNING_EVENTS || []).filter(e => e.planning_activity_id === a.id && days.includes(e.event_date));
    const row = [meta.label, a.phase || '', a.description || a.activity_id_text || '', _laResolveLocationPrefix(a.location) || ''];

    days.forEach(iso => {
      const ev = evs.find(e => e.event_date === iso);
      if (!ev) { row.push(''); return; }
      const shift = ev.shift_type === 'day_shift' ? 'D'
                  : ev.shift_type === 'night_shift' ? 'N'
                  : ev.shift_type === 'blanket_shift' ? 'B' : '·';
      const txt = (ev.status === 'cancelled' ? '🚫 ' : '') + shift +
                  (ev.start_time ? ' ' + ev.start_time.slice(0, 5) : '') +
                  (ev.end_time   ? '-' + ev.end_time.slice(0, 5) : '');
      row.push(txt);
    });

    // Trailing crew + BART + linked TRA + notes
    const evIds = evs.map(e => e.id);
    const hitachiNames = [...new Set((PLANNING_EVENT_RES || [])
      .filter(er => evIds.includes(er.event_id))
      .map(er => (PLANNING_RESOURCES || []).find(r => r.id === er.resource_id))
      .filter(r => r && r.company !== 'BART')
      .map(r => r.display_name))].join(', ');
    const bartReqs = [...new Set((PLANNING_EVENT_RES || [])
      .filter(er => evIds.includes(er.event_id))
      .map(er => {
        const r = (PLANNING_RESOURCES || []).find(x => x.id === er.resource_id);
        if (!r || r.company !== 'BART') return null;
        return `${r.display_name}×${er.quantity || 1}` + (er.denied_at ? ' (DENIED)' : '');
      })
      .filter(Boolean))].join(', ');
    row.push(hitachiNames, bartReqs, a.linked_test_register_activity || '', a.notes || '');
    rows.push(row);
  });

  // Build sheet
  const ws = XLSX.utils.aoa_to_sheet(rows);
  ws['!cols'] = [{ wch: 22 }, { wch: 42 }, ...days.map(() => ({ wch: 12 })), { wch: 28 }, { wch: 22 }, { wch: 22 }, { wch: 30 }];
  ws['!freeze'] = { xSplit: 2, ySplit: 2 };

  // Color-code group label cells (column A) on each activity row
  ordered.forEach(({ gk }, i) => {
    const cellRef = XLSX.utils.encode_cell({ r: 2 + i, c: 0 });
    const meta = _groupMeta(gk);
    if (!ws[cellRef]) return;
    ws[cellRef].s = {
      fill: { fgColor: { rgb: meta.bg.replace('#', '').toUpperCase() } },
      font: { color: { rgb: meta.fg.replace('#', '').toUpperCase() }, bold: true },
    };
  });

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, `${_laTimelineWindow}-Day Lookahead`);
  const fn = `Lookahead_${dayjs().format('YYYY-MM-DD')}_${_laTimelineWindow}d.xlsx`;
  XLSX.writeFile(wb, fn);
  toast(`✓ Exported ${ordered.length} activities × ${days.length} days`, 'success');
}

// BART Resource Map: flat, one row per (event × BART resource).
// Either .xlsx (with a header style) or .csv (raw, BART analysts can pivot).
function _laExportBARTResourceMap(format = 'xlsx') {
  if (format === 'xlsx' && typeof XLSX === 'undefined') { toast('Excel library not loaded', 'error'); return; }
  const header = [
    'Date', 'Day', 'Shift', 'Start', 'End',
    'Activity', 'Group', 'Location',
    'BART Role', 'Quantity', 'Status',
    'Cancellation Category', 'Cancellation Reason', 'Responsible Party',
    'Last Updated',
  ];
  const rows = [header];
  const acts = (PLANNING_ACTIVITIES || []).filter(a => !a.deleted_at);

  (PLANNING_EVENT_RES || []).forEach(er => {
    const r = (PLANNING_RESOURCES || []).find(x => x.id === er.resource_id);
    if (!r || r.company !== 'BART') return;   // BART only
    const ev = (PLANNING_EVENTS || []).find(e => e.id === er.event_id);
    if (!ev) return;
    const act = acts.find(a => a.id === ev.planning_activity_id);
    if (!act) return;
    const meta = _groupMeta(act.activity_group || 'other');
    const status = er.denied_at ? 'denied' : ev.status;
    rows.push([
      ev.event_date,
      dayjs(ev.event_date).format('ddd'),
      ev.shift_type || '',
      ev.start_time || '',
      ev.end_time   || '',
      act.description || act.activity_id_text || '',
      meta.label,
      act.location || '',
      r.display_name,
      er.quantity || 1,
      status,
      ev.cancellation_category || '',
      ev.cancellation_reason   || '',
      ev.cancellation_responsible_party || '',
      ev.updated_at ? dayjs(ev.updated_at).format('YYYY-MM-DD HH:mm') : '',
    ]);
  });

  const stamp = dayjs().format('YYYY-MM-DD');
  if (format === 'csv') {
    const csv = rows.map(r => r.map(v => {
      const s = String(v ?? '');
      return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
    }).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url  = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = `BART_Resource_Map_${stamp}.csv`;
    document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
  } else {
    const ws = XLSX.utils.aoa_to_sheet(rows);
    ws['!cols'] = header.map(h => ({ wch: Math.max(10, h.length + 2) }));
    ws['!freeze'] = { ySplit: 1 };
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'BART Resource Map');
    XLSX.writeFile(wb, `BART_Resource_Map_${stamp}.xlsx`);
  }
  toast(`✓ Exported ${rows.length - 1} BART resource rows`, 'success');
}

// ─── Soft delete from drawer (Phase 3A) ─────────────────────
async function _laDrawerSoftDeleteActivity(activityId) {
  const a = PLANNING_ACTIVITIES.find(x => x.id === activityId);
  if (!a) return;
  const evs = (PLANNING_EVENTS || []).filter(e => e.planning_activity_id === activityId);
  const liveEvs = evs.filter(e => e.status !== 'cancelled');
  const reason = prompt(
    `Soft-delete "${a.description || a.activity_id_text || '—'}"?\n\n` +
    `This row will be hidden from the grid but can be restored from\n` +
    `Admin → Planning → Recently Deleted.\n\n` +
    (liveEvs.length
      ? `${liveEvs.length} non-cancelled event${liveEvs.length>1?'s':''} on this row will be cancelled automatically.\n\n`
      : '') +
    `Reason (optional):`
  );
  if (reason === null) return;   // cancelled the prompt
  try {
    // 1. Soft-delete the activity
    await _dbUpdate('planning_activities', {
      deleted_at:      new Date().toISOString(),
      deleted_by:      currentProfile?.id || null,
      deletion_reason: reason?.trim() || null,
    }, { id: activityId });

    // 2. Auto-cancel live events under it (audit-friendly: keep history)
    for (const e of liveEvs) {
      await _dbUpdate('planning_events', {
        status:                         'cancelled',
        cancellation_category:          'OTHER',
        cancellation_reason:            'Activity row deleted' + (reason ? ` — ${reason.trim()}` : ''),
        cancellation_responsible_party: 'HITACHI',
        cancellation_by:                currentProfile?.id || null,
        cancellation_at:                new Date().toISOString(),
      }, { id: e.id });
    }

    toast(`✓ Activity deleted${liveEvs.length ? ` (${liveEvs.length} event${liveEvs.length>1?'s':''} auto-cancelled)` : ''}`, 'success');
    _laDrawerClose();
    await loadPlanningData(true);
    _renderLookaheadTabBody();
  } catch (err) {
    toast('Delete failed: ' + err.message, 'error');
  }
}

// Inline 🗑 button on an activity row — quick soft-delete.
// (Re-uses the proven soft-delete path so behaviour stays consistent
//  across imported and manually-created activities.)
async function _laDeleteManualActivity(activityId, ev) {
  try { ev?.stopPropagation?.(); } catch (_) {}
  if (!activityId) return;
  await _laDrawerSoftDeleteActivity(activityId);
}

// Link / unlink an activity to a Test Register activity (the 🔗 chip).
// ── Link-activity modal — searchable dropdown pre-filtered by activity location ──

function _laOpenLinkActivityModal(activityId) {
  const a = (PLANNING_ACTIVITIES || []).find(x => x.id === activityId);
  if (!a) { toast('Activity not found', 'error'); return; }
  _laRenderLinkModal(activityId, false);
}

function _laRenderLinkModal(activityId, showAll) {
  const a       = (PLANNING_ACTIVITIES || []).find(x => x.id === activityId);
  if (!a) return;
  const current = a.linked_test_register_activity || '';
  const actLoc  = (a.location || '').trim();

  // Collect all unique (Activity, Location) pairs from TI
  const tiMap = {}; // activity name → Set of locations
  (TI || []).forEach(t => {
    const act = (t.Activity || '').trim();
    const loc = (t.Location || '').trim();
    if (!act) return;
    if (!tiMap[act]) tiMap[act] = new Set();
    if (loc) tiMap[act].add(loc);
  });

  const allNames = Object.keys(tiMap).sort((a, b) => a.localeCompare(b));

  // Resolve the activity location to its canonical master name so that
  // "W40 TCR" → "W40 - Millbrae Station" and matching against TI rows works.
  const resolvedLoc = actLoc ? (_laResolveLocationPrefix(actLoc) || actLoc) : null;

  // Match using the resolved canonical name (covers "W40 TCR" → "W40 - Millbrae Station")
  // and fall back to also checking the raw actLoc string.
  const locNames = actLoc
    ? allNames.filter(name =>
        [...tiMap[name]].some(tiLoc =>
          _laMatchesLocation(resolvedLoc || actLoc, tiLoc) ||
          _laMatchesLocation(actLoc, tiLoc)
        )
      )
    : allNames;

  const hasLocMatch = locNames.length > 0;
  const displayNames = (showAll || !hasLocMatch) ? allNames : locNames;

  // Build select options — group: location-matched first (when showing all)
  let optsHTML = `<option value="">— Select a Test Register activity —</option>`;
  if (showAll && hasLocMatch) {
    // Group: matched at top, rest below
    const matched   = allNames.filter(n => locNames.includes(n));
    const unmatched = allNames.filter(n => !locNames.includes(n));
    optsHTML += `<optgroup label="📍 ${escapeHtml(resolvedLoc || actLoc)} — ${matched.length} match${matched.length !== 1 ? 'es' : ''}">`;
    matched.forEach(n => {
      optsHTML += `<option value="${escapeHtml(n)}" ${current === n ? 'selected' : ''}>${escapeHtml(n)}</option>`;
    });
    optsHTML += `</optgroup><optgroup label="All other locations — ${unmatched.length}">`;
    unmatched.forEach(n => {
      optsHTML += `<option value="${escapeHtml(n)}" ${current === n ? 'selected' : ''}>${escapeHtml(n)}</option>`;
    });
    optsHTML += `</optgroup>`;
  } else {
    displayNames.forEach(n => {
      optsHTML += `<option value="${escapeHtml(n)}" ${current === n ? 'selected' : ''}>${escapeHtml(n)}</option>`;
    });
  }

  // Location filter status bar
  const filterBar = actLoc ? `
    <div style="display:flex;align-items:center;gap:8px;padding:8px 12px;border-radius:7px;margin-bottom:12px;
                background:${hasLocMatch ? 'var(--info-light)' : 'var(--warn-light)'};
                border:1px solid ${hasLocMatch ? '#bfdbfe' : '#fde68a'};">
      <span style="font-size:14px;">${hasLocMatch ? '📍' : '⚠️'}</span>
      <div style="flex:1;font-size:12px;color:var(--gray-700);">
        ${hasLocMatch
          ? `Showing <strong>${locNames.length}</strong> activit${locNames.length !== 1 ? 'ies' : 'y'} matching location <strong>${escapeHtml(resolvedLoc || actLoc)}</strong>`
          : `No Test Register activities found for <strong>${escapeHtml(resolvedLoc || actLoc)}</strong> — showing all locations`}
      </div>
      ${hasLocMatch
        ? `<button onclick="_laRenderLinkModal('${activityId}',${!showAll})" class="form-secondary" style="font-size:11px;padding:3px 10px;white-space:nowrap;">
             ${showAll ? '📍 Filter by location' : '🌐 Show all'}
           </button>`
        : ''}
    </div>` : '';

  modal({
    title: '🔗 Link Test Register Activity',
    sub:   escapeHtml(a.description || a.activity_id_text || '—'),
    size:  'medium',
    body: `
      <div style="display:flex;flex-direction:column;gap:4px;">
        ${filterBar}
        <label style="font-size:11px;font-weight:600;color:var(--gray-500);text-transform:uppercase;letter-spacing:.04em;">Test Register Activity</label>
        <select id="la-link-tra" class="form-input" style="font-size:13px;">
          ${optsHTML}
        </select>
        <div style="font-size:11px;color:var(--gray-500);margin-top:4px;">
          Linking pulls live test-completion counts onto this lookahead row.
          ${current ? `Currently linked: <strong>${escapeHtml(current)}</strong>` : 'No link set.'}
        </div>
      </div>`,
    footer:
      '<button class="form-secondary" onclick="closeModal()">Cancel</button>' +
      (current ? `<button class="form-secondary" style="color:#b91c1c;border-color:#fca5a5;" onclick="_laSaveActivityLink('${activityId}',true)">🔗 Unlink</button>` : '') +
      `<button class="form-submit" onclick="_laSaveActivityLink('${activityId}',false)">Save Link</button>`,
  });

  // Wire TomSelect for searchability after modal renders
  setTimeout(() => {
    const el = document.getElementById('la-link-tra');
    if (el && typeof TomSelect !== 'undefined' && !el.tomselect) {
      new TomSelect(el, { create: false, allowEmptyOption: true, maxOptions: 500 });
      // Restore current selection in TomSelect
      if (current && el.tomselect) el.tomselect.setValue(current, true);
    }
  }, 80);
}

async function _laSaveActivityLink(activityId, unlink) {
  let val = null;
  if (!unlink) {
    const el = document.getElementById('la-link-tra');
    // Read from TomSelect if initialised, otherwise native select
    val = (el?.tomselect ? el.tomselect.getValue() : el?.value || '').trim() || null;
  }
  try {
    await _dbUpdate('planning_activities',
      { linked_test_register_activity: val }, { id: activityId });
    closeModal();
    toast(val ? `✓ Linked to "${val}"` : '✓ Activity unlinked', 'success');
    await loadPlanningData(true);
    _renderLookaheadTabBody();
  } catch (err) {
    toast('Link failed: ' + err.message, 'error');
  }
}

function _laResourcePanelHTML() {
  const active = PLANNING_RESOURCES.filter(r => r.is_active).sort((a, b) => a.display_name.localeCompare(b.display_name));
  const byType = {};
  active.forEach(r => {
    const t = r.resource_type || 'other';
    if (!byType[t]) byType[t] = [];
    byType[t].push(r);
  });
  const TYPE_LABELS = { admin: 'Admin', field_engineer: 'Field Engineers', manual: 'Team Members', other: 'Other' };
  const colors = ['#e60012','#1e40af','#00875a','#b45309','#5b21b6','#065f46','#9a3412','#1f2937'];

  const selCount = _laSelectedResIds.size;

  let html = `<div class="la-res-panel" id="la-res-panel">
    <div class="la-res-panel-head">
      <div style="font-size:12px;font-weight:700;color:var(--charcoal);">Resources</div>
      <div style="font-size:11px;color:var(--gray-400);">${active.length} active</div>
    </div>
    <div style="padding:6px 8px;display:flex;flex-direction:column;gap:5px;">
      <input type="text" class="la-res-search" placeholder="🔍 Search…" oninput="_laFilterResPanel(this.value)">
      <div id="la-sel-bar" style="display:${selCount?'flex':'none'};align-items:center;justify-content:space-between;background:var(--hitachi-red);color:#fff;border-radius:5px;padding:4px 8px;font-size:11px;font-weight:600;">
        <span>${selCount} selected</span>
        <button onclick="_laClearResSelection()" style="background:none;border:none;color:#fff;cursor:pointer;font-size:11px;padding:0;">✕ Clear</button>
      </div>
    </div>
    <div style="padding:4px 8px 4px;font-size:10px;color:var(--gray-400);">Click to select · drag to assign</div>
    <div class="la-res-list" id="la-res-list">`;

  Object.entries(byType).forEach(([type, members]) => {
    html += `<div class="la-res-group-label">${TYPE_LABELS[type] || type}</div>`;
    members.forEach((r, i) => {
      const color   = colors[i % colors.length];
      const initials = r.initials || r.display_name.split(' ').map(w => w[0]).join('').slice(0, 2).toUpperCase();
      const isSel   = _laSelectedResIds.has(r.id);
      html += `<div class="la-res-card${isSel ? ' la-res-card-selected' : ''}" draggable="true"
        data-res-id="${r.id}"
        data-res-name="${escapeHtml(r.display_name)}"
        onclick="_laToggleResSelect('${r.id}')"
        ondragstart="_laStartResourceDrag('${r.id}',this)"
        ondragend="_laEndResourceDrag(this)">
        <div class="la-res-avatar" style="background:${color};">${escapeHtml(initials)}</div>
        <div class="la-res-name">${escapeHtml(r.display_name)}${r.subsystem ? `<div style="font-size:9px;opacity:.7;margin-top:1px;">${escapeHtml(r.subsystem)}</div>` : ''}</div>
        ${isSel ? `<div class="la-res-check">✓</div>` : `<div class="la-drag-handle" title="Drag to assign">⠿</div>`}
      </div>`;
    });
  });

  html += `</div></div>`;
  return html;
}

function _laSetTimelineGroup(g) { _laTimelineGroupBy = g; _renderLookaheadTabBody(); }
function _laSetActivitySubGroup(sg) { _laActivitySubGroup = sg; _renderLookaheadTabBody(); }
function _laSetResCompanyFilter(f) { _laResCompanyFilter = f; _renderLookaheadTabBody(); }
// True if a resource passes the current Hitachi/BART filter
function _laResCompanyMatch(r) {
  if (_laResCompanyFilter === 'all') return true;
  if (_laResCompanyFilter === 'BART') return r.company === 'BART';
  return r.company !== 'BART'; // 'Hitachi' = everything not BART
}
function _laToggleGroupCollapse(groupKey) {
  _laCollapsedGroups[groupKey] = !_laCollapsedGroups[groupKey];
  _renderLookaheadTabBody();
}
function _laSetTimelineWindow(d) { _laTimelineWindow = d; _renderLookaheadTabBody(); }

// ─── Resource panel search filter ────────────────────────────
function _laFilterResPanel(query) {
  const q = query.trim().toLowerCase();
  document.querySelectorAll('#la-res-list .la-res-card').forEach(card => {
    const name = (card.dataset.resName || '').toLowerCase();
    card.style.display = (!q || name.includes(q)) ? '' : 'none';
  });
  document.querySelectorAll('#la-res-list .la-res-group-label').forEach(lbl => {
    // Hide group label if all its sibling cards are hidden
    let next = lbl.nextElementSibling;
    let hasVisible = false;
    while (next && !next.classList.contains('la-res-group-label')) {
      if (next.style.display !== 'none') hasVisible = true;
      next = next.nextElementSibling;
    }
    lbl.style.display = hasVisible ? '' : 'none';
  });
}

// ─── Resource card selection ──────────────────────────────────
function _laToggleResSelect(resourceId) {
  if (_laSelectedResIds.has(resourceId)) {
    _laSelectedResIds.delete(resourceId);
  } else {
    _laSelectedResIds.add(resourceId);
  }
  // Re-render panel in place (preserves search query)
  const panel = document.getElementById('la-res-panel');
  if (panel) panel.outerHTML = _laResourcePanelHTML();
}

function _laClearResSelection() {
  _laSelectedResIds.clear();
  const panel = document.getElementById('la-res-panel');
  if (panel) panel.outerHTML = _laResourcePanelHTML();
}

// ─── Cell multi-select + Copy/Paste (Excel-style editing) ─────

// Floating action banner — shown whenever cells are selected or clipboard has content
function _laCellSelActionsHTML() {
  const n = _laSelectedCellKeys.size;
  const nc = _laCreateSel.length;
  const hasClipboard = !!_laClipboard;
  const hasTarget = !!_laPasteTarget;
  if (!n && !hasClipboard && !nc) return '';

  const parts = [];
  if (nc > 0) {
    parts.push(`<span style="font-size:12px;font-weight:700;color:#065f46;">\u271a ${nc} date${nc>1?'s':''} staged</span>`);
    parts.push(`<button class="form-secondary" style="font-size:11px;padding:4px 10px;background:#d1fae5;border-color:#6ee7b7;color:#065f46;" onclick="_laOpenCreateEventModal(_laCreateSel.slice())">\u2795 Create ${nc} event${nc>1?'s':''}</button>`);
    parts.push(`<button class="form-secondary" style="font-size:11px;padding:4px 10px;" onclick="_laClearCreateSel()">\u2715 Clear</button>`);
    if (n > 0 || hasClipboard) parts.push('<span style="width:1px;background:#e5e7eb;align-self:stretch;margin:0 4px;"></span>');
  }
  if (n > 0) {
    parts.push(`<span style="font-size:12px;font-weight:700;color:#7f0000;">${n} cell${n>1?'s':''} selected</span>`);
    parts.push(`<button class="form-secondary" style="font-size:11px;padding:4px 10px;" onclick="_laClearCellSelection()">✕ Clear</button>`);
    parts.push(`<button class="form-secondary" style="font-size:11px;padding:4px 10px;" onclick="_laCopySelection('copy')" title="Ctrl+C">📋 Copy</button>`);
    parts.push(`<button class="form-secondary" style="font-size:11px;padding:4px 10px;" onclick="_laCopySelection('cut')" title="Ctrl+X">✂ Cut</button>`);
    parts.push(`<button class="form-secondary" style="font-size:11px;padding:4px 10px;color:#7f1d1d;border-color:#fca5a5;" onclick="_laDeleteSelection()" title="Del">🗑 Delete</button>`);
    parts.push(`<button class="form-secondary" style="font-size:11px;padding:4px 10px;color:#7f1d1d;border-color:#fca5a5;" onclick="_laBulkCancelCells()">🚫 Cancel</button>`);
    parts.push(`<button class="form-secondary" style="font-size:11px;padding:4px 10px;" onclick="_laBulkRemoveCellResources()">Remove users only</button>`);
    parts.push('<span style="width:1px;background:#e5e7eb;align-self:stretch;margin:0 4px;"></span>');
    parts.push(`<select onchange="_laBulkSetShift(this.value);this.selectedIndex=0;" title="Set shift for all selected cells" style="font-size:11px;padding:4px 6px;border:1px solid var(--gray-300);border-radius:5px;">
      <option value="">Set shift…</option>
      <option value="day_shift">☀ Day</option>
      <option value="swing_shift">↔ Swing</option>
      <option value="night_shift">☾ Night</option>
      <option value="blanket_shift">■ Blanket</option>
    </select>`);
    parts.push(`<input id="la-bulk-loc" placeholder="Set location…" style="font-size:11px;padding:4px 6px;border:1px solid var(--gray-300);border-radius:5px;width:120px;">`);
    parts.push(`<button class="form-secondary" style="font-size:11px;padding:4px 10px;" onclick="_laBulkSetLocation()">Apply loc</button>`);
    parts.push(`<input id="la-bulk-hours" placeholder="Set hours 0700-1500" title="Bulk set work hours (military). Auto-sets shift type." style="font-size:11px;padding:4px 6px;border:1px solid var(--gray-300);border-radius:5px;width:130px;">`);
    parts.push(`<button class="form-secondary" style="font-size:11px;padding:4px 10px;" onclick="_laBulkSetHours()">Apply hrs</button>`);
  }
  if (hasClipboard) {
    if (n > 0) parts.push('<span style="width:1px;background:#e5e7eb;align-self:stretch;margin:0 4px;"></span>');
    const mode = _laClipboard.mode === 'cut' ? 'Cut' : 'Copied';
    parts.push(`<span style="font-size:12px;color:#1e40af;font-weight:600;">📋 ${mode} ${_laClipboard.items.length}</span>`);
    if (hasTarget) {
      parts.push(`<span style="font-size:11px;color:#059669;">Target: ${_laPasteTarget.date}</span>`);
      parts.push(`<button class="admin-action-btn" style="font-size:11px;padding:4px 10px;" onclick="_laPasteAtTarget()" title="Ctrl+V">📥 Paste</button>`);
    } else {
      parts.push(`<span style="font-size:11px;color:#6b7280;">click an empty cell, then Ctrl+V</span>`);
    }
    parts.push(`<button class="form-secondary" style="font-size:11px;padding:4px 10px;" onclick="_laClearClipboard()">✕ Cancel</button>`);
  }
  return `<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;flex-shrink:0;">${parts.join('')}</div>`;
}

// Find the live DOM element for a given event id (data attribute set on render)
function _laFindCellEl(eventId) {
  return document.querySelector(`[data-cell-event-id="${eventId}"]`);
}

// Toggle one cell's selection state (works in any mode)
function _laToggleCellSelect(eventId, el) {
  if (!el) el = _laFindCellEl(eventId);
  if (_laSelectedCellKeys.has(eventId)) {
    _laSelectedCellKeys.delete(eventId);
    el?.classList.remove('la-cell-selected');
    el?.querySelector('.la-cell-sel-mark')?.remove();
  } else {
    _laSelectedCellKeys.add(eventId);
    el?.classList.add('la-cell-selected');
    if (el && !el.querySelector('.la-cell-sel-mark')) {
      const mark = document.createElement('span');
      mark.className = 'la-cell-sel-mark';
      mark.textContent = '✓';
      el.appendChild(mark);
    }
  }
  _laRefreshActionBanner();
}

function _laRefreshActionBanner() {
  const actEl = document.getElementById('la-cell-sel-actions');
  if (actEl) actEl.innerHTML = _laCellSelActionsHTML();
  _laUpdateSelectionChrome();
}

function _laClearCellSelection() {
  _laSelectedCellKeys.clear();
  document.querySelectorAll('.la-cell-selected').forEach(el => {
    el.classList.remove('la-cell-selected');
    el.querySelector('.la-cell-sel-mark')?.remove();
  });
  _laRefreshActionBanner();
}

// ─── Cell click router (single entry point for all click types) ───
// Plain click  = open detail (or toggle in assign mode, or set paste target if clipboard active)
// Ctrl+click   = toggle multi-select
// Shift+click  = range-select (not implemented yet)
function _laCellClick(ev, eventId, actId, iso, el) {
  if (ev.ctrlKey || ev.metaKey) {
    ev.preventDefault();
    ev.stopPropagation();
    _laToggleCellSelect(eventId, el);
    return;
  }
  if (_laAssignMode) {
    _laToggleCellSelect(eventId, el);
    return;
  }
  // Clipboard active → clicking ANY cell (including colored) sets the paste target.
  // To still open details with clipboard active: right-click → Open details, or press Esc first.
  if (_laClipboard && actId) {
    ev.stopPropagation();
    _laSetPasteTarget(actId, iso, el);
    return;
  }
  // Phase 2C: click opens the right drawer (replaces the detail modal).
  // Multi-select bulk view auto-shows when 2+ cells are selected.
  if (_laSelectedCellKeys.size >= 2) {
    _laDrawerOpen('multi', null);
  } else {
    _laDrawerOpen('cell', eventId);
  }
}

// Click on an empty cell
function _laEmptyCellClick(ev, actId, iso, el) {
  if (!actId) return;
  ev.stopPropagation();
  if (_laClipboard) { _laSetPasteTarget(actId, iso, el); return; }
  if (ev.ctrlKey || ev.metaKey) { ev.preventDefault(); _laToggleCreateSel(actId, iso, el); return; }
  if (!_laCreateSel.some(s => s.actId === actId && s.iso === iso)) _laCreateSel.push({ actId, iso, el });
  const cells = _laCreateSel.slice();
  _laClearCreateSel(false);
  _laOpenCreateEventModal(cells);
}

function _laToggleCreateSel(actId, iso, el) {
  const idx = _laCreateSel.findIndex(s => s.actId === actId && s.iso === iso);
  if (idx >= 0) { _laCreateSel.splice(idx, 1); el?.classList.remove('la-create-sel'); }
  else          { _laCreateSel.push({ actId, iso, el }); el?.classList.add('la-create-sel'); }
  _laRefreshActionBanner();
}

function _laClearCreateSel(refresh = true) {
  _laCreateSel.forEach(s => s.el?.classList.remove('la-create-sel'));
  _laCreateSel = [];
  if (refresh) _laRefreshActionBanner();
}
// ─── Shift inference from military time "0700-1500" ─────────────────────
function _laInferShiftFromHours(hoursRaw) {
  if (!hoursRaw || !hoursRaw.trim()) return { start: null, end: null, shift_type: null };
  const raw = hoursRaw.trim().replace(/\s+/g, '');
  const m = raw.match(/^(\d{3,4})(?:[-\u2013](\d{3,4}))?$/);
  if (!m) return { start: null, end: null, shift_type: null };
  const pad = s => s.length === 3 ? '0' + s : s;
  const toTime = s => s ? pad(s).slice(0,2) + ':' + pad(s).slice(2) : null;
  const start = toTime(m[1]), end = toTime(m[2] || null);
  const h = start ? parseInt(start.slice(0,2), 10) : -1;
  const shift_type = h < 0       ? 'blanket_shift'
    : (h >= 4 && h < 12)  ? 'day_shift'
    : (h >= 12 && h < 18) ? 'swing_shift'
    : 'night_shift';
  return { start, end, shift_type };
}

// Called by the Work Hours input in the existing cell drawer
function _laDrawerCellHoursChanged() {
  _laDrawerMarkDirty();
  const { start, end, shift_type } = _laInferShiftFromHours(document.getElementById('dw-cell-hours')?.value || '');
  if (start) { const el = document.getElementById('dw-cell-start'); if (el) el.value = start; }
  if (end)   { const el = document.getElementById('dw-cell-end');   if (el) el.value = end;   }
  const sel = document.getElementById('dw-cell-shift');
  if (shift_type && sel && !sel.dataset.manualOverride) sel.value = shift_type;
}

// ─── Create Event modal (single or multi-date) ───────────────────────────
function _laOpenCreateEventModal(cells) {
  if (!cells || !cells.length) return;
  _laCreateResState = [];
  const actIds   = [...new Set(cells.map(c => c.actId))];
  const actLabel = actIds.length === 1
    ? (() => { const a = (PLANNING_ACTIVITIES||[]).find(x => x.id === actIds[0]); return a?.description || a?.activity_id_text || '—'; })()
    : actIds.length + ' activities';

  const dateChips = cells.map(c => {
    const d = (typeof dayjs !== 'undefined') ? dayjs(c.iso) : null;
    const isWknd = d ? (d.day() === 0 || d.day() === 6) : false;
    const bg = isWknd ? '#fef3c7' : '#d1fae5', col = isWknd ? '#92400e' : '#065f46', brd = isWknd ? '#fcd34d' : '#6ee7b7';
    return '<span style="display:inline-block;background:' + bg + ';color:' + col + ';font-size:11px;font-weight:600;padding:2px 8px;border-radius:12px;border:1px solid ' + brd + ';">' + escapeHtml(d ? d.format('ddd MMM D') : c.iso) + '</span>';
  }).join(' ');

  const allRes    = (PLANNING_RESOURCES || []).filter(r => r.is_active);
  const hitRes    = allRes.filter(r => (r.kind === 'person' || !r.kind) && r.company !== 'BART');
  const bartRoles = allRes.filter(r => r.kind === 'role' && r.is_requestable);
  const hitOpts   = hitRes.map(r  => '<option value="' + r.id + '" data-name="' + escapeHtml(r.display_name) + '">' + escapeHtml(r.display_name) + '</option>').join('');
  const bartOpts  = bartRoles.map(r => '<option value="' + r.id + '" data-name="' + escapeHtml(r.display_name) + '">' + escapeHtml(r.display_name) + '</option>').join('');

  modal({
    title: cells.length > 1 ? '➕ Create ' + cells.length + ' Events' : '➕ Create Event',
    sub:   actLabel,
    size:  'medium',
    body: (
      '<div style="margin-bottom:14px;">' +
        '<div style="font-size:11px;color:var(--gray-500);margin-bottom:6px;">Date' + (cells.length > 1 ? 's' : '') + ' (' + cells.length + '):</div>' +
        '<div style="display:flex;flex-wrap:wrap;gap:4px;">' + dateChips + '</div>' +
      '</div>' +
      '<div class="form-grid">' +
        '<div class="form-field">' +
          '<label>Work hours <span style="font-size:10px;font-weight:400;color:var(--gray-500);">e.g. 0700-1500</span></label>' +
          '<input type="text" id="ce-hours" class="form-input" placeholder="0700-1500" oninput="_laCEHoursChanged()">' +
        '</div>' +
        '<div class="form-field">' +
          '<label>Shift type <span style="font-size:10px;font-weight:400;color:var(--gray-500);">auto-detected</span></label>' +
          '<select id="ce-shift" class="form-input" onchange="this.dataset.manual=1;">' +
            '<option value="">— select —</option>' +
            '<option value="day_shift">☀ Day (0600–1800)</option>' +
            '<option value="swing_shift">↔ Swing (1200–2200)</option>' +
            '<option value="night_shift">☾ Night (1800–0600)</option>' +
            '<option value="blanket_shift">■ Blanket (all day)</option>' +
          '</select>' +
        '</div>' +
        '<div class="form-field form-field-full">' +
          '<label>Title <span style="font-size:10px;font-weight:400;color:var(--gray-500);">optional</span></label>' +
          '<input type="text" id="ce-title" class="form-input" placeholder="Defaults to activity description">' +
        '</div>' +
        '<div class="form-field form-field-full">' +
          '<label>Notes</label>' +
          '<textarea id="ce-notes" class="form-input" rows="2" placeholder="Any notes for this shift…"></textarea>' +
        '</div>' +
      '</div>' +
      '<div style="margin-top:12px;padding:10px;background:#f8fafc;border-radius:6px;">' +
        '<div style="font-size:11px;font-weight:600;margin-bottom:6px;">Hitachi resources</div>' +
        '<div id="ce-hit-pills" style="display:flex;flex-wrap:wrap;gap:4px;margin-bottom:6px;min-height:22px;"><span style="color:var(--gray-400);font-size:12px;">None</span></div>' +
        '<div style="display:flex;gap:6px;">' +
          '<select id="ce-hit-pick" class="form-input" style="flex:1;"><option value="">+ Add Hitachi person…</option>' + hitOpts + '</select>' +
          '<button class="form-secondary" style="font-size:11px;white-space:nowrap;" onclick="_laCEAddResource(\'hit\')">Add</button>' +
        '</div>' +
      '</div>' +
      '<div style="margin-top:8px;padding:10px;background:#f8fafc;border-radius:6px;">' +
        '<div style="font-size:11px;font-weight:600;margin-bottom:6px;">BART requests</div>' +
        '<div id="ce-bart-pills" style="display:flex;flex-wrap:wrap;gap:4px;margin-bottom:6px;min-height:22px;"><span style="color:var(--gray-400);font-size:12px;">None</span></div>' +
        '<div style="display:flex;gap:6px;">' +
          '<select id="ce-bart-pick" class="form-input" style="flex:1;"><option value="">+ Request BART role…</option>' + bartOpts + '</select>' +
          '<input type="number" id="ce-bart-qty" class="form-input" value="1" min="1" max="50" style="width:60px;" title="Qty">' +
          '<button class="form-secondary" style="font-size:11px;white-space:nowrap;" onclick="_laCEAddResource(\'bart\')">Add</button>' +
        '</div>' +
      '</div>'
    ),
    footer: (
      '<button class="form-secondary" onclick="closeModal()">Cancel</button>' +
      '<button class="form-submit" id="ce-save-btn" onclick="_laSaveCreateEvents(window._laCECells)">➕ Create ' + cells.length + ' event' + (cells.length > 1 ? 's' : '') + '</button>'
    ),
  });
  window._laCECells = cells;
}

function _laCEHoursChanged() {
  const { shift_type } = _laInferShiftFromHours(document.getElementById('ce-hours')?.value || '');
  const sel = document.getElementById('ce-shift');
  if (sel && !sel.dataset.manual && shift_type) sel.value = shift_type;
}

function _laCEAddResource(company) {
  const isBart = company === 'bart';
  const pick   = document.getElementById(isBart ? 'ce-bart-pick' : 'ce-hit-pick');
  if (!pick || !pick.value) return;
  const qty  = isBart ? (parseInt(document.getElementById('ce-bart-qty')?.value) || 1) : 1;
  const name = pick.options[pick.selectedIndex]?.dataset?.name || pick.value;
  _laCreateResState.push({ resourceId: pick.value, qty, isBart, label: name });
  pick.value = '';
  _laCERefreshPills();
}

function _laCERemoveResource(idx) {
  _laCreateResState.splice(idx, 1);
  _laCERefreshPills();
}

function _laCERefreshPills() {
  const pill = (r) => '<span class="la-drawer-pill">' + escapeHtml(r.label) + (r.qty > 1 ? ' ×' + r.qty : '') +
    ' <button onclick="_laCERemoveResource(' + _laCreateResState.indexOf(r) + ')" title="Remove">×</button></span>';
  const none = '<span style="color:var(--gray-400);font-size:12px;">None</span>';
  const hp = document.getElementById('ce-hit-pills');
  const bp = document.getElementById('ce-bart-pills');
  if (hp) hp.innerHTML = _laCreateResState.filter(r => !r.isBart).map(pill).join('') || none;
  if (bp) bp.innerHTML = _laCreateResState.filter(r =>  r.isBart).map(pill).join('') || none;
}

async function _laSaveCreateEvents(cells) {
  if (!cells || !cells.length) return;
  const btn = document.getElementById('ce-save-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }

  const hoursRaw  = (document.getElementById('ce-hours')?.value || '').trim();
  const { start, end } = _laInferShiftFromHours(hoursRaw);
  const shiftType = document.getElementById('ce-shift')?.value || null;
  const titleInput = (document.getElementById('ce-title')?.value || '').trim();
  const notes     = (document.getElementById('ce-notes')?.value || '').trim() || null;
  const allDay    = shiftType === 'blanket_shift' && !start;

  const eventRows = cells.map(({ actId, iso }) => {
    const act = (PLANNING_ACTIVITIES || []).find(x => x.id === actId);
    const titleFallback = act?.description || act?.activity_id_text || 'Scheduled work';
    return {
      planning_activity_id: actId,
      event_date:  iso,
      title:       titleInput || titleFallback,
      // Inherit location from the parent activity row; still editable per-cell
      // in the drawer afterwards.
      location:    act?.location || null,
      start_time:  start     || null,
      end_time:    end       || null,
      shift_type:  shiftType || null,
      all_day:     allDay,
      notes:       notes     || null,
      status:      'planned',
      version:     1,
      created_by:  (typeof currentProfile !== 'undefined') ? (currentProfile?.id || null) : null,
    };
  });

  try {
    const created = await _dbInsert('planning_events', eventRows);
    if (_laCreateResState.length && created?.length) {
      const resRows = [];
      created.forEach(ev => _laCreateResState.forEach(r => resRows.push({
        event_id: ev.id, resource_id: r.resourceId,
        role: 'owner', quantity: r.qty, assignment_source: 'manual',
      })));
      if (resRows.length) await _dbInsert('planning_event_resources', resRows);
    }
    closeModal();
    toast('✓ ' + (created?.length || cells.length) + ' event' + (cells.length > 1 ? 's' : '') + ' created', 'success');
    await loadPlanningData(true);
    _renderLookaheadTabBody();
  } catch (err) {
    toast('Create failed: ' + err.message, 'error');
    if (btn) { btn.disabled = false; btn.textContent = '➕ Create'; }
  }
}


function _laSetPasteTarget(actId, iso, el) {
  document.querySelectorAll('.la-paste-target').forEach(x => x.classList.remove('la-paste-target'));
  _laPasteTarget = { activityId: actId, date: iso };
  if (el) el.classList.add('la-paste-target');
  _laRefreshActionBanner();
}

// ─── Copy / Cut ────────────────────────────────────────────────
function _laCopySelection(mode = 'copy', opts) {
  if (_laSelectedCellKeys.size === 0) {
    if (!opts?.silent) toast('Ctrl+click colored cells to select them first.', 'warn');
    return;
  }
  const selectedEvents = PLANNING_EVENTS.filter(e => _laSelectedCellKeys.has(e.id));
  if (selectedEvents.length === 0) return;

  // Anchor = earliest date in the selection (top-left)
  const sorted = [...selectedEvents].sort((a, b) =>
    a.event_date.localeCompare(b.event_date) ||
    String(a.planning_activity_id || '').localeCompare(String(b.planning_activity_id || ''))
  );
  const anchorActId = sorted[0].planning_activity_id;
  const anchorDate = sorted[0].event_date;

  const items = selectedEvents.map(e => {
    const resources = PLANNING_EVENT_RES.filter(er => er.event_id === e.id);
    const dayOffset = dayjs(e.event_date).diff(dayjs(anchorDate), 'day');
    return {
      event: e,
      resources,
      dayOffset,
      sameActivityAsAnchor: e.planning_activity_id === anchorActId,
    };
  });

  _laClipboard = { mode, items, anchorActId, anchorDate };

  // Marching-ants visual on copied cells
  document.querySelectorAll('.la-cell-clipboard, .la-cell-cut').forEach(x => {
    x.classList.remove('la-cell-clipboard', 'la-cell-cut');
  });
  selectedEvents.forEach(e => {
    const el = _laFindCellEl(e.id);
    if (el) {
      el.classList.add('la-cell-clipboard');
      if (mode === 'cut') el.classList.add('la-cell-cut');
    }
  });

  document.body.classList.add('la-clipboard-active');
  _laRefreshActionBanner();
  if (!opts?.silent) toast(`${mode === 'copy' ? '📋 Copied' : '✂ Cut'} ${items.length} cell${items.length>1?'s':''}. Click an empty cell, then Ctrl+V.`, 'success');
}

function _laClearClipboard() {
  _laClipboard = null;
  _laPasteTarget = null;
  document.querySelectorAll('.la-cell-clipboard, .la-cell-cut').forEach(x => {
    x.classList.remove('la-cell-clipboard', 'la-cell-cut');
  });
  document.querySelectorAll('.la-paste-target').forEach(x => x.classList.remove('la-paste-target'));
  document.body.classList.remove('la-clipboard-active');
  _laRefreshActionBanner();
}

// ─── Paste ─────────────────────────────────────────────────────
async function _laPasteAtTarget() {
  if (!_laClipboard) { toast('Nothing to paste. Copy some cells first (Ctrl+C).', 'warn'); return; }
  if (!_laPasteTarget) { toast('Click an empty cell to set the paste target.', 'warn'); return; }

  const { activityId: targetActId, date: targetDate } = _laPasteTarget;
  const { items, anchorDate } = _laClipboard;

  // Compute new positions for each clipboard item
  const dayShift = dayjs(targetDate).diff(dayjs(anchorDate), 'day');
  const ops = items.map(it => {
    const newDate = dayjs(it.event.event_date).add(dayShift, 'day').format('YYYY-MM-DD');
    const newActId = it.sameActivityAsAnchor ? targetActId : it.event.planning_activity_id;
    return { src: it, newDate, newActId };
  });

  // Detect collisions, locked targets, and PTO conflicts
  const collisions = [], lockedSkips = [], ptoConflicts = [];
  ops.forEach(op => {
    const existing = PLANNING_EVENTS.find(e =>
      e.planning_activity_id === op.newActId &&
      e.event_date === op.newDate &&
      e.status !== 'cancelled'
    );
    if (existing) {
      if (existing.is_locked) lockedSkips.push({ op, existing });
      else collisions.push({ op, existing });
    }
    op.src.resources.forEach(er => {
      const onPTO = PTO_REQUESTS.some(p =>
        p.status === 'approved' &&
        p.resource_id === er.resource_id &&
        op.newDate >= p.start_date &&
        op.newDate <= p.end_date
      );
      if (onPTO) {
        const r = PLANNING_RESOURCES.find(x => x.id === er.resource_id);
        ptoConflicts.push({ name: r?.display_name || '?', date: op.newDate });
      }
    });
  });

  // If anything to ask about, show the summary modal
  if (collisions.length > 0 || lockedSkips.length > 0 || ptoConflicts.length > 0) {
    const decision = await _laPasteConfirmModal({ ops, collisions, lockedSkips, ptoConflicts });
    if (!decision) return;
    return _laExecutePaste(ops, decision);
  }
  return _laExecutePaste(ops, { collisionAction: 'overwrite' });
}

function _laPasteConfirmModal({ ops, collisions, lockedSkips, ptoConflicts }) {
  return new Promise(resolve => {
    let html = '<div style="font-size:13px;max-height:60vh;overflow-y:auto;">';
    html += `<p style="margin:0 0 10px;">Paste <strong>${ops.length}</strong> event${ops.length>1?'s':''}.</p>`;

    if (lockedSkips.length > 0) {
      html += `<div style="background:#fef3c7;border:1px solid #f59e0b;border-radius:6px;padding:10px;margin:10px 0;">
        <strong>🔒 ${lockedSkips.length} target${lockedSkips.length>1?'s':''} locked</strong> — will be skipped silently.
      </div>`;
    }

    if (collisions.length > 0) {
      html += `<div style="background:#fee2e2;border:1px solid #ef4444;border-radius:6px;padding:10px;margin:10px 0;">
        <strong>⚠ ${collisions.length} collision${collisions.length>1?'s':''}</strong> — existing event${collisions.length>1?'s':''} on these cells:
        <ul style="margin:6px 0 8px 18px;padding:0;font-size:12px;">
          ${collisions.slice(0,8).map(c => `<li>${escapeHtml(c.existing.title||'(untitled)')} · ${c.op.newDate}</li>`).join('')}
          ${collisions.length>8?`<li>…and ${collisions.length-8} more</li>`:''}
        </ul>
        <label style="display:block;margin-top:4px;"><input type="radio" name="collision" value="overwrite" checked> Overwrite existing events</label>
        <label style="display:block;"><input type="radio" name="collision" value="skip"> Skip these (keep existing)</label>
      </div>`;
    }

    if (ptoConflicts.length > 0) {
      html += `<div style="background:#fef3c7;border:1px solid #f59e0b;border-radius:6px;padding:10px;margin:10px 0;">
        <strong>🌴 ${ptoConflicts.length} PTO conflict${ptoConflicts.length>1?'s':''}:</strong>
        <ul style="margin:4px 0 0 18px;padding:0;font-size:12px;">
          ${ptoConflicts.slice(0,10).map(c => `<li>${escapeHtml(c.name)} on ${c.date}</li>`).join('')}
          ${ptoConflicts.length>10?`<li>…and ${ptoConflicts.length-10} more</li>`:''}
        </ul>
        <p style="margin:6px 0 0;font-size:12px;color:#92400e;">Resources will still be assigned — review and unassign manually if needed.</p>
      </div>`;
    }

    html += '</div>';

    modal({
      title: 'Confirm Paste',
      body: html,
      footer: `
        <button class="form-secondary" onclick="window._laPasteResolve(null)">Cancel</button>
        <button class="form-submit" onclick="window._laPasteResolve('go')">Continue Paste</button>
      `,
    });

    window._laPasteResolve = (result) => {
      if (!result) { closeModal(); resolve(null); return; }
      const radio = document.querySelector('input[name="collision"]:checked');
      const collisionAction = radio ? radio.value : 'overwrite';
      closeModal();
      delete window._laPasteResolve;
      resolve({ collisionAction });
    };
  });
}

async function _laExecutePaste(ops, { collisionAction }) {
  let inserted = 0, overwritten = 0, skipped = 0;
  const wasCut = _laClipboard?.mode === 'cut';
  const cutSourceIds = wasCut ? _laClipboard.items.map(it => it.event.id) : [];

  for (const op of ops) {
    try {
      const existing = PLANNING_EVENTS.find(e =>
        e.planning_activity_id === op.newActId &&
        e.event_date === op.newDate &&
        e.status !== 'cancelled'
      );

      // Locked → always skip
      if (existing && existing.is_locked) { skipped++; continue; }

      if (existing) {
        if (collisionAction === 'skip') { skipped++; continue; }
        // Overwrite: delete existing first (and its resources)
        await _dbDelete('planning_event_resources', { event_id: existing.id });
        await _dbDelete('planning_events', { id: existing.id });
        overwritten++;
      }

      // Build payload for new event (clone of source with new date / activity)
      const src = op.src.event;
      const payload = {
        planning_activity_id: op.newActId,
        title: src.title,
        event_date: op.newDate,
        start_time: src.start_time,
        end_time: src.end_time,
        all_day: src.all_day,
        location: src.location,
        work_hours_raw: src.work_hours_raw,
        shift_type: src.shift_type,
        cell_color_hex: src.cell_color_hex,
        source: 'manual',
        status: src.status === 'cancelled' ? 'planned' : (src.status || 'planned'),
        is_locked: false,
        notes: src.notes,
        created_by: currentProfile?.id || null,
        updated_by: currentProfile?.id || null,
      };

      const newRows = await _dbInsert('planning_events', [payload]);
      inserted++;
      const newEventId = newRows?.[0]?.id;

      // Clone resources (unless source row is being cut and is the same row — avoid double assign)
      if (newEventId && op.src.resources.length > 0) {
        const resPayload = op.src.resources.map(er => ({
          event_id:          newEventId,
          resource_id:       er.resource_id,
          role:              er.role || 'owner',
          quantity:          er.quantity || 1,
          assignment_source: er.assignment_source || 'manual',
          notes:             er.notes || null,
        }));
        await _dbInsert('planning_event_resources', resPayload);
      }
    } catch (err) {
      console.error('[paste] op failed:', err);
      toast('One paste op failed: ' + err.message, 'error');
    }
  }

  // Cut mode → delete sources (skip locked)
  if (wasCut) {
    for (const eid of cutSourceIds) {
      const ev = PLANNING_EVENTS.find(e => e.id === eid);
      if (!ev || ev.is_locked) continue;
      try {
        await _dbDelete('planning_event_resources', { event_id: eid });
        await _dbDelete('planning_events', { id: eid });
      } catch (err) {
        console.error('[paste/cut] source delete failed:', err);
      }
    }
  }

  toast(`✓ Pasted: ${inserted} inserted${overwritten?`, ${overwritten} overwritten`:''}${skipped?`, ${skipped} skipped`:''}`, 'success');
  _laSelectedCellKeys.clear();
  _laClearClipboard();
  await loadPlanningData(true);
  _renderLookaheadTabBody();
}

// ─── Bulk delete selected cells ───────────────────────────────
async function _laDeleteSelection() {
  if (_laSelectedCellKeys.size === 0) { toast('No cells selected.', 'warn'); return; }
  const eventIds = [..._laSelectedCellKeys];
  const events = PLANNING_EVENTS.filter(e => eventIds.includes(e.id));
  const lockedCount = events.filter(e => e.is_locked).length;
  const deletable = events.filter(e => !e.is_locked);
  if (deletable.length === 0) {
    toast('All selected cells are locked. Nothing to delete.', 'warn');
    return;
  }
  const msg = `Delete ${deletable.length} event${deletable.length>1?'s':''}?${lockedCount > 0 ? `\n(${lockedCount} locked event${lockedCount>1?'s':''} will be skipped)` : ''}\n\nYou can undo this right after.`;
  if (!confirm(msg)) return;

  // Snapshot rows so the action is reversible (Undo re-inserts them).
  const delIds = deletable.map(e => e.id);
  const snap = {
    events: deletable.map(e => ({ ...e })),
    resources: PLANNING_EVENT_RES.filter(er => delIds.includes(er.event_id)).map(er => ({ ...er })),
  };

  let count = 0;
  for (const e of deletable) {
    try {
      await _dbDelete('planning_event_resources', { event_id: e.id });
      await _dbDelete('planning_events', { id: e.id });
      count++;
    } catch (err) {
      console.error('[bulk-delete] failed for', e.id, err);
    }
  }
  _laSelectedCellKeys.clear();
  if (count > 0) _laToastUndo(`✓ Deleted ${count} event${count>1?'s':''}`, () => _laUndoDelete(snap));
  else toast('Nothing deleted.', 'warn');
  await loadPlanningData(true);
  _renderLookaheadTabBody();
}

// ─── Bulk cancel selected cells ───────────────────────────────
// Asks user for a cancellation reason + responsible party, then marks all
// selected (non-locked, non-already-cancelled) events as cancelled.
function _laBulkCancelCells() {
  if (_laSelectedCellKeys.size === 0) { toast('No cells selected.', 'warn'); return; }

  const eventIds = [..._laSelectedCellKeys];
  const events   = PLANNING_EVENTS.filter(e => eventIds.includes(e.id));
  const locked   = events.filter(e => e.is_locked);
  const already  = events.filter(e => !e.is_locked && e.status === 'cancelled');
  const toCancel = events.filter(e => !e.is_locked && e.status !== 'cancelled');

  if (toCancel.length === 0) {
    const reasons = [];
    if (locked.length)  reasons.push(`${locked.length} locked`);
    if (already.length) reasons.push(`${already.length} already cancelled`);
    toast(`Nothing to cancel — ${reasons.join(', ')}.`, 'warn');
    return;
  }

  const skipNote = [];
  if (locked.length)  skipNote.push(`${locked.length} locked`);
  if (already.length) skipNote.push(`${already.length} already cancelled`);
  const sub = `Cancelling ${toCancel.length} event${toCancel.length > 1 ? 's' : ''}${skipNote.length ? ` (skipping: ${skipNote.join(', ')})` : ''}`;

  _cancelReasonModalOpen(sub, async ({ category, reason, party }) => {
    const now = new Date().toISOString();
    let saved = 0;
    for (const ev of toCancel) {
      try {
        await _dbUpdate('planning_events', {
          status:                         'cancelled',
          cancellation_category:          category,
          cancellation_reason:            reason,
          cancellation_responsible_party: party || null,
          cancellation_by:                currentProfile?.id || null,
          cancellation_at:                now,
          updated_by:                     currentProfile?.id || null,
        }, { id: ev.id });
        saved++;
      } catch (err) {
        console.error('[bulk-cancel] failed for', ev.id, err);
      }
    }
    _laSelectedCellKeys.clear();
    toast(`✓ Cancelled ${saved} event${saved > 1 ? 's' : ''}`, 'success');
    await loadPlanningData(true);
    _renderLookaheadTabBody();
  });
}

// ─── Keyboard shortcuts (Ctrl+C / X / V / Del / Esc) ──────────
function _laKeyboardHandler(ev) {
  // Only when lookahead page is active
  if (!document.getElementById('page-lookahead')?.classList.contains('active')) return;
  // Don't intercept when typing
  const tag = ev.target.tagName;
  if (['INPUT', 'TEXTAREA', 'SELECT'].includes(tag) || ev.target.isContentEditable) return;
  const ctrl = ev.ctrlKey || ev.metaKey;
  const k = ev.key.toLowerCase();

  if (ctrl && k === 'c')        { ev.preventDefault(); _laCopySelection('copy'); }
  else if (ctrl && k === 'x')   { ev.preventDefault(); _laCopySelection('cut'); }
  else if (ctrl && k === 'v')   { ev.preventDefault(); _laPasteAtTarget(); }
  else if (k === 'delete')      { ev.preventDefault(); _laDeleteSelection(); }
  else if (k === 'escape')      {
    ev.preventDefault();
    if (_laDrawer.mode !== 'closed') { _laDrawerClose(); return; }
    _laClearCellSelection(); _laClearClipboard();
  }
}
// Attach the listener once on script load (gated to lookahead tab inside the handler)
document.addEventListener('keydown', _laKeyboardHandler);

// ─── Range-paint selection (Ctrl+drag) and drag-to-move ─────────
// Ctrl + mousedown + drag across cells → adds every colored cell in the
// rectangle to the multi-selection (anchor cell ↔ current cell).
// Plain mousedown + drag on a colored cell → moves it (and any other
// selected cells) to wherever you drop them. Reuses the cut+paste pipeline
// so collision/lock/PTO handling all works the same.

const _LA_DRAG_THRESHOLD_PX = 5;
let _laRangeSelState = null;   // { anchor row/col, baseKeys snapshot, didMove, ... }
let _laMoveDragState = null;   // { sourceIds, ghost el, current drop cell, ... }
let _laRowDragState  = null;   // Phase 2E: { activityId, originRowEl, ghost, dropIndicator, dropTarget }
let _laSuppressNextClick = false;

// Walk up from a target element to the underlying `.tlg-data-cell` and
// return its row/column coordinates within the rendered grid.
function _laCellCoord(el) {
  if (!el || !el.closest) return null;
  const cell = el.closest('.tlg-data-cell');
  if (!cell) return null;
  return {
    cell,
    actId: cell.dataset.activityId || '',
    iso:   cell.dataset.eventDate || '',
  };
}

// Snapshot of the grid's row/column index. Rebuilt at the start of each drag.
function _laBuildGridIndex() {
  const rowEls = [...document.querySelectorAll('.tlg-shell .tlg-data-row[data-activity-id]')];
  const rowByActId = new Map(rowEls.map((el, i) => [el.dataset.activityId, i]));
  const dateSet = new Set();
  rowEls.forEach(row => {
    row.querySelectorAll('.tlg-data-cell[data-event-date]').forEach(c => dateSet.add(c.dataset.eventDate));
  });
  const dateOrder = [...dateSet].sort();
  const colByDate = new Map(dateOrder.map((d, i) => [d, i]));
  return { rowEls, rowByActId, colByDate, dateOrder };
}

// Re-paint selection visuals + sync `_laSelectedCellKeys` to match `newKeys`.
function _laApplySelectionSet(newKeys) {
  document.querySelectorAll('.la-cell-selected').forEach(el => {
    el.classList.remove('la-cell-selected');
    el.querySelector('.la-cell-sel-mark')?.remove();
  });
  _laSelectedCellKeys.clear();
  newKeys.forEach(k => {
    _laSelectedCellKeys.add(k);
    const cellEl = _laFindCellEl(k);
    if (!cellEl) return;
    cellEl.classList.add('la-cell-selected');
    if (!cellEl.querySelector('.la-cell-sel-mark')) {
      const mark = document.createElement('span');
      mark.className = 'la-cell-sel-mark';
      mark.textContent = '✓';
      cellEl.appendChild(mark);
    }
  });
  _laRefreshActionBanner();
}

function _laTimelineMouseDown(ev) {
  if (ev.button !== 0) return;                                    // left button only
  if (!document.getElementById('page-lookahead')?.classList.contains('active')) return;
  // Bail on interactive children (buttons, fill handle, inputs)
  if (ev.target.closest('.tlg-fill-handle, button, a, input, select, textarea, .la-context-menu')) return;

  // ── Mode C: drag a ROW LABEL to reorder (Phase 2E) ───────────
  // Only in activity-mode (where group bands + sort_order are meaningful)
  // and not in assign mode (which already has a row-drop semantic).
  const rowLabel = ev.target.closest('.tlg-row-label');
  if (rowLabel && _laTimelineGroupBy === 'activity' && !_laAssignMode) {
    const row = rowLabel.closest('.tlg-data-row[data-activity-id]');
    if (row) {
      const actId = row.dataset.activityId;
      const a = PLANNING_ACTIVITIES.find(x => x.id === actId);
      if (a) {
        ev.preventDefault();
        _laRowDragState = {
          activityId:    actId,
          activity:      a,
          originRowEl:   row,
          startX:        ev.clientX,
          startY:        ev.clientY,
          didMove:       false,
          ghost:         null,
          dropIndicator: null,
          dropTarget:    null,   // { insertBefore: rowEl|null, group: 'tc'|... }
        };
        return;
      }
    }
  }

  const coord = _laCellCoord(ev.target);
  if (!coord || !coord.actId) return;

  const isCtrl = ev.ctrlKey || ev.metaKey;
  const shiftBlock = ev.target.closest('.tlg-shift-block');

  // ── Mode A: Ctrl+drag → range-paint ──────────────────────────
  if (isCtrl) {
    ev.preventDefault();
    const idx = _laBuildGridIndex();
    _laRangeSelState = {
      idx,
      anchorRow: idx.rowByActId.get(coord.actId),
      anchorCol: idx.colByDate.get(coord.iso),
      startX:   ev.clientX,
      startY:   ev.clientY,
      didMove:  false,
      baseKeys: new Set(_laSelectedCellKeys),   // additive — preserve prior picks
    };
    return;
  }

  // ── Mode B: plain drag on a colored cell → move ──────────────
  if (shiftBlock) {
    const eventId = shiftBlock.dataset.cellEventId;
    if (!eventId) return;
    // Skip drag on locked or cancelled events — they shouldn't move
    const evObj = PLANNING_EVENTS.find(e => e.id === eventId);
    if (!evObj || evObj.is_locked || evObj.status === 'cancelled') return;
    // Suppress native text-selection / HTML5 drag so our gesture wins
    ev.preventDefault();
    // If already selected → drag the whole selection; else drag just this one
    const sourceIds = _laSelectedCellKeys.has(eventId)
      ? [..._laSelectedCellKeys]
      : [eventId];
    _laMoveDragState = {
      anchorEventId: eventId,
      sourceIds,
      startX:  ev.clientX,
      startY:  ev.clientY,
      didMove: false,
      ghost:   null,
      dropCellEl: null,
    };
    console.log('[la-move] start drag', { eventId, sourceCount: sourceIds.length });
  }
}

function _laTimelineMouseMove(ev) {
  // ── Range-paint ──────────────────────────────────────────────
  if (_laRangeSelState) {
    const st = _laRangeSelState;
    if (!st.didMove) {
      const dx = Math.abs(ev.clientX - st.startX);
      const dy = Math.abs(ev.clientY - st.startY);
      if (dx + dy < _LA_DRAG_THRESHOLD_PX) return;
      st.didMove = true;
      document.body.classList.add('la-range-painting');
    }
    const hit = document.elementFromPoint(ev.clientX, ev.clientY);
    const coord = hit ? _laCellCoord(hit) : null;
    if (!coord || !coord.actId) return;
    const curRow = st.idx.rowByActId.get(coord.actId);
    const curCol = st.idx.colByDate.get(coord.iso);
    if (curRow == null || curCol == null) return;

    const r0 = Math.min(st.anchorRow, curRow), r1 = Math.max(st.anchorRow, curRow);
    const c0 = Math.min(st.anchorCol, curCol), c1 = Math.max(st.anchorCol, curCol);

    const newKeys = new Set(st.baseKeys);
    for (let r = r0; r <= r1; r++) {
      const rowEl = st.idx.rowEls[r];
      if (!rowEl) continue;
      rowEl.querySelectorAll('.tlg-data-cell[data-event-date]').forEach(c => {
        const col = st.idx.colByDate.get(c.dataset.eventDate);
        if (col == null || col < c0 || col > c1) return;
        c.querySelectorAll('.tlg-shift-block[data-cell-event-id]').forEach(sb => {
          newKeys.add(sb.dataset.cellEventId);
        });
      });
    }
    _laApplySelectionSet(newKeys);
    return;
  }

  // ── Move-drag ────────────────────────────────────────────────
  if (_laMoveDragState) {
    const st = _laMoveDragState;
    const dx = ev.clientX - st.startX;
    const dy = ev.clientY - st.startY;
    if (!st.didMove) {
      if (Math.abs(dx) + Math.abs(dy) < _LA_DRAG_THRESHOLD_PX) return;
      st.didMove = true;
      const ghost = document.createElement('div');
      ghost.className = 'la-move-ghost';
      ghost.textContent = st.sourceIds.length === 1
        ? '↔ Move 1 cell'
        : `↔ Move ${st.sourceIds.length} cells`;
      document.body.appendChild(ghost);
      st.ghost = ghost;
      document.body.classList.add('la-move-dragging');
      console.log('[la-move] crossed threshold — ghost spawned');
    }
    if (st.ghost) {
      st.ghost.style.left = (ev.clientX + 12) + 'px';
      st.ghost.style.top  = (ev.clientY + 12) + 'px';
    }
    const hit = document.elementFromPoint(ev.clientX, ev.clientY);
    const coord = hit ? _laCellCoord(hit) : null;
    const newDrop = (coord && coord.actId) ? coord.cell : null;
    if (st.dropCellEl !== newDrop) {
      st.dropCellEl?.classList.remove('la-move-target');
      st.dropCellEl = newDrop;
      newDrop?.classList.add('la-move-target');
    }
  }

  // ── Row drag-reorder (Phase 2E) ──────────────────────────────
  if (_laRowDragState) {
    const st = _laRowDragState;
    const dx = ev.clientX - st.startX;
    const dy = ev.clientY - st.startY;
    if (!st.didMove) {
      if (Math.abs(dx) + Math.abs(dy) < _LA_DRAG_THRESHOLD_PX) return;
      st.didMove = true;
      // Ghost
      const ghost = document.createElement('div');
      ghost.className = 'la-row-ghost';
      ghost.textContent = `↕ ${st.activity.description || st.activity.activity_id_text || 'row'}`;
      document.body.appendChild(ghost);
      st.ghost = ghost;
      // Drop indicator (horizontal line)
      const ind = document.createElement('div');
      ind.className = 'la-row-drop-indicator';
      document.body.appendChild(ind);
      st.dropIndicator = ind;
      document.body.classList.add('la-row-dragging');
      st.originRowEl.classList.add('la-row-dragging-src');
    }
    if (st.ghost) {
      st.ghost.style.left = (ev.clientX + 12) + 'px';
      st.ghost.style.top  = (ev.clientY + 12) + 'px';
    }

    // Find the row OR group header under the cursor (within .tlg-shell)
    const hit = document.elementFromPoint(ev.clientX, ev.clientY);
    const targetRow  = hit?.closest('.tlg-data-row[data-activity-id]');
    const targetGrpHdr = hit?.closest('.tlg-grp-hdr-row');

    if (targetRow && targetRow !== st.originRowEl) {
      // Drop into a row: above or below based on cursor vertical position
      const r = targetRow.getBoundingClientRect();
      const above = ev.clientY < r.top + r.height / 2;
      const insertBefore = above ? targetRow : targetRow.nextElementSibling;
      // Resolve the group from the nearest preceding band header
      const group = _laFindRowGroup(targetRow);
      st.dropTarget = { insertBefore, group };
      st.dropIndicator.style.display = 'block';
      st.dropIndicator.style.left  = r.left + 'px';
      st.dropIndicator.style.width = r.width + 'px';
      st.dropIndicator.style.top   = (above ? r.top : r.bottom) - 1 + 'px';
    } else if (targetGrpHdr) {
      // Drop onto a group band — append to that group (sort_order = max+10)
      const groupKey = targetGrpHdr.dataset.groupKey || _laFindGroupKeyFromHeader(targetGrpHdr);
      st.dropTarget = { insertBefore: targetGrpHdr.nextElementSibling, group: groupKey };
      const r = targetGrpHdr.getBoundingClientRect();
      st.dropIndicator.style.display = 'block';
      st.dropIndicator.style.left  = r.left + 'px';
      st.dropIndicator.style.width = r.width + 'px';
      st.dropIndicator.style.top   = (r.bottom - 1) + 'px';
    } else {
      st.dropTarget = null;
      st.dropIndicator.style.display = 'none';
    }
  }
}

// Walk back from a data-row to find which activity_group band precedes it
function _laFindRowGroup(rowEl) {
  let n = rowEl.previousElementSibling;
  while (n) {
    if (n.classList.contains('tlg-grp-hdr-row')) {
      return n.dataset.groupKey || _laFindGroupKeyFromHeader(n);
    }
    n = n.previousElementSibling;
  }
  return 'tc';
}
function _laFindGroupKeyFromHeader(hdrEl) {
  // Parse from the onclick attr we set on the band header
  const m = hdrEl.getAttribute('onclick')?.match(/_laToggleGroupCollapse\('([^']+)'\)/);
  return m ? m[1] : 'other';
}

async function _laTimelineMouseUp(ev) {
  // ── Range-paint finish ──────────────────────────────────────
  if (_laRangeSelState) {
    const didMove = _laRangeSelState.didMove;
    _laRangeSelState = null;
    document.body.classList.remove('la-range-painting');
    if (didMove) {
      _laSuppressNextClick = true;
      setTimeout(() => { _laSuppressNextClick = false; }, 60);
    }
    return;
  }

  // ── Move-drag finish ────────────────────────────────────────
  if (_laMoveDragState) {
    const st = _laMoveDragState;
    _laMoveDragState = null;
    st.ghost?.remove();
    document.body.classList.remove('la-move-dragging');
    st.dropCellEl?.classList.remove('la-move-target');
    if (!st.didMove) { console.log('[la-move] no drag — treating as click'); return; }
    _laSuppressNextClick = true;
    setTimeout(() => { _laSuppressNextClick = false; }, 60);

    const dropCell = st.dropCellEl;
    console.log('[la-move] drop', { dropCell, targetActId: dropCell?.dataset.activityId, targetIso: dropCell?.dataset.eventDate });
    if (!dropCell) { toast('Drop on a cell to move.', 'warn'); return; }
    const targetActId = dropCell.dataset.activityId;
    const targetIso   = dropCell.dataset.eventDate;
    if (!targetActId || !targetIso) return;

    // Same-cell drop with single source → noop
    if (st.sourceIds.length === 1) {
      const src = PLANNING_EVENTS.find(e => e.id === st.sourceIds[0]);
      if (src && src.planning_activity_id === targetActId && src.event_date === targetIso) return;
    }

    // Reuse the cut+paste pipeline so collisions/lock/PTO are handled identically.
    _laSelectedCellKeys.clear();
    st.sourceIds.forEach(id => _laSelectedCellKeys.add(id));
    _laCopySelection('cut', { silent: true });
    _laSetPasteTarget(targetActId, targetIso, dropCell);
    await _laPasteAtTarget();
  }

  // ── Row-drag finish (Phase 2E) ──────────────────────────────
  if (_laRowDragState) {
    const st = _laRowDragState;
    _laRowDragState = null;
    st.ghost?.remove();
    st.dropIndicator?.remove();
    document.body.classList.remove('la-row-dragging');
    st.originRowEl?.classList.remove('la-row-dragging-src');
    if (!st.didMove) return;                  // not a drag, let click pass through
    _laSuppressNextClick = true;
    setTimeout(() => { _laSuppressNextClick = false; }, 60);

    if (!st.dropTarget) return;
    const { insertBefore, group } = st.dropTarget;

    // Compute new sort_order from neighbors in the destination band:
    //   - find the rendered activity rows currently between this group's
    //     band header and the next band header
    //   - find the rows that flank the drop position (prev, next)
    //   - new sort_order = midpoint, or max+10 if at end, or min-10 if at top
    const newOrder = _laComputeDropSortOrder(group, insertBefore, st.activityId);
    if (newOrder == null) return;

    try {
      await _dbUpdate('planning_activities', {
        activity_group: group,
        sort_order:     newOrder,
      }, { id: st.activityId });
      toast(`✓ Row moved to ${_groupMeta(group).label}`, 'success');
      await loadPlanningData(true);
      _renderLookaheadTabBody();
    } catch (err) {
      toast('Move failed: ' + err.message, 'error');
    }
  }
}

// Compute the new sort_order for a row being dropped before `insertBefore`
// (or at end of group if insertBefore is null/outside the group). The
// resulting integer is midway between flanking neighbors, or max+10 at the
// tail / min-10 at the head, to preserve drag gaps.
function _laComputeDropSortOrder(targetGroup, insertBefore, draggedId) {
  // Build the list of activities currently in the target group, by sort_order
  const peers = (PLANNING_ACTIVITIES || [])
    .filter(a => !a.deleted_at && (a.activity_group || 'other') === targetGroup && a.id !== draggedId)
    .sort((a, b) => (a.sort_order ?? 999999) - (b.sort_order ?? 999999));

  // Identify the activity that the cursor was hovering "just above"
  const beforeActId = insertBefore?.dataset?.activityId || null;
  const idx = beforeActId ? peers.findIndex(p => p.id === beforeActId) : -1;

  if (peers.length === 0)          return 10;                           // empty group
  if (idx === -1)                  return (peers[peers.length - 1].sort_order ?? 0) + 10;  // append
  if (idx === 0)                   return Math.max(1, (peers[0].sort_order ?? 10) - 10);   // prepend
  const prev = peers[idx - 1].sort_order ?? 0;
  const next = peers[idx].sort_order ?? (prev + 20);
  if (next - prev <= 1) {
    // gaps exhausted — return prev+1 and trigger background renumber later
    console.warn('[reorder] sort_order gap exhausted between', prev, 'and', next);
    return prev + 1;
  }
  return Math.round((prev + next) / 2);
}

document.addEventListener('mousedown', _laTimelineMouseDown);
document.addEventListener('mousemove', _laTimelineMouseMove);
document.addEventListener('mouseup',   _laTimelineMouseUp);

// Swallow the click that follows a drag so we don't open the detail modal
// (or toggle selection) on mouseup. Capture-phase so it runs before onclick.
// Clear the flag on first click so we don't keep suppressing future clicks.
document.addEventListener('click', function(ev) {
  if (_laSuppressNextClick) {
    _laSuppressNextClick = false;
    ev.preventDefault();
    ev.stopPropagation();
    ev.stopImmediatePropagation();
  }
}, true);

// ─── Drag-to-fill (Excel fill-handle) ──────────────────────────
// Grab the small handle on the right edge of a colored cell, drag horizontally,
// and on release the source event is duplicated onto every empty cell in range.
let _laFillState = null;   // { srcEventId, srcActId, srcDate, currentTargets: [{actId,date,el}] }

function _laFillStart(ev, eventId, actId, iso, sourceCellEl) {
  ev.preventDefault();
  ev.stopPropagation();
  if (!actId) {
    console.warn('[_laFillStart] No activity id — drag fill requires Activity group-by view.');
    toast('Drag-fill works in Activity group-by view only.', 'warn');
    return;
  }
  console.log(`[_laFillStart] dragging from event=${eventId} activity=${actId} date=${iso}`);
  _laFillState = {
    srcEventId: eventId,
    srcActId: actId,
    srcDate: iso,
    sourceCellEl,
    currentTargets: [],
    didDrag: false,
  };
  document.body.classList.add('la-fill-active');
  sourceCellEl?.classList.add('la-fill-source');
  document.addEventListener('mousemove', _laFillMove);
  document.addEventListener('mouseup', _laFillEnd);
  // Swallow the next click event so the cell's onclick (open detail) doesn't fire
  // after the user releases the drag.
  const swallowClick = (e) => {
    e.preventDefault();
    e.stopPropagation();
    document.removeEventListener('click', swallowClick, true);
  };
  document.addEventListener('click', swallowClick, true);
}

function _laFillMove(ev) {
  if (!_laFillState) return;
  _laFillState.didDrag = true;
  // Use elementFromPoint to find the cell under cursor
  const target = document.elementFromPoint(ev.clientX, ev.clientY);
  if (!target) return;
  // Walk up to the tlg-data-cell (or shift-block which lives inside)
  const cellEl = target.closest('.tlg-data-cell');
  if (!cellEl) return;
  const actId = cellEl.dataset.activityId;
  const date = cellEl.dataset.eventDate;
  if (!actId || !date) return;
  // Only allow filling within the source row (same activity)
  if (actId !== _laFillState.srcActId) return;

  // Compute the range from source to current target (inclusive, by date)
  const start = _laFillState.srcDate < date ? _laFillState.srcDate : date;
  const end   = _laFillState.srcDate < date ? date : _laFillState.srcDate;

  // Clear old highlights
  _laFillState.currentTargets.forEach(t => t.el?.classList.remove('la-fill-target'));
  _laFillState.currentTargets = [];

  // Find every tlg-data-cell in this row whose date falls in [start, end]
  document.querySelectorAll(`.tlg-data-cell[data-activity-id="${_laFillState.srcActId}"]`).forEach(c => {
    const d = c.dataset.eventDate;
    if (d >= start && d <= end && d !== _laFillState.srcDate) {
      c.classList.add('la-fill-target');
      _laFillState.currentTargets.push({ actId: _laFillState.srcActId, date: d, el: c });
    }
  });

  // Update the preview count badge on the source cell
  const badge = _laFillState.sourceCellEl?.querySelector('.tlg-fill-count');
  const n = _laFillState.currentTargets.length;
  if (badge) badge.textContent = n > 0 ? `+${n}` : '';
  else if (n > 0 && _laFillState.sourceCellEl) {
    const b = document.createElement('span');
    b.className = 'tlg-fill-count';
    b.textContent = `+${n}`;
    _laFillState.sourceCellEl.appendChild(b);
  }
}

async function _laFillEnd(ev) {
  document.removeEventListener('mousemove', _laFillMove);
  document.removeEventListener('mouseup', _laFillEnd);
  document.body.classList.remove('la-fill-active');
  if (!_laFillState) return;

  const { srcEventId, currentTargets, sourceCellEl, didDrag } = _laFillState;
  sourceCellEl?.classList.remove('la-fill-source');
  sourceCellEl?.querySelector('.tlg-fill-count')?.remove();
  currentTargets.forEach(t => t.el?.classList.remove('la-fill-target'));

  if (currentTargets.length === 0) {
    if (didDrag) toast('Drag further across cells in the same row to fill.', 'warn');
    console.log(`[_laFillEnd] no targets (didDrag=${didDrag}) — release happened on source cell.`);
    _laFillState = null;
    return;
  }
  console.log(`[_laFillEnd] filling ${currentTargets.length} cells`);

  const src = PLANNING_EVENTS.find(e => e.id === srcEventId);
  if (!src) { _laFillState = null; toast('Source event not found', 'error'); return; }

  // Detect any locked cells in the range — those are skipped silently
  // Detect collisions (existing events on target dates) — confirm once
  const collisions = [];
  const lockedSkips = [];
  const ptoConflicts = [];
  const srcResources = PLANNING_EVENT_RES.filter(er => er.event_id === srcEventId);

  currentTargets.forEach(t => {
    const existing = PLANNING_EVENTS.find(e =>
      e.planning_activity_id === t.actId &&
      e.event_date === t.date &&
      e.status !== 'cancelled'
    );
    if (existing) {
      if (existing.is_locked) lockedSkips.push(t);
      else collisions.push({ target: t, existing });
    }
    srcResources.forEach(er => {
      const onPTO = PTO_REQUESTS.some(p =>
        p.status === 'approved' &&
        p.resource_id === er.resource_id &&
        t.date >= p.start_date && t.date <= p.end_date
      );
      if (onPTO) {
        const r = PLANNING_RESOURCES.find(x => x.id === er.resource_id);
        ptoConflicts.push({ name: r?.display_name || '?', date: t.date });
      }
    });
  });

  let collisionAction = 'overwrite';
  if (collisions.length > 0 || lockedSkips.length > 0 || ptoConflicts.length > 0) {
    const decision = await _laFillConfirmModal({
      total: currentTargets.length, collisions, lockedSkips, ptoConflicts,
    });
    if (!decision) { _laFillState = null; return; }
    collisionAction = decision.collisionAction;
  }

  let inserted = 0, overwritten = 0, skipped = 0;
  for (const t of currentTargets) {
    try {
      const existing = PLANNING_EVENTS.find(e =>
        e.planning_activity_id === t.actId &&
        e.event_date === t.date &&
        e.status !== 'cancelled'
      );
      if (existing && existing.is_locked) { skipped++; continue; }
      if (existing) {
        if (collisionAction === 'skip') { skipped++; continue; }
        await _dbDelete('planning_event_resources', { event_id: existing.id });
        await _dbDelete('planning_events', { id: existing.id });
        overwritten++;
      }
      const payload = {
        planning_activity_id: t.actId,
        title: src.title,
        event_date: t.date,
        start_time: src.start_time,
        end_time: src.end_time,
        all_day: src.all_day,
        location: src.location,
        work_hours_raw: src.work_hours_raw,
        shift_type: src.shift_type,
        cell_color_hex: src.cell_color_hex,
        source: 'manual',
        status: 'planned',
        is_locked: false,
        notes: src.notes,
        created_by: currentProfile?.id || null,
        updated_by: currentProfile?.id || null,
      };
      const newRows = await _dbInsert('planning_events', [payload]);
      inserted++;
      const newId = newRows?.[0]?.id;
      if (newId && srcResources.length > 0) {
        await _dbInsert('planning_event_resources', srcResources.map(er => ({
          event_id:          newId,
          resource_id:       er.resource_id,
          role:              er.role || 'owner',
          quantity:          er.quantity || 1,
          assignment_source: er.assignment_source || 'manual',
          notes:             er.notes || null,
        })));
      }
    } catch (err) {
      console.error('[fill] target failed:', err);
    }
  }

  toast(`✓ Filled: ${inserted} created${overwritten?`, ${overwritten} overwritten`:''}${skipped?`, ${skipped} skipped`:''}`, 'success');
  _laFillState = null;
  await loadPlanningData(true);
  _renderLookaheadTabBody();
}

function _laFillConfirmModal({ total, collisions, lockedSkips, ptoConflicts }) {
  return new Promise(resolve => {
    let html = '<div style="font-size:13px;max-height:60vh;overflow-y:auto;">';
    html += `<p style="margin:0 0 10px;">Fill <strong>${total}</strong> cell${total>1?'s':''} from this event.</p>`;
    if (lockedSkips.length > 0) {
      html += `<div style="background:#fef3c7;border:1px solid #f59e0b;border-radius:6px;padding:10px;margin:10px 0;">
        <strong>🔒 ${lockedSkips.length} locked</strong> — will be skipped silently.
      </div>`;
    }
    if (collisions.length > 0) {
      html += `<div style="background:#fee2e2;border:1px solid #ef4444;border-radius:6px;padding:10px;margin:10px 0;">
        <strong>⚠ ${collisions.length} existing event${collisions.length>1?'s':''}</strong> in the fill range.<br>
        <label style="display:block;margin-top:8px;"><input type="radio" name="fillcol" value="overwrite" checked> Overwrite existing</label>
        <label style="display:block;"><input type="radio" name="fillcol" value="skip"> Skip these (keep existing)</label>
      </div>`;
    }
    if (ptoConflicts.length > 0) {
      html += `<div style="background:#fef3c7;border:1px solid #f59e0b;border-radius:6px;padding:10px;margin:10px 0;">
        <strong>🌴 ${ptoConflicts.length} PTO conflict${ptoConflicts.length>1?'s':''}:</strong>
        <ul style="margin:4px 0 0 18px;padding:0;font-size:12px;">
          ${ptoConflicts.slice(0,8).map(c => `<li>${escapeHtml(c.name)} on ${c.date}</li>`).join('')}
          ${ptoConflicts.length>8?`<li>…and ${ptoConflicts.length-8} more</li>`:''}
        </ul>
      </div>`;
    }
    html += '</div>';
    modal({
      title: 'Confirm Fill',
      body: html,
      footer: `
        <button class="form-secondary" onclick="window._laFillResolve(null)">Cancel</button>
        <button class="form-submit" onclick="window._laFillResolve('go')">Continue Fill</button>
      `,
    });
    window._laFillResolve = (result) => {
      if (!result) { closeModal(); resolve(null); return; }
      const radio = document.querySelector('input[name="fillcol"]:checked');
      const collisionAction = radio ? radio.value : 'overwrite';
      closeModal();
      delete window._laFillResolve;
      resolve({ collisionAction });
    };
  });
}

// ─── Add Activity Row (build schedule from scratch) ────────────
function _laOpenNewActivityModal() {
  modal({
    title: '+ Add Activity',
    sub: 'Create a new row for the lookahead grid',
    size: 'medium',
    body: `
      <div class="form-grid">
        <div class="form-field">
          <label>Activity ID <span style="font-size:11px;font-weight:400;color:var(--gray-500);">— auto-filled if P6 linked</span></label>
          <input type="text" id="new-act-id" class="form-input" placeholder="DCS-101">
        </div>
        <div class="form-field">
          <label>Location <span style="color:#dc2626;">*</span></label>
          <input type="text" id="new-act-loc" class="form-input" placeholder="W40, Cab, Hayward, etc." oninput="_laNewActivityLocChanged()">
          <div id="new-act-loc-phase-hint" style="font-size:11px;margin-top:3px;min-height:16px;"></div>
        </div>
        <div class="form-field">
          <label>Phase</label>
          <input type="text" id="new-act-phase" class="form-input" placeholder="e.g. Phase 1">
        </div>
        <div class="form-field form-field-full">
          <label>Description <span style="color:#dc2626;">*</span></label>
          <input type="text" id="new-act-desc" class="form-input" placeholder="What is this activity?" required>
        </div>
        <div class="form-field">
          <label>SSWP</label>
          <input type="text" id="new-act-sswp" class="form-input" placeholder="SSWP reference">
        </div>
        <div class="form-field form-field-full">
          <label>🔗 P6 Activity <span style="font-size:11px;font-weight:400;color:var(--gray-500);">— filtered by location · auto-fills Activity ID</span></label>
          <select id="new-act-p6" class="form-input" onchange="_laNewActivityP6Changed()">
            <option value="">— Not linked —</option>
          </select>
        </div>
        <div class="form-field form-field-full">
          <label>🔗 Test Register Activity <span style="font-size:11px;font-weight:400;color:var(--gray-500);">— filtered by location</span></label>
          <select id="new-act-linked-tra" class="form-input">
            <option value="">— Not linked —</option>
          </select>
        </div>
        <div class="form-field form-field-full">
          <label>Notes</label>
          <textarea id="new-act-notes" class="form-input" rows="2"></textarea>
        </div>
      </div>
      <p style="font-size:12px;color:var(--gray-500);margin-top:14px;line-height:1.5;">
        After creating, the new row appears in the lookahead. Add shift cells by clicking a cell or using copy/paste.
        Work hours (e.g. 0700–1500) are set per day-cell in the cell details drawer.
      </p>
    `,
    footer: `
      <button class="form-secondary" onclick="closeModal()">Cancel</button>
      <button class="form-submit" onclick="_laSaveNewActivity()">Create Activity</button>
    `,
  });
  // Populate cascade pickers (unfiltered on open)
  _laNewActivityRebuildLinks();
  setTimeout(() => document.getElementById('new-act-desc')?.focus(), 50);
}

// Called on every keystroke in the Location field — auto-fills phase + rebuilds pickers
function _laNewActivityLocChanged() {
  _laNewActivityRebuildLinks();
  const locVal  = (document.getElementById('new-act-loc')?.value || '').trim();
  const phaseEl = document.getElementById('new-act-phase');
  const hintEl  = document.getElementById('new-act-loc-phase-hint');
  if (!phaseEl || !hintEl) return;
  const inferred = _laInferPhaseFromLocation(locVal);
  const current  = phaseEl.value.trim();
  if (!inferred) {
    hintEl.innerHTML = locVal ? `<span style="color:var(--gray-400);">Ad-hoc location — set phase manually if needed</span>` : '';
    return;
  }
  if (!current || current === inferred) {
    phaseEl.value = inferred;
    hintEl.innerHTML = `<span style="color:var(--good);">✓ Phase auto-set: ${escapeHtml(inferred)}</span>`;
  } else {
    const safe = JSON.stringify(inferred);
    hintEl.innerHTML = `<span>Master suggests: <strong>${escapeHtml(inferred)}</strong></span>
      <button type="button" class="form-secondary" style="font-size:10px;padding:1px 6px;margin-left:6px;"
        onclick="document.getElementById('new-act-phase').value=${safe};document.getElementById('new-act-loc-phase-hint').innerHTML='<span style=\'color:var(--good);\'>✓ Phase auto-set: ${escapeHtml(inferred)}</span>';">Use</button>`;
  }
}

// Called when P6 picker changes — auto-fills Activity ID from p6_id
function _laNewActivityP6Changed() {
  const p6El  = document.getElementById('new-act-p6');
  const idEl  = document.getElementById('new-act-id');
  if (!p6El || !idEl) return;
  const p6Id = p6El.tomselect ? p6El.tomselect.getValue() : p6El.value;
  if (!p6Id) {
    idEl.style.color = '';
    return;
  }
  const p6 = (P6_ACTS || []).find(p => p.id === p6Id);
  if (p6) {
    idEl.value = p6.p6_id || p6.p6_name || '';
    idEl.style.color = 'var(--blue)';
  }
}

// Rebuilds both P6 and TRA dropdowns, cascade-filtered by current Location value
function _laNewActivityRebuildLinks() {
  const loc = (document.getElementById('new-act-loc')?.value || '').trim();

  // ── P6 options ──
  const p6Pool = (P6_ACTS || []).filter(p =>
    !loc || _laMatchesLocation(loc, (p.p6_location_code || '').trim())
  );
  p6Pool.sort((a, b) => (a.p6_id || '').localeCompare(b.p6_id || ''));
  const p6El = document.getElementById('new-act-p6');
  if (p6El) {
    const curP6 = p6El.tomselect ? p6El.tomselect.getValue() : p6El.value;
    if (p6El.tomselect) { try { p6El.tomselect.destroy(); } catch {} }
    p6El.innerHTML = '<option value="">— Not linked —</option>' +
      p6Pool.map(p => `<option value="${p.id}" ${p.id === curP6 ? 'selected' : ''}>${escapeHtml(p.p6_id || '?')} · ${escapeHtml((p.p6_name || '').slice(0, 55))}${(p.p6_name || '').length > 55 ? '…' : ''}</option>`).join('');
    if (window.TomSelect) { try { new TomSelect('#new-act-p6', { create: false, allowEmptyOption: true }); } catch {} }
  }

  // ── TRA options ──
  const pool = TI.filter(t =>
    !loc || _laMatchesLocation(loc, (t.Location || '').trim())
  );
  const activityCounts = {};
  pool.forEach(t => { const k = (t.Activity || '').trim(); if (k) activityCounts[k] = (activityCounts[k] || 0) + 1; });
  const sortedActs = Object.entries(activityCounts).sort((a, b) => a[0].localeCompare(b[0]));
  const traEl = document.getElementById('new-act-linked-tra');
  if (traEl) {
    const curTRA = traEl.tomselect ? traEl.tomselect.getValue() : traEl.value;
    if (traEl.tomselect) { try { traEl.tomselect.destroy(); } catch {} }
    traEl.innerHTML = '<option value="">— Not linked —</option>' +
      sortedActs.map(([name, count]) => `<option value="${escapeHtml(name)}" ${name === curTRA ? 'selected' : ''}>${escapeHtml(name)} (${count} test${count > 1 ? 's' : ''})</option>`).join('');
    if (window.TomSelect) { try { new TomSelect('#new-act-linked-tra', { create: false, allowEmptyOption: true }); } catch {} }
  }
}

async function _laSaveNewActivity() {
  const desc = document.getElementById('new-act-desc').value.trim();
  const loc  = document.getElementById('new-act-loc').value.trim();
  if (!desc) { toast('Description is required', 'error'); return; }
  if (!loc)  { toast('Location is required', 'error'); return; }
  const defaultGroup = 'tc';
  const groupMaxSort = (PLANNING_ACTIVITIES || [])
    .filter(a => a.activity_group === defaultGroup)
    .reduce((m, a) => Math.max(m, a.sort_order || 0), 0);

  // Read TomSelect-aware values
  const p6El  = document.getElementById('new-act-p6');
  const traEl = document.getElementById('new-act-linked-tra');
  const p6Id  = p6El?.tomselect  ? p6El.tomselect.getValue()  : (p6El?.value  || '');
  const tra   = traEl?.tomselect ? traEl.tomselect.getValue() : (traEl?.value || '');

  const payload = {
    activity_id_text: document.getElementById('new-act-id').value.trim()    || null,
    phase:            document.getElementById('new-act-phase')?.value.trim() || null,
    description: desc,
    location: loc,
    sswp: document.getElementById('new-act-sswp').value.trim() || null,
    notes: document.getElementById('new-act-notes').value.trim() || null,
    linked_test_register_activity: tra   || null,
    linked_p6_activity_id:         p6Id  || null,
    match_status: 'manual',
    activity_group: defaultGroup,
    sort_order:    groupMaxSort + 10,
    batch_id: null,
  };
  try {
    await _dbInsert('planning_activities', [payload]);
    closeModal();
    toast('✓ Activity created', 'success');
    await loadPlanningData(true);
    _renderLookaheadTabBody();
  } catch (err) {
    toast('Create failed: ' + err.message, 'error');
  }
}
// ─── Right-click context menu on cells ─────────────────────────
function _laCellContextMenu(ev, eventId, actId, iso, el) {
  ev.preventDefault();
  // Remove any existing menu
  document.querySelectorAll('.la-context-menu').forEach(x => x.remove());

  const onColored = !!eventId;
  const ev_obj    = onColored ? PLANNING_EVENTS.find(e => e.id === eventId) : null;
  const isLocked  = !!ev_obj?.is_locked;
  const hasClip   = !!_laClipboard;

  // If clicking a colored cell that's not already in the selection, select just it
  if (onColored && !_laSelectedCellKeys.has(eventId)) {
    _laClearCellSelection();
    _laToggleCellSelect(eventId, el);
  }

  const items = [];
  if (onColored) {
    items.push({ label: '🔍 Open details',  fn: () => _planningOpenEventDetail(eventId) });
    items.push({ label: '📋 Copy',          fn: () => _laCopySelection('copy'), title: 'Ctrl+C' });
    items.push({ label: '✂ Cut',            fn: () => _laCopySelection('cut'),  disabled: isLocked, title: 'Ctrl+X' });
    items.push({ label: isLocked ? '🔒 Locked — can\'t delete' : '🗑 Delete', fn: () => _laDeleteSelection(), disabled: isLocked, title: 'Del' });
    items.push({ label: isLocked ? '🔒 Locked — can\'t cancel' : '🚫 Cancel event(s)', fn: () => _laBulkCancelCells(), disabled: isLocked });
  } else {
    if (hasClip) {
      items.push({
        label: `📥 Paste here (${_laClipboard.items.length})`,
        fn: () => {
          _laSetPasteTarget(actId, iso, el);
          _laPasteAtTarget();
        },
        title: 'Ctrl+V',
      });
      items.push({ label: '📍 Set as paste target', fn: () => _laSetPasteTarget(actId, iso, el) });
    } else {
      items.push({ label: 'Copy a cell first (Ctrl+C)', disabled: true });
    }
  }

  const menu = document.createElement('div');
  menu.className = 'la-context-menu';
  menu.style.cssText = `position:fixed;left:${ev.clientX}px;top:${ev.clientY}px;z-index:99999;
    background:#fff;border:1px solid #d1d5db;border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,0.18);
    padding:6px 0;min-width:200px;font-size:13px;`;
  menu.innerHTML = items.map(it => {
    if (it.disabled) {
      return `<div style="padding:6px 14px;color:#9ca3af;cursor:not-allowed;">${escapeHtml(it.label)}</div>`;
    }
    return `<div class="la-context-menu-item"
      style="padding:6px 14px;cursor:pointer;display:flex;justify-content:space-between;align-items:center;"
      onmouseover="this.style.background='#f3f4f6';"
      onmouseout="this.style.background='';">
      <span>${escapeHtml(it.label)}</span>
      ${it.title ? `<span style="color:#9ca3af;font-size:11px;margin-left:14px;">${it.title}</span>` : ''}
    </div>`;
  }).join('');

  document.body.appendChild(menu);

  // Wire up the click handlers (avoid inline since fn references are closures)
  [...menu.querySelectorAll('.la-context-menu-item')].forEach((node, i) => {
    const enabledItems = items.filter(x => !x.disabled);
    const fn = enabledItems[i]?.fn;
    if (fn) node.addEventListener('click', () => { menu.remove(); fn(); });
  });

  // Click outside to dismiss
  setTimeout(() => {
    const dismiss = (e) => {
      if (!menu.contains(e.target)) { menu.remove(); document.removeEventListener('mousedown', dismiss); }
    };
    document.addEventListener('mousedown', dismiss);
  }, 0);

  return false;
}

async function _laBulkRemoveCellResources() {
  const eventIds = [..._laSelectedCellKeys];
  if (!eventIds.length) return;

  const totalRows = PLANNING_EVENT_RES.filter(er => eventIds.includes(er.event_id)).length;
  if (!totalRows) { toast('No resources assigned to selected cells', 'warn'); return; }

  const count = eventIds.length;
  if (!confirm(`Remove all resources from ${count} shift${count>1?'s':''}? This cannot be undone.`)) return;

  try {
    // Delete event_resources for each selected event
    for (const eid of eventIds) {
      const rows = PLANNING_EVENT_RES.filter(er => er.event_id === eid);
      for (const row of rows) {
        await _dbDelete('planning_event_resources', { event_id: eid, resource_id: row.resource_id });
      }
    }
    _laSelectedCellKeys.clear();
    toast(`Resources cleared from ${count} shift${count>1?'s':''}`, 'success');
    await loadPlanningData(true);
    _laMountLookaheadTL();
  } catch (err) {
    toast('Bulk remove failed: ' + err.message, 'error');
  }
}

// ─── HTML5 Drag-and-Drop ─────────────────────────────────────
function _laStartResourceDrag(resourceId, el) {
  // If the dragged card is part of the selection, carry ALL selected IDs.
  // Otherwise drag only this card (and clear the selection).
  if (_laSelectedResIds.has(resourceId)) {
    _laCurrentDragRes = [..._laSelectedResIds];
  } else {
    _laSelectedResIds.clear();
    _laCurrentDragRes = [resourceId];
  }
  if (el) el.classList.add('la-res-card-dragging');
}

function _laEndResourceDrag(el) {
  _laCurrentDragRes = null;
  if (el) el.classList.remove('la-res-card-dragging');
  // Clear any leftover highlights
  document.querySelectorAll('.la-row-droppable').forEach(r => r.classList.remove('la-drop-over'));
}

function _laInitAssignDnD(gridEl) {
  let _overCell  = null;
  let _overLabel = null;

  function _clearHighlights() {
    if (_overCell)  { _overCell.classList.remove('la-cell-drop-over');   _overCell  = null; }
    if (_overLabel) { _overLabel.classList.remove('la-row-label-over');  _overLabel = null; }
  }

  gridEl.addEventListener('dragover', e => {
    if (!_laCurrentDragRes || !_laCurrentDragRes.length) return;

    // Priority: cell (specific date) > label (whole activity)
    const cell  = e.target.closest('.la-cell-droppable');
    const label = !cell && e.target.closest('.la-drop-label');
    if (!cell && !label) return;

    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';

    if (cell && cell !== _overCell) {
      _clearHighlights();
      cell.classList.add('la-cell-drop-over');
      _overCell = cell;
    } else if (label && label !== _overLabel) {
      _clearHighlights();
      label.classList.add('la-row-label-over');
      _overLabel = label;
    }
  });

  gridEl.addEventListener('dragleave', e => {
    // Only clear if leaving the highlighted element entirely
    if (_overCell  && !_overCell.contains(e.relatedTarget))  { _overCell.classList.remove('la-cell-drop-over');  _overCell  = null; }
    if (_overLabel && !_overLabel.contains(e.relatedTarget)) { _overLabel.classList.remove('la-row-label-over'); _overLabel = null; }
  });

  gridEl.addEventListener('drop', e => {
    e.preventDefault();
    const cell  = e.target.closest('.la-cell-droppable');
    const label = !cell && e.target.closest('.la-drop-label');
    _clearHighlights();

    const resourceIds = _laCurrentDragRes;  // now an array
    _laCurrentDragRes = null;
    if (!resourceIds || !resourceIds.length) return;

    if (cell) {
      // Drop on a shift cell → assign all selected resources to that specific event/date
      const activityId = cell.dataset.activityId;
      const eventDate  = cell.dataset.eventDate;
      if (activityId && eventDate) {
        resourceIds.forEach(rid => _laAssignResourceToEvent(activityId, eventDate, rid));
      }
    } else if (label) {
      // Drop on the row label → assign all selected resources to the full activity
      const activityId = label.dataset.activityId;
      if (activityId) {
        resourceIds.forEach(rid => _laAssignResourceToActivity(activityId, rid));
      }
    }
  });
}

// ─── Assign / Remove ─────────────────────────────────────────
// Detect conflicts a resource assignment would create:
//  • PTO overlap   — resource has approved PTO on the event date
//  • Double-booked  — resource already on another event the same day
//                     whose shift time overlaps
// Returns an array of conflict descriptors (empty if clean).
function _laDetectAssignmentConflicts(resourceId, events) {
  const r = (PLANNING_RESOURCES || []).find(x => x.id === resourceId);
  const name = r?.display_name || 'Resource';
  const found = [];
  for (const ev of (events || [])) {
    if (!ev || ev.status === 'cancelled') continue;

    // PTO overlap
    const pto = _ptoOverlapsRange(resourceId, ev.event_date, ev.start_time, ev.end_time);
    if (pto) {
      found.push({
        kind: 'pto', ev, pto,
        text: `${name} is on approved PTO (${pto.start_date} → ${pto.end_date}) during "${ev.title || 'shift'}" on ${ev.event_date}`,
        row: {
          event_id: ev.id, resource_id: resourceId,
          conflict_type: 'pto_overlap', severity: 'critical',
          message: `${name} is on approved PTO during "${ev.title || 'shift'}" on ${ev.event_date}`,
          payload_json: { pto_id: pto.id, event_id: ev.id, resource_id: resourceId },
        },
      });
    }

    // Double-booked — resource already on a different overlapping event
    (PLANNING_EVENT_RES || [])
      .filter(er => er.resource_id === resourceId && er.event_id !== ev.id)
      .forEach(er => {
        const other = (PLANNING_EVENTS || []).find(e => e.id === er.event_id);
        if (!other || other.status === 'cancelled') return;
        if (!_planningEventsOverlap(ev, other)) return;
        if (found.some(f => f.kind === 'double' && f.ev.id === ev.id && f.otherEv?.id === other.id)) return;
        const oAct = (PLANNING_ACTIVITIES || []).find(a => a.id === other.planning_activity_id);
        const tAct = (PLANNING_ACTIVITIES || []).find(a => a.id === ev.planning_activity_id);
        const oLoc = oAct?.location || other.location || other.title || 'another shift';
        const tLoc = tAct?.location || ev.location || ev.title || 'this shift';
        found.push({
          kind: 'double', ev, otherEv: other,
          text: `${name} is already booked on ${ev.event_date} for "${oLoc}" — double-booking with "${tLoc}" (overlapping shift time)`,
          row: {
            event_id: ev.id, resource_id: resourceId,
            conflict_type: 'double_booked', severity: 'critical',
            message: `${name} is double-booked on ${ev.event_date}: "${ev.title || tLoc}" + "${other.title || oLoc}"`,
            payload_json: { other_event_id: other.id, resource_id: resourceId },
          },
        });
      });
  }
  return found;
}

// Real-time popup: confirm (assign anyway & flag for later) or cancel/adjust.
// Resolves true = proceed, false = cancel.
function _laConflictConfirmModal(resourceName, conflicts) {
  return new Promise(resolve => {
    const items = conflicts.slice(0, 12).map(c => {
      const tag = c.kind === 'pto'
        ? '<span style="background:#fef3c7;color:#92400e;font-weight:700;font-size:10px;padding:1px 6px;border-radius:8px;">🌴 PTO</span>'
        : '<span style="background:#fee2e2;color:#b91c1c;font-weight:700;font-size:10px;padding:1px 6px;border-radius:8px;">⚡ DOUBLE-BOOKED</span>';
      return `<li style="margin:6px 0;list-style:none;display:flex;gap:8px;align-items:flex-start;">
        ${tag}<span style="font-size:12px;">${escapeHtml(c.text)}</span></li>`;
    }).join('');
    const more = conflicts.length > 12 ? `<li style="font-size:12px;color:var(--gray-500);">…and ${conflicts.length - 12} more</li>` : '';
    modal({
      title: '⚠ Scheduling conflict detected',
      sub: escapeHtml(resourceName),
      size: 'medium',
      body: `
        <div style="font-size:13px;margin-bottom:10px;">
          This assignment creates <strong>${conflicts.length} conflict${conflicts.length > 1 ? 's' : ''}</strong>:
        </div>
        <ul style="margin:0;padding:0;max-height:46vh;overflow-y:auto;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;padding:10px 12px;">
          ${items}${more}
        </ul>
        <div style="font-size:12px;color:var(--gray-500);margin-top:12px;">
          <strong>Assign anyway</strong> proceeds and logs this to the Conflicts module
          (Planning Admin) to resolve later. <strong>Cancel</strong> lets you adjust the
          allocation now.
        </div>`,
      footer:
        '<button class="form-secondary" onclick="window._laConflictResolve(false)">Cancel / adjust</button>' +
        '<button class="form-submit" style="background:#b45309;border-color:#b45309;" onclick="window._laConflictResolve(true)">Assign anyway &amp; flag</button>',
    });
    window._laConflictResolve = (proceed) => {
      closeModal();
      delete window._laConflictResolve;
      resolve(!!proceed);
    };
  });
}

// Insert detected conflicts into planning_conflicts (dedup vs open ones).
async function _laLogConflicts(conflicts) {
  const rows = [];
  for (const c of conflicts) {
    const dup = (PLANNING_CONFLICTS || []).some(x =>
      x.conflict_type === c.row.conflict_type && !x.is_acknowledged &&
      x.event_id === c.row.event_id && x.resource_id === c.row.resource_id);
    if (!dup) rows.push(c.row);
  }
  if (rows.length) {
    try { await _dbInsert('planning_conflicts', rows); }
    catch (e) { console.warn('Conflict log failed:', e.message); }
  }
  return rows.length;
}

// Gate an assignment behind the real-time conflict popup.
// Returns true to proceed, false to abort. Logs conflicts if user proceeds.
async function _laConflictGate(resourceId, events) {
  const conflicts = _laDetectAssignmentConflicts(resourceId, events);
  if (!conflicts.length) return { proceed: true, conflicts: [] };
  const r = (PLANNING_RESOURCES || []).find(x => x.id === resourceId);
  const ok = await _laConflictConfirmModal(r?.display_name || 'Resource', conflicts);
  return { proceed: ok, conflicts };
}

async function _laAssignResourceToActivity(activityId, resourceId) {
  // Duplicate check
  if (PLANNING_ACTIVITY_RES.some(r => r.planning_activity_id === activityId && r.resource_id === resourceId)) {
    const res = PLANNING_RESOURCES.find(r => r.id === resourceId);
    toast(`${res?.display_name || 'Resource'} is already assigned to this activity`, 'warn');
    return;
  }

  const res = PLANNING_RESOURCES.find(r => r.id === resourceId);

  // Real-time conflict gate (PTO + double-booking) before committing
  const _evsForCheck = PLANNING_EVENTS.filter(e =>
    e.planning_activity_id === activityId && e.status !== 'cancelled');
  const _gate = await _laConflictGate(resourceId, _evsForCheck);
  if (!_gate.proceed) { toast('Assignment cancelled — adjust the allocation.', 'warn'); return; }

  // Optimistic update
  const temp = { id: '_tmp_' + Date.now(), planning_activity_id: activityId, resource_id: resourceId, role: 'crew' };
  PLANNING_ACTIVITY_RES.push(temp);
  _laMountLookaheadTL();

  try {
    await _dbInsert('planning_activity_resources', {
      planning_activity_id: activityId,
      resource_id:          resourceId,
      role:                 'crew',
    });

    // Also propagate to all existing events of this activity for conflict detection
    const evs = PLANNING_EVENTS.filter(e => e.planning_activity_id === activityId);
    for (const ev of evs) {
      if (PLANNING_EVENT_RES.some(er => er.event_id === ev.id && er.resource_id === resourceId)) continue;
      try {
        await _dbInsert('planning_event_resources', {
          event_id:          ev.id,
          resource_id:       resourceId,
          role:              'crew',
          assignment_source: 'manual',
        });
      } catch (e2) {
        if (!e2.message?.includes('duplicate') && !e2.message?.includes('23505')) throw e2;
      }
    }

    toast(`${res?.display_name || 'Resource'} assigned ✓`, 'success');
    if (_gate.conflicts.length) {
      await _laLogConflicts(_gate.conflicts);
      toast(`⚠ ${_gate.conflicts.length} conflict${_gate.conflicts.length>1?'s':''} flagged — see Planning Admin → Conflicts`, 'warn');
    }
    await loadPlanningData(true);
    _laMountLookaheadTL();
  } catch (err) {
    // Rollback optimistic update
    const idx = PLANNING_ACTIVITY_RES.indexOf(temp);
    if (idx > -1) PLANNING_ACTIVITY_RES.splice(idx, 1);
    _laMountLookaheadTL();
    toast('Assignment failed: ' + err.message, 'error');
  }
}

async function _laAssignResourceToEvent(activityId, eventDate, resourceId) {
  // Find the specific event for this activity on this date
  const ev = PLANNING_EVENTS.find(e =>
    e.planning_activity_id === activityId && e.event_date === eventDate
  );
  if (!ev) {
    toast('No shift scheduled on this date for this activity', 'warn');
    return;
  }

  // Duplicate guard
  if (PLANNING_EVENT_RES.some(er => er.event_id === ev.id && er.resource_id === resourceId)) {
    const res = PLANNING_RESOURCES.find(r => r.id === resourceId);
    toast(`${res?.display_name || 'Resource'} is already on this shift`, 'warn');
    return;
  }

  const res  = PLANNING_RESOURCES.find(r => r.id === resourceId);
  const dateLabel = dayjs(eventDate).format('ddd MMM D');

  // Real-time conflict gate (PTO + double-booking) before committing
  const _gate = await _laConflictGate(resourceId, [ev]);
  if (!_gate.proceed) { toast('Assignment cancelled — adjust the allocation.', 'warn'); return; }

  try {
    await _dbInsert('planning_event_resources', {
      event_id:          ev.id,
      resource_id:       resourceId,
      role:              'crew',
      assignment_source: 'manual',
    });
    toast(`${res?.display_name || 'Resource'} → ${dateLabel} shift ✓`, 'success');
    if (_gate.conflicts.length) {
      await _laLogConflicts(_gate.conflicts);
      toast(`⚠ ${_gate.conflicts.length} conflict${_gate.conflicts.length>1?'s':''} flagged — see Planning Admin → Conflicts`, 'warn');
    }
    await loadPlanningData(true);
    _laMountLookaheadTL();
  } catch (err) {
    if (err.message?.includes('23505') || err.message?.includes('duplicate')) {
      toast(`${res?.display_name || 'Resource'} is already on this shift`, 'warn');
    } else {
      toast('Assignment failed: ' + err.message, 'error');
    }
  }
}

async function _laRemoveActivityResource(activityId, resourceId) {
  const record = PLANNING_ACTIVITY_RES.find(r => r.planning_activity_id === activityId && r.resource_id === resourceId);
  if (!record) return;
  const res = PLANNING_RESOURCES.find(r => r.id === resourceId);

  // Optimistic remove
  const idx = PLANNING_ACTIVITY_RES.indexOf(record);
  PLANNING_ACTIVITY_RES.splice(idx, 1);
  _laMountLookaheadTL();

  try {
    await _dbDelete('planning_activity_resources', { planning_activity_id: activityId, resource_id: resourceId });
    toast(`${res?.display_name || 'Resource'} removed`, 'success');
    await loadPlanningData(true);
    _laMountLookaheadTL();
  } catch (err) {
    PLANNING_ACTIVITY_RES.splice(idx, 0, record); // rollback
    _laMountLookaheadTL();
    toast('Remove failed: ' + err.message, 'error');
  }
}

function _laMountLookaheadTL() {
  const target = document.getElementById('lookahead-timeline');
  if (!target) return;

  // Date window: today → today + N days
  const winStart = dayjs().startOf('day');
  const days = Array.from({ length: _laTimelineWindow }, (_, i) =>
    winStart.add(i, 'day').format('YYYY-MM-DD')
  );

  // Milestones: batch upload dates + P6 point milestones
  const milestones = [];
  (PLANNING_BATCHES || []).forEach(b => {
    const iso = (b.uploaded_at || '').slice(0, 10);
    if (days.includes(iso)) milestones.push({ date: iso, label: `Import: ${b.batch_name || iso}`, icon: '●' });
  });
  if (_planningShowP6 && Array.isArray(P6_ACTS)) {
    P6_ACTS.forEach(p6 => {
      if (p6.start_date === p6.finish_date && days.includes(p6.finish_date))
        milestones.push({ date: p6.finish_date, label: p6.p6_id || 'P6 milestone', icon: '★' });
    });
  }

  // Build groups
  const groups = [];

  if (_laTimelineGroupBy === 'resource') {
    PLANNING_RESOURCES
      .filter(r => r.is_active && _laResCompanyMatch(r))
      .sort((a, b) => a.display_name.localeCompare(b.display_name))
      .forEach(r => {
        const evs = PLANNING_EVENTS.filter(e => {
          return PLANNING_EVENT_RES.some(er => er.event_id === e.id && er.resource_id === r.id);
        });
        if (!evs.length && !PTO_REQUESTS.some(p => p.resource_id === r.id && p.status === 'approved')) return;
        const c = _planningSubsystemColor(r.display_name);
        const ini = r.initials || _planningDeriveInitials(r.display_name);
        groups.push({
          id: 'res-' + r.id,
          // Single thin line: "AK - Alex Khoury"
          label: (ini ? ini + ' - ' : '') + r.display_name,
          sublabel: '',
          color: c.bg,
          // Resource view → show location in each cell
          byDate: _laBuildByDate(evs, days, e => e.location || ''),
          ptoByDate: _laBuildPtoByDate(r.id, days),
        });
      });
    // Unassigned
    const unassigned = PLANNING_EVENTS.filter(e =>
      days.includes(e.event_date) && !PLANNING_EVENT_RES.some(er => er.event_id === e.id)
    );
    if (unassigned.length) {
      groups.push({ id: 'res-unassigned', label: 'Unassigned', sublabel: '', color: '#9ca3af',
        byDate: _laBuildByDate(unassigned, days, e => e.location || '') });
    }

  } else if (_laTimelineGroupBy === 'subsystem') {
    const subMap = {};
    PLANNING_EVENTS.filter(e => days.includes(e.event_date)).forEach(e => {
      // Collect all subsystems: event direct → activity → each assigned resource
      const directSub  = e.subsystem || null;
      const act        = PLANNING_ACTIVITIES.find(a => a.id === e.planning_activity_id);
      const actSub     = act?.subsystem || null;
      const resSubs    = PLANNING_EVENT_RES
        .filter(er => er.event_id === e.id)
        .map(er => PLANNING_RESOURCES.find(r => r.id === er.resource_id)?.subsystem)
        .filter(Boolean);

      const allSubs = [...new Set([directSub, actSub, ...resSubs].filter(Boolean))];
      const buckets = allSubs.length ? allSubs : ['Other'];

      buckets.forEach(sub => {
        if (!subMap[sub]) subMap[sub] = [];
        subMap[sub].push(e);
      });
    });

    // Sort: known subsystems first (alphabetically), then Other last
    const subsKeys = Object.keys(subMap).sort((a, b) =>
      a === 'Other' ? 1 : b === 'Other' ? -1 : a.localeCompare(b)
    );
    subsKeys.forEach(sub => {
      const c = _planningSubsystemColor(sub === 'Other' ? null : sub);
      groups.push({ id: 'sub-' + sub, label: sub, color: c.bg,
        byDate: _laBuildByDate(subMap[sub], days, e => e.location || '') });
    });

  } else if (_laTimelineGroupBy === 'location') {
    const locMap = {};
    PLANNING_EVENTS.filter(e => days.includes(e.event_date)).forEach(e => {
      const loc = e.location || 'No location';
      if (!locMap[loc]) locMap[loc] = [];
      locMap[loc].push(e);
    });
    Object.keys(locMap).sort().forEach(loc => {
      const c = _planningSubsystemColor(loc === 'No location' ? null : loc);
      // Location view → show resource initials in each cell
      groups.push({ id: 'loc-' + loc, label: loc, color: c.bg,
        byDate: _laBuildByDate(locMap[loc], days, e => _planningEventResourceInitials(e.id)) });
    });

  } else { // activity — grouped by activity_group (T&C, Construction, Design…)
    // Bucket by activity_group in the fixed enum order, then sort by sort_order.
    // Optional sub-grouping by Phase and/or Location (_laActivitySubGroup).
    const actsInWindow = PLANNING_ACTIVITIES.filter(a => !a.deleted_at);

    const grpBuckets = {};
    actsInWindow.forEach(a => {
      const g = a.activity_group || 'other';
      if (!grpBuckets[g]) grpBuckets[g] = [];
      grpBuckets[g].push(a);
    });

    // Render in fixed enum order; surface unknown-group rows under 'other'
    const orderedKeys = [..._GROUP_ORDER, ...Object.keys(grpBuckets).filter(k => !_GROUP_ORDER.includes(k))];

    orderedKeys.forEach(gk => {
      const acts = grpBuckets[gk];
      if (!acts || acts.length === 0) return;
      const meta      = _groupMeta(gk);
      const collapsed = !!_laCollapsedGroups[gk];

      // ── Group band header ────────────────────────────────────
      groups.push({
        id:            'grp-hdr-' + gk,
        isGroupHeader: true,
        groupKey:      gk,
        label:         meta.label,
        activityCount: acts.length,
        bg:            meta.bg,
        fg:            meta.fg,
        accent:        meta.accent,
        collapsed,
      });
      if (collapsed) return;

      // Sort activities by sort_order within the group
      const sortedActs = acts.slice().sort((a, b) =>
        (a.sort_order ?? 999999) - (b.sort_order ?? 999999) ||
        (a.description || a.activity_id_text || '').localeCompare(b.description || b.activity_id_text || '')
      );

      // ── Helper: push one activity row ───────────────────────
      const pushActRow = a => {
        const sub = a.subsystem || a.location || null;
        const c   = _planningSubsystemColor(sub);
        const evs = PLANNING_EVENTS.filter(e => e.planning_activity_id === a.id);
        const assignedResources = PLANNING_ACTIVITY_RES
          .filter(ar => ar.planning_activity_id === a.id)
          .map(ar => PLANNING_RESOURCES.find(r => r.id === ar.resource_id))
          .filter(Boolean);
        const disc  = _laActDiscipline(a);
        const trade = _laActTrade(a);
        const phase = (a.phase || '').trim() || _laInferPhaseFromLocation(a.location) || '';
        const status = _laActStatus(a, evs);
        groups.push({
          id:                    'act-' + a.id,
          activityId:            a.id,
          activityGroup:         gk,
          assignedResources,
          label:                 a.description || a.activity_id_text || '—',
          sublabel:              sub,
          color:                 c.bg,
          actLocation:           a.location || '',
          actWorkHours:          a.work_hours_raw || '',
          actSswp:               a.sswp || '',
          actParty:              Array.isArray(a.party_to_action) ? a.party_to_action : [],
          actCode:               a.activity_id_text || '',
          actDiscipline:         disc,
          actTrade:              trade,
          actPhase:              phase,
          actStatus:             status,
          linkedTestRegActivity: a.linked_test_register_activity || null,
          // Activity view shows BART-only chips always visible in each cell
          byDate:                _laBuildByDateActivity(evs, days),
        });
      };

      // ── No sub-grouping ──────────────────────────────────────
      if (_laActivitySubGroup === 'none') {
        sortedActs.forEach(pushActRow);
        return;
      }

      // ── Helper: build a sub-group header entry ───────────────
      const pushSubHdr = (subKey, label, icon, count, indent = false) => {
        const subColl = !!_laCollapsedGroups[subKey];
        groups.push({
          id:              'subgrp-' + subKey,
          isSubGroupHeader: true,
          subGroupKey:     subKey,
          groupKey:        gk,
          label,
          icon,
          activityCount:   count,
          bg:              meta.bg,
          fg:              meta.fg,
          accent:          meta.accent,
          collapsed:       subColl,
          indent,
        });
        return subColl; // returns true if collapsed — caller skips rows
      };

      // ── Phase sub-grouping ───────────────────────────────────
      if (_laActivitySubGroup === 'phase') {
        const phaseBuckets = {};
        sortedActs.forEach(a => {
          const p = (a.phase || '').trim() || '(No Phase)';
          (phaseBuckets[p] = phaseBuckets[p] || []).push(a);
        });
        const phaseKeys = Object.keys(phaseBuckets).sort((a, b) =>
          a === '(No Phase)' ? 1 : b === '(No Phase)' ? -1 :
          a.localeCompare(b, undefined, { numeric: true })
        );
        phaseKeys.forEach(pk => {
          const subColl = pushSubHdr('phase::' + gk + '::' + pk, pk, '🏷', phaseBuckets[pk].length);
          if (!subColl) phaseBuckets[pk].forEach(pushActRow);
        });

      // ── Location sub-grouping ────────────────────────────────
      } else if (_laActivitySubGroup === 'location') {
        const locBuckets = {};
        sortedActs.forEach(a => {
          const l = _laResolveLocationPrefix(a.location) || '(No Location)';
          (locBuckets[l] = locBuckets[l] || []).push(a);
        });
        const locKeys = Object.keys(locBuckets).sort((a, b) =>
          a === '(No Location)' ? 1 : b === '(No Location)' ? -1 : a.localeCompare(b)
        );
        locKeys.forEach(lk => {
          const subColl = pushSubHdr('loc::' + gk + '::' + lk, lk, '📍', locBuckets[lk].length);
          if (!subColl) locBuckets[lk].forEach(pushActRow);
        });

      // ── Phase + Location sub-grouping (nested) ───────────────
      } else if (_laActivitySubGroup === 'phase_location') {
        const phaseBuckets = {};
        sortedActs.forEach(a => {
          const p = (a.phase || '').trim() || '(No Phase)';
          (phaseBuckets[p] = phaseBuckets[p] || []).push(a);
        });
        const phaseKeys = Object.keys(phaseBuckets).sort((a, b) =>
          a === '(No Phase)' ? 1 : b === '(No Phase)' ? -1 :
          a.localeCompare(b, undefined, { numeric: true })
        );
        phaseKeys.forEach(pk => {
          const phColl = pushSubHdr('phase::' + gk + '::' + pk, pk, '🏷', phaseBuckets[pk].length);
          if (phColl) return;
          // Inner: location buckets within this phase
          const locBuckets = {};
          phaseBuckets[pk].forEach(a => {
            const l = _laResolveLocationPrefix(a.location) || '(No Location)';
            (locBuckets[l] = locBuckets[l] || []).push(a);
          });
          const locKeys = Object.keys(locBuckets).sort((a, b) =>
            a === '(No Location)' ? 1 : b === '(No Location)' ? -1 : a.localeCompare(b)
          );
          locKeys.forEach(lk => {
            const lColl = pushSubHdr('loc::' + gk + '::' + pk + '::' + lk, lk, '📍', locBuckets[lk].length, true);
            if (!lColl) locBuckets[lk].forEach(pushActRow);
          });
        });
      }
    });
  }

  _laRenderGrid(target, { groups, days, milestones });

  // Wire up drag-and-drop if assign mode is active
  if (_laAssignMode) _laInitAssignDnD(target);
}

// ── GANTT TAB ────────────────────────────────────────────────
function _laGanttHTML() {
  return `
    ${_planningKPIStrip()}
    ${_planningShiftLegend()}

    <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin-bottom:12px;">
      <span style="font-size:13px;color:var(--gray-600);">One row per activity — cells shaded by shift type. P6 baseline shown when overlay is on.</span>
      <label style="margin-left:auto;display:flex;align-items:center;gap:6px;font-size:12px;color:var(--gray-600);cursor:pointer;">
        <input type="checkbox" ${_planningShowP6 ? 'checked' : ''} onchange="_planningTogglePO6Overlay(this.checked)">
        P6 baseline
      </label>
    </div>

    <div class="data-card" style="padding:0;overflow:hidden;">
      <div id="gantt-timeline"></div>
    </div>`;
}

function _laMountGanttTL() {
  const target = document.getElementById('gantt-timeline');
  if (!target) return;

  const actsWithEvents = PLANNING_ACTIVITIES.filter(a =>
    PLANNING_EVENTS.some(e => e.planning_activity_id === a.id)
  );
  if (!actsWithEvents.length) {
    target.innerHTML = `<div style="padding:48px;text-align:center;color:var(--gray-400);font-size:13px;">No planning activities to chart yet. Import a lookahead first.</div>`;
    return;
  }

  // Date window: span all event dates (capped at 90 days from earliest)
  const allDates = PLANNING_EVENTS.map(e => e.event_date).filter(Boolean).sort();
  if (!allDates.length) { target.innerHTML = `<div style="padding:48px;text-align:center;color:var(--gray-400);">No events imported yet.</div>`; return; }
  const winStart = allDates[0];
  const winEnd   = dayjs(allDates[allDates.length - 1]).format('YYYY-MM-DD');
  const capEnd   = dayjs(winStart).add(90, 'day').format('YYYY-MM-DD');
  const endISO   = winEnd > capEnd ? capEnd : winEnd;
  const days = [];
  let d = dayjs(winStart);
  while (!d.isAfter(dayjs(endISO))) { days.push(d.format('YYYY-MM-DD')); d = d.add(1, 'day'); }

  // P6 milestones
  const milestones = [];
  if (_planningShowP6 && Array.isArray(P6_ACTS)) {
    P6_ACTS.forEach(p6 => {
      if (p6.start_date === p6.finish_date && days.includes(p6.finish_date))
        milestones.push({ date: p6.finish_date, label: p6.p6_id || 'Milestone', icon: '★' });
    });
  }

  // Groups: one per activity, coloured by subsystem
  const groups = actsWithEvents.map(a => {
    const sub = a.subsystem || null;
    const c   = _planningSubsystemColor(sub);
    const evs = PLANNING_EVENTS.filter(e => e.planning_activity_id === a.id);

    // P6 baseline range for this activity
    let p6Range = null;
    if (_planningShowP6 && a.linked_p6_activity_id) {
      const p6 = P6_ACTS.find(x => x.id === a.linked_p6_activity_id);
      if (p6 && p6.start_date && p6.finish_date) {
        p6Range = new Set(days.filter(iso => iso >= p6.start_date && iso <= p6.finish_date));
      }
    }

    return {
      id: 'act-' + a.id,
      label: (a.activity_id_text || a.description || '—').slice(0, 24),
      sublabel: sub || '',
      color: c.bg,
      byDate: _laBuildByDate(evs, days),
      p6Range,
    };
  });

  _laRenderGrid(target, { groups, days, milestones });
}

// ── RESOURCES TAB (availability board) ───────────────────────
function _laResourcesBoardHTML() {
  const today    = new Date().toISOString().slice(0, 10);
  const outToday = _ptoActiveOnDate(today);
  return `
    ${outToday.length ? `
      <div style="margin-bottom:14px;padding:10px 14px;background:#fef3c7;border:1px solid #fde68a;border-radius:8px;font-size:13px;color:#92400e;">
        🌴 <strong>Out today:</strong> ${outToday.map(x => escapeHtml(x.resource?.display_name || '—')).join(', ')}
      </div>` : ''}
    ${_planningShiftLegend()}

    <div style="margin-bottom:12px;font-size:13px;color:var(--gray-600);">
      Resource availability — 2-week rolling window. PTO shown in amber. ⚠ = PTO conflict. Click any cell to view details.
    </div>

    <div class="data-card" style="padding:0;overflow:hidden;">
      <div id="resources-timeline"></div>
    </div>`;
}

function _laMountResourcesTL() {
  const target = document.getElementById('resources-timeline');
  if (!target) return;

  const active = PLANNING_RESOURCES
    .filter(r => r.is_active)
    .sort((a, b) => a.display_name.localeCompare(b.display_name));

  if (!active.length) {
    target.innerHTML = `<div style="padding:48px;text-align:center;color:var(--gray-400);font-size:13px;">No active resources yet.</div>`;
    return;
  }

  // 2-week window from today
  const winStart = dayjs().startOf('day');
  const days = Array.from({ length: 14 }, (_, i) =>
    winStart.add(i, 'day').format('YYYY-MM-DD')
  );

  const groups = active.map(r => {
    const c = _planningSubsystemColor(r.display_name);
    // Events assigned to this resource
    const evs = PLANNING_EVENT_RES
      .filter(er => er.resource_id === r.id)
      .map(er => PLANNING_EVENTS.find(e => e.id === er.event_id))
      .filter(Boolean);

    // Mark PTO-conflicted events; include location as cell label
    const byDate = {};
    evs.filter(e => days.includes(e.event_date)).forEach(e => {
      const isCancel = e.status === 'cancelled';
      const conflict = _ptoOverlapsRange(r.id, e.event_date, e.start_time, e.end_time);
      (byDate[e.event_date] = byDate[e.event_date] || []).push({
        event_id: e.id, shift_type: e.shift_type, start_time: e.start_time,
        end_time: e.end_time, all_day: !!e.all_day, isCancel,
        title:     `${conflict ? '⚠ CONFLICT: ' : ''}${e.title || ''}`,
        cellLabel: e.location || '',   // shown inside the coloured cell
      });
    });

    const ini = r.initials || _planningDeriveInitials(r.display_name);
    return {
      id: 'res-' + r.id,
      label: (ini ? ini + ' - ' : '') + r.display_name,
      sublabel: '',
      color: c.bg,
      byDate,
      ptoByDate: _laBuildPtoByDate(r.id, days),
    };
  });

  _laRenderGrid(target, { groups, days, milestones: [] });
}

// ── Event Detail Modal ───────────────────────────────────────
function _planningOpenEventDetail(eventId) {
  const e = PLANNING_EVENTS.find(x => x.id === eventId);
  if (!e) return;

  const isAdmin = currentRoleUser?.role === 'admin';
  const isCancel = e.status === 'cancelled';
  const v = isCancel ? _CANCEL_VISUAL : (_SHIFT_VISUAL[e.shift_type] || _SHIFT_VISUAL.custom);
  const assignments = _planningResourceAssignmentsForEvent(e.id);
  const ti = e.test_item_id ? TI.find(t => String(t.TestID) === String(e.test_item_id)) : null;

  // Resolve batch info for source display
  const _evActivity = e.planning_activity_id ? PLANNING_ACTIVITIES.find(a => a.id === e.planning_activity_id) : null;
  const _evBatch    = _evActivity?.batch_id ? PLANNING_BATCHES.find(b => b.id === _evActivity.batch_id) : null;
  const _sourceLabel = (() => {
    if (e.source === 'lookahead' && _evBatch) {
      const ts = _evBatch.uploaded_at ? new Date(_evBatch.uploaded_at).toLocaleString() : '—';
      const fn = _evBatch.filename ? _evBatch.filename.replace(/\.[^.]+$/, '') : '—';
      return `Lookahead Import — ${fn} · ${ts}`;
    }
    if (e.source === 'manual') return 'Manual Entry';
    return escapeHtml(e.source || '—');
  })();

  // PTO conflicts per assigned resource
  const conflicts = [];
  assignments.forEach(a => {
    if (!a.resource) return;
    const c = _ptoOverlapsRange(a.resource.id, e.event_date, e.start_time, e.end_time);
    if (c) conflicts.push({ resource: a.resource, pto: c });
  });

  const timeStr = e.all_day
    ? 'All day'
    : `${(e.start_time || '00:00').slice(0,5)} – ${(e.end_time || '23:59').slice(0,5)}${
        e.start_time && e.end_time && e.end_time <= e.start_time ? ' (overnight)' : ''
      }`;

  modal({
    title: e.title || '(no title)',
    sub:   `${e.event_date} · ${v.label}${e.is_locked ? ' · 🔒 Locked' : ''}${e.source === 'lookahead' ? ' · From import' : ''}`,
    body: `
      <div style="display:grid;grid-template-columns:140px 1fr;gap:8px 14px;font-size:13px;">
        <div style="color:var(--gray-500);">Status:</div>
        <div>
          <span class="badge" style="background:${v.bg};color:${v.text};border:1px solid ${isCancel ? '#7f1d1d' : v.bg};">${v.icon} ${v.label}</span>
          ${isCancel && e.cancellation_reason ? `<div style="margin-top:6px;font-size:12px;color:#7f1d1d;background:#fef2f2;padding:6px 10px;border-radius:6px;line-height:1.6;">
            <span style="font-weight:600;">Reason:</span> ${escapeHtml(e.cancellation_reason)}
            ${e.cancellation_responsible_party ? `<span style="margin-left:8px;padding:1px 8px;background:#fee2e2;border-radius:10px;font-weight:700;font-size:11px;">⚠ ${escapeHtml(e.cancellation_responsible_party)}</span>` : ''}
          </div>` : ''}
        </div>

        <div style="color:var(--gray-500);">Time:</div>
        <div>${escapeHtml(timeStr)}</div>

        <div style="color:var(--gray-500);">Location:</div>
        <div>${escapeHtml(e.location || '—')}</div>

        <div style="color:var(--gray-500);">Test Item:</div>
        <div>${ti ? `<strong>${escapeHtml(ti.TestCaseCode || ti.TestID)}</strong> — ${escapeHtml(ti.TestName || '')}` : '<em style="color:#9ca3af;">Not linked</em>'}</div>

        <div style="color:var(--gray-500);">Source:</div>
        <div style="font-size:12px;">${_sourceLabel}${e.work_hours_raw ? `<span style="color:var(--gray-500);"> · Hours: ${escapeHtml(e.work_hours_raw)}</span>` : ''}</div>

        <div style="color:var(--gray-500);">Resources:</div>
        <div>
          <div style="display:flex;flex-wrap:wrap;gap:5px;align-items:center;margin-bottom:${isAdmin ? '8px' : '0'};">
            ${assignments.length === 0
              ? '<em style="color:#9ca3af;">No resources assigned</em>'
              : assignments.map(a => {
                  const hasPTO = !!conflicts.find(c => c.resource?.id === a.resource?.id);
                  const badgeClass = hasPTO ? 'badge-failed' : 'badge-passed';
                  const removeBtn = isAdmin
                    ? `<button onclick="event.stopPropagation();_planningRemoveEventResource('${e.id}','${a.resource?.id}')"
                         style="background:none;border:none;cursor:pointer;color:inherit;opacity:.65;font-size:13px;line-height:1;padding:0 0 0 3px;"
                         title="Remove ${escapeHtml(a.resource?.display_name || '')}">×</button>`
                    : '';
                  return `<span class="badge ${badgeClass}" style="display:inline-flex;align-items:center;gap:2px;">
                    ${a.resource ? escapeHtml(a.resource.display_name) : '—'}
                    ${hasPTO ? ' ⚠ PTO' : ''}
                    ${removeBtn}
                  </span>`;
                }).join('')}
          </div>
          ${isAdmin ? (() => {
            const assigned = new Set(assignments.map(a => a.resource?.id).filter(Boolean));
            const available = PLANNING_RESOURCES.filter(r => r.is_active && !assigned.has(r.id));
            return available.length ? `
              <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;">
                <select id="ped-res-select" class="form-input" style="font-size:12px;padding:4px 8px;height:32px;flex:1;min-width:160px;">
                  <option value="">— Assign resource…</option>
                  ${available.map(r => `<option value="${r.id}">${escapeHtml(r.display_name)}${r.initials ? ' ('+escapeHtml(r.initials)+')' : ''}${r.subsystem ? ' · '+escapeHtml(r.subsystem) : ''}</option>`).join('')}
                </select>
                <button class="admin-action-btn" style="font-size:12px;padding:4px 12px;height:32px;" onclick="_planningAssignResourceFromDetail('${e.id}')">Assign</button>
              </div>` : '<em style="font-size:11px;color:var(--gray-400);">All active resources assigned</em>';
          })() : ''}
        </div>

        <div style="color:var(--gray-500);">Notes:</div>
        <div>
          ${isAdmin ? `
            <textarea id="ped-notes" class="form-input" rows="3"
              style="font-size:12px;resize:vertical;width:100%;box-sizing:border-box;"
              placeholder="Add notes about this activity…">${escapeHtml(e.notes || '')}</textarea>
            <button class="form-secondary" style="font-size:11px;padding:3px 10px;margin-top:4px;" onclick="_planningUpdateEventNotes('${e.id}')">💾 Save Notes</button>
          ` : `<div style="font-size:12px;">${e.notes ? escapeHtml(e.notes) : '<em style="color:#9ca3af;">No notes</em>'}</div>`}
        </div>
      </div>

      ${conflicts.length ? `
        <div style="margin-top:14px;padding:10px 14px;background:#fef2f2;border:1px solid #fca5a5;border-radius:8px;font-size:13px;color:#7f1d1d;">
          ⚠ <strong>PTO conflict${conflicts.length === 1 ? '' : 's'}:</strong>
          ${conflicts.map(c => `${escapeHtml(c.resource.display_name)} (${escapeHtml(c.pto.start_date)} → ${escapeHtml(c.pto.end_date)})`).join('; ')}
        </div>` : ''}
    `,
    footer: isAdmin ? `
      <button class="form-secondary" onclick="closeModal()">Close</button>
      <button class="form-secondary" onclick="_planningToggleLock('${e.id}')">${e.is_locked ? '🔓 Unlock' : '🔒 Lock'}</button>
      ${!isCancel ? `<button class="form-secondary" style="color:var(--bad);" onclick="_planningCancelEvent('${e.id}')">✕ Cancel Event</button>` : ''}
      ${isCancel && !e.cancellation_reason ? `<button class="form-submit" onclick="_planningAddCancellationReason('${e.id}')">+ Add Cancel Reason</button>` : ''}
      ${!e.is_locked ? `<button class="form-secondary" style="color:#7f1d1d;border-color:#fca5a5;" onclick="_planningDeleteEvent('${e.id}')">🗑 Delete</button>` : ''}
    ` : `
      <button class="form-secondary" onclick="closeModal()">Close</button>
    `,
  });
  document.getElementById('modal-overlay')?.classList.add('active');
}

async function _planningRemoveEventResource(eventId, resourceId) {
  if (!resourceId) return;
  const res = PLANNING_RESOURCES.find(r => r.id === resourceId);
  try {
    await _dbDelete('planning_event_resources', { event_id: eventId, resource_id: resourceId });
    // Optimistic local remove so re-opened modal reflects change instantly
    const idx = PLANNING_EVENT_RES.findIndex(er => er.event_id === eventId && er.resource_id === resourceId);
    if (idx > -1) PLANNING_EVENT_RES.splice(idx, 1);
    toast(`${res?.display_name || 'Resource'} removed`, 'success');
    // Re-open modal with fresh data
    _planningOpenEventDetail(eventId);
    // Refresh timeline + resource board in background
    loadPlanningData(true).then(() => {
      if (_lookaheadTab === 'lookahead') _laMountLookaheadTL();
      if (_lookaheadTab === 'resources') _laMountResourcesTL();
    });
  } catch (err) {
    toast('Remove failed: ' + err.message, 'error');
  }
}

async function _planningDeleteEvent(eventId) {
  const ev = PLANNING_EVENTS.find(e => e.id === eventId);
  if (!ev) return;
  if (ev.is_locked) { toast('Cannot delete a locked event', 'error'); return; }
  if (!confirm(`Delete "${ev.title}" on ${ev.event_date}? This cannot be undone.`)) return;
  try {
    // Remove all resource assignments first
    const erRows = PLANNING_EVENT_RES.filter(er => er.event_id === eventId);
    for (const er of erRows) {
      await _dbDelete('planning_event_resources', { id: er.id });
    }
    await _dbDelete('planning_events', { id: eventId });
    closeModal();
    toast('Event deleted', 'success');
    await loadPlanningData(true);
    if (_lookaheadTab === 'lookahead') _laMountLookaheadTL();
    if (_lookaheadTab === 'resources') _laMountResourcesTL();
    _laMountCalendar();
  } catch (err) {
    toast('Delete failed: ' + err.message, 'error');
  }
}

async function _planningAssignResourceFromDetail(eventId) {
  const sel = document.getElementById('ped-res-select');
  const resourceId = sel?.value;
  if (!resourceId) { toast('Select a resource first', 'warn'); return; }
  const res = PLANNING_RESOURCES.find(r => r.id === resourceId);
  // Duplicate guard
  if (PLANNING_EVENT_RES.some(er => er.event_id === eventId && er.resource_id === resourceId)) {
    toast(`${res?.display_name || 'Resource'} is already assigned`, 'warn'); return;
  }
  try {
    const [row] = await _dbInsert('planning_event_resources', [{
      event_id:          eventId,
      resource_id:       resourceId,
      role:              'crew',
      assignment_source: 'manual',
    }]);
    if (row) PLANNING_EVENT_RES.push(row);
    toast(`${res?.display_name || 'Resource'} assigned ✓`, 'success');
    // Re-open modal to reflect new assignment
    _planningOpenEventDetail(eventId);
    // Background refresh
    loadPlanningData(true).then(() => {
      if (_lookaheadTab === 'lookahead') _laMountLookaheadTL();
      if (_lookaheadTab === 'resources') _laMountResourcesTL();
    });
  } catch (err) {
    toast('Assignment failed: ' + err.message, 'error');
  }
}

async function _planningUpdateEventNotes(eventId) {
  const notes = (document.getElementById('ped-notes')?.value || '').trim();
  try {
    await _dbUpdate('planning_events', { notes: notes || null }, { id: eventId });
    // Optimistic local update
    const ev = PLANNING_EVENTS.find(e => e.id === eventId);
    if (ev) ev.notes = notes || null;
    toast('Notes saved ✓', 'success');
  } catch (err) {
    toast('Save failed: ' + err.message, 'error');
  }
}

function _planningOpenPTODetail(p) {
  const isAdmin = currentRoleUser?.role === 'admin';
  const r = PLANNING_RESOURCES.find(x => x.id === p.resource_id);
  modal({
    title: `🌴 PTO — ${r?.display_name || '—'}`,
    sub:   _ptoFmtRange(p),
    body: `
      <div style="display:grid;grid-template-columns:140px 1fr;gap:8px 14px;font-size:13px;">
        <div style="color:var(--gray-500);">Status:</div>
        <div><span class="badge badge-passed">Approved</span></div>
        <div style="color:var(--gray-500);">Days:</div>
        <div>${_ptoDays(p)}</div>
        ${isAdmin && p.reason ? `
          <div style="color:var(--gray-500);">Reason:</div>
          <div style="font-size:12px;">${escapeHtml(p.reason)}</div>` : ''}
        ${p.partial_day ? `
          <div style="color:var(--gray-500);">Partial:</div>
          <div>${p.partial_start?.slice(0,5)} – ${p.partial_end?.slice(0,5)}</div>` : ''}
      </div>
    `,
    footer: `<button class="form-secondary" onclick="closeModal()">Close</button>`,
  });
  document.getElementById('modal-overlay')?.classList.add('active');
}

async function _planningToggleLock(eventId) {
  const e = PLANNING_EVENTS.find(x => x.id === eventId);
  if (!e) return;
  try {
    await _dbUpdate('planning_events', { is_locked: !e.is_locked, updated_by: currentProfile?.id || null }, { id: eventId });
    toast(`Event ${e.is_locked ? 'unlocked' : 'locked'}`, 'success');
    closeModal();
    await loadPlanningData(true);
    _renderLookaheadTabBody();
  } catch(err) {
    toast('Update failed: ' + err.message, 'error');
  }
}

async function _planningCancelEvent(eventId) {
  const ev = PLANNING_EVENTS.find(e => e.id === eventId);
  if (!ev) return;
  _cancelReasonModalOpen(
    `"${escapeHtml(ev.title || '')}" · ${ev.event_date}`,
    async ({ category, reason, party }) => {
      try {
        await _dbUpdate('planning_events', {
          status:                         'cancelled',
          cancellation_category:          category,
          cancellation_reason:            reason,
          cancellation_responsible_party: party || null,
          cancellation_by:                currentProfile?.id || null,
          cancellation_at:                new Date().toISOString(),
          updated_by:                     currentProfile?.id || null,
        }, { id: eventId });
        toast('Event cancelled', 'success');
        // Close detail modal if it was open; close drawer too
        if (typeof closeModal === 'function') closeModal();
        if (_laDrawer.mode === 'cell' && _laDrawer.targetId === eventId) _laDrawer.dirty = false;
        await loadPlanningData(true);
        _renderLookaheadTabBody();
      } catch (err) {
        toast('Cancel failed: ' + err.message, 'error');
      }
    }
  );
}

// ── PTO Tab ──────────────────────────────────────────────────
let _ptoFilter = 'all';            // all | pending | approved | rejected | mine
let _ptoEditingId = null;          // for edit/review modal

function _ptoCurrentResource() {
  // Find planning_resource row for the logged-in user
  if (!currentProfile) return null;
  return PLANNING_RESOURCES.find(r => r.user_id === currentProfile.id) || null;
}

function _ptoResourceName(resourceId) {
  const r = PLANNING_RESOURCES.find(x => x.id === resourceId);
  return r ? r.display_name : '—';
}

function _ptoFmtRange(p) {
  if (!p.start_date) return '—';
  const s = new Date(p.start_date + 'T00:00:00').toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' });
  if (!p.end_date || p.end_date === p.start_date) {
    if (p.partial_day && p.partial_start && p.partial_end) return `${s} (${p.partial_start.slice(0,5)}–${p.partial_end.slice(0,5)})`;
    return s;
  }
  const e = new Date(p.end_date + 'T00:00:00').toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' });
  return `${s} → ${e}`;
}

function _ptoDays(p) {
  if (!p.start_date || !p.end_date) return 0;
  const s = new Date(p.start_date + 'T00:00:00');
  const e = new Date(p.end_date   + 'T00:00:00');
  const days = Math.round((e - s) / 86400000) + 1;
  return p.partial_day ? 0.5 : Math.max(1, days);
}

function _laPTOStub() {
  const isAdmin    = currentRoleUser?.role === 'admin';
  const myResource = _ptoCurrentResource();
  const canSubmit  = isAdmin || (myResource !== null);

  const pending  = PTO_REQUESTS.filter(p => p.status === 'pending').length;
  const approved = PTO_REQUESTS.filter(p => p.status === 'approved').length;
  const rejected = PTO_REQUESTS.filter(p => p.status === 'rejected').length;
  const totalDays = PTO_REQUESTS.filter(p => p.status === 'approved').reduce((s,p) => s + _ptoDays(p), 0);

  let filtered = PTO_REQUESTS;
  if (_ptoFilter === 'pending')   filtered = filtered.filter(p => p.status === 'pending');
  if (_ptoFilter === 'approved')  filtered = filtered.filter(p => p.status === 'approved');
  if (_ptoFilter === 'rejected')  filtered = filtered.filter(p => p.status === 'rejected');
  if (_ptoFilter === 'mine')      filtered = filtered.filter(p => myResource && p.resource_id === myResource.id);

  const filterChips = [
    ['all',      `All (${PTO_REQUESTS.length})`],
    ['pending',  `Pending (${pending})`],
    ['approved', `Approved (${approved})`],
    ['rejected', `Rejected (${rejected})`],
    ['mine',     'My Requests'],
  ];

  return `
    <div class="kpi-grid kpi-grid-mini" style="margin-bottom:16px;">
      <div class="kpi-card kpi-mini"><div class="kpi-label">Pending</div><div class="kpi-value" style="color:var(--warn);">${pending}</div></div>
      <div class="kpi-card kpi-mini"><div class="kpi-label">Approved</div><div class="kpi-value good">${approved}</div></div>
      <div class="kpi-card kpi-mini"><div class="kpi-label">Rejected</div><div class="kpi-value" style="color:var(--gray-500);">${rejected}</div></div>
      <div class="kpi-card kpi-mini"><div class="kpi-label">Total Days Out</div><div class="kpi-value">${totalDays}</div></div>
    </div>

    <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:14px;justify-content:space-between;">
      <div style="display:flex;gap:6px;flex-wrap:wrap;">
        ${filterChips.map(([id, label]) => `
          <button class="admin-tab${_ptoFilter === id ? ' active' : ''}" style="font-size:12px;padding:6px 12px;" onclick="_ptoSetFilter('${id}')">${label}</button>
        `).join('')}
      </div>
      <div style="display:flex;gap:8px;">
        ${canSubmit
          ? `<button class="admin-action-btn" onclick="_ptoOpenSubmitModal()">+ Submit PTO</button>`
          : `<button class="admin-action-btn" disabled style="opacity:.55;cursor:not-allowed;" title="No planning resource linked to your account">+ Submit PTO</button>`}
      </div>
    </div>

    <div class="data-card" style="padding:0;overflow:hidden;">
      <table class="data-table">
        <thead>
          <tr>
            <th>Resource</th>
            <th>Dates</th>
            <th>Days</th>
            ${isAdmin ? `<th>Reason</th>` : ''}
            <th>Status</th>
            <th>Submitted</th>
            <th style="width:160px;">Actions</th>
          </tr>
        </thead>
        <tbody>
          ${filtered.length === 0
            ? `<tr><td colspan="${isAdmin ? 7 : 6}" style="text-align:center;padding:32px;color:var(--gray-400);">No PTO requests${_ptoFilter !== 'all' ? ' in this filter' : ' yet'}.</td></tr>`
            : filtered.map(p => _ptoRowHTML(p, isAdmin, myResource)).join('')}
        </tbody>
      </table>
    </div>

    ${!isAdmin ? `
      <div style="margin-top:14px;padding:10px 14px;background:#f0f9ff;border:1px solid #bae6fd;border-radius:8px;font-size:11px;color:#0c4a6e;">
        ℹ All approved PTO is visible to everyone. Personal reasons are visible only to admins.
      </div>` : ''}
  `;
}

function _ptoRowHTML(p, isAdmin, myResource) {
  const statusBadge = {
    pending:   `<span class="badge badge-warn">Pending</span>`,
    approved:  `<span class="badge badge-passed">Approved</span>`,
    rejected:  `<span class="badge badge-failed">Rejected</span>`,
    cancelled: `<span class="badge badge-notstarted">Cancelled</span>`,
  }[p.status] || escapeHtml(p.status);

  const isMine = myResource && p.resource_id === myResource.id;
  const submitted = p.created_at ? new Date(p.created_at).toLocaleDateString('en-US',{ month:'short', day:'numeric' }) : '—';

  let actions = '';
  if (isAdmin && p.status === 'pending') {
    actions = `
      <button class="form-secondary" style="font-size:11px;padding:4px 8px;color:#16a34a;" onclick="_ptoReview('${p.id}','approve')">✓ Approve</button>
      <button class="form-secondary" style="font-size:11px;padding:4px 8px;color:var(--bad);margin-left:4px;" onclick="_ptoReview('${p.id}','reject')">✕ Reject</button>`;
  } else if (isAdmin && p.status !== 'pending') {
    actions = `<button class="form-secondary" style="font-size:11px;padding:4px 8px;" onclick="_ptoReview('${p.id}','reopen')">↺ Reopen</button>`;
  } else if (isMine && p.status === 'pending') {
    actions = `<button class="form-secondary" style="font-size:11px;padding:4px 8px;color:var(--bad);" onclick="_ptoCancel('${p.id}')">Cancel</button>`;
  } else {
    actions = `<span style="font-size:11px;color:var(--gray-400);">—</span>`;
  }

  return `
    <tr>
      <td>${escapeHtml(_ptoResourceName(p.resource_id))}</td>
      <td style="font-size:13px;">${escapeHtml(_ptoFmtRange(p))}</td>
      <td style="font-size:13px;">${_ptoDays(p)}</td>
      ${isAdmin ? `<td style="font-size:12px;color:var(--gray-600);max-width:240px;">${escapeHtml((p.reason || '').slice(0, 80))}${(p.reason || '').length > 80 ? '…' : ''}</td>` : ''}
      <td>${statusBadge}</td>
      <td style="font-size:12px;color:var(--gray-500);">${submitted}</td>
      <td>${actions}</td>
    </tr>`;
}

function _ptoSetFilter(f) { _ptoFilter = f; _renderLookaheadTabBody(); }

// ── Submit PTO Modal ─────────────────────────────────────────
function _ptoOpenSubmitModal() {
  const isAdmin    = currentRoleUser?.role === 'admin';
  const myResource = _ptoCurrentResource();

  // Admins can pick any active resource; non-admins are locked to their own
  const resourcePicker = isAdmin
    ? `
      <select id="pto-resource" class="form-input" required>
        <option value="">— Select resource —</option>
        ${PLANNING_RESOURCES.filter(r => r.is_active)
          .sort((a,b) => a.display_name.localeCompare(b.display_name))
          .map(r => `<option value="${r.id}" ${myResource && r.id === myResource.id ? 'selected' : ''}>${escapeHtml(r.display_name)}${r.initials ? ` (${escapeHtml(r.initials)})` : ''}</option>`)
          .join('')}
      </select>`
    : `<input class="form-input" value="${escapeHtml(myResource?.display_name || 'No linked resource')}" disabled>
       <input type="hidden" id="pto-resource" value="${myResource?.id || ''}">`;

  const today = new Date().toISOString().slice(0,10);

  modal({
    title: 'Submit PTO Request',
    sub:   'Submit a request for time off. Admin will review and approve.',
    body: `
      <div class="form-grid">
        <div class="form-field form-field-full">
          <label>Resource</label>
          ${resourcePicker}
        </div>
        <div class="form-field">
          <label>Start Date</label>
          <input type="date" id="pto-start" class="form-input" value="${today}" required>
        </div>
        <div class="form-field">
          <label>End Date</label>
          <input type="date" id="pto-end" class="form-input" value="${today}" required>
        </div>
        <div class="form-field form-field-full">
          <label style="display:flex;align-items:center;gap:8px;">
            <input type="checkbox" id="pto-partial" onchange="_ptoTogglePartial(this.checked)">
            <span>Partial day only</span>
          </label>
        </div>
        <div class="form-field" id="pto-partial-start-wrap" style="display:none;">
          <label>Start Time</label>
          <input type="time" id="pto-partial-start" class="form-input" value="09:00">
        </div>
        <div class="form-field" id="pto-partial-end-wrap" style="display:none;">
          <label>End Time</label>
          <input type="time" id="pto-partial-end" class="form-input" value="13:00">
        </div>
        <div class="form-field form-field-full">
          <label>Reason</label>
          <textarea id="pto-reason" class="form-input" rows="3" placeholder="Vacation, sick leave, family event, etc."></textarea>
          <div style="font-size:11px;color:var(--gray-500);margin-top:4px;">ℹ Reason is visible to admins only.</div>
        </div>
      </div>
    `,
    footer: `
      <button class="form-secondary" onclick="closeModal()">Cancel</button>
      <button class="form-submit" onclick="_ptoSubmit()">Submit Request</button>
    `,
  });
  document.getElementById('modal-overlay')?.classList.add('active');
}

function _ptoTogglePartial(on) {
  document.getElementById('pto-partial-start-wrap').style.display = on ? '' : 'none';
  document.getElementById('pto-partial-end-wrap').style.display   = on ? '' : 'none';
  // Force same-day when partial
  if (on) {
    const start = document.getElementById('pto-start').value;
    document.getElementById('pto-end').value = start;
  }
}

async function _ptoSubmit() {
  const resourceId = document.getElementById('pto-resource')?.value || '';
  const startDate  = document.getElementById('pto-start').value;
  const endDate    = document.getElementById('pto-end').value;
  const partial    = document.getElementById('pto-partial').checked;
  const partialS   = partial ? document.getElementById('pto-partial-start').value : null;
  const partialE   = partial ? document.getElementById('pto-partial-end').value   : null;
  const reason     = document.getElementById('pto-reason').value.trim();

  if (!resourceId)          { toast('Resource is required', 'error'); return; }
  if (!startDate || !endDate) { toast('Start and end dates required', 'error'); return; }
  if (new Date(endDate) < new Date(startDate)) { toast('End date must be on or after start date', 'error'); return; }
  if (partial && (!partialS || !partialE)) { toast('Partial day requires both times', 'error'); return; }
  if (partial && partialE <= partialS) { toast('Partial end time must be after start time', 'error'); return; }

  const btns = [...document.querySelectorAll('.modal-footer .form-submit')];
  const btn = btns[btns.length - 1];
  if (btn) { btn.disabled = true; btn.textContent = 'Submitting…'; }

  try {
    await _dbInsert('pto_requests', [{
      user_id:       currentProfile?.id || null,
      resource_id:   resourceId,
      start_date:    startDate,
      end_date:      endDate,
      partial_day:   partial,
      partial_start: partialS,
      partial_end:   partialE,
      reason:        reason || null,
      status:        'pending',
    }]);
    closeModal();
    toast('PTO request submitted', 'success');
    await loadPlanningData(true);
    if (_lookaheadTab === 'pto') _renderLookaheadTabBody();
  } catch(err) {
    toast('Submit failed: ' + err.message, 'error');
    if (btn) { btn.disabled = false; btn.textContent = 'Submit Request'; }
  }
}

// ── Admin: approve / reject / reopen ─────────────────────────
async function _ptoReview(id, action) {
  if (currentRoleUser?.role !== 'admin') { toast('Admin only', 'error'); return; }
  const req = PTO_REQUESTS.find(p => p.id === id);
  if (!req) return;

  const labels = { approve: 'Approve', reject: 'Reject', reopen: 'Reopen for review' };
  const newStatus = { approve: 'approved', reject: 'rejected', reopen: 'pending' }[action];
  const promptNote = action === 'reject' ? 'Reason for rejection (optional):'
                  : action === 'approve' ? 'Review notes (optional):'
                  : 'Notes (optional):';
  const note = prompt(`${labels[action]} PTO for ${_ptoResourceName(req.resource_id)} (${_ptoFmtRange(req)})\n\n${promptNote}`);
  if (note === null) return; // cancelled

  try {
    await _dbUpdate('pto_requests', {
      status:       newStatus,
      reviewed_by:  currentProfile?.id || null,
      reviewed_at:  new Date().toISOString(),
      review_notes: note || null,
    }, { id });
    toast(`PTO ${newStatus}`, 'success');
    await loadPlanningData(true);
    if (_lookaheadTab === 'pto') _renderLookaheadTabBody();
  } catch(err) {
    toast('Update failed: ' + err.message, 'error');
  }
}

async function _ptoCancel(id) {
  const req = PTO_REQUESTS.find(p => p.id === id);
  if (!req) return;
  if (!confirm(`Cancel your PTO request for ${_ptoFmtRange(req)}?`)) return;
  try {
    await _dbUpdate('pto_requests', { status: 'cancelled' }, { id });
    toast('Request cancelled', 'success');
    await loadPlanningData(true);
    if (_lookaheadTab === 'pto') _renderLookaheadTabBody();
  } catch(err) {
    toast('Cancel failed: ' + err.message, 'error');
  }
}

// ══════════════════════════════════════════════════════════════
// DELAYS & CANCELLATIONS REPORT TAB
// ══════════════════════════════════════════════════════════════

let _cancelRpt = {
  dateFrom:  '',
  dateTo:    '',
  type:      'all',   // all | cancellations | delays
  party:     '',
  location:  '',
  subsystem: '',
};
let _cancelRptSel = new Set();   // IDs of rows selected for export

// Build normalised rows from both data sources
function _cancelRptBuildRows() {
  const rows = [];

  // ── 1. Cancelled planning events ─────────────────────────────
  PLANNING_EVENTS.filter(e => e.status === 'cancelled').forEach(e => {
    const act = PLANNING_ACTIVITIES.find(a => a.id === e.planning_activity_id);
    const sub = _planningGetSubsystem(e) || act?.subsystem || '';
    const batch = act?.batch_id ? PLANNING_BATCHES.find(b => b.id === act.batch_id) : null;
    const sourceLabel = e.source === 'lookahead' && batch
      ? `Lookahead Import · ${batch.filename || ''}`
      : e.source === 'manual' ? 'Manual' : (e.source || '—');
    const cancelledByRes = e.cancellation_by
      ? (PLANNING_RESOURCES.find(r => r.id === e.cancellation_by)?.display_name || e.cancellation_by)
      : '—';
    rows.push({
      _id:    'cancel-' + e.id,
      _type:  'cancellation',
      date:   e.event_date || '',
      title:  e.title || '(no title)',
      location:  e.location || act?.location || '',
      subsystem: sub,
      shift:  e.shift_type || '',
      reason: e.cancellation_reason || '',
      party:  e.cancellation_responsible_party || '',
      source: sourceLabel,
      loggedBy:  cancelledByRes,
      loggedAt:  e.cancellation_at ? new Date(e.cancellation_at).toLocaleString() : '',
      duration:  '',
      notes:     e.notes || '',
    });
  });

  // ── 2. Delay log entries (delay_occurred = Yes) ───────────────
  DELAY_LOG.forEach(d => {
    rows.push({
      _id:    'delay-' + (d.id || Math.random()),
      _type:  'delay',
      date:   d.log_date || '',
      title:  d.delay_category || 'Delay',
      location:  d.location || '',
      subsystem: d.subsystem || '',
      shift:  '',
      reason: d.delay_notes || '',
      party:  d.delay_responsible_party || '',
      source: 'Field Report',
      loggedBy:  d.submitted_by || '',
      loggedAt:  d.created_at ? new Date(d.created_at).toLocaleString() : '',
      duration:  d.delay_duration ? d.delay_duration + ' hr' : '',
      notes:     d.overall_notes || '',
    });
  });

  return rows.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
}

function _cancelRptApplyFilters(rows) {
  return rows.filter(r => {
    if (_cancelRpt.type === 'cancellations' && r._type !== 'cancellation') return false;
    if (_cancelRpt.type === 'delays'         && r._type !== 'delay')        return false;
    if (_cancelRpt.dateFrom && r.date < _cancelRpt.dateFrom) return false;
    if (_cancelRpt.dateTo   && r.date > _cancelRpt.dateTo)   return false;
    if (_cancelRpt.party    && !r.party.toLowerCase().includes(_cancelRpt.party.toLowerCase())) return false;
    if (_cancelRpt.location && !r.location.toLowerCase().includes(_cancelRpt.location.toLowerCase())) return false;
    if (_cancelRpt.subsystem && r.subsystem !== _cancelRpt.subsystem) return false;
    return true;
  });
}

function _cancelRptSetFilter(key, val) {
  _cancelRpt[key] = val;
  _cancelRptSel.clear();
  document.getElementById('cancel-rpt-body').innerHTML = _cancelRptTableBody();
  _cancelRptUpdateBulkBtn();
}

function _cancelRptToggleSel(id, checked) {
  if (checked) _cancelRptSel.add(id); else _cancelRptSel.delete(id);
  _cancelRptUpdateBulkBtn();
}

function _cancelRptToggleAll(checked) {
  document.querySelectorAll('.crpt-cb').forEach(cb => {
    cb.checked = checked;
    _cancelRptToggleSel(cb.dataset.id, checked);
  });
}

function _cancelRptUpdateBulkBtn() {
  const n = _cancelRptSel.size;
  const btn = document.getElementById('crpt-export-btn');
  const allCb = document.getElementById('crpt-sel-all');
  if (btn) btn.textContent = n ? `📄 Export PDF (${n} selected)` : '📄 Export All as PDF';
  const total = document.querySelectorAll('.crpt-cb').length;
  if (allCb) {
    allCb.indeterminate = n > 0 && n < total;
    allCb.checked = total > 0 && n === total;
  }
}

function _cancelRptTableBody() {
  const allRows = _cancelRptBuildRows();
  const filtered = _cancelRptApplyFilters(allRows);

  if (!filtered.length) {
    return `<tr><td colspan="9" style="text-align:center;padding:40px;color:var(--gray-400);">
      No records match the current filters.</td></tr>`;
  }

  return filtered.map(r => {
    const isCxl  = r._type === 'cancellation';
    const color  = isCxl ? '#b91c1c' : '#b45309';
    const badge  = isCxl
      ? `<span class="badge" style="background:#fef2f2;color:#b91c1c;border:1px solid #fca5a5;font-size:10px;">✕ Cancellation</span>`
      : `<span class="badge" style="background:#fffbeb;color:#b45309;border:1px solid #fde68a;font-size:10px;">⚠ Delay</span>`;
    const checked = _cancelRptSel.has(r._id) ? 'checked' : '';
    return `<tr style="border-left:3px solid ${color};">
      <td style="width:32px;padding:8px 6px;">
        <input type="checkbox" class="crpt-cb" data-id="${r._id}" ${checked}
          onchange="_cancelRptToggleSel('${r._id}',this.checked)" style="width:14px;height:14px;cursor:pointer;">
      </td>
      <td style="white-space:nowrap;font-size:12px;font-weight:600;">${escapeHtml(r.date || '—')}</td>
      <td>${badge}</td>
      <td style="font-size:12px;max-width:220px;">${escapeHtml(r.title)}</td>
      <td style="font-size:12px;color:var(--gray-600);">${escapeHtml(r.location || '—')}</td>
      <td style="font-size:12px;">${escapeHtml(r.subsystem || '—')}</td>
      <td style="font-size:12px;max-width:200px;">
        ${r.reason ? escapeHtml(r.reason) : '<em style="color:#9ca3af;">—</em>'}
        ${r.duration ? `<div style="font-size:11px;color:#b45309;margin-top:2px;">⏱ ${escapeHtml(r.duration)}</div>` : ''}
      </td>
      <td style="font-size:12px;">
        ${r.party ? `<span class="badge" style="background:#fee2e2;color:#7f1d1d;font-size:11px;font-weight:700;">${escapeHtml(r.party)}</span>` : '<span style="color:#9ca3af;">—</span>'}
      </td>
      <td style="font-size:11px;color:var(--gray-500);">
        <div>${escapeHtml(r.source)}</div>
        <div style="margin-top:2px;">${escapeHtml(r.loggedBy)}${r.loggedAt ? ` · ${escapeHtml(r.loggedAt)}` : ''}</div>
      </td>
    </tr>`;
  }).join('');
}

// ═══════════════════════════════════════════════════════════════
// LOOKAHEAD HEALTH — KPI dashboard tab
// ═══════════════════════════════════════════════════════════════
function _laHealthTabHTML() {
  const today = new Date().toISOString().slice(0, 10);
  const winStart = dayjs().format('YYYY-MM-DD');
  const winEnd   = dayjs().add(28, 'day').format('YYYY-MM-DD');
  const lookbackStart = dayjs().subtract(28, 'day').format('YYYY-MM-DD');

  // ── Forecast Accuracy ──
  // For events in the past 28 days that were planned, what % had test_results recorded?
  const pastEvents = PLANNING_EVENTS.filter(e =>
    e.event_date >= lookbackStart && e.event_date < today &&
    e.status !== 'cancelled'
  );
  const pastLinked = pastEvents.filter(e => {
    const act = PLANNING_ACTIVITIES.find(a => a.id === e.planning_activity_id);
    return act?.linked_test_register_activity;
  });
  const pastWithResults = pastLinked.filter(e => {
    const act = PLANNING_ACTIVITIES.find(a => a.id === e.planning_activity_id);
    return (PLANNING_TEST_RESULTS || []).some(r =>
      (r.activity || '').trim() === (act.linked_test_register_activity || '').trim() &&
      r.date_tested === e.event_date
    );
  });
  const forecastPct = pastLinked.length ? Math.round((pastWithResults.length / pastLinked.length) * 100) : null;

  // ── Unmapped % ──
  // What % of planning_activities have NO link (neither TR nor P6)?
  const totalActs = PLANNING_ACTIVITIES.length;
  const unmapped = PLANNING_ACTIVITIES.filter(a =>
    !a.linked_test_register_activity && !a.linked_p6_activity_id
  ).length;
  const unmappedPct = totalActs ? Math.round((unmapped / totalActs) * 100) : 0;

  // ── Activity Completion velocity (last 4 weeks) ──
  // Tests completed per week, based on test_items with completed_date
  const weekly = [];
  for (let i = 3; i >= 0; i--) {
    const wStart = dayjs().startOf('week').subtract(i, 'week').format('YYYY-MM-DD');
    const wEnd   = dayjs().startOf('week').subtract(i, 'week').add(6, 'day').format('YYYY-MM-DD');
    const count = (PLANNING_TEST_RESULTS || []).filter(r =>
      r.result === 'Pass' && r.date_tested >= wStart && r.date_tested <= wEnd
    ).length;
    weekly.push({ label: dayjs(wStart).format('MMM D'), count });
  }
  const maxWeekly = Math.max(1, ...weekly.map(w => w.count));

  // ── Coverage Gap ──
  // Distinct TI.Activity values that have NO planning_activities link in the future window
  const linkedActivities = new Set(PLANNING_ACTIVITIES
    .filter(a => a.linked_test_register_activity)
    .map(a => (a.linked_test_register_activity || '').trim()));
  const allTRA = [...new Set(TI.map(t => (t.Activity || '').trim()).filter(Boolean))];
  const uncovered = allTRA
    .filter(name => !linkedActivities.has(name))
    .map(name => ({
      name,
      total:    TI.filter(t => (t.Activity || '').trim() === name).length,
      complete: TI.filter(t => (t.Activity || '').trim() === name && (t.Status === 'Complete' || t.Status === 'Pass' || t.Status === 'Passed')).length,
    }))
    .filter(x => x.complete < x.total)  // hide fully complete (no need to schedule)
    .sort((a, b) => (b.total - b.complete) - (a.total - a.complete))
    .slice(0, 8);

  // ── Schedule Drift vs P6 ──
  // For each linked-P6 activity, compute the day delta between the latest planning_event
  // and the p6_activity.finish_date.
  const drift = PLANNING_ACTIVITIES
    .filter(a => a.linked_p6_activity_id)
    .map(a => {
      const p6 = (P6_ACTS || []).find(p => p.id === a.linked_p6_activity_id);
      if (!p6 || !p6.finish_date) return null;
      const evs = PLANNING_EVENTS.filter(e => e.planning_activity_id === a.id && e.status !== 'cancelled');
      if (!evs.length) return null;
      const latestPlanned = evs.map(e => e.event_date).sort().slice(-1)[0];
      const delta = dayjs(latestPlanned).diff(dayjs(p6.finish_date), 'day');
      return { activity: a, p6, delta, latestPlanned };
    })
    .filter(Boolean)
    .sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta))
    .slice(0, 8);

  // ── Top activities by remaining workload ──
  const remainingByActivity = PLANNING_ACTIVITIES
    .filter(a => a.linked_test_register_activity)
    .map(a => {
      const stats = _planningTestActivityStats(a.linked_test_register_activity);
      return {
        activity: a,
        ...stats,
        remaining: stats ? Math.max(0, stats.totalInActivity - stats.completeInActivity) : 0,
      };
    })
    .filter(x => x.remaining > 0)
    .sort((a, b) => b.remaining - a.remaining)
    .slice(0, 6);

  return `
    <div style="margin-bottom:14px;">
      <h2 style="margin:0 0 4px;font-size:18px;font-weight:700;">Lookahead Health</h2>
      <p style="margin:0;font-size:12px;color:var(--gray-500);">
        KPIs derived from the link between lookahead activities and the Test Register / P6 schedule.
        Window: ${lookbackStart} → ${winEnd} (28 days back, 28 ahead).
      </p>
    </div>

    <!-- ── Top metric row ─────────────────────────────────────────────── -->
    <div class="kpi-grid" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;margin-bottom:18px;">
      <div class="kpi-card">
        <div class="kpi-label">Forecast Accuracy</div>
        <div class="kpi-value" style="color:${forecastPct === null ? '#9ca3af' : forecastPct >= 70 ? '#16a34a' : forecastPct >= 40 ? '#d97706' : '#dc2626'};">
          ${forecastPct === null ? '—' : forecastPct + '%'}
        </div>
        <div style="font-size:10px;color:#6b7280;">
          ${forecastPct === null ? 'No linked past cells' : `${pastWithResults.length} / ${pastLinked.length} planned cells had results`}
        </div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Unmapped Activities</div>
        <div class="kpi-value" style="color:${unmappedPct <= 30 ? '#16a34a' : unmappedPct <= 60 ? '#d97706' : '#dc2626'};">
          ${unmappedPct}%
        </div>
        <div style="font-size:10px;color:#6b7280;">
          ${unmapped} of ${totalActs} have no link (overhead)
        </div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Total Activities</div>
        <div class="kpi-value">${totalActs}</div>
        <div style="font-size:10px;color:#6b7280;">
          ${PLANNING_ACTIVITIES.filter(a => a.linked_test_register_activity).length} linked to TR ·
          ${PLANNING_ACTIVITIES.filter(a => a.linked_p6_activity_id).length} linked to P6
        </div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Tests Passed (4 wks)</div>
        <div class="kpi-value">${weekly.reduce((s, w) => s + w.count, 0)}</div>
        <div style="font-size:10px;color:#6b7280;">
          ${weekly[weekly.length-1].count} this week
        </div>
      </div>
    </div>

    <!-- ── Phase 4D: per-group progress rollups ─────────────────────── -->
    ${_laHealthGroupRollupHTML()}

    <!-- ── Two-column row: velocity + remaining ─────────────────────── -->
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:18px;">
      <div class="data-card" style="padding:14px;">
        <div style="font-weight:600;font-size:13px;margin-bottom:10px;">Test Completion Velocity (last 4 weeks)</div>
        <div style="display:flex;align-items:flex-end;gap:8px;height:100px;padding-bottom:24px;border-bottom:1px solid #e5e7eb;">
          ${weekly.map(w => {
            const h = Math.max(4, Math.round((w.count / maxWeekly) * 80));
            return `
              <div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:4px;">
                <div style="font-size:11px;font-weight:600;color:#374151;">${w.count}</div>
                <div style="width:100%;background:#0891b2;height:${h}px;border-radius:3px 3px 0 0;"></div>
                <div style="font-size:10px;color:#6b7280;position:absolute;margin-top:${h + 6}px;">${w.label}</div>
              </div>`;
          }).join('')}
        </div>
      </div>

      <div class="data-card" style="padding:14px;">
        <div style="font-weight:600;font-size:13px;margin-bottom:10px;">Top remaining workload</div>
        ${remainingByActivity.length === 0 ? '<div style="font-size:12px;color:#6b7280;">No linked activities with remaining tests.</div>' :
          remainingByActivity.map(x => {
            const pct = Math.round((x.completeInActivity / x.totalInActivity) * 100);
            return `
              <div style="margin-bottom:10px;">
                <div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:3px;">
                  <span style="font-weight:500;">${escapeHtml(x.activity.linked_test_register_activity)}</span>
                  <span style="color:#6b7280;font-family:monospace;">${x.completeInActivity}/${x.totalInActivity}</span>
                </div>
                <div style="background:#f3f4f6;height:6px;border-radius:3px;overflow:hidden;">
                  <div style="background:${pct>=80?'#16a34a':pct>=50?'#0891b2':'#9ca3af'};height:100%;width:${pct}%;"></div>
                </div>
              </div>`;
          }).join('')
        }
      </div>
    </div>

    <!-- ── Two-column row: coverage gap + schedule drift ────────────── -->
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:18px;">
      <div class="data-card" style="padding:14px;">
        <div style="font-weight:600;font-size:13px;margin-bottom:10px;">⚠ Coverage gap — Activities not in any lookahead</div>
        ${uncovered.length === 0 ? '<div style="font-size:12px;color:#16a34a;">✓ Every Test Register Activity is linked to a lookahead row.</div>' :
          `<div style="font-size:11px;color:#6b7280;margin-bottom:8px;">These Test Register Activities have remaining tests but no lookahead row pointing at them — they need to be scheduled or linked.</div>
          <table style="width:100%;border-collapse:collapse;font-size:11px;">
            <thead><tr style="background:#f8fafc;">
              <th style="text-align:left;padding:4px 8px;">Activity</th>
              <th style="text-align:right;padding:4px 8px;">Remaining</th>
            </tr></thead>
            <tbody>
              ${uncovered.map(u => `
                <tr style="border-top:1px solid #f1f5f9;">
                  <td style="padding:3px 8px;">${escapeHtml(u.name)}</td>
                  <td style="padding:3px 8px;text-align:right;font-weight:600;color:#dc2626;">${u.total - u.complete}</td>
                </tr>`).join('')}
            </tbody>
          </table>`
        }
      </div>

      <div class="data-card" style="padding:14px;">
        <div style="font-weight:600;font-size:13px;margin-bottom:10px;">📅 Schedule Drift vs P6</div>
        ${drift.length === 0 ? '<div style="font-size:12px;color:#6b7280;">No P6-linked activities with scheduled cells.</div>' :
          `<table style="width:100%;border-collapse:collapse;font-size:11px;">
            <thead><tr style="background:#f8fafc;">
              <th style="text-align:left;padding:4px 8px;">Activity</th>
              <th style="text-align:left;padding:4px 8px;">P6 finish</th>
              <th style="text-align:left;padding:4px 8px;">Latest planned</th>
              <th style="text-align:right;padding:4px 8px;">Δ</th>
            </tr></thead>
            <tbody>
              ${drift.map(d => {
                const sign = d.delta > 0 ? '+' : '';
                const color = d.delta > 5 ? '#dc2626' : d.delta < -5 ? '#16a34a' : '#6b7280';
                return `
                  <tr style="border-top:1px solid #f1f5f9;">
                    <td style="padding:3px 8px;">${escapeHtml((d.activity.description || d.activity.activity_id_text || '').slice(0, 30))}${(d.activity.description||'').length > 30 ? '…' : ''}</td>
                    <td style="padding:3px 8px;">${escapeHtml(d.p6.finish_date || '—')}</td>
                    <td style="padding:3px 8px;">${escapeHtml(d.latestPlanned || '—')}</td>
                    <td style="padding:3px 8px;text-align:right;font-weight:600;color:${color};">${sign}${d.delta}d</td>
                  </tr>`;
              }).join('')}
            </tbody>
          </table>
          <div style="font-size:10px;color:#6b7280;margin-top:8px;">Δ = days the latest planned cell is past the P6 finish date. Positive = late, negative = early.</div>`
        }
      </div>
    </div>

    <div style="font-size:11px;color:#9ca3af;text-align:center;margin-top:24px;">
      Data refreshes when planning data is re-loaded. Forecast accuracy needs at least one linked past cell with results.
    </div>
  `;
}

function _laCancellationsTabHTML() {
  const allRows   = _cancelRptBuildRows();
  const cancels   = allRows.filter(r => r._type === 'cancellation').length;
  const delays    = allRows.filter(r => r._type === 'delay').length;

  // Unique subsystems + parties for filter dropdowns
  const subsystems = [...new Set(allRows.map(r => r.subsystem).filter(Boolean))].sort();
  const parties    = [...new Set(allRows.map(r => r.party).filter(Boolean))].sort();

  // Phase 4D — category + party rollups for this week's meeting
  const allCancelEvents = (PLANNING_EVENTS || []).filter(e => e.status === 'cancelled');
  const weekStart = dayjs().startOf('week').format('YYYY-MM-DD');
  const weekEnd   = dayjs().endOf('week').format('YYYY-MM-DD');
  const thisWeek = allCancelEvents.filter(e =>
    (e.cancellation_at || e.event_date) >= weekStart && (e.cancellation_at || e.event_date) <= weekEnd + 'T23:59'
  );

  // Group by category
  const catCounts = {};
  thisWeek.forEach(e => {
    const k = e.cancellation_category || 'UNCATEGORIZED';
    catCounts[k] = (catCounts[k] || 0) + 1;
  });
  const catRow = _cancelCats().map(([code, label], ci) => {
    const n     = catCounts[code] || 0;
    const color = _cancelCatColor(code, ci);
    return `<div style="flex:1;min-width:140px;background:#fff;border:1px solid var(--gray-200);border-left:4px solid ${color};border-radius:6px;padding:10px;">
      <div style="font-size:10px;font-weight:700;color:var(--gray-500);text-transform:uppercase;letter-spacing:.03em;">${escapeHtml(label)}</div>
      <div style="font-size:24px;font-weight:700;color:${color};margin-top:4px;">${n}</div>
    </div>`;
  }).join('');

  // Group by responsible party
  const partyCounts = {};
  thisWeek.forEach(e => {
    const k = e.cancellation_responsible_party || 'Unknown';
    partyCounts[k] = (partyCounts[k] || 0) + 1;
  });

  return `
  <div style="display:flex;flex-wrap:wrap;gap:10px;margin-bottom:16px;align-items:center;">
    <div class="kpi-card kpi-mini" style="flex:none;min-width:130px;">
      <div class="kpi-label">Total Records</div>
      <div class="kpi-value" style="font-size:28px;">${allRows.length}</div>
    </div>
    <div class="kpi-card kpi-mini" style="flex:none;min-width:130px;border-left:4px solid #b91c1c;">
      <div class="kpi-label">Cancellations</div>
      <div class="kpi-value" style="font-size:28px;color:#b91c1c;">${cancels}</div>
    </div>
    <div class="kpi-card kpi-mini" style="flex:none;min-width:130px;border-left:4px solid #b45309;">
      <div class="kpi-label">Delays Logged</div>
      <div class="kpi-value" style="font-size:28px;color:#b45309;">${delays}</div>
    </div>
    <div class="kpi-card kpi-mini" style="flex:none;min-width:130px;border-left:4px solid #1e40af;">
      <div class="kpi-label">This Week</div>
      <div class="kpi-value" style="font-size:28px;color:#1e40af;">${thisWeek.length}</div>
    </div>
  </div>

  <!-- Phase 4D: Cancellation breakdown for the weekly meeting -->
  <div style="margin-bottom:18px;">
    <div style="font-size:12px;font-weight:700;color:var(--gray-600);text-transform:uppercase;letter-spacing:.04em;margin-bottom:8px;">
      📊 This week — by category
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;">${catRow}</div>
  </div>

  ${Object.keys(partyCounts).length ? `
  <div style="margin-bottom:18px;">
    <div style="font-size:12px;font-weight:700;color:var(--gray-600);text-transform:uppercase;letter-spacing:.04em;margin-bottom:8px;">
      🏢 This week — by responsible party
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;">
      ${Object.entries(partyCounts).sort((a,b) => b[1]-a[1]).map(([party, n]) =>
        `<div style="background:${party==='BART'?'#dbeafe':party==='HITACHI'?'#fef3c7':'#f3f4f6'};color:${party==='BART'?'#1e3a8a':party==='HITACHI'?'#78350f':'#374151'};padding:8px 14px;border-radius:8px;display:flex;align-items:center;gap:8px;">
          <strong style="font-size:13px;">${escapeHtml(party)}</strong>
          <span style="font-size:18px;font-weight:700;">${n}</span>
        </div>`
      ).join('')}
    </div>
  </div>` : ''}

  <div class="crpt-filter-bar" style="display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end;margin-bottom:14px;padding:12px 14px;background:var(--gray-50);border:1px solid var(--gray-200);border-radius:8px;">
    <div>
      <div class="form-label" style="margin-bottom:3px;font-size:11px;">Type</div>
      <div style="display:flex;gap:0;">
        ${[['all','All'],['cancellations','Cancellations'],['delays','Delays']].map(([v,l]) =>
          `<button class="admin-tab${_cancelRpt.type===v?' active':''}" style="font-size:11px;padding:5px 12px;"
            onclick="_cancelRptSetFilter('type','${v}');this.closest('.crpt-filter-bar').querySelectorAll('[data-crpt-type]').forEach(b=>b.classList.toggle('active',b.dataset.crptType==='${v}'));"
            data-crpt-type="${v}">${l}</button>`).join('')}
      </div>
    </div>
    <div>
      <div class="form-label" style="margin-bottom:3px;font-size:11px;">From</div>
      <input type="date" class="form-input" style="font-size:12px;padding:5px 8px;height:32px;" value="${_cancelRpt.dateFrom}"
        onchange="_cancelRptSetFilter('dateFrom',this.value)">
    </div>
    <div>
      <div class="form-label" style="margin-bottom:3px;font-size:11px;">To</div>
      <input type="date" class="form-input" style="font-size:12px;padding:5px 8px;height:32px;" value="${_cancelRpt.dateTo}"
        onchange="_cancelRptSetFilter('dateTo',this.value)">
    </div>
    <div>
      <div class="form-label" style="margin-bottom:3px;font-size:11px;">Responsible Party</div>
      <select class="form-input" style="font-size:12px;padding:5px 8px;height:32px;min-width:120px;"
        onchange="_cancelRptSetFilter('party',this.value)">
        <option value="">All parties</option>
        ${parties.map(p => `<option value="${escapeHtml(p)}" ${_cancelRpt.party===p?'selected':''}>${escapeHtml(p)}</option>`).join('')}
      </select>
    </div>
    <div>
      <div class="form-label" style="margin-bottom:3px;font-size:11px;">Location</div>
      <input type="text" class="form-input" style="font-size:12px;padding:5px 8px;height:32px;width:130px;"
        placeholder="Filter…" value="${escapeHtml(_cancelRpt.location)}"
        oninput="_cancelRptSetFilter('location',this.value)">
    </div>
    <div>
      <div class="form-label" style="margin-bottom:3px;font-size:11px;">Subsystem</div>
      <select class="form-input" style="font-size:12px;padding:5px 8px;height:32px;min-width:110px;"
        onchange="_cancelRptSetFilter('subsystem',this.value)">
        <option value="">All</option>
        ${subsystems.map(s => `<option value="${escapeHtml(s)}" ${_cancelRpt.subsystem===s?'selected':''}>${escapeHtml(s)}</option>`).join('')}
      </select>
    </div>
    <button class="form-secondary" style="font-size:11px;padding:5px 12px;height:32px;margin-left:auto;"
      onclick="_cancelRpt={dateFrom:'',dateTo:'',type:'all',party:'',location:'',subsystem:''};_cancelRptSel.clear();document.getElementById('lookahead-tab-body').innerHTML=_laCancellationsTabHTML();">
      ✕ Clear
    </button>
    <button id="crpt-export-btn" class="admin-action-btn" style="font-size:11px;padding:5px 14px;height:32px;"
      onclick="_cancelRptExportPDF()">📄 Export All as PDF</button>
  </div>

  <div class="data-card" style="padding:0;overflow:hidden;">
    <table class="data-table" style="table-layout:auto;">
      <thead>
        <tr>
          <th style="width:32px;padding:8px 6px;">
            <input type="checkbox" id="crpt-sel-all" onchange="_cancelRptToggleAll(this.checked)"
              style="width:14px;height:14px;cursor:pointer;">
          </th>
          <th>Date</th>
          <th>Type</th>
          <th>Activity / Category</th>
          <th>Location</th>
          <th>Subsystem</th>
          <th>Reason / Notes</th>
          <th>Responsible Party</th>
          <th>Source · Logged By</th>
        </tr>
      </thead>
      <tbody id="cancel-rpt-body">${_cancelRptTableBody()}</tbody>
    </table>
  </div>`;
}

function _cancelRptExportPDF() {
  const allRows    = _cancelRptBuildRows();
  const filtered   = _cancelRptApplyFilters(allRows);
  const exportRows = _cancelRptSel.size
    ? filtered.filter(r => _cancelRptSel.has(r._id))
    : filtered;

  if (!exportRows.length) { toast('No rows to export', 'warn'); return; }

  const title    = 'Delays & Cancellations Report';
  const project  = 'BART CBTC Testing & Commissioning';
  const genDate  = new Date().toLocaleString();
  const cancels  = exportRows.filter(r => r._type === 'cancellation').length;
  const delays   = exportRows.filter(r => r._type === 'delay').length;

  const rowsHTML = exportRows.map(r => {
    const isCxl = r._type === 'cancellation';
    const borderColor = isCxl ? '#b91c1c' : '#b45309';
    const typeLabel   = isCxl ? '✕ Cancellation' : '⚠ Delay';
    const typeStyle   = isCxl
      ? 'background:#fef2f2;color:#b91c1c;border:1px solid #fca5a5;'
      : 'background:#fffbeb;color:#b45309;border:1px solid #fde68a;';
    return `
      <tr style="border-left:4px solid ${borderColor};">
        <td style="white-space:nowrap;font-weight:600;font-size:11px;">${r.date || '—'}</td>
        <td><span style="padding:2px 7px;border-radius:8px;font-size:10px;font-weight:700;${typeStyle}">${typeLabel}</span></td>
        <td style="font-size:11px;max-width:180px;">${r.title}</td>
        <td style="font-size:11px;">${r.location || '—'}</td>
        <td style="font-size:11px;">${r.subsystem || '—'}</td>
        <td style="font-size:11px;max-width:200px;">${r.reason || '—'}${r.duration ? ` (${r.duration})` : ''}</td>
        <td style="font-size:11px;font-weight:700;color:${borderColor};">${r.party || '—'}</td>
        <td style="font-size:10px;color:#6b7280;">${r.source}<br>${r.loggedBy}${r.loggedAt ? ' · '+r.loggedAt : ''}</td>
      </tr>`;
  }).join('');

  const html = `<!DOCTYPE html><html><head><meta charset="utf-8">
  <title>${title}</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: Arial, sans-serif; font-size: 12px; color: #111; padding: 24px; }
    .report-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 20px; border-bottom: 3px solid #e60012; padding-bottom: 12px; }
    .report-title { font-size: 20px; font-weight: 800; color: #e60012; }
    .report-sub { font-size: 12px; color: #6b7280; margin-top: 3px; }
    .report-meta { font-size: 11px; color: #9ca3af; text-align: right; }
    .kpi-row { display: flex; gap: 16px; margin-bottom: 16px; }
    .kpi-box { padding: 10px 16px; border-radius: 6px; border: 1px solid #e5e7eb; flex: 1; }
    .kpi-box .lbl { font-size: 10px; text-transform: uppercase; letter-spacing: .5px; color: #9ca3af; }
    .kpi-box .val { font-size: 24px; font-weight: 800; margin-top: 2px; }
    table { width: 100%; border-collapse: collapse; font-size: 11px; }
    th { background: #1f2937; color: #fff; padding: 7px 8px; text-align: left; font-weight: 600; font-size: 10px; text-transform: uppercase; letter-spacing: .4px; }
    td { padding: 7px 8px; border-bottom: 1px solid #e5e7eb; vertical-align: top; }
    tr:nth-child(even) td { background: #f9fafb; }
    tr:nth-child(even) td:first-child { background: inherit; }
    .filter-summary { font-size: 10px; color: #6b7280; margin-bottom: 10px; }
    @media print { body { padding: 12px; } }
  </style>
  </head><body>
  <div class="report-header">
    <div>
      <div class="report-title">${title}</div>
      <div class="report-sub">${project}</div>
    </div>
    <div class="report-meta">Generated: ${genDate}<br>${exportRows.length} record${exportRows.length!==1?'s':''}</div>
  </div>
  <div class="kpi-row">
    <div class="kpi-box"><div class="lbl">Total</div><div class="val">${exportRows.length}</div></div>
    <div class="kpi-box" style="border-left:4px solid #b91c1c;"><div class="lbl">Cancellations</div><div class="val" style="color:#b91c1c;">${cancels}</div></div>
    <div class="kpi-box" style="border-left:4px solid #b45309;"><div class="lbl">Delays Logged</div><div class="val" style="color:#b45309;">${delays}</div></div>
  </div>
  ${Object.entries(_cancelRpt).some(([,v])=>v&&v!=='all') ? `<div class="filter-summary">Filters: ${
    [_cancelRpt.type!=='all'?'Type: '+_cancelRpt.type:'',
     _cancelRpt.dateFrom?'From: '+_cancelRpt.dateFrom:'',
     _cancelRpt.dateTo?'To: '+_cancelRpt.dateTo:'',
     _cancelRpt.party?'Party: '+_cancelRpt.party:'',
     _cancelRpt.location?'Location: '+_cancelRpt.location:'',
     _cancelRpt.subsystem?'Subsystem: '+_cancelRpt.subsystem:''
    ].filter(Boolean).join(' · ')
  }</div>` : ''}
  <table>
    <thead><tr>
      <th>Date</th><th>Type</th><th>Activity / Category</th><th>Location</th>
      <th>Subsystem</th><th>Reason / Notes</th><th>Responsible Party</th><th>Source · Logged By</th>
    </tr></thead>
    <tbody>${rowsHTML}</tbody>
  </table>
  <script>window.onload=function(){window.print();};<\/script>
  </body></html>`;

  const w = window.open('', '_blank', 'width=1100,height=800');
  if (!w) { toast('Pop-up blocked — allow pop-ups to export PDF', 'warn'); return; }
  w.document.write(html);
  w.document.close();
}

// ── PTO conflict detection utility (used by Batch 4 calendar) ─
function _ptoOverlapsRange(resourceId, dateISO, startTime, endTime) {
  // Returns the conflicting approved PTO row or null
  if (!resourceId || !dateISO) return null;
  const target = new Date(dateISO + 'T00:00:00');
  const candidates = PTO_REQUESTS.filter(p =>
    p.status === 'approved' &&
    p.resource_id === resourceId
  );
  for (const p of candidates) {
    const s = new Date(p.start_date + 'T00:00:00');
    const e = new Date(p.end_date   + 'T00:00:00');
    if (target < s || target > e) continue;
    if (!p.partial_day) return p;
    // Partial day: check time overlap if event has times
    if (!startTime || !endTime || !p.partial_start || !p.partial_end) return p;
    if (startTime < p.partial_end && endTime > p.partial_start) return p;
  }
  return null;
}

function _ptoActiveOnDate(dateISO) {
  // Returns array of { request, resource } for all approved PTO active on dateISO
  if (!dateISO) return [];
  const target = new Date(dateISO + 'T00:00:00');
  return PTO_REQUESTS
    .filter(p => p.status === 'approved')
    .filter(p => {
      const s = new Date(p.start_date + 'T00:00:00');
      const e = new Date(p.end_date   + 'T00:00:00');
      return target >= s && target <= e;
    })
    .map(p => ({
      request:  p,
      resource: PLANNING_RESOURCES.find(r => r.id === p.resource_id) || null,
    }));
}

// ── Main Admin Planning page render ──────────────────────────
function renderAdminPlanning() {
  const hero = document.getElementById('admin-planning-hero-content');
  const body = document.getElementById('admin-planning-content');
  if (!body) return;
  if (currentRoleUser?.role !== 'admin') {
    body.innerHTML = `<div class="docs-empty"><h3>Admin only</h3><p>You don't have permission to view this page.</p></div>`;
    return;
  }

  if (hero) hero.innerHTML = `
    <h1 style="margin:0;font-size:28px;font-weight:700;">Planning Admin</h1>
    <p style="margin:6px 0 0;color:var(--gray-500);font-size:14px;">
      Upload weekly lookahead, resolve unmatched rows, manage resources, and review conflicts.
    </p>`;

  const deletedCount = (PLANNING_ACTIVITIES || []).filter(a => a.deleted_at).length;
  const tabs = [
    ['upload',    'Upload Lookahead'],
    ['review',    'Review Queue'],
    ['conflicts', 'Conflicts'],
    ['resources', 'Resources'],
    ['deleted',   `Recently Deleted${deletedCount ? ` (${deletedCount})` : ''}`],
    ['history',   'Import History'],
  ];

  body.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;border-bottom:2px solid var(--gray-200);padding-bottom:0;">
      <div style="display:flex;gap:0;">
        ${tabs.map(([id, label]) => `
          <button class="admin-tab${_adminPlanningTab === id ? ' active' : ''}" data-ap-tab="${id}" onclick="_adminPlanningSetTab('${id}')">${label}</button>
        `).join('')}
      </div>
      <div style="display:flex;gap:8px;">
        <button class="form-secondary" onclick="showPage('lookahead')">📅 Lookahead</button>
        <button class="form-secondary" onclick="loadPlanningData(true).then(renderAdminPlanning);">↻ Refresh</button>
      </div>
    </div>
    <div id="admin-planning-tab-body"></div>
  `;
  _renderAdminPlanningTabBody();
}

function _adminPlanningSetTab(t) {
  _adminPlanningTab = t;
  document.querySelectorAll('#admin-planning-content [data-ap-tab]').forEach(b => {
    b.classList.toggle('active', b.getAttribute('data-ap-tab') === t);
  });
  _renderAdminPlanningTabBody();
}

function _renderAdminPlanningTabBody() {
  const el = document.getElementById('admin-planning-tab-body');
  if (!el) return;
  const tab = _adminPlanningTab;
  if (tab === 'upload')    el.innerHTML = _apUploadStub();
  if (tab === 'review')    el.innerHTML = _apReviewStub();
  if (tab === 'conflicts') el.innerHTML = _apConflictsStub();
  if (tab === 'resources') el.innerHTML = _apResourcesStub();
  if (tab === 'deleted')   el.innerHTML = _apDeletedActivitiesHTML();
  if (tab === 'history')   el.innerHTML = _apHistoryStub();
}

// ─── Recently Deleted activities tab (Phase 3A) ──────────────
function _apDeletedActivitiesHTML() {
  const deleted = (PLANNING_ACTIVITIES || [])
    .filter(a => a.deleted_at)
    .sort((a, b) => (b.deleted_at || '').localeCompare(a.deleted_at || ''));

  if (deleted.length === 0) {
    return `
      <div class="data-card" style="padding:48px;text-align:center;">
        <div style="font-size:48px;margin-bottom:12px;">🗑</div>
        <h3 style="margin:0 0 6px;font-weight:600;color:var(--gray-600);">No deleted activities</h3>
        <p style="margin:0;color:var(--gray-500);font-size:13px;">
          Activities soft-deleted from the master grid will appear here for review and restore.
        </p>
      </div>`;
  }

  return `
    <div class="data-card" style="padding:0;">
      <div style="padding:12px 16px;background:#fef3c7;border-bottom:1px solid var(--gray-200);font-size:12px;color:#78350f;">
        🗂 Soft-deleted activities stay in the database for audit purposes. Restore brings them back to the grid but does <strong>not</strong> auto-uncancel events that were cancelled when the row was deleted.
      </div>
      <table style="width:100%;border-collapse:collapse;font-size:13px;">
        <thead>
          <tr style="background:#f8fafc;border-bottom:1px solid var(--gray-200);">
            <th style="text-align:left;padding:8px 12px;font-weight:600;color:var(--gray-600);">Description</th>
            <th style="text-align:left;padding:8px 12px;font-weight:600;color:var(--gray-600);">Group</th>
            <th style="text-align:left;padding:8px 12px;font-weight:600;color:var(--gray-600);">Location</th>
            <th style="text-align:left;padding:8px 12px;font-weight:600;color:var(--gray-600);">Deleted</th>
            <th style="text-align:left;padding:8px 12px;font-weight:600;color:var(--gray-600);">By</th>
            <th style="text-align:left;padding:8px 12px;font-weight:600;color:var(--gray-600);">Reason</th>
            <th style="text-align:left;padding:8px 12px;font-weight:600;color:var(--gray-600);">Events</th>
            <th style="text-align:right;padding:8px 12px;font-weight:600;color:var(--gray-600);">Actions</th>
          </tr>
        </thead>
        <tbody>
          ${deleted.map(a => {
            const meta = _groupMeta(a.activity_group || 'other');
            const evCount = (PLANNING_EVENTS || []).filter(e => e.planning_activity_id === a.id).length;
            const delByName = (window.PROFILES || []).find(p => p.id === a.deleted_by)?.display_name
                          || (window.PROFILES || []).find(p => p.id === a.deleted_by)?.email
                          || (a.deleted_by ? a.deleted_by.slice(0, 8) : '—');
            return `<tr style="border-bottom:1px solid var(--gray-100);">
              <td style="padding:8px 12px;max-width:280px;">${escapeHtml(a.description || a.activity_id_text || '—')}</td>
              <td style="padding:8px 12px;"><span style="background:${meta.bg};color:${meta.fg};padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600;">${meta.label}</span></td>
              <td style="padding:8px 12px;color:var(--gray-600);">${escapeHtml(a.location || '—')}</td>
              <td style="padding:8px 12px;color:var(--gray-500);font-size:11px;white-space:nowrap;">${a.deleted_at ? dayjs(a.deleted_at).format('YYYY-MM-DD HH:mm') : '—'}</td>
              <td style="padding:8px 12px;color:var(--gray-500);font-size:11px;">${escapeHtml(delByName)}</td>
              <td style="padding:8px 12px;color:var(--gray-600);font-style:italic;max-width:200px;">${escapeHtml(a.deletion_reason || '—')}</td>
              <td style="padding:8px 12px;color:var(--gray-500);font-size:11px;">${evCount}</td>
              <td style="padding:8px 12px;text-align:right;white-space:nowrap;">
                <button class="form-secondary" style="font-size:11px;padding:4px 10px;" onclick="_apRestoreActivity('${a.id}')">↩ Restore</button>
                <button class="form-secondary" style="font-size:11px;padding:4px 10px;color:#dc2626;border-color:#fca5a5;" onclick="_apHardDeleteActivity('${a.id}')">✕ Purge</button>
              </td>
            </tr>`;
          }).join('')}
        </tbody>
      </table>
    </div>
  `;
}

async function _apRestoreActivity(activityId) {
  const a = (PLANNING_ACTIVITIES || []).find(x => x.id === activityId);
  if (!a) return;
  if (!confirm(`Restore "${a.description || a.activity_id_text || '—'}"?\n\nThis brings the activity row back. Events that were cancelled when the row was deleted stay cancelled (you can uncancel them individually).`)) return;
  try {
    await _dbUpdate('planning_activities', {
      deleted_at:      null,
      deleted_by:      null,
      deletion_reason: null,
    }, { id: activityId });
    toast('✓ Activity restored', 'success');
    await loadPlanningData(true);
    renderAdminPlanning();
  } catch (err) {
    toast('Restore failed: ' + err.message, 'error');
  }
}

async function _apHardDeleteActivity(activityId) {
  const a = (PLANNING_ACTIVITIES || []).find(x => x.id === activityId);
  if (!a) return;
  if (!confirm(`PERMANENTLY DELETE "${a.description || a.activity_id_text || '—'}"?\n\nThis cascades to all events on this row. This cannot be undone.\n\nType "delete" in the next prompt to confirm.`)) return;
  const t = prompt('Type "delete" to confirm:');
  if (t !== 'delete') { toast('Cancelled', 'warn'); return; }
  try {
    // Cascade in code (FK is ON DELETE CASCADE for events but not for activity_resources)
    const arRows = (PLANNING_ACTIVITY_RES || []).filter(ar => ar.planning_activity_id === activityId);
    for (const ar of arRows) await _dbDelete('planning_activity_resources', { id: ar.id });
    await _dbDelete('planning_activities', { id: activityId });
    toast('✓ Purged permanently', 'success');
    await loadPlanningData(true);
    renderAdminPlanning();
  } catch (err) {
    toast('Purge failed: ' + err.message, 'error');
  }
}

