// ╔════════════════════════════════════════════════════════════════════════╗
// ║  FORMS — Test Data Sheets module                                       ║
// ║                                                                        ║
// ║  Storage today: Supabase Storage bucket "forms"                        ║
// ║  Migration:     Swap _formsStorage adapter to MS Graph at SharePoint   ║
// ║                 cutover — nothing above the adapter changes.           ║
// ║                                                                        ║
// ║  Tables: forms, form_test_item_links, form_template_links              ║
// ║  Schema: see supabase_forms_schema.sql                                 ║
// ╚════════════════════════════════════════════════════════════════════════╝

const _formsStorage = {
  bucket: 'forms',
  _objectUrl(path, cacheBust = false) {
    const cleanPath = String(path || '').split('/').map(encodeURIComponent).join('/');
    const url = `${SUPABASE_URL}/storage/v1/object/${this.bucket}/${cleanPath}`;
    return cacheBust ? `${url}?t=${Date.now()}` : url;
  },
  _headers(extra = {}) {
    return {
      apikey: SUPABASE_ANON_KEY,
      Authorization: _getAuthHeader(),
      ...extra,
    };
  },
  async upload(formId, file) {
    const path = `${formId}.pdf`;
    return this.uploadPath(path, file);
  },
  async uploadPath(path, file, contentType = 'application/pdf') {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 30000);
    try {
      const res = await fetch(this._objectUrl(path), {
        method: 'POST',
        signal: ctrl.signal,
        cache: 'no-store',
        headers: this._headers({
          'Content-Type': contentType,
          'x-upsert': 'true',
        }),
        body: file,
      });
      clearTimeout(timer);
      if (!res.ok) throw new Error(`Storage upload failed (${res.status}): ${await res.text()}`);
      return path;
    } catch (e) {
      clearTimeout(timer);
      if (e.name === 'AbortError') throw new Error('Storage upload timed out after 30s');
      throw e;
    }
  },
  async downloadBlob(path) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 30000);
    try {
      const res = await fetch(this._objectUrl(path, true), {
        method: 'GET',
        signal: ctrl.signal,
        cache: 'no-store',
        headers: this._headers({
          Accept: 'application/pdf',
          'Cache-Control': 'no-cache',
          Pragma: 'no-cache',
        }),
      });
      clearTimeout(timer);
      if (!res.ok) throw new Error(`Storage download failed (${res.status}): ${await res.text()}`);
      return await res.blob();
    } catch (e) {
      clearTimeout(timer);
      if (e.name === 'AbortError') throw new Error('Storage download timed out after 30s');
      throw e;
    }
  },
  async downloadBytes(path) {
    const blob = await this.downloadBlob(path);
    return new Uint8Array(await blob.arrayBuffer());
  },
  async uploadJson(path, data) {
    const text = JSON.stringify(data);
    const blob = new Blob([text], { type: 'application/json' });
    await this.uploadPath(path, blob, 'application/json');
    const saved = await this.downloadJson(path);
    if (JSON.stringify(saved) !== text) throw new Error('Storage verification failed: saved form state did not match');
    return saved;
  },
  async downloadJson(path) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 30000);
    try {
      const res = await fetch(this._objectUrl(path, true), {
        method: 'GET',
        signal: ctrl.signal,
        cache: 'no-store',
        headers: this._headers({
          Accept: 'application/json',
          'Cache-Control': 'no-cache',
          Pragma: 'no-cache',
        }),
      });
      clearTimeout(timer);
      if (res.status === 404) return null;
      if (!res.ok) throw new Error(`Storage state download failed (${res.status}): ${await res.text()}`);
      return await res.json();
    } catch (e) {
      clearTimeout(timer);
      if (e.name === 'AbortError') throw new Error('Storage state download timed out after 30s');
      throw e;
    }
  },
  async verifyBytes(path, expectedBytes) {
    const actual = await this.downloadBytes(path);
    const expectedHash = await _sha256Hex(expectedBytes);
    const actualHash = await _sha256Hex(actual);
    if (expectedHash !== actualHash) {
      throw new Error('Storage verification failed: uploaded PDF did not match the saved PDF');
    }
    return actual;
  },
  async copy(sourcePath, destPath) {
    const { error } = await _sb.storage.from(this.bucket).copy(sourcePath, destPath);
    if (error) throw new Error('Storage copy failed: ' + error.message);
  },
  async remove(path) {
    const { error } = await _sb.storage.from(this.bucket).remove([path]);
    if (error) throw new Error('Storage delete failed: ' + error.message);
  },
};

async function _sha256Hex(bytes) {
  const data = bytes instanceof Uint8Array ? bytes : new Uint8Array(await bytes.arrayBuffer());
  const hash = await crypto.subtle.digest('SHA-256', data);
  return Array.from(new Uint8Array(hash)).map(b => b.toString(16).padStart(2, '0')).join('');
}

async function _inspectPdfBytes(bytes) {
  const doc = await PDFLib.PDFDocument.load(bytes);
  const form = doc.getForm();
  return {
    bytes: bytes.length,
    fields: form.getFields().map(f => {
      const name = f.getName();
      const type = f.constructor.name;
      let value = null;
      try {
        if (type === 'PDFTextField') value = f.getText();
        else if (type === 'PDFCheckBox') value = f.isChecked();
        else if (type === 'PDFRadioGroup') value = f.getSelected();
        else if (type === 'PDFDropdown' || type === 'PDFOptionList') value = f.getSelected();
      } catch { /* inspection only */ }
      return { name, type, value };
    }),
  };
}

function _formsEditStatePath(form) {
  const path = form?.storage_path || `${form?.id || 'form'}.pdf`;
  return `${path}.edit-state.json`;
}

function _emptyFormEditState() {
  return { version: 2, fields: {}, signatures: {}, layouts: [], updatedAt: null };
}

function _normalizeFormEditState(state) {
  const base = _emptyFormEditState();
  if (!state || typeof state !== 'object') return base;
  return {
    version: 2,
    fields: state.fields && typeof state.fields === 'object' ? state.fields : {},
    signatures: state.signatures && typeof state.signatures === 'object' ? state.signatures : {},
    layouts: Array.isArray(state.layouts) ? state.layouts : [],
    updatedAt: state.updatedAt || null,
  };
}

async function _formsLoadEditState(form) {
  try {
    return _normalizeFormEditState(await _formsStorage.downloadJson(_formsEditStatePath(form)));
  } catch (e) {
    console.warn('[_formsLoadEditState]', e.message);
    return _emptyFormEditState();
  }
}

async function _formsSaveEditState(formId, state) {
  const form = FORMS.find(f => f.id === formId);
  if (!form) throw new Error('Form not found while saving edit state');
  const normalized = _normalizeFormEditState({ ...state, updatedAt: new Date().toISOString() });
  await _formsStorage.uploadJson(_formsEditStatePath(form), normalized);
  await _formsUpdateMetadata(formId, { storage_path: form.storage_path });
  return normalized;
}

let FORMS           = [];
let FORM_TEST_LINKS = [];
let FORM_TPL_LINKS  = [];

async function loadForms() {
  try {
    const [forms, testLinks, tplLinks] = await Promise.all([
      _dbSelect('forms'),
      _dbSelect('form_test_item_links'),
      _dbSelect('form_template_links'),
    ]);
    FORMS           = forms     || [];
    FORM_TEST_LINKS = testLinks || [];
    FORM_TPL_LINKS  = tplLinks  || [];
  } catch (e) {
    console.warn('[loadForms]', e.message);
    FORMS = []; FORM_TEST_LINKS = []; FORM_TPL_LINKS = [];
  }
}

function _formsForTest(testId) {
  const ids = FORM_TEST_LINKS.filter(l => l.test_id === testId).map(l => l.form_id);
  return FORMS.filter(f => ids.includes(f.id));
}
function _formsForTemplate(templateId) {
  const ids = FORM_TPL_LINKS.filter(l => l.template_id === templateId).map(l => l.form_id);
  return FORMS.filter(f => ids.includes(f.id));
}
function _formsForTemplateTestCase(templateId, testCaseCode) {
  const code = String(testCaseCode || '').trim();
  if (!templateId || !code) return [];
  const ids = FORM_TPL_LINKS
    .filter(l => l.template_id === templateId && String(l.test_case_code || '').trim() === code)
    .map(l => l.form_id);
  return FORMS.filter(f => ids.includes(f.id));
}
function _formsLegacyForTemplate(templateId) {
  const ids = FORM_TPL_LINKS
    .filter(l => l.template_id === templateId && !String(l.test_case_code || '').trim())
    .map(l => l.form_id);
  return FORMS.filter(f => ids.includes(f.id));
}
function _formsCountForTest(testId) {
  return FORM_TEST_LINKS.filter(l => l.test_id === testId).length;
}

function _formsNewId() {
  return (window.crypto && crypto.randomUUID)
    ? crypto.randomUUID()
    : 'frm-' + Date.now() + '-' + Math.random().toString(36).slice(2, 10);
}

async function _formsCreate({ name, description, subsystem, phase, location, isTemplate, sourceFormId, originalFilename, fileSize, file }) {
  const id = _formsNewId();
  await _formsStorage.upload(id, file);
  const actor = currentProfile?.full_name || currentRoleUser?.name || null;
  const row = {
    id, name, description: description || null,
    subsystem: subsystem || null, phase: phase || null, location: location || null,
    storage_path: `${id}.pdf`,
    original_filename: originalFilename || null, file_size: fileSize || null,
    is_template: !!isTemplate, source_form_id: sourceFormId || null,
    created_by: actor, updated_by: actor,
  };
  const [inserted] = await _dbInsert('forms', [row]);
  FORMS.push(inserted);
  return inserted;
}

async function _formsUpdateMetadata(formId, patch) {
  patch.updated_by = currentProfile?.full_name || currentRoleUser?.name || null;
  patch.updated_at = new Date().toISOString();
  const [updated] = await _dbUpdate('forms', patch, { id: formId });
  if (!updated) throw new Error('Form metadata update returned no rows');
  const i = FORMS.findIndex(f => f.id === formId);
  if (i >= 0) FORMS[i] = updated;
  return updated;
}

async function _formsReuploadFile(formId, fileOrBlob, expectedBytes = null) {
  const form = FORMS.find(f => f.id === formId);
  const storagePath = form?.storage_path || `${formId}.pdf`;
  const bytesToVerify = expectedBytes
    ? _clonePdfBytes(expectedBytes)
    : new Uint8Array(await fileOrBlob.arrayBuffer());
  await _formsStorage.uploadPath(storagePath, fileOrBlob);
  await _formsStorage.verifyBytes(storagePath, bytesToVerify);
  return _formsUpdateMetadata(formId, { file_size: fileOrBlob.size, storage_path: storagePath });
}

async function _formsDelete(formId) {
  const form = FORMS.find(f => f.id === formId);
  if (!form) return;
  try { await _formsStorage.remove(form.storage_path); }
  catch (e) { console.warn('[_formsDelete] storage remove:', e.message); }
  await _dbDelete('forms', { id: formId });
  FORMS           = FORMS          .filter(f => f.id !== formId);
  FORM_TEST_LINKS = FORM_TEST_LINKS.filter(l => l.form_id !== formId);
  FORM_TPL_LINKS  = FORM_TPL_LINKS .filter(l => l.form_id !== formId);
  // Invalidate local caches so stale bytes never resurface.
  _idbRecentDelete(formId).catch(() => {});
  _idbDraftDelete(formId).catch(() => {});
  _idbPinDelete(formId).catch(() => {});
}

// ── Scope-aware form ↔ test linking ──────────────────────────────────────
// A link row is keyed by (form_id, test_id, asset_id). The asset_id column
// is nullable:
//   • asset_id = NULL  → "parent-scope": link applies to the parent test case
//                        as a whole. For a parent test case with N child
//                        assets, the single PDF covers all of them. Statuses
//                        remain per-asset; only the form is shared.
//   • asset_id = <uuid> → "per-asset": link applies only to that specific
//                        child asset row. Each asset can carry its own form.
// For a standalone (non-parent) test case, asset_id is always NULL and
// behaves exactly like before the migration.
async function _formsLinkToTest(formId, testId, assetId = null) {
  const norm = assetId || null;
  if (FORM_TEST_LINKS.find(l => l.form_id === formId && l.test_id === testId && (l.asset_id || null) === norm)) return;
  const linkedBy = currentProfile?.full_name || currentRoleUser?.name || null;
  const [link] = await _dbInsert('form_test_item_links', [{
    form_id: formId, test_id: testId, asset_id: norm, linked_by: linkedBy,
  }]);
  FORM_TEST_LINKS.push(link);
}
async function _formsUnlinkFromTest(formId, testId, assetId = undefined) {
  // assetId === undefined → unlink ALL scopes for this (form, test) pair (legacy behavior).
  // assetId === null      → unlink the parent-scope row only (asset_id IS NULL).
  // assetId === <uuid>    → unlink that specific per-asset row only.
  // Delete by primary key id so PostgREST's eq.null limitation never bites us.
  const norm = assetId === undefined ? undefined : (assetId || null);
  const targets = FORM_TEST_LINKS.filter(l => {
    if (l.form_id !== formId || l.test_id !== testId) return false;
    if (norm === undefined) return true;
    return (l.asset_id || null) === norm;
  });
  for (const link of targets) {
    if (!link.id) continue;
    try { await _dbDelete('form_test_item_links', { id: link.id }); }
    catch (e) { console.warn('[_formsUnlinkFromTest] delete by id failed:', e.message); }
  }
  FORM_TEST_LINKS = FORM_TEST_LINKS.filter(l => !targets.includes(l));
}

// Returns the forms relevant to a single TI row, taking parent/child scope
// into account. Used by the test-register forms button and per-row counts.
function _formsForTestRow(row) {
  if (!row) return [];
  const isChild = row.ParentTestId && row.AssetId;
  if (!isChild) {
    // Parent or standalone test case: include every link for this test_id
    // regardless of scope.
    const ids = FORM_TEST_LINKS.filter(l => l.test_id === row.TestID).map(l => l.form_id);
    return FORMS.filter(f => ids.includes(f.id));
  }
  // Child asset row: parent-scoped links + this asset's own per-asset links.
  const ids = FORM_TEST_LINKS
    .filter(l => l.test_id === row.ParentTestId &&
      (l.asset_id == null || String(l.asset_id) === String(row.AssetId)))
    .map(l => l.form_id);
  return FORMS.filter(f => ids.includes(f.id));
}
function _formsCountForTestRow(row) {
  return _formsForTestRow(row).length;
}

// Returns a deduped attachment plan for a parent (or standalone) test case,
// used by the Test Report Extract to decide what to bundle and how to label
// each attachment. Children are NOT processed here — they share their
// parent's plan.
//   Each entry: { form, scope: 'parent'|'asset', assetId, assetName, scopeLabel, sortKey }
function _formsAttachmentPlanForTestCase(parentOrStandaloneRow) {
  if (!parentOrStandaloneRow) return [];
  const links = FORM_TEST_LINKS.filter(l => l.test_id === parentOrStandaloneRow.TestID);
  const plan = links.map(l => {
    const form = FORMS.find(f => f.id === l.form_id);
    if (!form) return null;
    if (l.asset_id == null) {
      return { form, scope: 'parent', assetId: null, assetName: null,
        scopeLabel: parentOrStandaloneRow.IsParent ? 'Covers all assets' : '',
        sortKey: `0_${form.name || ''}` };
    }
    const asset = (typeof ASSETS !== 'undefined' ? ASSETS : []).find(a => a.id === l.asset_id);
    const assetName = asset?.name || `(asset ${String(l.asset_id).slice(0, 8)})`;
    return { form, scope: 'asset', assetId: l.asset_id, assetName,
      scopeLabel: `Asset: ${assetName}`,
      sortKey: `1_${assetName}_${form.name || ''}` };
  }).filter(Boolean);
  plan.sort((a, b) => a.sortKey.localeCompare(b.sortKey, undefined, { numeric: true, sensitivity: 'base' }));
  return plan;
}

// Convenience: list all link rows for a test case with their resolved scope.
// Used by the parent's form-picker UI to render the scope column + unlink
// buttons that target the exact (form, asset) row.
function _formsLinkRowsForTestCase(testId) {
  return FORM_TEST_LINKS
    .filter(l => l.test_id === testId)
    .map(l => {
      const form = FORMS.find(f => f.id === l.form_id);
      const asset = l.asset_id ? (typeof ASSETS !== 'undefined' ? ASSETS : []).find(a => a.id === l.asset_id) : null;
      return { link: l, form, asset, scope: l.asset_id ? 'asset' : 'parent' };
    })
    .filter(r => r.form);
}
async function _formsLinkToTemplate(formId, templateId, testCaseCode = '') {
  const scopeCode = String(testCaseCode || '').trim();
  if (FORM_TPL_LINKS.find(l => l.form_id === formId && l.template_id === templateId && String(l.test_case_code || '').trim() === scopeCode)) return;
  const linkedBy = currentProfile?.full_name || currentRoleUser?.name || null;
  const [link] = await _dbInsert('form_template_links', [{
    form_id: formId,
    template_id: templateId,
    test_case_code: scopeCode || null,
    linked_by: linkedBy,
  }]);
  FORM_TPL_LINKS.push(link);
}
async function _formsUnlinkFromTemplate(formId, templateId, testCaseCode) {
  const matches = FORM_TPL_LINKS.filter(l => {
    if (l.form_id !== formId || l.template_id !== templateId) return false;
    if (testCaseCode === undefined) return true;
    return String(l.test_case_code || '').trim() === String(testCaseCode || '').trim();
  });
  for (const link of matches) {
    await _dbDelete('form_template_links', { id: link.id });
  }
  const removed = new Set(matches.map(l => l.id));
  FORM_TPL_LINKS = FORM_TPL_LINKS.filter(l => !removed.has(l.id));
}

// Deployment clone — called from confirmDeploy after test_items are inserted.
async function _formsCloneTemplateForDeployment(templateId, depId, selections, tpl) {
  const scopedLinks = FORM_TPL_LINKS.filter(l => l.template_id === templateId && String(l.test_case_code || '').trim());
  if (!scopedLinks.length) return 0;
  let cloned = 0;
  for (const s of selections) {
    for (const tcCode of s.tcCodes) {
      const newTestId = `${depId}-${s.locId}-${tcCode}`;
      const templateForms = _formsForTemplateTestCase(templateId, tcCode);
      for (const src of templateForms) {
        try {
          const newId   = _formsNewId();
          const newPath = `${newId}.pdf`;
          await _formsStorage.copy(src.storage_path, newPath);
          const actor = currentProfile?.full_name || currentRoleUser?.name || null;
          const row = {
            id: newId, name: src.name, description: src.description,
            subsystem: tpl.subsystem || src.subsystem,
            phase:     s.phaseName  || src.phase,
            location:  s.locName    || src.location,
            storage_path: newPath,
            original_filename: src.original_filename, file_size: src.file_size,
            is_template: false, source_form_id: src.id,
            created_by: actor, updated_by: actor,
          };
          const [inserted] = await _dbInsert('forms', [row]);
          FORMS.push(inserted);
          await _formsLinkToTest(inserted.id, newTestId);
          cloned += 1;
        } catch (e) { console.warn('[_formsCloneTemplateForDeployment]', e.message); }
      }
    }
  }
  return cloned;
}

// ── PDF VIEWER (pdf.js render + HTML overlay + pdf-lib save) ────────────
// Desktop-first, touch-safe. Offline-capable via IndexedDB drafts + SW cache.
// Public API kept stable: openFormViewer, saveFormPDF, downloadFormPDF, closeFormViewer.

let _pdfViewerState = null;
let _pdfBeforeUnloadBound = false;
const _PDF_AUTOSAVE_DELAY_MS = 1500;
const _PDF_ZOOM_MIN = 0.5;
const _PDF_ZOOM_MAX = 3.0;

// ── IndexedDB tiny wrapper for offline drafts + pinned PDFs + recents ──
const _IDB_DB      = 'cxportal-forms';
const _IDB_VER     = 2;
const _IDB_DRAFTS  = 'drafts';
const _IDB_PINS    = 'pins';
const _IDB_RECENTS = 'recents';
const _RECENTS_MAX = 20;
let   _idbPromise = null;

function _idbOpen() {
  if (_idbPromise) return _idbPromise;
  _idbPromise = new Promise((resolve, reject) => {
    const req = indexedDB.open(_IDB_DB, _IDB_VER);
    req.onupgradeneeded = (e) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains(_IDB_DRAFTS))  db.createObjectStore(_IDB_DRAFTS,  { keyPath: 'formId' });
      if (!db.objectStoreNames.contains(_IDB_PINS))    db.createObjectStore(_IDB_PINS,    { keyPath: 'formId' });
      if (!db.objectStoreNames.contains(_IDB_RECENTS)) db.createObjectStore(_IDB_RECENTS, { keyPath: 'formId' });
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror   = () => reject(req.error);
  });
  return _idbPromise;
}
async function _idbTx(store, mode, fn) {
  const db = await _idbOpen();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(store, mode);
    const os = tx.objectStore(store);
    const out = fn(os);
    tx.oncomplete = () => resolve(out?.result !== undefined ? out.result : out);
    tx.onerror    = () => reject(tx.error);
    tx.onabort    = () => reject(tx.error);
  });
}
async function _idbDraftGet(formId)            { return _idbTx(_IDB_DRAFTS, 'readonly',  os => os.get(formId)); }
async function _idbDraftPut(record)            { return _idbTx(_IDB_DRAFTS, 'readwrite', os => os.put(record)); }
async function _idbDraftDelete(formId)         { return _idbTx(_IDB_DRAFTS, 'readwrite', os => os.delete(formId)); }
async function _idbDraftAll()                  { return _idbTx(_IDB_DRAFTS, 'readonly',  os => os.getAll()); }
async function _idbPinGet(formId)              { return _idbTx(_IDB_PINS,   'readonly',  os => os.get(formId)); }
async function _idbPinPut(record)              { return _idbTx(_IDB_PINS,   'readwrite', os => os.put(record)); }
async function _idbPinDelete(formId)           { return _idbTx(_IDB_PINS,   'readwrite', os => os.delete(formId)); }
async function _idbPinAll()                    { return _idbTx(_IDB_PINS,   'readonly',  os => os.getAll()); }
async function _idbRecentGet(formId)           { return _idbTx(_IDB_RECENTS,'readonly',  os => os.get(formId)); }
async function _idbRecentPut(record)           { return _idbTx(_IDB_RECENTS,'readwrite', os => os.put(record)); }
async function _idbRecentAll()                 { return _idbTx(_IDB_RECENTS,'readonly',  os => os.getAll()); }
async function _idbRecentDelete(formId)        { return _idbTx(_IDB_RECENTS,'readwrite', os => os.delete(formId)); }
async function _idbRecentTouch(formId, name, updatedAt, bytes, thumb) {
  // Upsert with LRU eviction. `bytes`/`thumb` optional — pass when we have fresh data.
  try {
    const all = (await _idbRecentAll()) || [];
    const now = new Date().toISOString();
    const existing = all.find(r => r.formId === formId);
    const next = {
      formId,
      name: name || existing?.name || '',
      updatedAt: updatedAt || existing?.updatedAt || null,
      openedAt: now,
      bytes: bytes ? (bytes.buffer ? bytes.buffer.slice(0) : new Uint8Array(bytes).buffer) : (existing?.bytes || null),
      thumb: thumb || existing?.thumb || null,
    };
    await _idbRecentPut(next);
    // Evict beyond cap, sorted by openedAt desc.
    const after = (await _idbRecentAll()) || [];
    after.sort((a, b) => (b.openedAt || '').localeCompare(a.openedAt || ''));
    for (let i = _RECENTS_MAX; i < after.length; i++) {
      await _idbRecentDelete(after[i].formId).catch(() => {});
    }
  } catch (e) { console.warn('[_idbRecentTouch]', e.message); }
}

// Render page 1 of an open PDF document to a small JPEG dataURL for use as
// a recents-row thumbnail. Returns null on failure (callers should treat
// this as best-effort decoration).
async function _formsGeneratePageThumb(pdfDoc, maxWidth = 240) {
  try {
    const page = await pdfDoc.getPage(1);
    const baseVp = page.getViewport({ scale: 1 });
    const scale = Math.min(maxWidth / baseVp.width, 1.5);
    const vp = page.getViewport({ scale });
    const canvas = document.createElement('canvas');
    canvas.width  = Math.round(vp.width);
    canvas.height = Math.round(vp.height);
    const ctx = canvas.getContext('2d');
    await page.render({ canvasContext: ctx, viewport: vp }).promise;
    return canvas.toDataURL('image/jpeg', 0.7);
  } catch (e) {
    console.warn('[_formsGeneratePageThumb]', e.message);
    return null;
  }
}

// Request persistent storage so IDB caches (drafts, pins, recents) are not
// evicted under storage pressure. Best-effort, no-op if unsupported / denied.
let _formsStoragePersistRequested = false;
async function _formsRequestPersistentStorage() {
  if (_formsStoragePersistRequested) return;
  _formsStoragePersistRequested = true;
  try {
    if (navigator.storage?.persist) {
      const already = await navigator.storage.persisted?.();
      if (!already) await navigator.storage.persist();
    }
  } catch (e) { console.warn('[_formsRequestPersistentStorage]', e.message); }
}

// ── Forms-page "Recently opened" row ────────────────────────────────────
// Reads from the `recents` IDB store and renders a horizontal strip of
// quick-open tiles above the main forms table. Re-rendered after every
// successful viewer open (see `openFormViewer`).
const _FORMS_RECENTS_ROW_MAX = 8;

function _formsRelativeTime(iso) {
  if (!iso) return '';
  const t = Date.parse(iso);
  if (!t) return '';
  const diff = Date.now() - t;
  const m = Math.round(diff / 60000);
  if (m < 1)    return 'just now';
  if (m < 60)   return `${m}m ago`;
  const h = Math.round(m / 60);
  if (h < 24)   return `${h}h ago`;
  const d = Math.round(h / 24);
  if (d < 7)    return `${d}d ago`;
  return new Date(t).toLocaleDateString();
}

async function _formsRenderRecentsRow() {
  const host = document.getElementById('forms-recents-row');
  if (!host) return;
  let entries = [];
  let pinned = new Set();
  try {
    const [recents, pins] = await Promise.all([_idbRecentAll(), _idbPinAll()]);
    entries = recents || [];
    pinned = new Set((pins || []).map(p => p.formId));
  } catch (e) { console.warn('[_formsRenderRecentsRow]', e.message); host.hidden = true; return; }
  // Filter to forms that still exist locally (FORMS), then sort by openedAt desc.
  const known = new Map(FORMS.map(f => [f.id, f]));
  entries = entries.filter(r => known.has(r.formId));
  entries.sort((a, b) => (b.openedAt || '').localeCompare(a.openedAt || ''));
  entries = entries.slice(0, _FORMS_RECENTS_ROW_MAX);
  if (entries.length === 0) { host.hidden = true; host.innerHTML = ''; return; }
  host.hidden = false;
  const tiles = entries.map(r => {
    const f = known.get(r.formId);
    const sub = [f.phase, f.subsystem].filter(Boolean).join(' · ');
    const isPinned = pinned.has(f.id);
    const visual = r.thumb
      ? `<span class="forms-recent-thumb" style="background-image:url('${r.thumb}');" aria-hidden="true"></span>`
      : `<span class="forms-recent-icon" aria-hidden="true">📄</span>`;
    return `
      <button type="button" class="forms-recent-tile" data-form-id="${escapeHtml(f.id)}"
              title="${escapeHtml(f.name)}${sub ? ' — ' + escapeHtml(sub) : ''}${isPinned ? ' (offline)' : ''}">
        ${visual}
        <span class="forms-recent-body">
          <span class="forms-recent-name">${escapeHtml(f.name)}${isPinned ? ' <span class="forms-recent-pin" title="Available offline">📌</span>' : ''}</span>
          <span class="forms-recent-meta">${escapeHtml(sub || '—')}</span>
          <span class="forms-recent-time">${escapeHtml(_formsRelativeTime(r.openedAt))}</span>
        </span>
        <span class="forms-recent-close" title="Remove from recents"
              data-recent-remove="${escapeHtml(f.id)}">×</span>
      </button>`;
  }).join('');
  host.innerHTML = `
    <div class="forms-recents-head">
      <span class="forms-recents-title">Recently opened</span>
      <button type="button" class="forms-recents-clear" id="forms-recents-clear">Clear</button>
    </div>
    <div class="forms-recents-strip">${tiles}</div>
  `;
  // Delegate clicks: open form, or remove from recents on the × button.
  host.querySelector('.forms-recents-strip').addEventListener('click', (e) => {
    const removeBtn = e.target.closest('[data-recent-remove]');
    if (removeBtn) {
      e.stopPropagation();
      const id = removeBtn.getAttribute('data-recent-remove');
      _idbRecentDelete(id).catch(() => {}).finally(() => _formsRenderRecentsRow());
      return;
    }
    const tile = e.target.closest('.forms-recent-tile');
    if (tile) {
      const id = tile.getAttribute('data-form-id');
      if (id) openFormViewer(id);
    }
  });
  document.getElementById('forms-recents-clear')?.addEventListener('click', async () => {
    try {
      const all = (await _idbRecentAll()) || [];
      await Promise.all(all.map(r => _idbRecentDelete(r.formId).catch(() => {})));
    } finally { _formsRenderRecentsRow(); }
  });
}

// ── Telemetry shim (no-op for now; ready for AppInsights) ───────────────
function formViewerEvent(name, props = {}) {
  if (window.__cxFormsTelemetry) { try { window.__cxFormsTelemetry(name, props); } catch { /* noop */ } }
}

// ── Storage adapter contract (formalized for Azure/SharePoint cutover) ──
// Required methods: upload(formId,file), uploadPath(path,file,contentType?),
// downloadBlob(path), downloadBytes(path), uploadJson(path,data),
// downloadJson(path), verifyBytes(path,expected), copy(src,dst), remove(path).
// Optional: list(prefix), signedUrl(path).
// _formsStorageAzure and _formsStorageGraph are stubs used at cutover.
// eslint-disable-next-line no-unused-vars
const _formsStorageAzure = {
  bucket: 'forms',
  async upload()        { throw new Error('Azure adapter not wired yet'); },
  async uploadPath()    { throw new Error('Azure adapter not wired yet'); },
  async downloadBlob()  { throw new Error('Azure adapter not wired yet'); },
  async downloadBytes() { throw new Error('Azure adapter not wired yet'); },
  async uploadJson()    { throw new Error('Azure adapter not wired yet'); },
  async downloadJson()  { throw new Error('Azure adapter not wired yet'); },
  async verifyBytes()   { throw new Error('Azure adapter not wired yet'); },
  async copy()          { throw new Error('Azure adapter not wired yet'); },
  async remove()        { throw new Error('Azure adapter not wired yet'); },
};
// eslint-disable-next-line no-unused-vars
const _formsStorageGraph = {
  bucket: 'forms',
  async upload()        { throw new Error('SharePoint Graph adapter not wired yet'); },
  async uploadPath()    { throw new Error('SharePoint Graph adapter not wired yet'); },
  async downloadBlob()  { throw new Error('SharePoint Graph adapter not wired yet'); },
  async downloadBytes() { throw new Error('SharePoint Graph adapter not wired yet'); },
  async uploadJson()    { throw new Error('SharePoint Graph adapter not wired yet'); },
  async downloadJson()  { throw new Error('SharePoint Graph adapter not wired yet'); },
  async verifyBytes()   { throw new Error('SharePoint Graph adapter not wired yet'); },
  async copy()          { throw new Error('SharePoint Graph adapter not wired yet'); },
  async remove()        { throw new Error('SharePoint Graph adapter not wired yet'); },
};

function _formsViewerScale(baseViewport, pagesEl) {
  const availableWidth = Math.max(360, (pagesEl?.clientWidth || window.innerWidth) - 48);
  return Math.max(_PDF_ZOOM_MIN, Math.min(_PDF_ZOOM_MAX, availableWidth / baseViewport.width));
}

function _clonePdfBytes(bytes) {
  return bytes instanceof Uint8Array ? bytes.slice() : new Uint8Array(bytes).slice();
}

// ── Open viewer (entry point) ───────────────────────────────────────────
async function openFormViewer(formId) {
  const form = FORMS.find(f => f.id === formId);
  if (!form) { toast('Form not found', 'error'); return; }
  if (typeof pdfjsLib === 'undefined') { toast('PDF viewer library not loaded', 'error'); return; }
  if (!pdfjsLib.GlobalWorkerOptions.workerSrc) {
    pdfjsLib.GlobalWorkerOptions.workerSrc =
      'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/legacy/build/pdf.worker.min.js';
  }
  // Kick off pin + recents lookups in parallel — both are needed before render but
  // can run concurrently with the modal mount.
  const pinP    = _idbPinGet(formId).catch(() => null);
  const recentP = _idbRecentGet(formId).catch(() => null);
  const pin     = await pinP;
  modal({
    title: form.name,
    sub: [form.phase, form.location, form.subsystem].filter(Boolean).join(' · '),
    size: 'pdf',
    body: `
      <div class="pdf-viewer-shell">
        <div class="pdf-viewer-toolbar" id="pdf-viewer-toolbar">
          <div class="pdf-tb-group">
            <button type="button" class="pdf-tb-btn" id="pdf-tb-thumbs"   title="Toggle thumbnails (Alt+T)">☰</button>
            <button type="button" class="pdf-tb-btn" id="pdf-tb-prev"     title="Previous field (Shift+Tab)">◀</button>
            <button type="button" class="pdf-tb-btn" id="pdf-tb-next"     title="Next field (Tab)">▶</button>
            <span class="pdf-tb-divider"></span>
            <button type="button" class="pdf-tb-btn" id="pdf-tb-zoom-out" title="Zoom out (-)">−</button>
            <span id="pdf-tb-zoom-label" class="pdf-tb-label">100%</span>
            <button type="button" class="pdf-tb-btn" id="pdf-tb-zoom-in"  title="Zoom in (+)">+</button>
            <button type="button" class="pdf-tb-btn" id="pdf-tb-fit-w"    title="Fit width">↔</button>
            <button type="button" class="pdf-tb-btn" id="pdf-tb-fit-p"    title="Fit page">⤢</button>
            <span class="pdf-tb-divider"></span>
            <span class="pdf-tb-label">Page</span>
            <input type="number" min="1" id="pdf-tb-page" class="pdf-tb-input" value="1" />
            <span id="pdf-tb-page-total" class="pdf-tb-label">/ 1</span>
          </div>
          <div class="pdf-tb-group pdf-tb-right">
            <label class="pdf-tb-pin" title="Cache PDF locally for offline use">
              <input type="checkbox" id="pdf-tb-pin" ${pin ? 'checked' : ''}/> Available offline
            </label>
            <span id="pdf-tb-status" class="pdf-tb-status pdf-tb-status-saved">Loaded</span>
          </div>
        </div>
        <div class="pdf-viewer-main">
          <aside id="pdf-thumbs" class="pdf-thumbs" hidden></aside>
          <div id="form-viewer-pages" class="pdf-pages"></div>
        </div>
        ${form.description ? `<div class="pdf-viewer-desc">${escapeHtml(form.description)}</div>` : ''}
        <div id="form-viewer-skeleton" class="pdf-viewer-skeleton">
          <div class="pdf-skel-shimmer"></div>
          <div class="pdf-skel-shimmer"></div>
          <div class="pdf-skel-shimmer"></div>
        </div>
        <div id="form-viewer-status" class="pdf-viewer-substatus" style="display:none;"></div>
      </div>
    `,
    footer: `
      <button class="form-secondary" onclick="closeFormViewer()">Close</button>
      <button class="form-secondary" onclick="downloadFormPDF('${form.id}')">↓ Download</button>
      <button class="form-submit" id="form-viewer-save" onclick="saveFormPDF('${form.id}')">Save</button>
    `,
  });

  try {
    // Resolve PDF bytes: prefer pin, then valid recents cache, else storage.
    // In all "miss" paths we kick the network request off in parallel with
    // edit-state + local-draft loads so we don't pay for two sequential RTTs.
    const recent = await recentP;
    const recentValid = recent?.bytes && recent.updatedAt && recent.updatedAt === (form.updated_at || null);
    let bytesPromise;
    if (pin?.bytes) {
      bytesPromise = Promise.resolve(new Uint8Array(pin.bytes));
    } else if (recentValid) {
      bytesPromise = Promise.resolve(new Uint8Array(recent.bytes));
    } else {
      bytesPromise = _formsStorage.downloadBytes(form.storage_path);
    }
    const remoteStateP = _formsLoadEditState(form);
    const localDraftP  = _idbDraftGet(formId).catch(() => null);
    const [bytes, remoteState, localDraft] = await Promise.all([bytesPromise, remoteStateP, localDraftP]);
    let editState = remoteState;
    if (localDraft && localDraft.state) {
      const localTs  = Date.parse(localDraft.state.updatedAt || localDraft.savedAt || 0) || 0;
      const remoteTs = Date.parse(remoteState.updatedAt || 0) || 0;
      const localNewer = localTs > remoteTs;
      if (localNewer) {
        const restore = await _pdfRestorePrompt(localDraft, remoteState);
        if (restore) editState = _normalizeFormEditState(localDraft.state);
        else await _idbDraftDelete(formId);
      }
    }

    const pdfDoc = await pdfjsLib.getDocument({ data: _clonePdfBytes(bytes) }).promise;
    _pdfViewerState = {
      formId,
      pdfBytes: _clonePdfBytes(bytes),
      pdfDoc,
      editState,
      signatures: { ...(editState.signatures || {}) },
      fieldLayouts: [],
      renderedLayoutIds: new Set(),
      pageOverlays: [],
      pageRecords: [],   // {wrap, canvas, overlay, page, baseViewport, rendered, observer}
      zoom: null,        // null => fit width
      zoomMode: 'fit-w', // 'fit-w' | 'fit-p' | 'pct'
      dirty: false,
      saving: false,
      lastSavedAt: editState.updatedAt ? new Date(editState.updatedAt) : null,
      autosaveTimer: null,
      online: navigator.onLine !== false,
      currentField: -1,
    };
    formViewerEvent('viewer_open', { formId, pages: pdfDoc.numPages });

    await _pdfBuildPages(form);
    _pdfBindToolbar(form);
    _pdfBindOnlineEvents();
    _pdfBindBeforeUnload();
    const skel = document.getElementById('form-viewer-skeleton');
    if (skel) skel.remove();
    const statusEl = document.getElementById('form-viewer-status');
    if (statusEl) { statusEl.textContent = ''; statusEl.style.display = 'none'; }
    _pdfUpdateStatus('saved', `Loaded · ${pdfDoc.numPages} page${pdfDoc.numPages !== 1 ? 's' : ''}`);
    // Best-effort: ask the browser for persistent storage so caches survive
    // pressure-eviction. Fired once per session, non-blocking.
    _formsRequestPersistentStorage().catch(() => {});
    // Touch recents (LRU cache for instant re-open) — fire an immediate
    // touch so the row entry exists, then update with the page-1 thumbnail
    // once it finishes rendering. The Forms page row re-renders after each
    // successful touch so the user sees the tile appear, then upgrade with
    // the thumb when ready.
    const _refreshRecentsRow = () => {
      if (typeof _formsRenderRecentsRow === 'function'
          && document.getElementById('page-forms')?.classList.contains('active')) {
        try { _formsRenderRecentsRow(); } catch { /* noop */ }
      }
    };
    _idbRecentTouch(formId, form.name, form.updated_at || null, bytes)
      .then(_refreshRecentsRow)
      .catch(() => {});
    _formsGeneratePageThumb(pdfDoc).then(thumb => {
      if (!thumb) return;
      _idbRecentTouch(formId, form.name, form.updated_at || null, null, thumb)
        .then(_refreshRecentsRow)
        .catch(() => {});
    });
  } catch (e) {
    console.error('[openFormViewer]', e);
    const skel = document.getElementById('form-viewer-skeleton');
    if (skel) skel.remove();
    const stat = document.getElementById('form-viewer-status');
    if (stat) { stat.style.display = ''; stat.textContent = '✗ Failed to load PDF: ' + e.message; stat.style.color = 'var(--bad)'; }
  }
}

async function _pdfRestorePrompt(localDraft, _remoteState) {
  return new Promise((resolve) => {
    const ts = localDraft?.savedAt ? new Date(localDraft.savedAt).toLocaleString() : 'recently';
    const ov = document.createElement('div');
    ov.className = 'pdf-restore-overlay';
    ov.innerHTML = `
      <div class="pdf-restore-modal">
        <div class="pdf-restore-title">Unsaved changes found</div>
        <div class="pdf-restore-body">A local draft saved <b>${escapeHtml(ts)}</b> is newer than the version on the server. Restore it?</div>
        <div class="pdf-restore-foot">
          <button class="form-secondary" id="pdf-restore-discard">Discard local</button>
          <button class="form-submit" id="pdf-restore-keep">Restore</button>
        </div>
      </div>`;
    document.body.appendChild(ov);
    document.getElementById('pdf-restore-keep').onclick    = () => { ov.remove(); resolve(true); };
    document.getElementById('pdf-restore-discard').onclick = () => { ov.remove(); resolve(false); };
  });
}

// ── Page build / lazy render ────────────────────────────────────────────
async function _pdfBuildPages(form) {
  const pagesEl = document.getElementById('form-viewer-pages');
  const thumbsEl = document.getElementById('pdf-thumbs');
  // Cancel any in-flight renders + disconnect old observer before tearing down.
  if (_pdfViewerState.pageObserver) { try { _pdfViewerState.pageObserver.disconnect(); } catch { /* noop */ } }
  for (const rec of (_pdfViewerState.pageRecords || [])) {
    if (rec?.renderTask) { try { rec.renderTask.cancel(); } catch { /* noop */ } }
  }
  pagesEl.innerHTML = '';
  if (thumbsEl) thumbsEl.innerHTML = '';
  _pdfViewerState.pageOverlays = [];
  _pdfViewerState.pageRecords  = [];
  _pdfViewerState.renderedLayoutIds = new Set();
  _pdfViewerState.fieldLayouts = [];

  const pdfDoc = _pdfViewerState.pdfDoc;
  const numPages = pdfDoc.numPages;
  document.getElementById('pdf-tb-page-total').textContent = `/ ${numPages}`;
  document.getElementById('pdf-tb-page').max = numPages;

  // Compute zoom from current zoomMode using page 1 as reference.
  const firstPage = await pdfDoc.getPage(1);
  const baseVp1 = firstPage.getViewport({ scale: 1 });
  const fitWidthScale = _formsViewerScale(baseVp1, pagesEl);
  const fitPageScale  = Math.max(_PDF_ZOOM_MIN, Math.min(_PDF_ZOOM_MAX,
    (pagesEl.clientHeight - 32) / baseVp1.height));
  const zoom = _pdfViewerState.zoomMode === 'fit-w' ? fitWidthScale
             : _pdfViewerState.zoomMode === 'fit-p' ? fitPageScale
             : (_pdfViewerState.zoom || fitWidthScale);
  _pdfViewerState.zoom = zoom;
  _pdfUpdateZoomLabel();

  const io = ('IntersectionObserver' in window) ? new IntersectionObserver((entries) => {
    entries.forEach(en => {
      if (en.isIntersecting) {
        const idx = Number(en.target.dataset.pageIndex);
        const rec = _pdfViewerState?.pageRecords?.[idx];
        if (rec && !rec.rendered && !rec.renderPromise) _pdfRenderPage(idx);
        if (rec) document.getElementById('pdf-tb-page').value = String(idx + 1);
      }
    });
  }, { root: pagesEl, rootMargin: '200px' }) : null;
  _pdfViewerState.pageObserver = io;

  for (let p = 1; p <= numPages; p++) {
    const page = await pdfDoc.getPage(p);
    const baseViewport = page.getViewport({ scale: 1 });
    const viewport = page.getViewport({ scale: zoom });
    const wrap = document.createElement('div');
    wrap.className = 'form-viewer-page';
    wrap.dataset.pageIndex = String(p - 1);
    wrap.style.width  = `${viewport.width}px`;
    wrap.style.height = `${viewport.height}px`;
    const canvas = document.createElement('canvas');
    canvas.style.cssText = `display:block;position:absolute;top:0;left:0;width:${viewport.width}px;height:${viewport.height}px;`;
    wrap.appendChild(canvas);
    const overlay = document.createElement('div');
    overlay.style.cssText = `position:absolute;top:0;left:0;width:${viewport.width}px;height:${viewport.height}px;`;
    wrap.appendChild(overlay);
    pagesEl.appendChild(wrap);
    _pdfViewerState.pageOverlays[p - 1] = { overlay, viewport };
    _pdfViewerState.pageRecords[p - 1]  = { wrap, canvas, overlay, page, baseViewport, viewport, rendered: false };
    if (io) io.observe(wrap);

    if (thumbsEl) {
      const tb = document.createElement('button');
      tb.type = 'button';
      tb.className = 'pdf-thumb';
      tb.dataset.pageIndex = String(p - 1);
      tb.innerHTML = `<canvas></canvas><span class="pdf-thumb-num">${p}</span>`;
      tb.onclick = () => _pdfScrollToPage(p - 1);
      thumbsEl.appendChild(tb);
    }
  }

  // Render first page immediately + thumbnails for visible ones.
  await _pdfRenderPage(0);
  if (numPages > 1 && thumbsEl) _pdfRenderThumb(0);
  // Pre-render thumbnails + remaining pages opportunistically so field
  // navigation (prev/next) can see every field in the document.
  setTimeout(async () => {
    for (let i = 0; i < numPages; i++) {
      try { if (thumbsEl) await _pdfRenderThumb(i); } catch { /* noop */ }
    }
    for (let i = 1; i < numPages; i++) {
      if (!_pdfViewerState || _pdfViewerState.formId !== form.id) return;
      try { await _pdfRenderPage(i); } catch { /* noop */ }
    }
  }, 50);
}

async function _pdfRenderPage(idx) {
  const rec = _pdfViewerState?.pageRecords?.[idx];
  if (!rec || rec.rendered) return;
  // Guard against concurrent renders on the same page (IntersectionObserver +
  // explicit awaited call would otherwise both call page.render() and corrupt
  // the canvas — pdf.js does not allow two render tasks on one page).
  if (rec.renderPromise) { await rec.renderPromise.catch(() => {}); return; }
  const pixelRatio = Math.min(2, Math.max(1, window.devicePixelRatio || 1));
  const viewport = rec.viewport;
  rec.canvas.width  = Math.floor(viewport.width  * pixelRatio);
  rec.canvas.height = Math.floor(viewport.height * pixelRatio);
  const ctx = rec.canvas.getContext('2d');
  const renderContext = { canvasContext: ctx, viewport };
  if (pixelRatio !== 1) renderContext.transform = [pixelRatio, 0, 0, pixelRatio, 0, 0];
  rec.renderTask = rec.page.render(renderContext);
  rec.renderPromise = rec.renderTask.promise;
  try {
    await rec.renderPromise;
    const annots = await rec.page.getAnnotations();
    // Bail if the viewer was torn down or this record was replaced mid-render.
    if (!_pdfViewerState || _pdfViewerState.pageRecords?.[idx] !== rec) return;
    rec.overlay.innerHTML = '';
    _renderFormFieldOverlay(rec.overlay, annots, viewport, idx);
    _renderSavedFieldLayouts();
    rec.rendered = true;
  } catch (e) {
    if (e?.name !== 'RenderingCancelledException') console.warn('[_pdfRenderPage]', idx, e.message || e);
  } finally {
    rec.renderTask = null;
    rec.renderPromise = null;
  }
}

async function _pdfRenderThumb(idx) {
  const thumbsEl = document.getElementById('pdf-thumbs');
  if (!thumbsEl) return;
  const tb = thumbsEl.querySelector(`.pdf-thumb[data-page-index="${idx}"]`);
  if (!tb || tb.dataset.rendered === '1') return;
  const canvas = tb.querySelector('canvas');
  const rec = _pdfViewerState?.pageRecords?.[idx];
  if (!rec) return;
  const baseVp = rec.page.getViewport({ scale: 1 });
  const targetW = 120;
  const scale = targetW / baseVp.width;
  const vp = rec.page.getViewport({ scale });
  canvas.width = Math.floor(vp.width);
  canvas.height = Math.floor(vp.height);
  await rec.page.render({ canvasContext: canvas.getContext('2d'), viewport: vp }).promise;
  tb.dataset.rendered = '1';
}

function _pdfScrollToPage(idx) {
  const rec = _pdfViewerState?.pageRecords?.[idx];
  if (!rec) return;
  rec.wrap.scrollIntoView({ behavior: 'smooth', block: 'start' });
  document.getElementById('pdf-tb-page').value = String(idx + 1);
  document.querySelectorAll('.pdf-thumb.active').forEach(el => el.classList.remove('active'));
  document.querySelector(`.pdf-thumb[data-page-index="${idx}"]`)?.classList.add('active');
}

// ── Toolbar wiring ──────────────────────────────────────────────────────
function _pdfBindToolbar(form) {
  const $ = id => document.getElementById(id);
  $('pdf-tb-thumbs').onclick = () => {
    const el = $('pdf-thumbs');
    if (!el) return;
    el.hidden = !el.hidden;
  };
  $('pdf-tb-prev').onclick = () => _pdfFocusField(-1);
  $('pdf-tb-next').onclick = () => _pdfFocusField(+1);
  $('pdf-tb-zoom-in').onclick  = () => _pdfApplyZoom((_pdfViewerState.zoom || 1) * 1.15, 'pct');
  $('pdf-tb-zoom-out').onclick = () => _pdfApplyZoom((_pdfViewerState.zoom || 1) / 1.15, 'pct');
  $('pdf-tb-fit-w').onclick    = () => { _pdfViewerState.zoomMode = 'fit-w'; _pdfRebuildAtZoom(); };
  $('pdf-tb-fit-p').onclick    = () => { _pdfViewerState.zoomMode = 'fit-p'; _pdfRebuildAtZoom(); };
  $('pdf-tb-page').addEventListener('change', (e) => {
    const n = Math.max(1, Math.min(_pdfViewerState.pdfDoc.numPages, parseInt(e.target.value, 10) || 1));
    _pdfScrollToPage(n - 1);
  });
  $('pdf-tb-pin').addEventListener('change', async (e) => {
    try {
      if (e.target.checked) {
        const bytes = _pdfViewerState.pdfBytes || await _formsStorage.downloadBytes(form.storage_path);
        await _idbPinPut({ formId: form.id, bytes: bytes.buffer ? bytes.buffer.slice(0) : new Uint8Array(bytes).buffer, pinnedAt: new Date().toISOString(), name: form.name });
        toast('✓ Cached for offline use', 'success');
        formViewerEvent('offline_pin', { formId: form.id });
      } else {
        await _idbPinDelete(form.id);
        toast('Removed offline cache', 'info');
        formViewerEvent('offline_unpin', { formId: form.id });
      }
    } catch (err) { toast('Pin failed: ' + err.message, 'error'); e.target.checked = !e.target.checked; }
  });

  // Keyboard shortcuts within viewer.
  document.getElementById('pdf-viewer-toolbar').closest('.modal')?.addEventListener('keydown', (e) => {
    if (e.altKey && (e.key === 't' || e.key === 'T')) { e.preventDefault(); $('pdf-tb-thumbs').click(); }
    if ((e.ctrlKey || e.metaKey) && (e.key === '=' || e.key === '+')) { e.preventDefault(); $('pdf-tb-zoom-in').click(); }
    if ((e.ctrlKey || e.metaKey) && e.key === '-') { e.preventDefault(); $('pdf-tb-zoom-out').click(); }
    if ((e.ctrlKey || e.metaKey) && e.key === '0') { e.preventDefault(); $('pdf-tb-fit-w').click(); }
    if ((e.ctrlKey || e.metaKey) && (e.key === 's' || e.key === 'S')) { e.preventDefault(); saveFormPDF(form.id); }
  });
}

function _pdfApplyZoom(zoom, mode = 'pct') {
  const next = Math.max(_PDF_ZOOM_MIN, Math.min(_PDF_ZOOM_MAX, zoom));
  _pdfViewerState.zoom = next;
  _pdfViewerState.zoomMode = mode;
  _pdfRebuildAtZoom();
}

async function _pdfRebuildAtZoom() {
  // Persist current values from DOM before re-render
  const captured = _collectFormFieldValues();
  Object.assign(_pdfViewerState.editState.fields, captured);
  await _pdfBuildPages(FORMS.find(f => f.id === _pdfViewerState.formId));
  _pdfUpdateZoomLabel();
}

function _pdfUpdateZoomLabel() {
  const lbl = document.getElementById('pdf-tb-zoom-label');
  if (!lbl) return;
  lbl.textContent = `${Math.round((_pdfViewerState.zoom || 1) * 100)}%`;
}

// ── Status pill / dirty / autosave ──────────────────────────────────────
function _pdfUpdateStatus(kind, text) {
  const el = document.getElementById('pdf-tb-status');
  if (!el) return;
  el.classList.remove('pdf-tb-status-saved','pdf-tb-status-saving','pdf-tb-status-dirty','pdf-tb-status-offline','pdf-tb-status-error');
  el.classList.add(`pdf-tb-status-${kind}`);
  el.textContent = text;
}

function _pdfMarkDirty() {
  if (!_pdfViewerState) return;
  _pdfViewerState.dirty = true;
  const ts = _pdfViewerState.lastSavedAt;
  _pdfUpdateStatus('dirty', ts ? `Unsaved · last saved ${_pdfRelTime(ts)}` : 'Unsaved');
  // Save local draft immediately (cheap), debounce remote save.
  _pdfSaveLocalDraft().catch(err => console.warn('[localDraft]', err.message));
  if (_pdfViewerState.autosaveTimer) clearTimeout(_pdfViewerState.autosaveTimer);
  _pdfViewerState.autosaveTimer = setTimeout(() => {
    _pdfAutosaveRemote().catch(err => console.warn('[autosave]', err.message));
  }, _PDF_AUTOSAVE_DELAY_MS);
}

function _pdfRelTime(d) {
  const s = Math.max(0, Math.floor((Date.now() - new Date(d).getTime()) / 1000));
  if (s < 5)   return 'just now';
  if (s < 60)  return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s/60)}m ago`;
  return new Date(d).toLocaleTimeString();
}

async function _pdfSaveLocalDraft() {
  if (!_pdfViewerState) return;
  const values = _collectFormFieldValues();
  const state = {
    version: 2,
    fields: values,
    signatures: _pdfViewerState.signatures || {},
    layouts: _pdfViewerState.fieldLayouts || [],
    updatedAt: new Date().toISOString(),
  };
  await _idbDraftPut({ formId: _pdfViewerState.formId, state, savedAt: new Date().toISOString() });
}

async function _pdfAutosaveRemote() {
  if (!_pdfViewerState || _pdfViewerState.saving) return;
  if (!_pdfViewerState.dirty) return;
  if (!navigator.onLine) {
    _pdfUpdateStatus('offline', 'Offline · saved locally');
    return;
  }
  _pdfViewerState.saving = true;
  _pdfUpdateStatus('saving', 'Saving…');
  try {
    const values = _collectFormFieldValues();
    const next = await _formsSaveEditState(_pdfViewerState.formId, {
      version: 2,
      fields: values,
      signatures: _pdfViewerState.signatures || {},
      layouts: _pdfViewerState.fieldLayouts || [],
    });
    _pdfViewerState.editState = next;
    _pdfViewerState.dirty = false;
    _pdfViewerState.lastSavedAt = new Date(next.updatedAt || Date.now());
    _pdfUpdateStatus('saved', `Saved · ${_pdfRelTime(_pdfViewerState.lastSavedAt)}`);
    await _idbDraftDelete(_pdfViewerState.formId).catch(() => {});
    formViewerEvent('autosave_ok', { formId: _pdfViewerState.formId, fields: Object.keys(values).length });
  } catch (e) {
    console.warn('[autosave]', e.message);
    _pdfUpdateStatus('error', 'Sync failed · retry');
    document.getElementById('pdf-tb-status').onclick = () => { _pdfAutosaveRemote().catch(() => {}); };
  } finally {
    _pdfViewerState.saving = false;
  }
}

function _pdfBindOnlineEvents() {
  if (window.__cxFormsOnlineBound) return;
  window.__cxFormsOnlineBound = true;
  window.addEventListener('online',  () => { if (_pdfViewerState?.dirty) _pdfAutosaveRemote().catch(() => {}); _pdfFlushQueuedDrafts().catch(() => {}); });
  window.addEventListener('offline', () => { if (_pdfViewerState) _pdfUpdateStatus('offline', 'Offline · saved locally'); });
}
async function _pdfFlushQueuedDrafts() {
  // On reconnect, flush any other forms' drafts (best-effort).
  try {
    const all = await _idbDraftAll();
    for (const d of all) {
      if (_pdfViewerState && d.formId === _pdfViewerState.formId) continue;
      try {
        await _formsSaveEditState(d.formId, d.state);
        await _idbDraftDelete(d.formId);
      } catch (e) { console.warn('[draft flush]', d.formId, e.message); }
    }
  } catch { /* noop */ }
}

function _pdfBindBeforeUnload() {
  if (_pdfBeforeUnloadBound) return;
  _pdfBeforeUnloadBound = true;
  window.addEventListener('beforeunload', (e) => {
    if (_pdfViewerState?.dirty) {
      e.preventDefault();
      e.returnValue = '';
      return '';
    }
  });
}

// ── Field navigation ────────────────────────────────────────────────────
function _pdfAllInputEls() {
  return Array.from(document.querySelectorAll('#form-viewer-pages [data-pdf-field-name], #form-viewer-pages [data-pdf-signature-field]'));
}
function _pdfFocusField(delta) {
  const els = _pdfAllInputEls();
  if (!els.length) return;
  const cur = document.activeElement;
  let idx = els.indexOf(cur);
  if (idx === -1) idx = (delta > 0) ? -1 : 0;
  idx = (idx + delta + els.length) % els.length;
  const el = els[idx];
  el.focus({ preventScroll: false });
  el.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

// ── Annotations / overlay rendering ─────────────────────────────────────
function _pdfIsSignatureWidget(a) {
  const label = [a.fieldName, a.alternativeText, a.title, a.contents, a.id].filter(Boolean).join(' ');
  return a.fieldType === 'Sig' || /signature/i.test(label) || /(^|[\s_-])sig(n)?($|[\s_-])/i.test(label);
}

function _pdfLayoutId(layout) {
  const rect = (layout.rect || []).map(n => Math.round(Number(n) || 0)).join(',');
  return `${layout.pageIndex}:${layout.fieldName}:${layout.kind}:${rect}`;
}

function _pdfAnnotationLayout(a, pageIndex, index) {
  const fieldName = a.fieldName || a.id || `Signature ${pageIndex + 1}-${index + 1}`;
  let kind = null;
  if (_pdfIsSignatureWidget(a)) kind = 'signature';
  else if (a.fieldType === 'Tx') kind = a.multiLine ? 'textarea' : 'text';
  else if (a.fieldType === 'Btn' && a.radioButton) kind = 'radio';
  else if (a.fieldType === 'Btn' && a.checkBox) kind = 'checkbox';
  else if (a.fieldType === 'Ch') kind = 'select';
  if (!kind) return null;
  return {
    fieldName,
    kind,
    pageIndex,
    rect: a.rect,
    readOnly: !!a.readOnly,
    radioName: a.radioButton ? a.fieldName : null,
    value: a.buttonValue || a.exportValue || a.fieldValue || 'On',
    fieldValue: a.fieldValue,
    options: (a.options || []).map(opt => ({
      value: opt.exportValue ?? opt.displayValue ?? opt,
      label: opt.displayValue ?? opt.exportValue ?? opt,
    })),
  };
}

function _renderFormFieldOverlay(overlay, annotations, viewport, pageIndex) {
  annotations.filter(a => a.subtype === 'Widget' && (a.fieldName || _pdfIsSignatureWidget(a))).forEach((a, index) => {
    const layout = _pdfAnnotationLayout(a, pageIndex, index);
    if (!layout) return;
    const dup = (_pdfViewerState.fieldLayouts || []).find(l => _pdfLayoutId(l) === _pdfLayoutId(layout));
    if (!dup) _pdfViewerState?.fieldLayouts?.push(layout);
    _renderPdfFieldControl(overlay, layout, viewport);
  });
}

function _pdfInferInputMode(name) {
  const n = String(name || '').toLowerCase();
  if (/(amount|qty|quantity|count|number|hrs|hours|min|max|psi|temp|volt|amp|ohm)/.test(n)) return 'decimal';
  if (/(phone|tel)/.test(n)) return 'tel';
  if (/(email)/.test(n))     return 'email';
  return null;
}

function _renderPdfFieldControl(overlay, layout, viewport) {
  const [x1, y1, x2, y2] = layout.rect;
  const tl = viewport.convertToViewportPoint(x1, y2);
  const br = viewport.convertToViewportPoint(x2, y1);
  const left = Math.min(tl[0], br[0]), top = Math.min(tl[1], br[1]);
  const width = Math.abs(br[0] - tl[0]), height = Math.abs(br[1] - tl[1]);
  const fieldName = layout.fieldName;
  const editState = _pdfViewerState?.editState || _emptyFormEditState();
  const savedFields = editState.fields || {};
  const hasSavedValue = Object.prototype.hasOwnProperty.call(savedFields, fieldName);
  let el;
  if (layout.kind === 'signature') {
    el = document.createElement('button');
    el.type = 'button';
    el.className = 'pdf-signature-field';
    el.innerHTML = '<span>Click to sign</span>';
    el.dataset.pdfSignatureField = fieldName;
    el.addEventListener('click', () => openSignaturePad({
      fieldName,
      pageIndex: layout.pageIndex,
      rect: layout.rect,
      target: el,
    }));
  } else if (layout.kind === 'text' || layout.kind === 'textarea') {
    el = layout.kind === 'textarea' ? document.createElement('textarea') : document.createElement('input');
    if (layout.kind === 'text') el.type = 'text';
    el.value = hasSavedValue ? savedFields[fieldName] : (layout.fieldValue || '');
    const im = _pdfInferInputMode(fieldName);
    if (im) el.inputMode = im;
    el.addEventListener('input', _pdfMarkDirty);
  } else if (layout.kind === 'checkbox' || layout.kind === 'radio') {
    el = document.createElement('input');
    el.type = layout.kind;
    el.value = layout.value || 'On';
    if (layout.kind === 'radio') el.name = layout.radioName || fieldName;
    el.checked = hasSavedValue ? !!savedFields[fieldName] : (layout.fieldValue !== 'Off' && !!layout.fieldValue);
    el.addEventListener('change', _pdfMarkDirty);
  } else if (layout.kind === 'select') {
    el = document.createElement('select');
    (layout.options || []).forEach(opt => {
      const o = document.createElement('option');
      o.value = opt.value;
      o.textContent = opt.label;
      if (o.value === (hasSavedValue ? savedFields[fieldName] : layout.fieldValue)) o.selected = true;
      el.appendChild(o);
    });
    el.addEventListener('change', _pdfMarkDirty);
  } else { return; }
  if (!el.dataset.pdfSignatureField) el.dataset.pdfFieldName = fieldName;
  const fontPx = Math.max(11, Math.min(16, height * 0.65));
  el.className = (el.className ? el.className + ' ' : '') + 'pdf-field-input';
  el.style.cssText = `position:absolute;left:${left}px;top:${top}px;width:${width}px;height:${height}px;font-size:${fontPx}px;`;
  if (layout.readOnly && !el.dataset.pdfSignatureField) { el.disabled = true; el.classList.add('readonly'); }
  const savedSig = editState.signatures?.[fieldName]?.dataUrl;
  if (savedSig && el.dataset.pdfSignatureField) _setSignatureFieldPreview(el, savedSig);
  overlay.appendChild(el);
  _pdfViewerState?.renderedLayoutIds?.add(_pdfLayoutId(layout));
}

function _renderSavedFieldLayouts() {
  const state = _pdfViewerState?.editState;
  if (!state?.layouts?.length) return;
  state.layouts.forEach(layout => {
    const id = _pdfLayoutId(layout);
    if (_pdfViewerState.renderedLayoutIds?.has(id)) return;
    const page = _pdfViewerState.pageOverlays?.[layout.pageIndex];
    if (!page) return;
    _renderPdfFieldControl(page.overlay, layout, page.viewport);
  });
}

// ── Signature pad (Draw + Type modes) ───────────────────────────────────
function openSignaturePad({ fieldName, pageIndex, rect, target }) {
  if (!_pdfViewerState) return;
  document.getElementById('form-signature-overlay')?.remove();
  const existing = _pdfViewerState.signatures?.[fieldName]?.dataUrl || '';
  const profileName = (currentProfile?.full_name || currentRoleUser?.name || '').trim();
  const overlay = document.createElement('div');
  overlay.id = 'form-signature-overlay';
  overlay.className = 'signature-pad-overlay';
  overlay.innerHTML = `
    <div class="signature-pad-modal">
      <div class="signature-pad-head">
        <div>
          <div class="signature-pad-title">Signature</div>
          <div class="signature-pad-sub">${escapeHtml(fieldName)}</div>
        </div>
        <button class="modal-close" type="button" onclick="closeSignaturePad()">&times;</button>
      </div>
      <div class="signature-pad-tabs">
        <button type="button" class="sig-tab active"  data-mode="draw">Draw</button>
        <button type="button" class="sig-tab"         data-mode="type">Type</button>
      </div>
      <div class="signature-pad-body">
        <div class="sig-pane sig-pane-draw">
          <canvas id="signature-pad-canvas" class="signature-pad-canvas"></canvas>
          <div class="sig-tools">
            <button type="button" class="form-secondary" id="sig-undo">Undo</button>
            <button type="button" class="form-secondary" id="sig-clear">Clear</button>
          </div>
        </div>
        <div class="sig-pane sig-pane-type" hidden>
          <input type="text" id="sig-type-input" class="sig-type-input" placeholder="Type your name" value="${escapeHtml(profileName)}" />
          <div id="sig-type-preview" class="sig-type-preview">${escapeHtml(profileName)}</div>
        </div>
        <label class="sig-stamp">
          <input type="checkbox" id="sig-stamp-check" /> Add date &amp; name stamp on the PDF
        </label>
      </div>
      <div class="signature-pad-footer">
        <button class="form-secondary" type="button" onclick="closeSignaturePad()">Cancel</button>
        <button class="form-submit" type="button" id="signature-pad-apply">Apply Signature</button>
      </div>
    </div>
  `;
  document.body.appendChild(overlay);

  const canvas = document.getElementById('signature-pad-canvas');
  const ctx = canvas.getContext('2d');
  const ratio = Math.max(1, window.devicePixelRatio || 1);
  const cssWidth  = Math.min(720, Math.max(420, window.innerWidth - 80));
  const cssHeight = Math.max(180, Math.min(260, cssWidth * 0.32));
  canvas.style.width  = `${cssWidth}px`;
  canvas.style.height = `${cssHeight}px`;
  canvas.width  = Math.floor(cssWidth  * ratio);
  canvas.height = Math.floor(cssHeight * ratio);
  ctx.scale(ratio, ratio);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.strokeStyle = '#111827';

  const strokes = []; // [{points:[{x,y,p}], width}]
  let drawing = false;
  let curStroke = null;
  let hasInk = false;

  const redraw = () => {
    ctx.clearRect(0, 0, cssWidth, cssHeight);
    for (const s of strokes) {
      const pts = s.points;
      if (pts.length < 2) continue;
      for (let i = 1; i < pts.length; i++) {
        const a = pts[i - 1], b = pts[i];
        ctx.lineWidth = (a.w + b.w) / 2;
        ctx.beginPath();
        ctx.moveTo(a.x, a.y);
        const cx = (a.x + b.x) / 2, cy = (a.y + b.y) / 2;
        ctx.quadraticCurveTo(a.x, a.y, cx, cy);
        ctx.stroke();
      }
    }
  };

  if (existing) {
    const img = new Image();
    img.onload = () => ctx.drawImage(img, 0, 0, cssWidth, cssHeight);
    img.src = existing;
    hasInk = true;
  }

  const point = (e) => {
    const r = canvas.getBoundingClientRect();
    const pressure = (e.pressure && e.pressure > 0 && e.pressure < 1) ? e.pressure : 0.5;
    const w = 1.4 + pressure * 2.8;
    return { x: e.clientX - r.left, y: e.clientY - r.top, w };
  };
  canvas.addEventListener('pointerdown', (e) => {
    drawing = true;
    hasInk = true;
    canvas.setPointerCapture(e.pointerId);
    curStroke = { points: [point(e)] };
    strokes.push(curStroke);
  });
  canvas.addEventListener('pointermove', (e) => {
    if (!drawing) return;
    curStroke.points.push(point(e));
    redraw();
  });
  const stop = () => { drawing = false; curStroke = null; };
  canvas.addEventListener('pointerup', stop);
  canvas.addEventListener('pointercancel', stop);
  canvas.addEventListener('pointerleave', stop);

  document.getElementById('sig-undo').onclick = () => {
    strokes.pop();
    if (strokes.length === 0) hasInk = !!existing;
    redraw();
  };
  document.getElementById('sig-clear').onclick = () => {
    strokes.length = 0;
    hasInk = false;
    ctx.clearRect(0, 0, cssWidth, cssHeight);
  };

  // Tabs
  let mode = 'draw';
  overlay.querySelectorAll('.sig-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      overlay.querySelectorAll('.sig-tab').forEach(t => t.classList.toggle('active', t === tab));
      mode = tab.dataset.mode;
      overlay.querySelector('.sig-pane-draw').hidden = mode !== 'draw';
      overlay.querySelector('.sig-pane-type').hidden = mode !== 'type';
    });
  });

  // Type mode preview
  const typeInput = document.getElementById('sig-type-input');
  const typePrev  = document.getElementById('sig-type-preview');
  typeInput.addEventListener('input', () => { typePrev.textContent = typeInput.value || ''; });

  overlay._signatureContext = {
    ctx, canvas, cssWidth, cssHeight, fieldName, pageIndex, rect, target,
    getMode: () => mode,
    getTypeText: () => typeInput.value || '',
    hasInk: () => hasInk,
    setInk: v => { hasInk = v; },
    getStamp: () => document.getElementById('sig-stamp-check')?.checked,
  };
  document.getElementById('signature-pad-apply').onclick = applySignaturePad;
}

function clearSignaturePad() {
  const overlay = document.getElementById('form-signature-overlay');
  const s = overlay?._signatureContext;
  if (!s) return;
  s.ctx.clearRect(0, 0, s.cssWidth, s.cssHeight);
  s.setInk?.(false);
  delete _pdfViewerState.signatures[s.fieldName];
  if (s.target) {
    s.target.classList.remove('signed');
    s.target.style.backgroundImage = '';
    s.target.innerHTML = '<span>Click to sign</span>';
  }
}

function closeSignaturePad() {
  document.getElementById('form-signature-overlay')?.remove();
}

function _setSignatureFieldPreview(target, dataUrl) {
  if (!target) return;
  target.classList.add('signed');
  target.style.backgroundImage = '';
  target.innerHTML = '';
  const img = document.createElement('img');
  img.alt = 'Signed';
  img.src = dataUrl;
  target.appendChild(img);
}

function _typedSignatureToDataUrl(text, cssWidth = 600, cssHeight = 180) {
  const c = document.createElement('canvas');
  c.width = cssWidth; c.height = cssHeight;
  const cx = c.getContext('2d');
  cx.fillStyle = '#fff';
  cx.fillRect(0, 0, cssWidth, cssHeight);
  cx.fillStyle = '#111827';
  cx.textBaseline = 'middle';
  cx.textAlign = 'center';
  // Try Brush Script / cursive fallbacks; browser will sub if missing.
  cx.font = `italic 64px "Brush Script MT","Lucida Handwriting","Segoe Script",cursive`;
  cx.fillText(text || '', cssWidth / 2, cssHeight / 2);
  return c.toDataURL('image/png');
}

function applySignaturePad() {
  const overlay = document.getElementById('form-signature-overlay');
  const s = overlay?._signatureContext;
  if (!s) return;
  let dataUrl = '';
  if (s.getMode() === 'type') {
    const txt = s.getTypeText().trim();
    if (!txt) { toast('Type your name first', 'warn'); return; }
    dataUrl = _typedSignatureToDataUrl(txt);
  } else {
    if (!s.hasInk()) { toast('Draw a signature first', 'warn'); return; }
    dataUrl = s.canvas.toDataURL('image/png');
  }
  const stamp = s.getStamp() ? {
    name: (currentProfile?.full_name || currentRoleUser?.name || '').trim(),
    at:   new Date().toISOString(),
  } : null;
  _pdfViewerState.signatures[s.fieldName] = {
    name: s.fieldName,
    pageIndex: s.pageIndex,
    rect: s.rect,
    dataUrl,
    stamp,
  };
  _setSignatureFieldPreview(s.target, dataUrl);
  closeSignaturePad();
  _pdfMarkDirty();
}

// ── Field collection / download builder ─────────────────────────────────
function _collectFormFieldValues() {
  const values = {};
  document.querySelectorAll('#form-viewer-pages [data-pdf-field-name]').forEach(el => {
    const name = el.dataset.pdfFieldName;
    if (el.type === 'checkbox') values[name] = el.checked;
    else if (el.type === 'radio') { if (el.checked) values[name] = el.value; }
    else values[name] = el.value;
  });
  // Merge with previously-known editState values for fields not in DOM (lazy unrendered pages).
  const prior = _pdfViewerState?.editState?.fields || {};
  for (const k of Object.keys(prior)) {
    if (!Object.prototype.hasOwnProperty.call(values, k)) values[k] = prior[k];
  }
  return values;
}

function _pdfExportFieldName(layout, index) {
  const base = String(layout.fieldName || `field_${index + 1}`)
    .replace(/[^a-z0-9_.-]+/gi, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 80) || `field_${index + 1}`;
  return `cx_${index + 1}_${base}`;
}

function _pdfRectBox(rect) {
  const [x1, y1, x2, y2] = rect || [0, 0, 0, 0];
  return {
    x: Math.min(x1, x2),
    y: Math.min(y1, y2),
    width: Math.max(1, Math.abs(x2 - x1)),
    height: Math.max(1, Math.abs(y2 - y1)),
  };
}

function _pdfSavedValueForLayout(state, layout) {
  const fields = state.fields || {};
  if (Object.prototype.hasOwnProperty.call(fields, layout.fieldName)) return fields[layout.fieldName];
  return layout.fieldValue ?? '';
}

function _pdfIsLayoutChecked(state, layout) {
  const val = _pdfSavedValueForLayout(state, layout);
  if (layout.kind === 'radio') return String(val) === String(layout.value);
  return !!val;
}

function _setExistingPdfFieldValue(acroForm, layout, value) {
  if (!layout?.fieldName) return false;
  let field;
  try { field = acroForm.getField(layout.fieldName); }
  catch { return false; }
  try {
    if (layout.kind === 'text' || layout.kind === 'textarea') {
      field.setText(String(value ?? ''));
      return true;
    }
    if (layout.kind === 'checkbox') {
      if (value) field.check();
      else field.uncheck();
      return true;
    }
    if (layout.kind === 'radio') {
      if (value != null && String(value)) field.select(String(value));
      return true;
    }
    if (layout.kind === 'select') {
      if (value != null && String(value)) field.select(String(value));
      else field.clear();
      return true;
    }
  } catch (e) {
    console.warn('[_setExistingPdfFieldValue] skipped:', layout.fieldName, e.message);
  }
  return false;
}

async function _addDownloadStateFields(doc, acroForm, state) {
  const layouts = Array.isArray(state.layouts) ? state.layouts : [];
  const fontColor = PDFLib.rgb(0.05, 0.09, 0.16);
  const exportFont = await doc.embedFont(PDFLib.StandardFonts.Helvetica);
  layouts.forEach((layout, index) => {
    if (!layout?.rect || layout.kind === 'signature') return;
    const page = doc.getPages()[layout.pageIndex];
    if (!page) return;
    const box = _pdfRectBox(layout.rect);
    const fieldName = _pdfExportFieldName(layout, index);
    const value = _pdfSavedValueForLayout(state, layout);
    try {
      if (_setExistingPdfFieldValue(acroForm, layout, value)) return;
      if (layout.kind === 'text' || layout.kind === 'textarea') {
        const field = acroForm.createTextField(fieldName);
        if (layout.kind === 'textarea') field.enableMultiline();
        field.setText(String(value ?? ''));
        field.setFontSize(Math.max(8, Math.min(12, box.height * 0.55)));
        field.addToPage(page, {
          x: box.x, y: box.y, width: box.width, height: box.height,
          textColor: fontColor,
          borderColor: PDFLib.rgb(0.75, 0.79, 0.86),
          backgroundColor: PDFLib.rgb(1, 1, 1),
          borderWidth: 0.5,
        });
        field.updateAppearances(exportFont);
      } else if (layout.kind === 'checkbox' || layout.kind === 'radio') {
        const field = acroForm.createCheckBox(fieldName);
        if (_pdfIsLayoutChecked(state, layout)) field.check();
        field.addToPage(page, {
          x: box.x, y: box.y, width: box.width, height: box.height,
          borderColor: PDFLib.rgb(0.15, 0.2, 0.28),
          backgroundColor: PDFLib.rgb(1, 1, 1),
          borderWidth: 0.5,
        });
      } else if (layout.kind === 'select') {
        const field = acroForm.createDropdown(fieldName);
        const options = (layout.options || []).map(o => String(o.value ?? o.label ?? '')).filter(Boolean);
        if (options.length) field.addOptions(options);
        if (value != null && String(value)) field.select(String(value));
        field.addToPage(page, {
          x: box.x, y: box.y, width: box.width, height: box.height,
          textColor: fontColor,
          borderColor: PDFLib.rgb(0.75, 0.79, 0.86),
          backgroundColor: PDFLib.rgb(1, 1, 1),
          borderWidth: 0.5,
        });
        field.updateAppearances(exportFont);
      }
    } catch (e) {
      console.warn('[_addDownloadStateFields] skipped:', layout.fieldName, e.message);
    }
  });
}

async function saveFormPDF(formId) {
  if (!_pdfViewerState || _pdfViewerState.formId !== formId) { toast('Viewer state lost — reopen the form', 'error'); return; }
  const btn = document.getElementById('form-viewer-save');
  if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }
  try {
    const values = _collectFormFieldValues();
    const nextState = await _formsSaveEditState(formId, {
      version: 2,
      fields: values,
      signatures: _pdfViewerState.signatures || {},
      layouts: _pdfViewerState.fieldLayouts || [],
    });
    _pdfViewerState.editState = nextState;
    _pdfViewerState.dirty = false;
    _pdfViewerState.lastSavedAt = new Date(nextState.updatedAt || Date.now());
    _pdfUpdateStatus('saved', `Saved · ${_pdfRelTime(_pdfViewerState.lastSavedAt)}`);
    await _idbDraftDelete(formId).catch(() => {});
    logAudit('Saved Form', FORMS.find(f => f.id === formId)?.name || formId,
      `${Object.keys(values).length} field(s), ${Object.keys(nextState.signatures || {}).length} signature(s) · ${navigator.onLine ? 'online' : 'offline'}`);
    formViewerEvent('save_ok', { formId, fields: Object.keys(values).length, online: navigator.onLine });
    toast('✓ Form saved', 'success');
    if (btn) { btn.disabled = false; btn.textContent = 'Save'; }
  } catch (e) {
    console.error('[saveFormPDF]', e);
    toast('Save failed: ' + e.message, 'error');
    _pdfUpdateStatus('error', 'Save failed');
    if (btn) { btn.disabled = false; btn.textContent = 'Save'; }
  }
}

async function _buildEditedFormPdfBlob(formRow, stateOverride = null) {
  if (typeof PDFLib === 'undefined') throw new Error('pdf-lib not loaded');
  const state = stateOverride
    ? _normalizeFormEditState(stateOverride)
    : _normalizeFormEditState(await _formsLoadEditState(formRow));
  const bytes = await _formsStorage.downloadBytes(formRow.storage_path);
  const doc = await PDFLib.PDFDocument.load(bytes);
  try {
    const acroForm = doc.getForm();
    await _addDownloadStateFields(doc, acroForm, state);
    acroForm.updateFieldAppearances();
  } catch (e) {
    console.warn('[_buildEditedFormPdfBlob] AcroForm values skipped:', e.message);
  }
  // Optional helper font for stamps.
  let stampFont = null;
  for (const sig of Object.values(state.signatures || {})) {
    if (!sig?.dataUrl || !Array.isArray(sig.rect)) continue;
    try {
      const png = await doc.embedPng(sig.dataUrl);
      const page = doc.getPages()[sig.pageIndex];
      if (!page) continue;
      const [x1, y1, x2, y2] = sig.rect;
      const boxW = Math.abs(x2 - x1);
      const boxH = Math.abs(y2 - y1);
      const pad = Math.min(6, boxH * 0.14, boxW * 0.04);
      const maxW = Math.max(1, boxW - pad * 2);
      const maxH = Math.max(1, boxH - pad * 2);
      const imgRatio = png.width / png.height;
      let drawW = maxW;
      let drawH = drawW / imgRatio;
      if (drawH > maxH) { drawH = maxH; drawW = drawH * imgRatio; }
      page.drawImage(png, {
        x: Math.min(x1, x2) + (boxW - drawW) / 2,
        y: Math.min(y1, y2) + (boxH - drawH) / 2,
        width: drawW,
        height: drawH,
      });
      if (sig.stamp?.name || sig.stamp?.at) {
        if (!stampFont) stampFont = await doc.embedFont(PDFLib.StandardFonts.Helvetica);
        const stampText = `${sig.stamp.name || ''}${sig.stamp.at ? '  ' + new Date(sig.stamp.at).toLocaleString() : ''}`.trim();
        const fontSize = Math.max(6, Math.min(9, boxH * 0.18));
        page.drawText(stampText, {
          x: Math.min(x1, x2) + pad,
          y: Math.min(y1, y2) + 1,
          size: fontSize,
          font: stampFont,
          color: PDFLib.rgb(0.25, 0.3, 0.4),
        });
      }
    } catch (e) {
      console.warn('[_buildEditedFormPdfBlob] signature skipped:', sig.name, e.message);
    }
  }
  return new Blob([await doc.save({ updateFieldAppearances: true })], { type: 'application/pdf' });
}

async function downloadFormPDF(formId) {
  const form = FORMS.find(f => f.id === formId);
  if (!form) return;
  try {
    const liveState = _pdfViewerState?.formId === formId ? {
      fields: _collectFormFieldValues(),
      signatures: _pdfViewerState.signatures || {},
      layouts: _pdfViewerState.fieldLayouts || [],
    } : null;
    const blob = await _buildEditedFormPdfBlob(form, liveState);
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = form.original_filename || `${form.name || 'form'}.pdf`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 5000);
    formViewerEvent('download_ok', { formId, online: navigator.onLine });
  } catch (e) { toast('Download failed: ' + e.message, 'error'); }
}

function closeFormViewer() {
  closeSignaturePad();
  if (_pdfViewerState?.dirty) {
    // Best-effort flush: local draft is already saved; try remote async.
    _pdfAutosaveRemote().catch(() => {});
  }
  if (_pdfViewerState?.autosaveTimer) clearTimeout(_pdfViewerState.autosaveTimer);
  _pdfViewerState = null;
  closeModal();
}

// ── FORM PICKER (per test case, scope-aware) ────────────────────────────
// `testId`  → the *parent* (or standalone) test case id. For child asset
//             rows we always use the parent's TestID and pass assetId
//             separately, because all link rows live keyed to the parent.
// `assetId` → '' (empty) means "open from parent context": list every link
//             on this test case (parent-scope + every per-asset link) and
//             allow scope to be chosen on attach/link.
//             A uuid means "open from one child asset row": list parent-
//             scope (read-only/inherited) + this asset's per-asset links;
//             new attach/link calls auto-target this asset's scope.
function _fpResolveContext(testIdOrChildId, assetIdArg) {
  // Accept either a parent TestID + assetId, or a child TestID alone — and
  // normalize to { parentRow, assetId, originalArg } so callers can hand us
  // whichever they have.
  let parentRow = TI.find(r => String(r.TestID) === String(testIdOrChildId));
  let assetId = (assetIdArg || '') === '' ? '' : String(assetIdArg);
  if (parentRow && parentRow.ParentTestId && parentRow.AssetId && !assetId) {
    // A child row id was passed directly — promote to its parent + asset.
    assetId = String(parentRow.AssetId);
    parentRow = TI.find(r => String(r.TestID) === String(parentRow.ParentTestId)) || parentRow;
  }
  return { parentRow, assetId, parentTestId: parentRow ? String(parentRow.TestID) : String(testIdOrChildId) };
}
function openFormPickerForTest(testId, assetId = '') {
  const ctx = _fpResolveContext(testId, assetId);
  const row = ctx.parentRow;
  const asset = ctx.assetId ? (typeof ASSETS !== 'undefined' ? ASSETS : []).find(a => a.id === ctx.assetId) : null;
  const baseSub = row ? `${row.TestCaseCode || row.TestID} · ${row.Activity || ''}`.trim() : ctx.parentTestId;
  const sub = asset ? `${baseSub}  ·  Asset: ${asset.name}` : baseSub;
  modal({
    title: 'Linked Forms', sub, size: 'large',
    body: _formPickerBody(ctx.parentTestId, ctx.assetId),
    footer: `<button class="form-secondary" onclick="closeModal()">Close</button>`,
  });
}

function _formPickerBody(testId, assetId = '') {
  const parentRow = TI.find(r => String(r.TestID) === String(testId));
  const isParentCase = !!(parentRow && parentRow.IsParent);
  const childRows = isParentCase ? TI.filter(r => String(r.ParentTestId) === String(testId)) : [];
  const allLinks = _formsLinkRowsForTestCase(testId);
  // Filter for the current scope view
  const visible = assetId
    ? allLinks.filter(r => r.scope === 'parent' || String(r.link.asset_id) === String(assetId))
    : allLinks;

  const targetAsset = assetId ? (typeof ASSETS !== 'undefined' ? ASSETS : []).find(a => a.id === assetId) : null;
  const tid = escapeHtml(String(testId));
  const aid = escapeHtml(String(assetId || ''));

  const scopeBanner = (() => {
    if (assetId) {
      return `<div style="margin-bottom:12px;padding:10px 12px;border-radius:6px;background:#eff6ff;border:1px solid #bfdbfe;font-size:12px;color:#1e3a8a;">
        Showing forms for <strong>${escapeHtml(targetAsset?.name || 'this asset')}</strong>. Forms with scope <em>“Covers all assets”</em> are inherited from the parent test case and managed there.
      </div>`;
    }
    if (isParentCase) {
      return `<div style="margin-bottom:12px;padding:10px 12px;border-radius:6px;background:#f5f3ff;border:1px solid #ddd6fe;font-size:12px;color:#4c1d95;">
        This test case has <strong>${childRows.length} child asset${childRows.length===1?'':'s'}</strong>. Forms can either <strong>cover all assets</strong> (one PDF for the whole test case) or be linked to a <strong>specific asset</strong>.
      </div>`;
    }
    return '';
  })();

  const rowsHtml = visible.length === 0
    ? `<div style="padding:24px;text-align:center;color:var(--gray-500);border:1px dashed var(--gray-300);border-radius:6px;">No forms linked${assetId ? ' to this asset' : ' to this test case'} yet.</div>`
    : `<table class="data-table">
         <thead><tr><th>Name</th>${isParentCase ? '<th>Scope</th>' : ''}<th>Phase</th><th>Subsystem</th><th>Description</th><th style="width:200px;">Actions</th></tr></thead>
         <tbody>${visible.map(({ form, scope, asset }) => {
            const inherited = !!(assetId && scope === 'parent');
            const scopeCell = isParentCase
              ? (scope === 'parent'
                  ? `<span class="tag" style="background:#ede9fe;color:#5b21b6;border:1px solid #ddd6fe;">All assets</span>`
                  : `<span class="tag" style="background:#dbeafe;color:#1d4ed8;border:1px solid #bfdbfe;">${escapeHtml(asset?.name || 'asset')}</span>`)
              : '';
            const unlinkBtn = inherited
              ? `<span style="font-size:11px;color:var(--gray-500);font-style:italic;">inherited</span>`
              : `<button class="form-secondary tr-mini-btn" onclick="unlinkFormFromTest('${form.id}','${tid}','${scope === 'asset' ? escapeHtml(String(asset?.id || '')) : ''}')">Unlink</button>`;
            return `
             <tr${inherited ? ' style="background:#fafafa;"' : ''}>
               <td style="font-weight:600;">${escapeHtml(form.name)}</td>
               ${isParentCase ? `<td>${scopeCell}</td>` : ''}
               <td style="font-size:12px;">${escapeHtml(form.phase || '—')}</td>
               <td><span class="tag">${escapeHtml(form.subsystem || '—')}</span></td>
               <td style="font-size:12px;color:var(--gray-600);">${escapeHtml(form.description || '')}</td>
               <td style="white-space:nowrap;">
                 <button class="admin-action-btn tr-mini-btn" onclick="openFormViewer('${form.id}')">Open</button>
                 ${unlinkBtn}
               </td>
             </tr>`;
           }).join('')}
         </tbody>
       </table>`;

  return `
    ${scopeBanner}
    <div style="margin-bottom:14px;display:flex;gap:8px;flex-wrap:wrap;">
      <button class="form-submit" onclick="openAttachNewForm('${tid}','${aid}')">+ Attach New PDF</button>
      <button class="form-secondary" onclick="openLinkExistingForm('${tid}','${aid}')">Link Existing Form</button>
    </div>
    ${rowsHtml}
  `;
}

// Renders the scope picker shown when attaching/linking from a parent
// test case that has child assets. Defaults to "Covers all assets" so the
// historical behavior (one form on the parent) keeps working unchanged.
function _fpScopeFieldHTML(testId, assetId, fieldId = 'frm-scope') {
  const parentRow = TI.find(r => String(r.TestID) === String(testId));
  const isParentCase = !!(parentRow && parentRow.IsParent);
  const childRows = isParentCase ? TI.filter(r => String(r.ParentTestId) === String(testId)) : [];
  if (!isParentCase) return ''; // standalone — scope is always implicit (NULL)
  // If we already know which asset (called from a child row), force-select it.
  const forced = assetId ? String(assetId) : '';
  const opts = [
    `<option value="" ${!forced ? 'selected' : ''}>Covers all assets (parent-scope)</option>`,
    ...childRows.map(c => {
      const a = (typeof ASSETS !== 'undefined' ? ASSETS : []).find(x => x.id === c.AssetId);
      const name = a?.name || c.TestID;
      return `<option value="${escapeHtml(String(c.AssetId))}" ${forced && forced === String(c.AssetId) ? 'selected' : ''}>Asset: ${escapeHtml(name)}</option>`;
    }),
  ].join('');
  return `
    <div class="form-field form-field-full">
      <label>Form Scope</label>
      <select id="${fieldId}" class="form-input">${opts}</select>
      <div style="font-size:11px;color:var(--gray-500);margin-top:4px;">
        <strong>Covers all assets</strong>: one PDF used for the whole test case; per-asset statuses still tracked separately.<br>
        <strong>Asset:&nbsp;…</strong>: this form is linked only to that child asset row.
      </div>
    </div>`;
}

function openAttachNewForm(testId, assetId = '') {
  const ctx = _fpResolveContext(testId, assetId);
  const row = ctx.parentRow;
  const tid = escapeHtml(ctx.parentTestId);
  const aid = escapeHtml(ctx.assetId || '');
  modal({
    title: 'Attach New PDF',
    sub: row ? `${row.TestCaseCode || row.TestID}` : '',
    body: `
      <div class="form-grid">
        <div class="form-field form-field-full"><label>PDF File</label><input type="file" id="frm-file" accept="application/pdf" class="form-input"></div>
        <div class="form-field form-field-full"><label>Form Name</label><input type="text" id="frm-name" class="form-input" placeholder="e.g. PWR-001 Data Sheet"></div>
        ${_fpScopeFieldHTML(ctx.parentTestId, ctx.assetId, 'frm-scope')}
        <div class="form-field"><label>Subsystem</label><input type="text" id="frm-sub" class="form-input" value="${escapeHtml(row?.SubSystem || row?.Subsystem || '')}"></div>
        <div class="form-field"><label>Phase</label><input type="text" id="frm-phase" class="form-input" value="${escapeHtml(row?.Phase || '')}"></div>
        <div class="form-field form-field-full"><label>Location</label><input type="text" id="frm-loc" class="form-input" value="${escapeHtml(row?.Location || '')}"></div>
        <div class="form-field form-field-full"><label>Notes / Description</label><textarea id="frm-desc" class="form-input" rows="2" placeholder="Optional high-level description"></textarea></div>
      </div>
    `,
    footer: `<button class="form-secondary" onclick="openFormPickerForTest('${tid}','${aid}')">Cancel</button>
             <button class="form-submit" onclick="submitAttachNewForm('${tid}','${aid}')">Upload &amp; Link</button>`,
  });
}

async function submitAttachNewForm(testId, assetId = '') {
  const file = document.getElementById('frm-file')?.files?.[0];
  if (!file) { toast('Select a PDF', 'error'); return; }
  if (file.type !== 'application/pdf') { toast('File must be a PDF', 'error'); return; }
  const name = document.getElementById('frm-name')?.value.trim();
  if (!name) { toast('Name is required', 'error'); return; }
  // Read scope: use form field if present (parent context), else use prefilled asset.
  const scopeField = document.getElementById('frm-scope');
  const scopeAssetId = scopeField ? (scopeField.value || '') : (assetId || '');
  const btn = document.querySelector('.modal-footer .form-submit');
  if (btn) { btn.disabled = true; btn.textContent = 'Uploading…'; }
  try {
    const created = await _formsCreate({
      name,
      description: document.getElementById('frm-desc')?.value.trim(),
      subsystem:   document.getElementById('frm-sub')?.value.trim(),
      phase:       document.getElementById('frm-phase')?.value.trim(),
      location:    document.getElementById('frm-loc')?.value.trim(),
      isTemplate: false, originalFilename: file.name, fileSize: file.size, file,
    });
    await _formsLinkToTest(created.id, testId, scopeAssetId || null);
    const scopeNote = scopeAssetId
      ? `asset:${(typeof ASSETS!=='undefined'?ASSETS:[]).find(a=>a.id===scopeAssetId)?.name || scopeAssetId}`
      : 'all assets';
    logAudit('Attached Form to Test Case', name, `${testId} · ${scopeNote}`);
    toast('✓ Form attached', 'success');
    openFormPickerForTest(testId, scopeAssetId);
    if (typeof _reRenderTR === 'function') _reRenderTR();
  } catch (e) {
    toast('Upload failed: ' + e.message, 'error');
    if (btn) { btn.disabled = false; btn.textContent = 'Upload & Link'; }
  }
}

function openLinkExistingForm(testId, assetId = '') {
  const ctx = _fpResolveContext(testId, assetId);
  const tid = escapeHtml(ctx.parentTestId);
  const aid = escapeHtml(ctx.assetId || '');
  // For per-asset context: hide forms already linked to *this asset* or as parent-scope.
  // For parent context: hide forms with any link to this test case.
  const scopeAssetId = ctx.assetId || '';
  const linksHere = FORM_TEST_LINKS.filter(l => l.test_id === ctx.parentTestId);
  const blocked = scopeAssetId
    ? new Set(linksHere.filter(l => l.asset_id == null || String(l.asset_id) === String(scopeAssetId)).map(l => l.form_id))
    : new Set(linksHere.map(l => l.form_id));
  const candidates = FORMS.filter(f => !blocked.has(f.id) && !f.is_template);
  window._lefAll = candidates;
  window._lefTestId = ctx.parentTestId;
  window._lefAssetId = scopeAssetId;
  modal({
    title: 'Link Existing Form', size: 'large',
    body: `
      ${_fpScopeFieldHTML(ctx.parentTestId, ctx.assetId, 'lef-scope')}
      <input type="text" class="form-input" placeholder="Search by name, subsystem, location…" style="margin-bottom:12px;"
             oninput="document.getElementById('lef-list').innerHTML = window._lefFilter(this.value)">
      <div id="lef-list" style="max-height:45vh;overflow:auto;">${_lefRenderList(candidates)}</div>
    `,
    footer: `<button class="form-secondary" onclick="openFormPickerForTest('${tid}','${aid}')">Cancel</button>`,
  });
  window._lefFilter = (q) => {
    q = (q || '').trim().toLowerCase();
    const m = !q ? window._lefAll :
      window._lefAll.filter(f =>
        (f.name||'').toLowerCase().includes(q) ||
        (f.subsystem||'').toLowerCase().includes(q) ||
        (f.location||'').toLowerCase().includes(q) ||
        (f.phase||'').toLowerCase().includes(q));
    return _lefRenderList(m);
  };
}

function _lefRenderList(list) {
  if (!list.length) return `<div style="padding:24px;text-align:center;color:var(--gray-500);">No matching forms.</div>`;
  return `<table class="data-table"><thead><tr><th>Name</th><th>Phase</th><th>Location</th><th>Subsystem</th><th style="width:90px;"></th></tr></thead>
    <tbody>${list.map(f => `
      <tr>
        <td style="font-weight:600;">${escapeHtml(f.name)}</td>
        <td style="font-size:12px;">${escapeHtml(f.phase || '—')}</td>
        <td style="font-size:12px;">${escapeHtml(f.location || '—')}</td>
        <td><span class="tag">${escapeHtml(f.subsystem || '—')}</span></td>
        <td><button class="admin-action-btn tr-mini-btn" onclick="linkExistingFormToTest('${f.id}', window._lefTestId)">Link</button></td>
      </tr>`).join('')}</tbody></table>`;
}

async function linkExistingFormToTest(formId, testId) {
  try {
    // Pick scope from the picker UI; fall back to whatever the picker was opened with.
    const scopeField = document.getElementById('lef-scope');
    const scopeAssetId = scopeField ? (scopeField.value || '') : (window._lefAssetId || '');
    await _formsLinkToTest(formId, testId, scopeAssetId || null);
    const scopeNote = scopeAssetId
      ? `asset:${(typeof ASSETS!=='undefined'?ASSETS:[]).find(a=>a.id===scopeAssetId)?.name || scopeAssetId}`
      : 'all assets';
    logAudit('Linked Existing Form to Test Case', FORMS.find(f => f.id === formId)?.name || formId, `${testId} · ${scopeNote}`);
    toast('✓ Linked', 'success');
    openFormPickerForTest(testId, scopeAssetId);
    if (typeof _reRenderTR === 'function') _reRenderTR();
  } catch (e) { toast('Link failed: ' + e.message, 'error'); }
}

async function unlinkFormFromTest(formId, testId, assetId = '') {
  if (!confirm('Unlink this form from the test case? The file itself is not deleted.')) return;
  try {
    // assetId === '' from a non-parent (standalone) case → unlink the
    // single (form, test) row. From a parent case the caller always sends
    // the explicit scope (asset uuid or '' for parent-scope), and we pass
    // that through. Note: '' here means parent-scope (NULL), not "any".
    const scope = assetId === '' && (() => {
      const r = TI.find(t => String(t.TestID) === String(testId));
      return !!(r && r.IsParent);
    })() ? null : (assetId || null);
    await _formsUnlinkFromTest(formId, testId, scope);
    logAudit('Unlinked Form from Test Case', FORMS.find(f => f.id === formId)?.name || formId, testId);
    openFormPickerForTest(testId, assetId);
    if (typeof _reRenderTR === 'function') _reRenderTR();
  } catch (e) { toast('Unlink failed: ' + e.message, 'error'); }
}

function _formsBadgeHTML(testIdOrRow, assetId = '') {
  // Back-compat: callers that pass a raw test_id string still work — we
  // resolve it to its TI row. New callers pass the row directly.
  const row = (typeof testIdOrRow === 'string')
    ? TI.find(r => String(r.TestID) === String(testIdOrRow))
    : testIdOrRow;
  if (!row) {
    const tid = escapeHtml(String(testIdOrRow || ''));
    return `<button class="form-secondary tr-mini-btn" title="Attach form" onclick="openFormPickerForTest('${tid}')" style="font-size:13px;padding:2px 6px;color:var(--gray-500);">📎</button>`;
  }
  const count = _formsCountForTestRow(row);
  // Child asset row → open picker focused on this asset's scope.
  const isChild = row.ParentTestId && row.AssetId;
  const targetTestId = isChild ? String(row.ParentTestId) : String(row.TestID);
  const targetAsset  = isChild ? String(row.AssetId) : (assetId || '');
  const tid = escapeHtml(targetTestId);
  const aid = escapeHtml(targetAsset);
  if (count === 0) {
    return `<button class="form-secondary tr-mini-btn" title="Attach form" onclick="openFormPickerForTest('${tid}','${aid}')" style="font-size:13px;padding:2px 6px;color:var(--gray-500);">📎</button>`;
  }
  const titleBits = [`${count} form${count===1?'':'s'} linked`];
  if (isChild) titleBits.push('(includes any covering all assets)');
  return `<button class="admin-action-btn tr-mini-btn" title="${titleBits.join(' ')}" onclick="openFormPickerForTest('${tid}','${aid}')" style="font-size:11px;padding:2px 7px;background:#dbeafe;color:#1d4ed8;border:1px solid #93c5fd;">📎 ${count}</button>`;
}

// ── TEMPLATE EDITOR INTEGRATION ─────────────────────────────────────────
function _tplFormsBlockHTML(templateId) {
  if (!templateId) return '';
  const attached = _formsLegacyForTemplate(templateId);
  if (!attached.length) return '';
  return `
    <div style="margin-top:18px;padding:14px;border:1px solid var(--gray-200);border-radius:6px;background:var(--gray-50);">
      <div style="font-weight:600;font-size:13px;margin-bottom:6px;">Legacy Activity-Level Form Templates</div>
      <div style="font-size:11px;color:var(--gray-600);margin-bottom:10px;">These older links are no longer cloned on deployment. Attach PDFs from the Form PDF column on each test case line.</div>
      <div style="display:flex;flex-direction:column;gap:6px;">
             ${attached.map(f => `
               <div style="display:flex;align-items:center;gap:10px;padding:6px 10px;background:var(--white);border:1px solid var(--gray-200);border-radius:5px;">
                 <span style="flex:1;font-size:13px;font-weight:600;">${escapeHtml(f.name)}</span>
                 <span class="tag">${escapeHtml(f.subsystem || '—')}</span>
                 <button class="admin-action-btn tr-mini-btn" onclick="openFormViewer('${f.id}')">View</button>
                 <button class="form-secondary tr-mini-btn" onclick="detachTemplateForm('${f.id}','${templateId}')">Remove</button>
               </div>`).join('')}
           </div>
    </div>
  `;
}

function _tplCaseCodeByIndex(si, ci) {
  return String(_templateSections?.[si]?.cases?.[ci]?.code || '').trim();
}

function _tplCaseNameByIndex(si, ci) {
  return String(_templateSections?.[si]?.cases?.[ci]?.name || '').trim();
}

function openAttachTemplateFormForCase(templateId, si, ci) {
  const code = _tplCaseCodeByIndex(si, ci);
  if (!code) { toast('Enter a test case code first', 'warn'); return; }
  openAttachTemplateForm(templateId, code, _tplCaseNameByIndex(si, ci));
}

function detachTemplateFormForCase(formId, templateId, si, ci) {
  const code = _tplCaseCodeByIndex(si, ci);
  if (!code) { toast('Test case code is missing', 'warn'); return; }
  detachTemplateForm(formId, templateId, code);
}

function openAttachTemplateForm(templateId, testCaseCode = '', testCaseName = '') {
  const tpl = TEMPLATES.find(t => t.id === templateId);
  if (!tpl) { toast('Template not found', 'error'); return; }
  const scopeCode = String(testCaseCode || '').trim();
  const scopeLabel = scopeCode ? `${scopeCode}${testCaseName ? ` - ${testCaseName}` : ''}` : tpl.name;
  modal({
    title: 'Attach Test Case PDF', sub: scopeLabel,
    body: `
      <input type="hidden" id="tplfrm-code" value="${escapeHtml(scopeCode)}">
      <div class="form-grid">
        <div class="form-field form-field-full"><label>PDF File</label><input type="file" id="tplfrm-file" accept="application/pdf" class="form-input"></div>
        <div class="form-field form-field-full"><label>Form Name</label><input type="text" id="tplfrm-name" class="form-input" placeholder="e.g. SAT Data Sheet — Power"></div>
        <div class="form-field form-field-full"><label>Notes / Description</label><textarea id="tplfrm-desc" class="form-input" rows="2"></textarea></div>
      </div>
      <div style="font-size:11px;color:var(--gray-500);margin-top:10px;">On deployment, this PDF is copied for this test case at each selected location and linked to that location's test item.</div>
    `,
    footer: `<button class="form-secondary" onclick="_reopenTemplateEditor('${templateId}')">Cancel</button>
             <button class="form-submit" onclick="submitAttachTemplateForm('${templateId}')">Upload &amp; Attach</button>`,
  });
}

async function submitAttachTemplateForm(templateId) {
  const tpl = TEMPLATES.find(t => t.id === templateId);
  if (!tpl) return;
  const scopeCode = document.getElementById('tplfrm-code')?.value.trim();
  if (!scopeCode) { toast('Test case code is required for template PDFs', 'error'); return; }
  const file = document.getElementById('tplfrm-file')?.files?.[0];
  if (!file) { toast('Select a PDF', 'error'); return; }
  if (file.type !== 'application/pdf') { toast('File must be a PDF', 'error'); return; }
  const name = document.getElementById('tplfrm-name')?.value.trim();
  if (!name) { toast('Name is required', 'error'); return; }
  const btn = document.querySelector('.modal-footer .form-submit');
  if (btn) { btn.disabled = true; btn.textContent = 'Uploading…'; }
  try {
    const created = await _formsCreate({
      name,
      description: document.getElementById('tplfrm-desc')?.value.trim(),
      subsystem: tpl.subsystem || null, phase: null, location: null,
      isTemplate: true, originalFilename: file.name, fileSize: file.size, file,
    });
    await _formsLinkToTemplate(created.id, templateId, scopeCode);
    logAudit('Attached Template Form', `${tpl.name} ← ${name}`, '');
    toast('✓ Template PDF attached', 'success');
    _reopenTemplateEditor(templateId);
  } catch (e) {
    toast('Upload failed: ' + e.message, 'error');
    if (btn) { btn.disabled = false; btn.textContent = 'Upload & Attach'; }
  }
}

async function detachTemplateForm(formId, templateId, testCaseCode) {
  if (!confirm('Remove this template PDF? It will no longer be cloned on future deployments. Already-deployed copies are untouched.')) return;
  try {
    await _formsUnlinkFromTemplate(formId, templateId, testCaseCode);
    logAudit('Detached Template Form', FORMS.find(f => f.id === formId)?.name || formId, templateId);
    _reopenTemplateEditor(templateId);
  } catch (e) { toast('Remove failed: ' + e.message, 'error'); }
}

function _reopenTemplateEditor(templateId) {
  closeModal();
  setTimeout(() => { if (typeof editTemplate === 'function') editTemplate(templateId); }, 30);
}

// ── FORMS MODULE PAGE ───────────────────────────────────────────────────
let _formsPageFilters = { phase: '', location: '', subsystem: '', search: '', showTemplates: false };
let _formsSearchDebounce = null;

async function renderFormsPage() {
  const root = document.getElementById('forms-page-content');
  if (!root) return;
  await loadForms();
  root.innerHTML = _formsPageHTML();
  _formsRenderRecentsRow();
  _formsRenderList();
}

// Re-render only the list (filters + table). Keeps the recents row intact
// so it doesn't flicker on every filter change. Does NOT re-fetch from DB —
// callers that need fresh data should use `renderFormsPage()`.
function _formsRenderList() {
  const host = document.getElementById('forms-page-list');
  if (!host) return;
  host.innerHTML = _formsPageListHTML();
}

function _formsPageHTML() {
  return `
    <div class="admin-section">
      <div id="forms-recents-row" class="forms-recents-row" hidden></div>
      <div id="forms-page-list">${_formsPageListHTML()}</div>
    </div>
  `;
}

function _formsPageListHTML() {
  const f = _formsPageFilters;
  const all = FORMS.filter(x => f.showTemplates ? x.is_template : !x.is_template);
  const phases    = [...new Set(all.map(x => x.phase    ).filter(Boolean))].sort();
  const locations = [...new Set(all.map(x => x.location ).filter(Boolean))].sort();
  const subs      = [...new Set(all.map(x => x.subsystem).filter(Boolean))].sort();
  let filtered = all.filter(x =>
    (!f.phase     || x.phase     === f.phase) &&
    (!f.location  || x.location  === f.location) &&
    (!f.subsystem || x.subsystem === f.subsystem));
  if (f.search) {
    const q = f.search.toLowerCase();
    filtered = filtered.filter(x =>
      (x.name||'').toLowerCase().includes(q) ||
      (x.description||'').toLowerCase().includes(q) ||
      (x.original_filename||'').toLowerCase().includes(q));
  }
  const rows = filtered.map(x => {
    const linkedTests = FORM_TEST_LINKS.filter(l => l.form_id === x.id).length;
    const linkedTpls  = FORM_TPL_LINKS .filter(l => l.form_id === x.id).length;
    const summary = x.is_template
      ? `${linkedTpls} template${linkedTpls === 1 ? '' : 's'}`
      : `${linkedTests} test case${linkedTests === 1 ? '' : 's'}`;
    return `
      <tr>
        <td style="font-weight:600;">${escapeHtml(x.name)}</td>
        <td><span class="tag">${escapeHtml(x.subsystem || '—')}</span></td>
        <td style="font-size:12px;">${escapeHtml(x.phase || '—')}</td>
        <td style="font-size:12px;">${escapeHtml(x.location || '—')}</td>
        <td style="font-size:12px;color:var(--gray-600);max-width:280px;">${escapeHtml(x.description || '')}</td>
        <td style="font-size:12px;">${summary}</td>
        <td style="font-size:11px;color:var(--gray-500);">${x.updated_at ? new Date(x.updated_at).toLocaleDateString() : '—'}</td>
        <td style="white-space:nowrap;">
          <button class="admin-action-btn tr-mini-btn" onclick="openFormViewer('${x.id}')">Open</button>
          <button class="form-secondary tr-mini-btn"   onclick="openEditFormMetadata('${x.id}')">Edit</button>
          <button class="form-secondary tr-mini-btn"   style="color:var(--bad);" onclick="deleteFormFromPage('${x.id}')">🗑</button>
        </td>
      </tr>`;
  }).join('');
  return `
      <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:14px;">
        <input type="text" class="form-input" id="forms-page-search" placeholder="Search name, description, filename…" style="flex:1;min-width:240px;"
               value="${escapeHtml(f.search)}" oninput="_formsSetSearch(this.value)">
        <select class="form-input" onchange="_formsSetFilter('phase', this.value)">
          <option value="">All Phases</option>
          ${phases.map(p => `<option value="${escapeHtml(p)}" ${f.phase === p ? 'selected' : ''}>${escapeHtml(p)}</option>`).join('')}
        </select>
        <select class="form-input" onchange="_formsSetFilter('location', this.value)">
          <option value="">All Locations</option>
          ${locations.map(p => `<option value="${escapeHtml(p)}" ${f.location === p ? 'selected' : ''}>${escapeHtml(p)}</option>`).join('')}
        </select>
        <select class="form-input" onchange="_formsSetFilter('subsystem', this.value)">
          <option value="">All Subsystems</option>
          ${subs.map(p => `<option value="${escapeHtml(p)}" ${f.subsystem === p ? 'selected' : ''}>${escapeHtml(p)}</option>`).join('')}
        </select>
        <label style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--gray-700);">
          <input type="checkbox" ${f.showTemplates ? 'checked' : ''} onchange="_formsSetFilter('showTemplates', this.checked)">
          Show template blanks
        </label>
      </div>
      <div class="data-card" style="padding:0;overflow:hidden;">
        <table class="data-table">
          <thead><tr><th>Name</th><th>Subsystem</th><th>Phase</th><th>Location</th><th>Description</th><th>Linked</th><th>Updated</th><th style="width:160px;">Actions</th></tr></thead>
          <tbody>
            ${filtered.length === 0
              ? `<tr><td colspan="8" style="text-align:center;padding:32px;color:var(--gray-400);">No forms match the current filters.</td></tr>`
              : rows}
          </tbody>
        </table>
      </div>
      <div style="font-size:11px;color:var(--gray-500);margin-top:10px;">
        ${filtered.length} of ${all.length} ${f.showTemplates ? 'template blanks' : 'forms'} shown. Attach new forms from the 📎 icon on a test case row, or as a template-level PDF in the Activity Templates editor.
      </div>
  `;
}

// Filter setter — re-renders only the list region (no DB hit, no flicker).
function _formsSetFilter(key, value) {
  _formsPageFilters[key] = value;
  _formsRenderList();
}

// Debounced search to avoid re-rendering the list on every keystroke.
function _formsSetSearch(value) {
  _formsPageFilters.search = value;
  if (_formsSearchDebounce) clearTimeout(_formsSearchDebounce);
  _formsSearchDebounce = setTimeout(() => {
    _formsSearchDebounce = null;
    _formsRenderList();
    // Re-focus the search input + restore caret since innerHTML replaced it.
    const el = document.getElementById('forms-page-search');
    if (el) {
      el.focus();
      const len = el.value.length;
      try { el.setSelectionRange(len, len); } catch { /* noop */ }
    }
  }, 180);
}

function openEditFormMetadata(formId) {
  const f = FORMS.find(x => x.id === formId);
  if (!f) return;
  modal({
    title: 'Edit Form Details', sub: f.name,
    body: `
      <div class="form-grid">
        <div class="form-field form-field-full"><label>Form Name</label><input type="text" id="ef-name" class="form-input" value="${escapeHtml(f.name)}"></div>
        <div class="form-field"><label>Subsystem</label><input type="text" id="ef-sub" class="form-input" value="${escapeHtml(f.subsystem || '')}"></div>
        <div class="form-field"><label>Phase</label><input type="text" id="ef-phase" class="form-input" value="${escapeHtml(f.phase || '')}"></div>
        <div class="form-field form-field-full"><label>Location</label><input type="text" id="ef-loc" class="form-input" value="${escapeHtml(f.location || '')}"></div>
        <div class="form-field form-field-full"><label>Notes / Description</label><textarea id="ef-desc" class="form-input" rows="2">${escapeHtml(f.description || '')}</textarea></div>
      </div>
    `,
    footer: `<button class="form-secondary" onclick="closeModal()">Cancel</button>
             <button class="form-submit" onclick="submitEditFormMetadata('${formId}')">Save</button>`,
  });
}

async function submitEditFormMetadata(formId) {
  const patch = {
    name:        document.getElementById('ef-name')?.value.trim(),
    subsystem:   document.getElementById('ef-sub')?.value.trim()   || null,
    phase:       document.getElementById('ef-phase')?.value.trim() || null,
    location:    document.getElementById('ef-loc')?.value.trim()   || null,
    description: document.getElementById('ef-desc')?.value.trim()  || null,
  };
  if (!patch.name) { toast('Name is required', 'error'); return; }
  try {
    await _formsUpdateMetadata(formId, patch);
    logAudit('Edited Form Metadata', patch.name, formId);
    toast('✓ Saved', 'success');
    closeModal();
    if (document.getElementById('page-forms')?.classList.contains('active')) renderFormsPage();
  } catch (e) { toast('Save failed: ' + e.message, 'error'); }
}

async function deleteFormFromPage(formId) {
  const f = FORMS.find(x => x.id === formId);
  if (!f) return;
  const lt = FORM_TEST_LINKS.filter(l => l.form_id === formId).length;
  const lp = FORM_TPL_LINKS .filter(l => l.form_id === formId).length;
  const warn = (lt + lp) > 0 ? `\n\nThis will also remove ${lt} test-case link(s) and ${lp} template link(s).` : '';
  if (!confirm(`Delete form "${f.name}"? The PDF file will be removed from storage.${warn}\n\nThis cannot be undone.`)) return;
  try {
    await _formsDelete(formId);
    logAudit('Deleted Form', f.name, formId);
    toast('✓ Deleted', 'success');
    renderFormsPage();
  } catch (e) { toast('Delete failed: ' + e.message, 'error'); }
}

// ═══════════════════════════════════════════════════════════════════════════
// TEST REPORT EXTRACT — compiled PDF (or ZIP) builder
// ───────────────────────────────────────────────────────────────────────────
// Produces a client-ready bundle for a Test Report row:
//   • Cover/overall summary page
//   • Per-activity index page
//   • Per-section summary tables
//   • Filled form PDFs grouped under each section
//   • PDF outline (bookmarks) for navigation
//   • Page-number footers
// Two output modes: single combined PDF, or numbered ZIP for very large reports.
// ═══════════════════════════════════════════════════════════════════════════

const _EXTRACT_PAGE_W = 612;   // US Letter portrait, in PDF points (72 dpi)
const _EXTRACT_PAGE_H = 792;
const _EXTRACT_MARGIN = 48;
const _EXTRACT_STATUS_KEYS = ['passed','failed','blocked','inProgress','notStarted','future'];
const _EXTRACT_STATUS_LABELS = {
  passed: 'Pass', failed: 'Fail', blocked: 'Blocked',
  inProgress: 'In Progress', notStarted: 'Not Started', future: 'Future',
};
const _EXTRACT_STATUS_COLORS = {
  passed:     [0.13, 0.55, 0.27],
  failed:     [0.78, 0.16, 0.16],
  blocked:    [0.83, 0.49, 0.04],
  inProgress: [0.13, 0.36, 0.78],
  notStarted: [0.42, 0.45, 0.50],
  future:     [0.45, 0.27, 0.65],
};

let _extractRunState = null;  // { cancelled, totalForms, doneForms }

// ── Status mapping (mirrors _trpStatusCounts buckets) ─────────────────────
function _extractStatusKey(status) {
  const s = String(status || '').toLowerCase();
  if (['pass', 'passed', 'complete', 'completed'].includes(s)) return 'passed';
  if (['fail', 'failed'].includes(s)) return 'failed';
  if (s === 'blocked') return 'blocked';
  if (s === 'in progress') return 'inProgress';
  if (s === 'future test' || s === 'future') return 'future';
  return 'notStarted';
}

function _extractSlug(s, max = 40) {
  return String(s || 'untitled')
    .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9._-]+/g, '_')
    .replace(/_+/g, '_').replace(/^_+|_+$/g, '')
    .slice(0, max) || 'untitled';
}

// ── Group an activity's items by TestSection (with stable section order) ──
function _extractGroupBySection(activity) {
  const map = new Map();
  (activity.items || []).forEach(t => {
    const key = String(t.TestSection || '').trim() || '(Unsectioned)';
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(t);
  });
  const sections = [...map.entries()].map(([name, items]) => ({
    name,
    items: items.slice().sort((a, b) =>
      String(a.TestCaseCode || '').localeCompare(String(b.TestCaseCode || ''), undefined, { numeric: true, sensitivity: 'base' })
    ),
    counts: _trpStatusCounts(items),
  }));
  // Numbered sections first, "(Unsectioned)" last
  sections.sort((a, b) => {
    const aU = a.name === '(Unsectioned)';
    const bU = b.name === '(Unsectioned)';
    if (aU && !bU) return 1;
    if (!aU && bU) return -1;
    return a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: 'base' });
  });
  return sections;
}

function _extractBuildPayload(row, opts) {
  const selectedActKeys = new Set(opts.activityKeys || []);
  const statusFilter = new Set(opts.statusFilter || _EXTRACT_STATUS_KEYS);
  const punchMode = opts.punchMode || 'open';   // 'open' | 'all' | 'none'

  const activities = (row.activities || [])
    .filter(act => selectedActKeys.has(act.key))
    .map(act => {
      const sections = _extractGroupBySection(act);
      let formCount = 0;
      sections.forEach(sec => {
        sec.items.forEach(item => {
          const include = statusFilter.has(_extractStatusKey(item.Status));
          item._extractInclude = include;
          // Scope-aware attachments: child asset rows don't carry forms
          // directly — they are listed under their parent. Parent (or
          // standalone) rows enumerate parent-scope + every per-asset link
          // once, each with its own scope label so the bundle stays deduped.
          const isChild = item.ParentTestId && item.AssetId;
          item._extractForms = isChild ? [] : _formsAttachmentPlanForTestCase(item);
          if (include) formCount += item._extractForms.length;
        });
      });
      return { ...act, sections, formCount };
    });

  const overallCounts = _trpStatusCounts(activities.flatMap(a => a.items || []));

  const allTestIds = new Set(activities.flatMap(a => (a.items||[]).map(t => String(t.TestID))));
  let punchItems = [];
  if (punchMode !== 'none' && Array.isArray(window.PUNCH_DB)) {
    punchItems = PUNCH_DB.filter(p => {
      if (p.is_deleted) return false;
      const linked = (p.linked_test_ids || []).some(id => allTestIds.has(String(id)));
      if (!linked) return false;
      if (punchMode === 'open' && p.status === 'closed') return false;
      return true;
    }).sort((a, b) => (a.number || 0) - (b.number || 0));
  }

  return {
    row,
    activities,
    overallCounts,
    punchItems,
    totalForms: activities.reduce((sum, a) => sum + a.formCount, 0),
    generatedAt: new Date(),
    generatedBy: (currentRoleUser?.name || currentProfile?.full_name || 'Unknown'),
    opts,
  };
}

// ── Modal UI ───────────────────────────────────────────────────────────────
function openExtractReportModal(uid) {
  const row = _trpFindReportRow(uid);
  if (!row) { toast('Report not found', 'error'); return; }
  if (row.isDerived) { toast('Sync this report to the master table before extracting.', 'warn'); return; }
  if (!row.activityCount) { toast('No activities linked — link activities first.', 'warn'); return; }

  const safeUid = encodeURIComponent(uid);
  const actListHTML = row.activities.map(act => {
    const sections = _extractGroupBySection(act);
    return `
      <label class="ext-act-row">
        <input type="checkbox" name="ext-act" value="${escapeHtml(act.key)}" checked
               onchange="_extractRecalcEstimate('${safeUid}')">
        <div class="ext-act-info">
          <div class="ext-act-name">${escapeHtml(act.activity)}</div>
          <div class="ext-act-meta">${escapeHtml(act.phase)} · ${escapeHtml(act.location)} · ${escapeHtml(act.subsystem)} · ${sections.length} section${sections.length===1?'':'s'} · ${act.items.length} test case${act.items.length===1?'':'s'}</div>
        </div>
        ${_trpStatusSummaryHTML(act.counts)}
      </label>`;
  }).join('');

  const statusBoxes = _EXTRACT_STATUS_KEYS.map(k => `
    <label class="ext-status-chip">
      <input type="checkbox" name="ext-status" value="${k}" checked
             onchange="_extractRecalcEstimate('${safeUid}')">
      <span>${_EXTRACT_STATUS_LABELS[k]}</span>
    </label>
  `).join('');

  modal({
    title: `Extract Test Report — ${escapeHtml(row.title)}`,
    sub: `Rev ${escapeHtml(row.revision || 'A')} · ${row.activityCount} activit${row.activityCount===1?'y':'ies'} · ${row.testCaseCount} test case${row.testCaseCount===1?'':'s'}`,
    size: 'large',
    body: `
      <div class="ext-modal-shell">
        <section class="ext-section">
          <h4 class="ext-section-title">1. Activities to include</h4>
          <p class="ext-section-hint">All test cases inside each selected activity will be summarized. Form PDFs are appended grouped by section.</p>
          <div class="ext-act-list">${actListHTML}</div>
        </section>

        <section class="ext-section">
          <h4 class="ext-section-title">2. Status filter — controls which form PDFs are appended</h4>
          <p class="ext-section-hint">Summary tables always show every test case. These checkboxes only affect which test cases' form PDFs get attached.</p>
          <div class="ext-status-row">${statusBoxes}</div>
        </section>

        <section class="ext-section">
          <h4 class="ext-section-title">3. Punch list</h4>
          <div class="ext-radio-row">
            <label><input type="radio" name="ext-punch" value="open"  checked onchange="_extractRecalcEstimate('${safeUid}')"> Open only</label>
            <label><input type="radio" name="ext-punch" value="all"   onchange="_extractRecalcEstimate('${safeUid}')"> Open + Closed</label>
            <label><input type="radio" name="ext-punch" value="none"  onchange="_extractRecalcEstimate('${safeUid}')"> None</label>
          </div>
        </section>

        <section class="ext-section">
          <h4 class="ext-section-title">4. Output mode</h4>
          <div class="ext-radio-row">
            <label><input type="radio" name="ext-mode" value="single" checked> Single combined PDF</label>
            <label><input type="radio" name="ext-mode" value="zip"> ZIP (numbered files, easy to staple in Acrobat)</label>
          </div>
        </section>

        <div class="ext-estimate" id="ext-estimate-line">Calculating estimate…</div>
        <div class="ext-progress" id="ext-progress" style="display:none;">
          <div class="ext-progress-label" id="ext-progress-label">Preparing…</div>
          <div class="ext-progress-bar"><div class="ext-progress-fill" id="ext-progress-fill" style="width:0%"></div></div>
        </div>
      </div>
    `,
    footer: `
      <button class="form-secondary" id="ext-cancel-btn" onclick="_extractCancel(); closeModal();">Cancel</button>
      <button class="admin-action-btn" id="ext-go-btn" onclick="_extractRun('${safeUid}')">Generate</button>
    `,
  });
  setTimeout(() => _extractRecalcEstimate(safeUid), 30);
}

function _extractReadOpts() {
  return {
    activityKeys: [...document.querySelectorAll('input[name="ext-act"]:checked')].map(el => el.value),
    statusFilter: [...document.querySelectorAll('input[name="ext-status"]:checked')].map(el => el.value),
    punchMode: document.querySelector('input[name="ext-punch"]:checked')?.value || 'open',
    mode: document.querySelector('input[name="ext-mode"]:checked')?.value || 'single',
  };
}

function _extractRecalcEstimate(safeUid) {
  const row = _trpFindReportRow(_trpDecodeUid(safeUid));
  if (!row) return;
  const opts = _extractReadOpts();
  const lineEl = document.getElementById('ext-estimate-line');
  const goBtn = document.getElementById('ext-go-btn');
  if (!opts.activityKeys.length) {
    if (lineEl) lineEl.textContent = 'Select at least one activity.';
    goBtn?.setAttribute('disabled', '');
    return;
  }
  goBtn?.removeAttribute('disabled');
  const payload = _extractBuildPayload(row, opts);
  const sectionCount = payload.activities.reduce((s, a) => s + a.sections.length, 0);
  const summaryPages = 1 + payload.activities.length + sectionCount;
  const estTotal = summaryPages + payload.totalForms * 4;
  const sizeNote = estTotal > 250 ? ' — ZIP mode recommended for this size' : '';
  if (lineEl) lineEl.innerHTML =
    `<b>${payload.activities.length}</b> activit${payload.activities.length===1?'y':'ies'} · ` +
    `<b>${sectionCount}</b> section${sectionCount===1?'':'s'} · ` +
    `<b>${payload.totalForms}</b> form${payload.totalForms===1?'':'s'} to attach · ` +
    `est. <b>~${estTotal}</b> page${estTotal===1?'':'s'}${sizeNote}`;
}

function _extractCancel() {
  if (_extractRunState) _extractRunState.cancelled = true;
}

function _extractSetProgress(label, pct) {
  const wrap = document.getElementById('ext-progress');
  if (wrap) wrap.style.display = '';
  const labelEl = document.getElementById('ext-progress-label');
  const fillEl = document.getElementById('ext-progress-fill');
  if (labelEl) labelEl.textContent = label;
  if (fillEl) fillEl.style.width = `${Math.max(0, Math.min(100, pct))}%`;
}

async function _extractRun(safeUid) {
  if (typeof PDFLib === 'undefined') { toast('pdf-lib not loaded — refresh the page', 'error'); return; }
  const row = _trpFindReportRow(_trpDecodeUid(safeUid));
  if (!row) { toast('Report not found', 'error'); return; }
  const opts = _extractReadOpts();
  if (!opts.activityKeys.length) { toast('Select at least one activity', 'warn'); return; }

  const goBtn = document.getElementById('ext-go-btn');
  if (goBtn) { goBtn.disabled = true; goBtn.textContent = 'Generating…'; }

  _extractRunState = { cancelled: false, doneForms: 0, totalForms: 0 };
  try {
    const payload = _extractBuildPayload(row, opts);
    _extractRunState.totalForms = payload.totalForms;
    let blob, filename;
    if (opts.mode === 'zip') {
      const JSZipCtor = await window._extractEnsureJSZip();
      if (!JSZipCtor) throw new Error('JSZip unavailable');
      ({ blob, filename } = await _extractBuildZip(payload, JSZipCtor));
    } else {
      ({ blob, filename } = await _extractBuildSinglePdf(payload));
    }
    if (_extractRunState.cancelled) { toast('Extract cancelled', 'warn'); return; }
    _extractDownloadBlob(blob, filename);
    try {
      logAudit('Test Report Extract', row.title,
        `${payload.activities.length} activities · ${payload.totalForms} forms · ${opts.mode === 'zip' ? 'ZIP' : 'PDF'}`);
    } catch { /* noop */ }
    toast('✓ Report extracted', 'success');
    closeModal();
  } catch (e) {
    console.error('[extract]', e);
    toast('Extract failed: ' + (e.message || e), 'error');
    if (goBtn) { goBtn.disabled = false; goBtn.textContent = 'Generate'; }
  } finally {
    _extractRunState = null;
  }
}

function _extractDownloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 4000);
}

function _extractFilenameBase(row) {
  return [
    row.cdrl_number || '',
    row.title || 'Test_Report',
    row.revision ? `Rev${row.revision}` : '',
    new Date().toISOString().slice(0, 10),
  ].filter(Boolean).map(p => _extractSlug(p, 60)).join('_');
}

// ── Drawing primitives ─────────────────────────────────────────────────────
function _extractRgb(arr) { return PDFLib.rgb(arr[0], arr[1], arr[2]); }

function _extractWrapText(text, font, size, maxWidth) {
  const safe = String(text == null ? '' : text);
  const words = safe.replace(/\s+/g, ' ').trim().split(' ');
  if (!words.length) return [''];
  const lines = [];
  let cur = '';
  for (const w of words) {
    const candidate = cur ? cur + ' ' + w : w;
    if (font.widthOfTextAtSize(candidate, size) <= maxWidth) {
      cur = candidate;
    } else {
      if (cur) lines.push(cur);
      if (font.widthOfTextAtSize(w, size) > maxWidth) {
        let chunk = '';
        for (const ch of w) {
          if (font.widthOfTextAtSize(chunk + ch, size) <= maxWidth) chunk += ch;
          else { lines.push(chunk); chunk = ch; }
        }
        cur = chunk;
      } else {
        cur = w;
      }
    }
  }
  if (cur) lines.push(cur);
  return lines;
}

function _extractDrawText(page, text, opts) {
  const { x, y, font, size = 10, color = [0.07, 0.09, 0.16], maxWidth, lineHeight = 1.25 } = opts;
  const lines = maxWidth ? _extractWrapText(text, font, size, maxWidth) : [String(text)];
  const lh = size * lineHeight;
  lines.forEach((line, i) => {
    page.drawText(line, { x, y: y - i * lh, size, font, color: _extractRgb(color) });
  });
  return lines.length * lh;
}

function _extractDrawHr(page, x, y, w, color = [0.85, 0.87, 0.91]) {
  page.drawRectangle({ x, y, width: w, height: 0.6, color: _extractRgb(color) });
}

function _extractDrawStatusBadge(page, x, y, key, count, font) {
  const label = `${_EXTRACT_STATUS_LABELS[key]}: ${count}`;
  const size = 9, padX = 6, padY = 3;
  const w = font.widthOfTextAtSize(label, size) + padX * 2;
  const h = size + padY * 2;
  page.drawRectangle({ x, y, width: w, height: h, color: _extractRgb(_EXTRACT_STATUS_COLORS[key]), opacity: 0.12 });
  page.drawText(label, { x: x + padX, y: y + padY, size, font, color: _extractRgb(_EXTRACT_STATUS_COLORS[key]) });
  return w + 6;
}

function _extractDrawTable(page, opts) {
  const { x, y, cols, rows, font, boldFont, fontSize = 9, rowHeight = 18, headerHeight = 22 } = opts;
  const totalW = cols.reduce((s, c) => s + c.width, 0);
  let cy = y;

  page.drawRectangle({ x, y: cy - headerHeight, width: totalW, height: headerHeight, color: _extractRgb([0.93, 0.95, 0.98]) });
  let cx = x;
  cols.forEach(col => {
    page.drawText(String(col.header || ''), {
      x: cx + 5, y: cy - headerHeight + 7, size: fontSize, font: boldFont, color: _extractRgb([0.20, 0.24, 0.32]),
    });
    cx += col.width;
  });
  cy -= headerHeight;
  _extractDrawHr(page, x, cy, totalW, [0.78, 0.82, 0.88]);

  rows.forEach((rowData, idx) => {
    const cellHeights = cols.map(col => {
      const lines = _extractWrapText(String(col.get(rowData) ?? ''), font, fontSize, col.width - 10);
      return lines.length * fontSize * 1.25;
    });
    const thisRowH = Math.max(rowHeight, Math.max(...cellHeights) + 8);
    if (idx % 2 === 1) {
      page.drawRectangle({ x, y: cy - thisRowH, width: totalW, height: thisRowH, color: _extractRgb([0.97, 0.98, 0.99]) });
    }
    let rowCx = x;
    cols.forEach(col => {
      const val = String(col.get(rowData) ?? '');
      const color = col.color ? col.color(rowData) : [0.20, 0.24, 0.32];
      _extractDrawText(page, val, { x: rowCx + 5, y: cy - 13, font, size: fontSize, color, maxWidth: col.width - 10 });
      rowCx += col.width;
    });
    cy -= thisRowH;
    _extractDrawHr(page, x, cy, totalW, [0.92, 0.94, 0.97]);
  });
  return y - cy;
}

function _extractAddPage(doc) {
  return doc.addPage([_EXTRACT_PAGE_W, _EXTRACT_PAGE_H]);
}

// ── Summary / cover / activity / section pages ─────────────────────────────
async function _extractDrawCover(doc, font, boldFont, payload) {
  const { row, overallCounts, activities, punchItems, opts } = payload;
  const page = _extractAddPage(doc);
  const W = _EXTRACT_PAGE_W, M = _EXTRACT_MARGIN;
  let y = _EXTRACT_PAGE_H - M;

  page.drawRectangle({ x: 0, y: y - 4, width: W, height: 4, color: _extractRgb([0.90, 0.10, 0.12]) });
  y -= 30;
  page.drawText('TEST REPORT — EXTRACT', { x: M, y, size: 11, font: boldFont, color: _extractRgb([0.55, 0.58, 0.65]) });
  y -= 28;
  _extractDrawText(page, row.title || 'Untitled Report', { x: M, y, font: boldFont, size: 22, maxWidth: W - M*2 });
  y -= 36;

  const metaPairs = [
    ['CDRL', row.cdrl_number || '—'],
    ['Revision', row.revision || 'A'],
    ['Status', row.status || 'Not Started'],
    ['Subsystem', row.subsystem || (row.subsystems?.join(', ') || '—')],
    ['Phase', row.phase || (row.phases?.join(', ') || '—')],
    ['Location', row.location || (row.locations?.join(', ') || '—')],
  ];
  const mw = (W - M*2) / 3;
  metaPairs.forEach((pair, i) => {
    const col = i % 3, rowI = Math.floor(i / 3);
    const px = M + col * mw;
    const py = y - rowI * 32;
    page.drawText(pair[0].toUpperCase(), { x: px, y: py, size: 8, font: boldFont, color: _extractRgb([0.55, 0.58, 0.65]) });
    _extractDrawText(page, pair[1], { x: px, y: py - 12, font, size: 11, maxWidth: mw - 8 });
  });
  y -= 80;
  _extractDrawHr(page, M, y, W - M*2);
  y -= 22;

  page.drawText('OVERALL STATUS SUMMARY', { x: M, y, size: 10, font: boldFont, color: _extractRgb([0.20, 0.24, 0.32]) });
  y -= 18;
  let bx = M;
  _EXTRACT_STATUS_KEYS.forEach(k => {
    bx += _extractDrawStatusBadge(page, bx, y - 4, k, overallCounts[k] || 0, font);
  });
  page.drawText(`Total: ${overallCounts.total}`, { x: bx + 4, y, size: 10, font: boldFont, color: _extractRgb([0.20, 0.24, 0.32]) });
  y -= 32;

  page.drawText('ACTIVITIES IN THIS REPORT', { x: M, y, size: 10, font: boldFont, color: _extractRgb([0.20, 0.24, 0.32]) });
  y -= 8;
  const actRows = activities.map((a, i) => ({
    n: `${i + 1}.`,
    activity: a.activity,
    meta: `${a.phase} · ${a.location} · ${a.subsystem}`,
    cases: `${a.items.length}`,
    sections: `${a.sections.length}`,
    forms: `${a.formCount}`,
  }));
  _extractDrawTable(page, {
    x: M, y, font, boldFont, fontSize: 9,
    cols: [
      { header: '#',          width: 22,  get: r => r.n },
      { header: 'Activity',   width: 200, get: r => r.activity },
      { header: 'Phase / Location / Subsystem', width: 170, get: r => r.meta },
      { header: 'Sec.',       width: 36,  get: r => r.sections },
      { header: 'Cases',      width: 44,  get: r => r.cases },
      { header: 'Forms',      width: 44,  get: r => r.forms },
    ],
    rows: actRows,
  });

  if (punchItems.length) {
    const pp = _extractAddPage(doc);
    let py = _EXTRACT_PAGE_H - M;
    pp.drawRectangle({ x: 0, y: py - 3, width: W, height: 3, color: _extractRgb([0.90, 0.10, 0.12]) });
    py -= 28;
    pp.drawText('LINKED PUNCH LIST ITEMS', { x: M, y: py, size: 14, font: boldFont, color: _extractRgb([0.07, 0.09, 0.16]) });
    py -= 6;
    pp.drawText(`${punchItems.length} item${punchItems.length===1?'':'s'} — filter: ${opts.punchMode === 'open' ? 'open only' : 'open + closed'}`,
      { x: M, y: py, size: 9, font, color: _extractRgb([0.55, 0.58, 0.65]) });
    py -= 18;
    _extractDrawTable(pp, {
      x: M, y: py, font, boldFont, fontSize: 9,
      cols: [
        { header: '#',        width: 32,  get: p => `#${p.number || ''}` },
        { header: 'Title',    width: 220, get: p => p.title || '—' },
        { header: 'Status',   width: 80,  get: p => (typeof PL_STATUS_LABELS !== 'undefined' && PL_STATUS_LABELS[p.status]) || p.status || '—' },
        { header: 'Priority', width: 60,  get: p => p.priority || '—' },
        { header: 'Linked Tests', width: 124, get: p => {
          const ids = p.linked_test_ids || [];
          const codes = ids.map(id => TI.find(t => String(t.TestID) === String(id))?.TestCaseCode).filter(Boolean);
          return codes.join(', ') || '—';
        } },
      ],
      rows: punchItems,
    });
  }

  page.drawText(`Generated ${payload.generatedAt.toLocaleString()} by ${payload.generatedBy}`,
    { x: M, y: M - 18, size: 8, font, color: _extractRgb([0.55, 0.58, 0.65]) });
}

function _extractDrawActivityPage(doc, font, boldFont, activity, idx) {
  const page = _extractAddPage(doc);
  const W = _EXTRACT_PAGE_W, M = _EXTRACT_MARGIN;
  let y = _EXTRACT_PAGE_H - M;
  page.drawRectangle({ x: 0, y: y - 3, width: W, height: 3, color: _extractRgb([0.13, 0.36, 0.78]) });
  y -= 32;
  page.drawText(`ACTIVITY ${idx + 1}`, { x: M, y, size: 10, font: boldFont, color: _extractRgb([0.55, 0.58, 0.65]) });
  y -= 24;
  _extractDrawText(page, activity.activity, { x: M, y, font: boldFont, size: 20, maxWidth: W - M*2 });
  y -= 30;
  _extractDrawText(page, `${activity.phase} · ${activity.location} · ${activity.subsystem}`,
    { x: M, y, font, size: 11, color: [0.42, 0.45, 0.50], maxWidth: W - M*2 });
  y -= 28;

  page.drawText('ACTIVITY STATUS SUMMARY', { x: M, y, size: 10, font: boldFont, color: _extractRgb([0.20, 0.24, 0.32]) });
  y -= 18;
  let bx = M;
  _EXTRACT_STATUS_KEYS.forEach(k => {
    bx += _extractDrawStatusBadge(page, bx, y - 4, k, activity.counts[k] || 0, font);
  });
  y -= 30;

  page.drawText('SECTIONS', { x: M, y, size: 10, font: boldFont, color: _extractRgb([0.20, 0.24, 0.32]) });
  y -= 8;
  _extractDrawTable(page, {
    x: M, y, font, boldFont, fontSize: 10,
    cols: [
      { header: 'Section',   width: 250, get: s => s.name },
      { header: 'Cases',     width: 60,  get: s => `${s.items.length}` },
      { header: 'P / F / B / IP', width: 110, get: s => `${s.counts.passed} / ${s.counts.failed} / ${s.counts.blocked} / ${s.counts.inProgress}` },
      { header: 'Forms',     width: 96,  get: s => `${s.items.reduce((sum, i) => sum + (i._extractForms?.length || 0), 0)}` },
    ],
    rows: activity.sections,
  });
}

function _extractDrawSectionPage(doc, font, boldFont, activity, section) {
  const page = _extractAddPage(doc);
  const W = _EXTRACT_PAGE_W, M = _EXTRACT_MARGIN;
  let y = _EXTRACT_PAGE_H - M;
  page.drawRectangle({ x: 0, y: y - 3, width: W, height: 3, color: _extractRgb([0.13, 0.55, 0.27]) });
  y -= 28;
  _extractDrawText(page, activity.activity, { x: M, y, font, size: 9, color: [0.55, 0.58, 0.65], maxWidth: W - M*2 });
  y -= 14;
  _extractDrawText(page, section.name, { x: M, y, font: boldFont, size: 18, maxWidth: W - M*2 });
  y -= 28;
  let bx = M;
  _EXTRACT_STATUS_KEYS.forEach(k => {
    bx += _extractDrawStatusBadge(page, bx, y - 4, k, section.counts[k] || 0, font);
  });
  y -= 28;

  _extractDrawTable(page, {
    x: M, y, font, boldFont, fontSize: 9,
    cols: [
      { header: 'Code',         width: 80,  get: r => r.TestCaseCode || '' },
      { header: 'Test Case',    width: 200, get: r => r.TestName || '' },
      { header: 'Status',       width: 70,  get: r => r.Status || '—',
        color: r => _EXTRACT_STATUS_COLORS[_extractStatusKey(r.Status)] || [0.20, 0.24, 0.32] },
      { header: 'Completed By', width: 90,  get: r => r.CompletedBy || '—' },
      { header: 'Date',         width: 60,  get: r => r.CompletedDate ? String(r.CompletedDate).slice(0,10) : '—' },
      { header: 'Forms',        width: 16,  get: r => `${(r._extractForms?.length || 0)}` },
    ],
    rows: section.items,
  });
}

function _extractDrawFormDivider(doc, font, boldFont, formName, parentCode, scopeLabel = '') {
  const page = _extractAddPage(doc);
  const W = _EXTRACT_PAGE_W, M = _EXTRACT_MARGIN;
  let y = _EXTRACT_PAGE_H - M;
  page.drawRectangle({ x: 0, y: y - 2, width: W, height: 2, color: _extractRgb([0.20, 0.24, 0.32]) });
  y -= 32;
  page.drawText('ATTACHED FORM', { x: M, y, size: 9, font: boldFont, color: _extractRgb([0.55, 0.58, 0.65]) });
  y -= 22;
  _extractDrawText(page, formName, { x: M, y, font: boldFont, size: 18, maxWidth: W - M*2 });
  y -= 24;
  if (parentCode) {
    page.drawText(`Linked to test case ${parentCode}`, { x: M, y, size: 11, font, color: _extractRgb([0.42, 0.45, 0.50]) });
    y -= 16;
  }
  if (scopeLabel) {
    page.drawText(`Scope: ${scopeLabel}`, { x: M, y, size: 11, font, color: _extractRgb([0.30, 0.35, 0.50]) });
  }
}

// ── Form bytes (filled when possible, else original) ───────────────────────
async function _extractGetFormBytes(formRow) {
  try {
    const blob = await _buildEditedFormPdfBlob(formRow);
    return new Uint8Array(await blob.arrayBuffer());
  } catch (e) {
    console.warn('[extract] filled build failed, fallback to original:', formRow.name, e.message);
  }
  return await _formsStorage.downloadBytes(formRow.storage_path);
}

async function _extractAppendForm(mainDoc, formRow) {
  const bytes = await _extractGetFormBytes(formRow);
  const srcDoc = await PDFLib.PDFDocument.load(bytes, { ignoreEncryption: true });
  const indices = srcDoc.getPageIndices();
  const copied = await mainDoc.copyPages(srcDoc, indices);
  copied.forEach(p => mainDoc.addPage(p));
  return copied.length;
}

// ── Page-number footers ────────────────────────────────────────────────────
function _extractDrawFooters(doc, font, reportTitle) {
  const pages = doc.getPages();
  const total = pages.length;
  const titleClip = String(reportTitle || '').slice(0, 80);
  pages.forEach((page, i) => {
    const w = page.getWidth();
    page.drawText(titleClip, { x: _EXTRACT_MARGIN, y: 18, size: 8, font, color: _extractRgb([0.55, 0.58, 0.65]) });
    const label = `Page ${i + 1} of ${total}`;
    const labelW = font.widthOfTextAtSize(label, 8);
    page.drawText(label, { x: w - _EXTRACT_MARGIN - labelW, y: 18, size: 8, font, color: _extractRgb([0.55, 0.58, 0.65]) });
  });
}

// ── PDF outline / bookmarks (low-level pdf-lib dict) ───────────────────────
// outlineTree: [{ title, pageIndex, children:[...] }]
function _extractAddOutline(doc, outlineTree) {
  if (!outlineTree?.length) return;
  const { context } = doc;
  const pages = doc.getPages();
  const { PDFName, PDFArray, PDFHexString, PDFNumber } = PDFLib;

  // Allocate refs for each node so we can wire siblings before assigning content
  function allocate(items) {
    return items.map(item => ({
      item,
      ref: context.register(context.obj({})),
      children: allocate(item.children || []),
    }));
  }
  const tree = allocate(outlineTree);
  const countDescendants = nodes => nodes.reduce((n, node) => n + 1 + countDescendants(node.children), 0);

  const rootRef = context.register(context.obj({}));

  function build(nodes, parentRef) {
    nodes.forEach((node, i) => {
      const dict = {};
      dict.Title = PDFHexString.fromText(node.item.title || '');
      dict.Parent = parentRef;
      const pageIdx = Math.max(0, Math.min(pages.length - 1, node.item.pageIndex || 0));
      const page = pages[pageIdx];
      if (page) {
        const dest = PDFArray.withContext(context);
        dest.push(page.ref);
        dest.push(PDFName.of('Fit'));
        dict.Dest = dest;
      }
      if (i > 0) dict.Prev = nodes[i - 1].ref;
      if (i < nodes.length - 1) dict.Next = nodes[i + 1].ref;
      if (node.children.length) {
        dict.First = node.children[0].ref;
        dict.Last  = node.children[node.children.length - 1].ref;
        dict.Count = PDFNumber.of(node.children.length);
      }
      context.assign(node.ref, context.obj(dict));
      build(node.children, node.ref);
    });
  }
  build(tree, rootRef);

  context.assign(rootRef, context.obj({
    Type: PDFName.of('Outlines'),
    First: tree[0].ref,
    Last:  tree[tree.length - 1].ref,
    Count: PDFNumber.of(countDescendants(tree)),
  }));

  doc.catalog.set(PDFName.of('Outlines'), rootRef);
  doc.catalog.set(PDFName.of('PageMode'), PDFName.of('UseOutlines'));
}

// ── Single-PDF mode ────────────────────────────────────────────────────────
async function _extractBuildSinglePdf(payload) {
  const doc = await PDFLib.PDFDocument.create();
  const font = await doc.embedFont(PDFLib.StandardFonts.Helvetica);
  const boldFont = await doc.embedFont(PDFLib.StandardFonts.HelveticaBold);

  doc.setTitle(`${payload.row.title || 'Test Report'} — Extract`);
  doc.setAuthor(payload.generatedBy);
  doc.setSubject(`Test Report Extract · ${payload.row.cdrl_number || ''}`);
  doc.setProducer('CX Portal');
  doc.setCreator('CX Portal Test Report Extract');

  const outline = [];
  const coverNode = { title: 'Overall Summary', pageIndex: 0, children: [] };
  outline.push(coverNode);

  _extractSetProgress('Building summary…', 2);
  await _extractDrawCover(doc, font, boldFont, payload);
  if (payload.punchItems.length) {
    coverNode.children.push({ title: 'Linked Punch Items', pageIndex: doc.getPages().length - 1, children: [] });
  }

  let formsDone = 0;
  for (let ai = 0; ai < payload.activities.length; ai++) {
    if (_extractRunState?.cancelled) throw new Error('Cancelled');
    const act = payload.activities[ai];
    const actPageIdx = doc.getPages().length;
    _extractDrawActivityPage(doc, font, boldFont, act, ai);
    const actNode = { title: `Activity ${ai + 1}: ${act.activity}`, pageIndex: actPageIdx, children: [] };
    outline.push(actNode);

    for (const section of act.sections) {
      if (_extractRunState?.cancelled) throw new Error('Cancelled');
      const secPageIdx = doc.getPages().length;
      _extractDrawSectionPage(doc, font, boldFont, act, section);
      const secNode = { title: section.name, pageIndex: secPageIdx, children: [] };
      actNode.children.push(secNode);

      for (const item of section.items) {
        if (!item._extractInclude) continue;
        for (const entry of (item._extractForms || [])) {
          if (_extractRunState?.cancelled) throw new Error('Cancelled');
          const formRow = entry.form || entry; // tolerate legacy shape
          const scopeLabel = entry.scopeLabel || '';
          formsDone++;
          const pct = 5 + Math.round(85 * (formsDone / Math.max(1, payload.totalForms)));
          _extractSetProgress(`Form ${formsDone} of ${payload.totalForms} — ${formRow.name}`, pct);
          const dividerIdx = doc.getPages().length;
          _extractDrawFormDivider(doc, font, boldFont, formRow.name, item.TestCaseCode, scopeLabel);
          try {
            await _extractAppendForm(doc, formRow);
            secNode.children.push({
              title: `${item.TestCaseCode || ''} — ${formRow.name}${scopeLabel ? '  ('+scopeLabel+')' : ''}`.trim(),
              pageIndex: dividerIdx, children: [],
            });
          } catch (e) {
            console.warn('[extract] form append failed:', formRow.name, e.message);
            secNode.children.push({
              title: `[FAILED] ${formRow.name}`.slice(0, 120),
              pageIndex: dividerIdx, children: [],
            });
          }
        }
      }
    }
  }

  _extractSetProgress('Adding bookmarks + page numbers…', 95);
  _extractDrawFooters(doc, font, payload.row.title);
  try { _extractAddOutline(doc, outline); }
  catch (e) { console.warn('[extract] outline add failed:', e.message); }

  _extractSetProgress('Saving…', 99);
  const bytes = await doc.save({ useObjectStreams: true });
  return {
    blob: new Blob([bytes], { type: 'application/pdf' }),
    filename: `${_extractFilenameBase(payload.row)}.pdf`,
  };
}

// ── ZIP mode ───────────────────────────────────────────────────────────────
async function _extractBuildSummaryOnlyDoc(payload) {
  const doc = await PDFLib.PDFDocument.create();
  const font = await doc.embedFont(PDFLib.StandardFonts.Helvetica);
  const boldFont = await doc.embedFont(PDFLib.StandardFonts.HelveticaBold);
  doc.setTitle(`${payload.row.title || 'Test Report'} — Summary`);

  const outline = [{ title: 'Overall Summary', pageIndex: 0, children: [] }];
  await _extractDrawCover(doc, font, boldFont, payload);
  payload.activities.forEach((act, ai) => {
    const actIdx = doc.getPages().length;
    _extractDrawActivityPage(doc, font, boldFont, act, ai);
    const actNode = { title: `Activity ${ai + 1}: ${act.activity}`, pageIndex: actIdx, children: [] };
    outline.push(actNode);
    act.sections.forEach(sec => {
      const secIdx = doc.getPages().length;
      _extractDrawSectionPage(doc, font, boldFont, act, sec);
      actNode.children.push({ title: sec.name, pageIndex: secIdx, children: [] });
    });
  });
  _extractDrawFooters(doc, font, `${payload.row.title} — Summary`);
  try { _extractAddOutline(doc, outline); } catch { /* noop */ }
  return new Uint8Array(await doc.save({ useObjectStreams: true }));
}

async function _extractBuildActivityDoc(payload, activity, idx) {
  const doc = await PDFLib.PDFDocument.create();
  const font = await doc.embedFont(PDFLib.StandardFonts.Helvetica);
  const boldFont = await doc.embedFont(PDFLib.StandardFonts.HelveticaBold);
  doc.setTitle(`${activity.activity} — Forms`);

  const outline = [];
  _extractDrawActivityPage(doc, font, boldFont, activity, idx);
  const actNode = { title: `Activity ${idx + 1}: ${activity.activity}`, pageIndex: 0, children: [] };
  outline.push(actNode);

  for (const section of activity.sections) {
    if (_extractRunState?.cancelled) throw new Error('Cancelled');
    const secIdx = doc.getPages().length;
    _extractDrawSectionPage(doc, font, boldFont, activity, section);
    const secNode = { title: section.name, pageIndex: secIdx, children: [] };
    actNode.children.push(secNode);

    for (const item of section.items) {
      if (!item._extractInclude) continue;
      for (const entry of (item._extractForms || [])) {
        if (_extractRunState?.cancelled) throw new Error('Cancelled');
        const formRow = entry.form || entry; // tolerate legacy shape
        const scopeLabel = entry.scopeLabel || '';
        if (_extractRunState) _extractRunState.doneForms++;
        const pct = 5 + Math.round(85 * ((_extractRunState?.doneForms || 0) / Math.max(1, payload.totalForms)));
        _extractSetProgress(`Form ${_extractRunState?.doneForms} of ${payload.totalForms} — ${formRow.name}`, pct);
        const divIdx = doc.getPages().length;
        _extractDrawFormDivider(doc, font, boldFont, formRow.name, item.TestCaseCode, scopeLabel);
        try {
          await _extractAppendForm(doc, formRow);
          secNode.children.push({
            title: `${item.TestCaseCode || ''} — ${formRow.name}${scopeLabel ? '  ('+scopeLabel+')' : ''}`.trim(),
            pageIndex: divIdx, children: [],
          });
        } catch (e) {
          secNode.children.push({
            title: `[FAILED] ${formRow.name}`.slice(0, 120),
            pageIndex: divIdx, children: [],
          });
        }
      }
    }
  }
  _extractDrawFooters(doc, font, `${payload.row.title} — ${activity.activity}`);
  try { _extractAddOutline(doc, outline); } catch { /* noop */ }
  return new Uint8Array(await doc.save({ useObjectStreams: true }));
}

async function _extractBuildZip(payload, JSZipCtor) {
  const zip = new JSZipCtor();
  const baseName = _extractFilenameBase(payload.row);

  _extractSetProgress('Building summary…', 3);
  zip.file('00_Summary.pdf', await _extractBuildSummaryOnlyDoc(payload));

  if (_extractRunState) _extractRunState.doneForms = 0;
  for (let ai = 0; ai < payload.activities.length; ai++) {
    if (_extractRunState?.cancelled) throw new Error('Cancelled');
    const act = payload.activities[ai];
    const num = String(ai + 1).padStart(2, '0');
    const slug = _extractSlug(act.activity, 50);
    zip.file(`${num}_${slug}.pdf`, await _extractBuildActivityDoc(payload, act, ai));
  }

  zip.file('README.txt',
`TEST REPORT EXTRACT — ZIP BUNDLE
==================================

Report:    ${payload.row.title}
CDRL:      ${payload.row.cdrl_number || '—'}
Revision:  ${payload.row.revision || 'A'}
Generated: ${payload.generatedAt.toLocaleString()} by ${payload.generatedBy}

CONTENTS
--------
00_Summary.pdf       Overall summary, activity index, and section summaries.
01_<Activity>.pdf    Activity 1 — full content (sections + form attachments).
02_<Activity>.pdf    Activity 2 — and so on.

The numeric prefixes preserve order. To produce a single stapled PDF for
client submission:

  Adobe Acrobat:   File → Combine Files → drag the PDFs in numeric order.
  PDFsam (free):   Open PDFsam → Merge → add files → start.
  macOS Preview:   Drag thumbnails of all files into one window in order, then File → Export as PDF.

Each PDF in this bundle has its own bookmark outline for fast navigation.
`);

  _extractSetProgress('Compressing ZIP…', 95);
  const blob = await zip.generateAsync({ type: 'blob', compression: 'DEFLATE', compressionOptions: { level: 5 } });
  return { blob, filename: `${baseName}.zip` };
}

// ╔════════════════════════════════════════════════════════════════════════╗
// ║  DRAWINGS MODULE                                                        ║
// ║  Tables: drawing_sets, drawing_sheets, drawing_markups                  ║
// ║  Schema: see supabase_drawings_schema.sql                               ║
// ╚════════════════════════════════════════════════════════════════════════╝

// ── Globals ───────────────────────────────────────────────────────────────
let DRAWING_SETS    = [];
let DRAWING_SHEETS  = [];
let DRAWING_MARKUPS = [];

// ── Storage helper ────────────────────────────────────────────────────────
const _drawStorage = {
  bucket: 'drawings',
  _url(path) {
    const clean = String(path || '').split('/').map(encodeURIComponent).join('/');
    return `${SUPABASE_URL}/storage/v1/object/${this.bucket}/${clean}`;
  },
  _hdrs(extra = {}) {
    return { apikey: SUPABASE_ANON_KEY, Authorization: _getAuthHeader(), ...extra };
  },
  async upload(path, file) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 120000);
    try {
      const res = await fetch(this._url(path), {
        method: 'POST', signal: ctrl.signal,
        headers: this._hdrs({ 'Content-Type': 'application/pdf', 'x-upsert': 'true' }),
        body: file,
      });
      clearTimeout(timer);
      if (!res.ok) throw new Error(`Upload failed (${res.status}): ${await res.text()}`);
      return path;
    } catch(e) { clearTimeout(timer); throw e; }
  },
  async downloadBytes(path) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 60000);
    try {
      const res = await fetch(this._url(path) + `?t=${Date.now()}`, {
        method: 'GET', signal: ctrl.signal,
        headers: this._hdrs({ Accept: 'application/pdf', 'Cache-Control': 'no-cache' }),
      });
      clearTimeout(timer);
      if (!res.ok) throw new Error(`Download failed (${res.status})`);
      return new Uint8Array(await res.arrayBuffer());
    } catch(e) { clearTimeout(timer); throw e; }
  },
};

// ── Data loader ────────────────────────────────────────────────────────────
async function loadDrawingsData() {
  try {
    const [sets, sheets, markups] = await Promise.all([
      _fetchAnon('drawing_sets?select=*&order=created_at.desc'),
      _fetchAnon('drawing_sheets?select=*&order=sheet_number.asc'),
      _fetchAnon('drawing_markups?select=*&order=created_at.desc'),
    ]);
    DRAWING_SETS    = sets    || [];
    DRAWING_SHEETS  = sheets  || [];
    DRAWING_MARKUPS = markups || [];
  } catch(e) { console.warn('[loadDrawingsData]', e.message); }
}

// ── Discipline detection ───────────────────────────────────────────────────
function _drwDiscipline(sheetNum) {
  if (!sheetNum) return 'General';
  const prefix = (sheetNum.match(/^([A-Z]+)/i) || [])[1]?.toUpperCase() || '';
  const map = { C:'Civil', E:'Electrical', G:'General', IN:'Index', I:'Index',
                TC:'Train Control', T:'Train Control', M:'Mechanical',
                P:'Plumbing', S:'Structural', A:'Architectural', L:'Landscape',
                FP:'Fire Protection', FS:'Fire & Safety' };
  return map[prefix] || prefix || 'General';
}

function _drwDisciplineOptions() {
  const opts = [
    ..._fsOptions('drawing_discipline'),
    ...DRAWING_SHEETS.map(s => s.discipline).filter(Boolean),
  ];
  const seen = new Set();
  return opts
    .map(v => String(v || '').trim())
    .filter(v => {
      if (!v) return false;
      const key = v.toLowerCase();
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }));
}

function _drwDisciplineListHTML() {
  return `<datalist id="drw-discipline-options">
    ${_drwDisciplineOptions().map(d => `<option value="${escapeHtml(d)}"></option>`).join('')}
  </datalist>`;
}

// ── PDF text parsing ───────────────────────────────────────────────────────
// Title-block field labels we must NOT confuse for values.
const _DRW_LABELS = [
  /^contract\s*sheet\s*no\.?$/i,
  /^sheet\s*no\.?(\s*of\s*\d+)?$/i,
  /^page\s*no\.?$/i,
  /^pg\.?\s*no\.?$/i,
  /^dwg\.?\s*no\.?$/i,
  /^drawing\s*no\.?$/i,
  /^drawing\s*number$/i,
  /^drawing\s*title$/i,
  /^rev\.?(ision)?$/i,
  /^revisions?$/i,
  /^scale$/i,
  /^size$/i,
  /^date$/i,
  /^drawn\s*by$/i,
  /^designed\s*by$/i,
  /^approved\s*by$/i,
  /^checked\s*by$/i,
  /^title$/i,
  /^sheet$/i,
  /^of$/i,
  /^cadd\s*filename:?$/i,
  /^filename:?$/i,
  /^nts$/i,
  /^n\.t\.s\.?$/i,
  /^project$/i,
  /^description$/i,
  /^bart$/i,
  /^contract\s*no\.?$/i,
  /^contract$/i,
];

// Project-banner text that appears on every sheet — should NEVER be picked as a title.
// Match by characteristic keywords so spelling variants ("COMMUNICATIONS" vs
// "COMMINICATIONS") and line splits don't matter.
const _DRW_BANNER_PATTERNS = [
  /design[\s-]+build/i,
  /\bCBTC\b/,
  /communications?\s+based\s+train\s+control/i,
  /train\s+control\s+\(?CBTC/i,
  /\bBART\b.*(contract|project)/i,
];

// Sheet-number formats — checked in order from most specific to least.
//   E11004-W30-001     long form with page suffix
//   E11004-W30         2-segment contract sheet no.
//   496H-110           mixed alpha/digit prefix
//   E-1001 / E101      legacy short form
const _DRW_SHEET_PATTERNS = [
  /^[A-Z]{1,4}\d{2,}-[A-Z0-9]+-\d+[A-Z]?$/i,   // E11004-W30-001
  /^[A-Z]{1,4}\d{2,}-[A-Z0-9]+$/i,             // E11004-W30
  /^\d+[A-Z]+-\d+[A-Z]?$/i,                      // 496H-110
  /^[A-Z]{1,4}-\d+[A-Z]?$/i,                     // E-1001
  /^[A-Z]{1,3}\d{1,4}[A-Z]?$/i,                  // E101, M22A
];

const _DRW_FILENAME_RE = /([A-Z]{1,4}\d{2,}-[A-Z0-9]+(?:-\d+[A-Z]?)?)/i;

function _drwIsLabel(s) {
  const t = s.replace(/\s+/g, ' ').trim();
  return _DRW_LABELS.some(re => re.test(t));
}

function _drwIsBanner(s) {
  return _DRW_BANNER_PATTERNS.some(re => re.test(s));
}

function _drwMatchSheetNum(s) {
  const t = s.trim();
  return _DRW_SHEET_PATTERNS.some(re => re.test(t));
}

function _drwBuildCells(items, W, H, region) {
  let pdfXMin = 0, pdfXMax = W, pdfYMin = 0, pdfYMax = H * 0.3;
  if (region && region.fw > 0.01 && region.fh > 0.01) {
    pdfYMax = H * (1 - region.fy);
    pdfYMin = H * (1 - region.fy - region.fh);
    pdfXMin = W * region.fx;
    pdfXMax = W * (region.fx + region.fw);
  }
  // Small tolerance so text items on the exact region boundary aren't excluded
  // due to float rounding (the difference between (1-fy-fh)*H and the original
  // boundary can be ~1e-13 even when they're conceptually identical).
  const EPS = 1;
  return items
    .map(it => {
      const x = it.transform[4], y = it.transform[5];
      return { x, y, w: it.width || 0, h: it.height || 10, str: (it.str || '').trim() };
    })
    .filter(c => c.str
      && c.x >= pdfXMin - EPS && c.x <= pdfXMax + EPS
      && c.y >= pdfYMin - EPS && c.y <= pdfYMax + EPS);
}

// Label-anchored value extraction: find the cell matching labelRe, then return the
// closest non-label cell that satisfies valueOk, preferring cells directly below
// or directly to the right of the label (the two standard title-block layouts).
function _drwFindNearLabel(cells, labelRe, valueOk = (() => true), opts = {}) {
  const { maxDist = 120 } = opts;
  const label = cells.find(c => labelRe.test(c.str));
  if (!label) return null;
  const cands = cells
    .filter(c => c !== label && !_drwIsLabel(c.str) && c.str !== label.str)
    .filter(c => valueOk(c.str))
    .map(c => {
      // PDF coords: y increases upward, so "below the label" means c.y < label.y.
      const below = label.y - c.y;     // positive when c is below
      const right = c.x - label.x;     // positive when c is to the right
      const vertical   = below > 0 && below < 40 && Math.abs(right) < 120;
      const horizontal = Math.abs(below) < 14 && right > 0 && right < 140;
      if (vertical)   return { c, dist: below + Math.abs(right) * 0.4 };
      if (horizontal) return { c, dist: right + Math.abs(below) * 0.4 };
      return { c, dist: Math.hypot(below, right) * 3 };
    })
    .filter(o => o.dist < maxDist)
    .sort((a, b) => a.dist - b.dist);
  return cands.length ? cands[0].c.str.trim() : null;
}

function _drwParseSheetInfo(items, W, H, region) {
  const cells = _drwBuildCells(items, W, H, region);
  if (!cells.length) {
    return { sheetNumber: null, sheetTitle: null, revision: null, pageNumber: null, discipline: 'General' };
  }

  // ── Sheet number (label-anchored first, pattern fallback) ────────────────
  let sheetNumber = _drwFindNearLabel(cells,
    /^contract\s*sheet\s*no\.?$/i,
    s => _drwMatchSheetNum(s),
  );
  if (!sheetNumber) {
    sheetNumber = _drwFindNearLabel(cells,
      /^(sheet|dwg|drawing)\s*no\.?$/i,
      s => _drwMatchSheetNum(s),
    );
  }
  // Pure pattern match — but exclude the cell adjacent to "CONTRACT NO." (which is
  // a project-level contract number, not a sheet number).
  if (!sheetNumber) {
    const contractNoVal = _drwFindNearLabel(cells, /^contract\s*no\.?$/i, () => true);
    for (const c of cells) {
      if (c.str === contractNoVal) continue;
      if (_drwMatchSheetNum(c.str) && !_drwIsLabel(c.str)) { sheetNumber = c.str.toUpperCase(); break; }
    }
  }
  // Fallback: pull from CADD FILENAME.
  if (!sheetNumber) {
    for (const c of cells) {
      if (/\.(dgn|dwg|pdf)\b/i.test(c.str)) {
        const m = c.str.match(_DRW_FILENAME_RE);
        if (m) { sheetNumber = m[1].toUpperCase(); break; }
      }
    }
  }
  if (sheetNumber) sheetNumber = sheetNumber.toUpperCase();

  // ── Page number ──────────────────────────────────────────────────────────
  // Always label-anchored — page numbers are bare digits that would match
  // anything if we pattern-matched alone.
  const pageNumber = _drwFindNearLabel(cells,
    /^(page|pg)\s*no\.?$/i,
    s => /^\d{1,4}[A-Z]?$/i.test(s) && s !== sheetNumber,
  );

  // ── Revision ─────────────────────────────────────────────────────────────
  let revision = _drwFindNearLabel(cells,
    /^rev\.?(ision)?$/i,
    s => /^[A-Z0-9]{1,3}$/i.test(s)
      && !/^(OF|NO|TO|NTS)$/i.test(s)
      && s !== (sheetNumber || '').slice(-1)
      && s !== pageNumber,
  );
  // Inline form: "REV. A" or "REV: 2" all in one text item.
  if (!revision) {
    for (const c of cells) {
      const m = c.str.match(/^rev\.?(?:ision)?[:.\s]+([A-Z0-9]{1,3})$/i);
      if (m) { revision = m[1]; break; }
    }
  }
  if (revision) revision = revision.toUpperCase();

  // ── Title ────────────────────────────────────────────────────────────────
  // Strip project banner, labels, sheet/rev/page/contract values, dates, filenames.
  const contractNo = _drwFindNearLabel(cells, /^contract\s*no\.?$/i, () => true);
  const knownValues = new Set([sheetNumber, revision, pageNumber, contractNo].filter(Boolean).map(s => s.toString().toUpperCase()));
  const titleCandidates = cells.filter(c => {
    const s = c.str;
    if (s.length < 4) return false;
    if (_drwIsLabel(s)) return false;
    if (_drwIsBanner(s)) return false;
    if (knownValues.has(s.toUpperCase())) return false;
    if (/^\d+$/.test(s)) return false;
    if (/^\d{1,2}[\/\-.]\d{1,2}[\/\-.]\d{2,4}$/.test(s)) return false;   // dates
    if (/\.(dgn|dwg|pdf)\b/i.test(s)) return false;
    if (_drwMatchSheetNum(s)) return false;
    return true;
  });
  let sheetTitle = null;
  if (titleCandidates.length) {
    // Prefer cells in the upper portion of the region (drawing titles sit
    // above the sheet-number / rev block in a typical title block).
    const ySorted = [...titleCandidates].sort((a, b) => b.y - a.y); // higher y = upper
    const upper   = ySorted.slice(0, Math.max(3, Math.ceil(ySorted.length / 2)));
    const pool    = upper.length ? upper : titleCandidates;
    sheetTitle    = pool.reduce((a, b) => b.str.length > a.str.length ? b : a).str;
  }

  return { sheetNumber, sheetTitle, revision, pageNumber, discipline: _drwDiscipline(sheetNumber) };
}

// ── Page render ────────────────────────────────────────────────────────────
function renderDrawingsPage() {
  const hero = document.getElementById('drawings-hero-content');
  const cont = document.getElementById('drawings-content');
  if (!hero || !cont) return;

  const isAdmin = currentRoleUser?.role === 'admin';

  hero.innerHTML = `
    <div class="page-hero-inner">
      <div class="role-badge" style="background:rgba(99,102,241,0.15);color:#6366f1;border:1px solid rgba(99,102,241,0.3);">Drawings</div>
      <h1 class="page-hero-title">Drawing Sets</h1>
      <p class="page-hero-sub">Site plan books, drawing sets, and markup tools by location.</p>
    </div>`;

  // Get unique locations that have drawings, plus any project locations
  const drwLocs = [...new Set(DRAWING_SETS.map(s => s.location).filter(Boolean))].sort();
  const projLocs = [...new Set(TI.map(r => r.Location).filter(Boolean))].sort();
  const allLocs  = [...new Set([...drwLocs, ...projLocs])].sort();

  if (!allLocs.length && !isAdmin) {
    cont.innerHTML = `<div class="docs-empty"><h3>No drawings yet</h3><p>An admin needs to upload drawing sets first.</p></div>`;
    return;
  }

  const uploadBtn = isAdmin ? `
    <button class="admin-action-btn" onclick="_drwOpenUpload()" style="background:#6366f1;color:#fff;border:none;padding:8px 18px;border-radius:7px;cursor:pointer;font-size:13px;font-weight:600;">
      + Upload Drawing Set
    </button>` : '';

  const locTabs = allLocs.map((loc, i) => `
    <button class="drw-loc-tab ${i === 0 ? 'active' : ''}" onclick="_drwSelectLocation('${escapeHtml(loc)}')" id="drw-loc-tab-${CSS.escape(loc)}">
      ${escapeHtml(loc)}
      <span class="drw-loc-badge">${DRAWING_SHEETS.filter(s => s.location === loc && s.is_current).length}</span>
    </button>`).join('');

  cont.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;">
      <div class="drw-loc-tabs" id="drw-loc-tabs">${locTabs}</div>
      ${uploadBtn}
    </div>
    <div id="drw-location-view"></div>`;

  if (allLocs.length) _drwSelectLocation(allLocs[0]);
}

function _drwSelectLocation(loc) {
  document.querySelectorAll('.drw-loc-tab').forEach(el => el.classList.remove('active'));
  const tab = document.getElementById(`drw-loc-tab-${CSS.escape(loc)}`);
  if (tab) tab.classList.add('active');
  _drwRenderLocationView(loc, 'current');
}

function _drwRenderLocationView(loc, activeSubtab = 'current') {
  const el = document.getElementById('drw-location-view');
  if (!el) return;
  const tabs = [
    { id: 'current', label: 'Current Drawings' },
    { id: 'sets',    label: 'Drawing Sets' },
    { id: 'history', label: 'Revision History' },
  ];
  el.innerHTML = `
    <div class="drw-subtabs" id="drw-subtabs">
      ${tabs.map(t => `
        <button class="drw-subtab ${t.id === activeSubtab ? 'active' : ''}"
          onclick="_drwRenderLocationView('${escapeHtml(loc)}','${t.id}')">
          ${t.label}
        </button>`).join('')}
    </div>
    <div id="drw-subtab-content" style="margin-top:16px;"></div>`;

  const content = document.getElementById('drw-subtab-content');
  if (activeSubtab === 'current') _drwTabCurrent(loc, content);
  if (activeSubtab === 'sets')    _drwTabSets(loc, content);
  if (activeSubtab === 'history') _drwTabHistory(loc, content);
}

// ── Tab 1: Current Drawings ────────────────────────────────────────────────
function _drwTabCurrent(loc, el) {
  const sheets = DRAWING_SHEETS.filter(s => s.location === loc && s.is_current && s.confirmed);
  if (!sheets.length) {
    el.innerHTML = `<div class="docs-empty"><p>No confirmed drawings for this location yet.</p></div>`;
    return;
  }
  const byDisc = {};
  sheets.forEach(s => {
    const d = s.discipline || 'General';
    if (!byDisc[d]) byDisc[d] = [];
    byDisc[d].push(s);
  });
  el.innerHTML = Object.entries(byDisc).sort(([a],[b]) => a.localeCompare(b)).map(([disc, list]) => `
    <div class="drw-disc-section">
      <div class="drw-disc-header">${escapeHtml(disc)}</div>
      <div class="drw-sheet-grid">
        ${list.sort((a,b) => (a.sheet_number||'').localeCompare(b.sheet_number||'')).map(s => _drwSheetCard(s)).join('')}
      </div>
    </div>`).join('');
}

// ── Tab 2: Drawing Sets ────────────────────────────────────────────────────
function _drwTabSets(loc, el) {
  const sets = DRAWING_SETS.filter(s => s.location === loc && s.status === 'ready');
  if (!sets.length) {
    el.innerHTML = `<div class="docs-empty"><p>No drawing sets uploaded for this location yet.</p></div>`;
    return;
  }
  el.innerHTML = sets.map(set => {
    const sheets = DRAWING_SHEETS.filter(s => s.set_id === set.id && s.confirmed);
    const byDisc = {};
    sheets.forEach(s => {
      const d = s.discipline || 'General';
      if (!byDisc[d]) byDisc[d] = [];
      byDisc[d].push(s);
    });
    const discHtml = Object.entries(byDisc).sort(([a],[b])=>a.localeCompare(b)).map(([disc, list]) => `
      <div class="drw-disc-section" style="margin-top:12px;">
        <div class="drw-disc-header" style="font-size:12px;">${escapeHtml(disc)} (${list.length})</div>
        <div class="drw-sheet-grid">
          ${list.sort((a,b) => (a.sheet_number||'').localeCompare(b.sheet_number||'')).map(s => _drwSheetCard(s)).join('')}
        </div>
      </div>`).join('');
    return `
      <div class="data-card" style="margin-bottom:16px;">
        <div style="display:flex;align-items:center;gap:12px;margin-bottom:8px;">
          <div>
            <div style="font-weight:700;font-size:14px;">${escapeHtml(set.title)}</div>
            <div style="font-size:12px;color:var(--gray-500);">
              ${set.revision_date ? `Rev date: ${set.revision_date}` : ''}
              ${set.release_date  ? ` · Released: ${set.release_date}` : ''}
              · ${sheets.length} sheets
            </div>
          </div>
        </div>
        ${discHtml || '<p style="color:var(--gray-400);font-size:12px;">No confirmed sheets yet.</p>'}
      </div>`;
  }).join('');
}

// ── Tab 3: Revision History ────────────────────────────────────────────────
function _drwTabHistory(loc, el) {
  const sets = DRAWING_SETS.filter(s => s.location === loc).sort((a,b) => b.created_at.localeCompare(a.created_at));
  if (!sets.length) {
    el.innerHTML = `<div class="docs-empty"><p>No upload history for this location.</p></div>`;
    return;
  }
  el.innerHTML = `
    <div class="data-card" style="padding:0;overflow:hidden;">
      <table class="data-table">
        <thead><tr>
          <th>Title</th><th>Sheets</th><th>Import Date</th><th>Rev Date</th><th>Release Date</th><th>Uploaded By</th><th>Status</th>
        </tr></thead>
        <tbody>${sets.map(set => {
          const sheetCount = DRAWING_SHEETS.filter(s => s.set_id === set.id).length;
          const statusColor = set.status === 'ready' ? 'var(--good)' : set.status === 'error' ? 'var(--bad)' : 'var(--warn)';
          return `<tr>
            <td style="font-weight:600;">${escapeHtml(set.title)}</td>
            <td>${sheetCount}</td>
            <td style="font-size:12px;">${set.import_date || '—'}</td>
            <td style="font-size:12px;">${set.revision_date || '—'}</td>
            <td style="font-size:12px;">${set.release_date || '—'}</td>
            <td style="font-size:12px;">${escapeHtml(set.uploaded_by || '—')}</td>
            <td><span style="color:${statusColor};font-weight:600;font-size:12px;text-transform:capitalize;">${set.status}</span></td>
          </tr>`;
        }).join('')}</tbody>
      </table>
    </div>`;
}

function _drwSheetCard(sheet) {
  const markups = DRAWING_MARKUPS.filter(m => m.sheet_id === sheet.id);
  const pubCount = markups.filter(m => m.is_published).length;
  return `
    <div class="drw-sheet-card" onclick="_drwOpenSheet('${sheet.id}','${sheet.set_id}',${sheet.page_index})" title="Open ${escapeHtml(sheet.sheet_number||'Sheet')}">
      <div class="drw-sheet-num">${escapeHtml(sheet.sheet_number || '—')}</div>
      <div class="drw-sheet-title">${escapeHtml(sheet.sheet_title || 'Untitled')}</div>
      <div class="drw-sheet-meta">
        ${sheet.revision ? `<span class="drw-rev-badge">Rev ${escapeHtml(sheet.revision)}</span>` : ''}
        ${pubCount ? `<span class="drw-markup-badge">${pubCount} markup${pubCount>1?'s':''}</span>` : ''}
      </div>
    </div>`;
}

// ── Upload Flow ────────────────────────────────────────────────────────────
let _drwUploadMeta    = null;
let _drwParsedSheets  = [];
let _drwUploadPdfDoc  = null;
let _drwTitleRegion   = null;
let _drwCalSel        = { active: false, x0:0, y0:0, x1:0, y1:0 };
let _drwCalPage       = 1;
let _drwCalRendering  = false;

function _drwRegionKey(loc) { return `drw_tb_${loc}`; }
function _drwLoadRegion(loc) { try { return JSON.parse(localStorage.getItem(_drwRegionKey(loc))); } catch { return null; } }
function _drwSaveRegion(loc, r) { localStorage.setItem(_drwRegionKey(loc), JSON.stringify(r)); }

function _drwCloseUpload() {
  closeModal();
  _drwUploadMeta = null; _drwParsedSheets = []; _drwUploadPdfDoc = null; _drwTitleRegion = null;
  _drwCalPage = 1; _drwCalRendering = false;
}

function _drwOpenUpload() {
  const locs    = [...new Set([...DRAWING_SETS.map(s=>s.location), ...TI.map(r=>r.Location)].filter(Boolean))].sort();
  const locOpts = locs.map(l => `<option value="${escapeHtml(l)}">${escapeHtml(l)}</option>`).join('');
  const today   = new Date().toISOString().slice(0,10);

  modal({
    title: 'Upload Drawing Set',
    sub:   'Import a multi-page PDF book of plans',
    body: `
      <div class="form-group">
        <label class="form-label">Document Title *</label>
        <input id="drw-title" class="form-input" placeholder="e.g. W40 Electrical Plans Rev B" />
      </div>
      <div class="form-group">
        <label class="form-label">Location *</label>
        <select id="drw-location" class="form-input">
          <option value="">Select location…</option>${locOpts}
        </select>
        <p style="font-size:11px;color:var(--gray-500);margin:4px 0 0;">
          Discipline is auto-detected per sheet from the sheet-number prefix (e.g. <strong>E</strong>→Electrical, <strong>C</strong>→Civil, <strong>S</strong>→Structural).
        </p>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;">
        <div class="form-group">
          <label class="form-label">Import Date</label>
          <input id="drw-import-date" class="form-input" type="date" value="${today}" />
        </div>
        <div class="form-group">
          <label class="form-label">Revision Date</label>
          <input id="drw-rev-date" class="form-input" type="date" />
        </div>
        <div class="form-group">
          <label class="form-label">Release Date</label>
          <input id="drw-rel-date" class="form-input" type="date" />
        </div>
      </div>
      <div class="form-group">
        <label class="form-label">PDF File *</label>
        <div id="drw-drop-zone" class="drw-drop-zone">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" style="width:36px;height:36px;color:var(--gray-400);margin-bottom:8px;"><path stroke-linecap="round" stroke-linejoin="round" d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m6.75 12l-3-3m0 0l-3 3m3-3v6m-1.5-15H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z"/></svg>
          <p style="color:var(--gray-500);font-size:13px;margin:0;">Drop PDF here or <label for="drw-file-input" style="color:var(--hitachi-red);cursor:pointer;font-weight:600;">browse</label></p>
          <p id="drw-file-name" style="color:var(--gray-600);font-size:12px;margin-top:4px;font-weight:600;"></p>
          <input id="drw-file-input" type="file" accept="application/pdf" style="display:none;" onchange="_drwFileChosen(this)" />
        </div>
      </div>
      <div id="drw-upload-err" style="color:var(--bad);font-size:12px;margin-top:4px;display:none;"></div>`,
    footer: `
      <button class="admin-action-btn-secondary" onclick="_drwCloseUpload()">Cancel</button>
      <button class="admin-action-btn" onclick="_drwStep1Next()">Next: Calibrate →</button>`,
  });

  const zone = document.getElementById('drw-drop-zone');
  zone.addEventListener('dragover',  e => { e.preventDefault(); zone.style.borderColor='var(--hitachi-red)'; });
  zone.addEventListener('dragleave', () => { zone.style.borderColor=''; });
  zone.addEventListener('drop', e => {
    e.preventDefault(); zone.style.borderColor='';
    const f = e.dataTransfer.files[0];
    if (f && f.type === 'application/pdf') { document.getElementById('drw-file-name').textContent = f.name; zone._file = f; }
  });
}

function _drwFileChosen(inp) {
  const f = inp.files[0];
  if (f) { document.getElementById('drw-file-name').textContent = f.name; document.getElementById('drw-drop-zone')._file = f; }
}

async function _drwStep1Next() {
  const title   = document.getElementById('drw-title')?.value.trim();
  const loc     = document.getElementById('drw-location')?.value;
  const impDate = document.getElementById('drw-import-date')?.value;
  const revDate = document.getElementById('drw-rev-date')?.value;
  const relDate = document.getElementById('drw-rel-date')?.value;
  const file    = document.getElementById('drw-drop-zone')?._file || document.getElementById('drw-file-input')?.files[0];
  const errEl   = document.getElementById('drw-upload-err');

  if (!title) { errEl.textContent = 'Document title is required.'; errEl.style.display='block'; return; }
  if (!loc)   { errEl.textContent = 'Location is required.';       errEl.style.display='block'; return; }
  if (!file)  { errEl.textContent = 'Please select a PDF file.';   errEl.style.display='block'; return; }

  _drwUploadMeta = { title, location: loc, import_date: impDate, revision_date: revDate, release_date: relDate, file };

  document.querySelector('#modal-overlay .modal-body').innerHTML = `
    <div style="text-align:center;padding:40px 20px;">
      <div class="spinner" style="margin:0 auto 16px;"></div>
      <p style="color:var(--gray-500);">Loading PDF…</p>
    </div>`;
  document.querySelector('#modal-overlay .modal-footer').innerHTML = '';

  try {
    if (typeof pdfjsLib === 'undefined') throw new Error('PDF.js not loaded');
    if (!pdfjsLib.GlobalWorkerOptions.workerSrc)
      pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/legacy/build/pdf.worker.min.js';
    _drwUploadPdfDoc = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
    await _drwShowCalibrate();
  } catch(e) {
    document.querySelector('#modal-overlay .modal-body').innerHTML = `<p style="color:var(--bad);padding:20px;">${escapeHtml(e.message)}</p>`;
    document.querySelector('#modal-overlay .modal-footer').innerHTML = `<button class="admin-action-btn-secondary" onclick="_drwCloseUpload()">Close</button>`;
  }
}

async function _drwShowCalibrate() {
  const loc        = _drwUploadMeta.location;
  const savedRegion = _drwLoadRegion(loc);
  const numPages   = _drwUploadPdfDoc.numPages;
  _drwCalPage = Math.min(Math.max(1, _drwCalPage || 1), numPages);

  // Switch to extra-large modal — fills most of the viewport so the PDF is readable
  const modalEl = document.querySelector('#modal-overlay .modal');
  modalEl.className = 'modal modal-large';
  modalEl.style.maxWidth  = '98vw';
  modalEl.style.width     = '98vw';
  modalEl.style.maxHeight = '95vh';
  document.querySelector('#modal-overlay .modal-head .modal-title').textContent = 'Calibrate Title Block';
  const subEl = document.querySelector('#modal-overlay .modal-head .modal-sub');
  if (subEl) subEl.textContent = 'Navigate to a sheet with a normal title block, then drag a box over the title block. The region applies to every page.';

  document.querySelector('#modal-overlay .modal-body').innerHTML = `
    <div style="display:flex;gap:16px;align-items:flex-start;">
      <div style="flex:1;min-width:0;">
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:10px;flex-wrap:wrap;">
          <button class="admin-action-btn-secondary" id="drw-cal-prev" style="padding:6px 12px;font-size:13px;">◀ Prev</button>
          <span style="font-size:13px;color:var(--gray-700);">Page</span>
          <input id="drw-cal-page-input" type="number" min="1" max="${numPages}" value="${_drwCalPage}"
                 style="width:64px;padding:5px 8px;border:1px solid var(--gray-300);border-radius:6px;font-size:13px;text-align:center;" />
          <span style="font-size:13px;color:var(--gray-500);">of ${numPages}</span>
          <button class="admin-action-btn-secondary" id="drw-cal-next" style="padding:6px 12px;font-size:13px;">Next ▶</button>
          <span style="flex:1;"></span>
          <span style="font-size:12px;color:var(--gray-500);">
            ${savedRegion
              ? `<span style="color:var(--good);font-weight:600;">✓ Saved region for ${escapeHtml(loc)}</span> — redraw to change, or Extract to use as-is.`
              : `Skip past cover pages — pick a sheet with a real title block.`}
          </span>
        </div>
        <div id="drw-cal-stage" style="position:relative;background:var(--gray-100);border:1px solid var(--gray-200);border-radius:6px;overflow:hidden;display:flex;align-items:center;justify-content:center;min-height:300px;">
          <canvas id="drw-cal-pdf" style="display:block;"></canvas>
          <canvas id="drw-cal-sel" style="position:absolute;cursor:crosshair;"></canvas>
        </div>
      </div>
      <div style="width:210px;flex-shrink:0;">
        <div style="font-size:12px;font-weight:700;color:var(--gray-700);margin-bottom:8px;text-transform:uppercase;letter-spacing:.05em;">How it works</div>
        <ol style="font-size:12px;color:var(--gray-600);padding-left:16px;line-height:1.7;margin:0;">
          <li>Use Prev / Next to find a sheet with a normal title block (cover pages often have none)</li>
          <li>Drag a box over the title block on that page</li>
          <li>The region is saved per location and reused for future imports</li>
          <li>Click <strong>Extract →</strong> to scan every page using that region</li>
        </ol>
        <div id="drw-cal-info" style="margin-top:14px;padding:10px;background:var(--gray-50);border-radius:6px;font-size:11px;color:var(--gray-500);line-height:1.6;">
          ${savedRegion ? `<span style="color:var(--good);">✓ Saved region loaded</span>` : 'No region selected yet'}
        </div>
        <button class="admin-action-btn-secondary" onclick="_drwCalClear()" style="margin-top:8px;font-size:12px;padding:6px 12px;width:100%;">Clear Selection</button>
      </div>
    </div>`;

  document.querySelector('#modal-overlay .modal-footer').innerHTML = `
    <button class="admin-action-btn-secondary" onclick="_drwOpenUpload()">← Back</button>
    <button class="admin-action-btn-secondary" onclick="_drwCloseUpload()">Cancel</button>
    <button class="admin-action-btn" onclick="_drwRunExtract()">Extract with Region →</button>`;

  if (savedRegion) _drwTitleRegion = savedRegion;

  // Wire navigation
  const prevBtn = document.getElementById('drw-cal-prev');
  const nextBtn = document.getElementById('drw-cal-next');
  const pageInp = document.getElementById('drw-cal-page-input');
  prevBtn.onclick = () => _drwCalGoToPage(_drwCalPage - 1);
  nextBtn.onclick = () => _drwCalGoToPage(_drwCalPage + 1);
  pageInp.onchange = () => _drwCalGoToPage(parseInt(pageInp.value, 10) || 1);

  await _drwCalRenderPage(_drwCalPage);
}

async function _drwCalGoToPage(n) {
  if (!_drwUploadPdfDoc) return;
  const target = Math.min(Math.max(1, n|0), _drwUploadPdfDoc.numPages);
  const inp = document.getElementById('drw-cal-page-input');
  if (inp) inp.value = String(target);
  if (target === _drwCalPage) return;
  _drwCalPage = target;
  await _drwCalRenderPage(target);
}

async function _drwCalRenderPage(pageNum) {
  if (_drwCalRendering) return;
  _drwCalRendering = true;
  try {
    const page  = await _drwUploadPdfDoc.getPage(pageNum);
    const vp0   = page.getViewport({ scale: 1 });
    // Size to fill the available stage area (modal is 98vw, sidebar ~210px + gap/padding)
    const stage = document.getElementById('drw-cal-stage');
    const maxW  = Math.max(400, (stage?.clientWidth  || window.innerWidth  * 0.7) - 4);
    const maxH  = Math.max(300, Math.min(window.innerHeight * 0.72, 900));
    const scale = Math.min(maxW / vp0.width, maxH / vp0.height);
    const viewport = page.getViewport({ scale });
    const pdfCv = document.getElementById('drw-cal-pdf');
    const selCv = document.getElementById('drw-cal-sel');
    if (!pdfCv || !selCv) return;
    pdfCv.width = viewport.width; pdfCv.height = viewport.height;
    selCv.width = viewport.width; selCv.height = viewport.height;
    selCv.style.width  = viewport.width + 'px';
    selCv.style.height = viewport.height + 'px';
    selCv.style.left = pdfCv.offsetLeft + 'px';
    selCv.style.top  = pdfCv.offsetTop + 'px';
    await page.render({ canvasContext: pdfCv.getContext('2d'), viewport }).promise;
    // Keep selection canvas aligned after render
    selCv.style.left = pdfCv.offsetLeft + 'px';
    selCv.style.top  = pdfCv.offsetTop + 'px';

    if (_drwTitleRegion) {
      const saved = _drwLoadRegion(_drwUploadMeta?.location);
      const isSaved = saved && saved.fx === _drwTitleRegion.fx && saved.fy === _drwTitleRegion.fy
                            && saved.fw === _drwTitleRegion.fw && saved.fh === _drwTitleRegion.fh;
      _drwDrawCalSel(selCv, _drwTitleRegion, !!isSaved);
    }

    _drwCalSel = { active: false, x0:0, y0:0, x1:0, y1:0 };
    selCv.onpointerdown = _drwCalDown;
    selCv.onpointermove = _drwCalMove;
    selCv.onpointerup   = _drwCalUp;
  } finally {
    _drwCalRendering = false;
  }
}

function _drwDrawCalSel(canvas, r, saved) {
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  if (!r) return;
  const x = r.fx*canvas.width, y = r.fy*canvas.height, w = r.fw*canvas.width, h = r.fh*canvas.height;
  ctx.strokeStyle = saved ? '#16a34a' : 'var(--hitachi-red)';
  ctx.lineWidth = 2;
  ctx.setLineDash(saved ? [] : [6,4]);
  ctx.strokeRect(x, y, w, h);
  ctx.fillStyle = saved ? 'rgba(22,163,74,0.08)' : 'rgba(230,0,18,0.08)';
  ctx.fillRect(x, y, w, h);
  ctx.setLineDash([]);
}

function _drwCalDown(e) {
  const c = document.getElementById('drw-cal-sel'), r = c.getBoundingClientRect();
  _drwCalSel = { active:true, x0:e.clientX-r.left, y0:e.clientY-r.top, x1:e.clientX-r.left, y1:e.clientY-r.top };
  c.setPointerCapture(e.pointerId);
}
function _drwCalMove(e) {
  if (!_drwCalSel.active) return;
  const c = document.getElementById('drw-cal-sel'), r = c.getBoundingClientRect();
  _drwCalSel.x1 = e.clientX-r.left; _drwCalSel.y1 = e.clientY-r.top;
  _drwDrawCalSel(c, { fx:Math.min(_drwCalSel.x0,_drwCalSel.x1)/c.width, fy:Math.min(_drwCalSel.y0,_drwCalSel.y1)/c.height, fw:Math.abs(_drwCalSel.x1-_drwCalSel.x0)/c.width, fh:Math.abs(_drwCalSel.y1-_drwCalSel.y0)/c.height }, false);
}
function _drwCalUp(e) {
  if (!_drwCalSel.active) return;
  _drwCalSel.active = false;
  const c = document.getElementById('drw-cal-sel');
  const reg = { fx:Math.min(_drwCalSel.x0,_drwCalSel.x1)/c.width, fy:Math.min(_drwCalSel.y0,_drwCalSel.y1)/c.height, fw:Math.abs(_drwCalSel.x1-_drwCalSel.x0)/c.width, fh:Math.abs(_drwCalSel.y1-_drwCalSel.y0)/c.height };
  if (reg.fw < 0.02 || reg.fh < 0.02) return;
  _drwTitleRegion = reg;
  _drwDrawCalSel(c, reg, false);
  const info = document.getElementById('drw-cal-info');
  if (info) info.innerHTML = `Region selected<br>x=${Math.round(reg.fx*100)}% y=${Math.round(reg.fy*100)}%<br>w=${Math.round(reg.fw*100)}% h=${Math.round(reg.fh*100)}%<br><span style="color:var(--hitachi-red);font-weight:600;">Will be saved for ${escapeHtml(_drwUploadMeta?.location||'')}</span>`;
}
function _drwCalClear() {
  _drwTitleRegion = null;
  const c = document.getElementById('drw-cal-sel');
  if (c) c.getContext('2d').clearRect(0, 0, c.width, c.height);
  const info = document.getElementById('drw-cal-info');
  if (info) info.textContent = 'No region selected yet';
}

async function _drwRunExtract() {
  if (_drwTitleRegion && _drwUploadMeta?.location) _drwSaveRegion(_drwUploadMeta.location, _drwTitleRegion);
  const numPages = _drwUploadPdfDoc.numPages;

  document.querySelector('#modal-overlay .modal-body').innerHTML = `
    <div style="text-align:center;padding:40px 20px;">
      <div class="spinner" style="margin:0 auto 16px;"></div>
      <p id="drw-parse-status" style="color:var(--gray-500);">Extracting page 1 of ${numPages}…</p>
      <div style="margin-top:12px;background:var(--gray-100);border-radius:6px;height:6px;width:260px;margin-left:auto;margin-right:auto;">
        <div id="drw-parse-bar" style="background:var(--hitachi-red);height:6px;border-radius:6px;width:0%;transition:width .2s;"></div>
      </div>
    </div>`;
  document.querySelector('#modal-overlay .modal-footer').innerHTML = '';

  try {
    const sheets = [];
    for (let i = 1; i <= numPages; i++) {
      document.getElementById('drw-parse-status').textContent = `Extracting page ${i} of ${numPages}…`;
      document.getElementById('drw-parse-bar').style.width = `${Math.round(i/numPages*100)}%`;
      const page     = await _drwUploadPdfDoc.getPage(i);
      const viewport = page.getViewport({ scale: 1 });
      const content  = await page.getTextContent();
      const parsed   = _drwParseSheetInfo(content.items, viewport.width, viewport.height, _drwTitleRegion);
      sheets.push({
        pageIndex: i-1, ...parsed,
        needsReview: !parsed.sheetNumber || !parsed.sheetTitle,
        // Pre-uncheck pages with no sheet number AND no title — usually covers/index pages.
        included: !!(parsed.sheetNumber || parsed.sheetTitle || parsed.pageNumber),
      });
    }
    _drwParsedSheets = sheets;
    _drwShowReview(numPages);
  } catch(e) {
    document.querySelector('#modal-overlay .modal-body').innerHTML = `<p style="color:var(--bad);padding:20px;">${escapeHtml(e.message)}</p>`;
    document.querySelector('#modal-overlay .modal-footer').innerHTML = `<button class="admin-action-btn-secondary" onclick="_drwCloseUpload()">Close</button>`;
  }
}

function _drwShowReview(numPages) {
  const needsReview   = _drwParsedSheets.filter(s => s.needsReview).length;
  const includedCount = _drwParsedSheets.filter(s => s.included).length;
  const allNeedReview = needsReview === _drwParsedSheets.length;

  document.querySelector('#modal-overlay .modal-head .modal-title').textContent = 'Review Sheets';
  const subEl = document.querySelector('#modal-overlay .modal-head .modal-sub');
  if (subEl) subEl.textContent = 'Verify extracted data, uncheck pages to omit them, then Confirm to import.';

  document.querySelector('#modal-overlay .modal-body').innerHTML = `
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;flex-wrap:wrap;">
      <span style="font-size:13px;color:var(--gray-600);">${numPages} pages parsed.</span>
      <span id="drw-included-pill" style="background:#e0e7ff;color:#3730a3;padding:3px 10px;border-radius:12px;font-size:12px;font-weight:600;">${includedCount} of ${numPages} to import</span>
      ${needsReview
        ? `<span style="background:#fef3c7;color:#92400e;padding:3px 10px;border-radius:12px;font-size:12px;font-weight:600;">⚠ ${needsReview} need manual entry</span>`
        : `<span style="background:#dcfce7;color:#166534;padding:3px 10px;border-radius:12px;font-size:12px;font-weight:600;">✓ All sheets parsed</span>`}
      <button class="admin-action-btn-secondary" onclick="_drwReviewSelectAll(true)" style="font-size:12px;padding:5px 10px;">Select all</button>
      <button class="admin-action-btn-secondary" onclick="_drwReviewSelectAll(false)" style="font-size:12px;padding:5px 10px;">Select none</button>
      ${allNeedReview ? `<button class="admin-action-btn-secondary" onclick="_drwShowCalibrate()" style="font-size:12px;padding:5px 10px;margin-left:auto;">↩ Recalibrate region</button>` : ''}
    </div>
    ${_drwDisciplineListHTML()}
    <div style="max-height:480px;overflow-y:auto;border:1px solid var(--gray-200);border-radius:8px;">
      <table class="data-table">
        <thead><tr>
          <th style="width:48px;"><input type="checkbox" id="drw-rev-toggle-all" ${includedCount === _drwParsedSheets.length ? 'checked' : ''} onchange="_drwReviewSelectAll(this.checked)" title="Toggle all" /></th>
          <th style="width:42px;">Pg</th><th>Sheet #</th><th>Page #</th><th>Title</th><th>Rev</th><th>Discipline</th>
        </tr></thead>
        <tbody>
          ${_drwParsedSheets.map((s, i) => `
            <tr id="drw-rev-row-${i}" style="${!s.included ? 'opacity:0.45;background:var(--gray-50);' : s.needsReview ? 'background:#fffbeb;' : ''}">
              <td style="text-align:center;"><input type="checkbox" ${s.included ? 'checked' : ''} onchange="_drwReviewToggle(${i}, this.checked)" /></td>
              <td style="color:var(--gray-400);font-size:12px;">${s.pageIndex+1}</td>
              <td><input class="form-input" value="${escapeHtml(s.sheetNumber||'')}"
                style="width:140px;font-family:monospace;font-size:12px;padding:3px 6px;border-color:${s.sheetNumber?'var(--gray-200)':'var(--warn)'};"
                onchange="_drwReviewEdit(${i},'sheetNumber',this.value)" /></td>
              <td><input class="form-input" value="${escapeHtml(s.pageNumber||'')}"
                style="width:62px;font-family:monospace;font-size:12px;padding:3px 6px;text-align:center;"
                onchange="_drwReviewEdit(${i},'pageNumber',this.value)" /></td>
              <td><input class="form-input" value="${escapeHtml(s.sheetTitle||'')}"
                style="width:240px;font-size:12px;padding:3px 6px;border-color:${s.sheetTitle?'var(--gray-200)':'var(--warn)'};"
                onchange="_drwReviewEdit(${i},'sheetTitle',this.value)" /></td>
              <td><input class="form-input" value="${escapeHtml(s.revision||'')}"
                style="width:52px;font-size:12px;padding:3px 6px;"
                onchange="_drwReviewEdit(${i},'revision',this.value)" /></td>
              <td style="font-size:12px;color:var(--gray-500);">${escapeHtml(s.discipline||'—')}</td>
            </tr>`).join('')}
        </tbody>
      </table>
    </div>
    <p style="font-size:11px;color:var(--gray-400);margin-top:8px;">Edit any field directly. Discipline suggestions come from Field Config; new free-text disciplines are added there after Confirm &amp; Import succeeds.</p>`;

  _drwHydrateDisciplineReviewInputs();

  document.querySelector('#modal-overlay .modal-footer').innerHTML = `
    <button class="admin-action-btn-secondary" onclick="_drwShowCalibrate()">← Recalibrate</button>
    <button class="admin-action-btn-secondary" onclick="_drwCloseUpload()">Cancel</button>
    <button class="admin-action-btn" onclick="_drwConfirmImport()">Confirm &amp; Import</button>`;
}

function _drwHydrateDisciplineReviewInputs() {
  _drwParsedSheets.forEach((s, i) => {
    const row = document.getElementById(`drw-rev-row-${i}`);
    const cell = row?.lastElementChild;
    if (!cell) return;
    cell.innerHTML = `
      <input id="drw-discipline-${i}" class="form-input" list="drw-discipline-options" value="${escapeHtml(s.discipline || '')}"
        style="width:160px;font-size:12px;padding:3px 6px;"
        placeholder="Discipline..." onchange="_drwReviewEdit(${i},'discipline',this.value)" />`;
  });
}

function _drwReviewEdit(idx, field, value) {
  if (_drwParsedSheets[idx]) {
    _drwParsedSheets[idx][field] = value;
    if (field === 'sheetNumber') {
      _drwParsedSheets[idx].discipline = _drwDiscipline(value);
      const disciplineInput = document.getElementById(`drw-discipline-${idx}`);
      if (disciplineInput) disciplineInput.value = _drwParsedSheets[idx].discipline || '';
    }
  }
}

function _drwReviewToggle(idx, included) {
  if (!_drwParsedSheets[idx]) return;
  _drwParsedSheets[idx].included = !!included;
  const row = document.getElementById(`drw-rev-row-${idx}`);
  if (row) {
    const s = _drwParsedSheets[idx];
    row.style.cssText = !s.included
      ? 'opacity:0.45;background:var(--gray-50);'
      : s.needsReview ? 'background:#fffbeb;' : '';
  }
  _drwReviewUpdateCounts();
}

function _drwReviewSelectAll(checked) {
  _drwParsedSheets.forEach((s, i) => {
    s.included = !!checked;
    const row = document.getElementById(`drw-rev-row-${i}`);
    const cb  = row?.querySelector('td:first-child input[type="checkbox"]');
    if (cb) cb.checked = !!checked;
    if (row) {
      row.style.cssText = !s.included
        ? 'opacity:0.45;background:var(--gray-50);'
        : s.needsReview ? 'background:#fffbeb;' : '';
    }
  });
  const toggle = document.getElementById('drw-rev-toggle-all');
  if (toggle) toggle.checked = !!checked;
  _drwReviewUpdateCounts();
}

function _drwReviewUpdateCounts() {
  const total    = _drwParsedSheets.length;
  const included = _drwParsedSheets.filter(s => s.included).length;
  const pill = document.getElementById('drw-included-pill');
  if (pill) pill.textContent = `${included} of ${total} to import`;
  const toggle = document.getElementById('drw-rev-toggle-all');
  if (toggle) toggle.checked = included === total && total > 0;
}

function _drwSheetInsertRows(setId, meta, sheets, includePageNumber = true) {
  return sheets.map(s => {
    const row = {
      set_id: setId, location: meta.location, page_index: s.pageIndex,
      sheet_number: s.sheetNumber || null, sheet_title: s.sheetTitle || null,
      discipline: s.discipline || null, revision: s.revision || null,
      is_current: true, confirmed: true, needs_review: s.needsReview || false,
    };
    if (includePageNumber) row.page_number = s.pageNumber || null;
    return row;
  });
}

async function _drwInsertSheetRows(setId, meta, sheets) {
  try {
    await _dbInsert('drawing_sheets', _drwSheetInsertRows(setId, meta, sheets, true));
    return { pageNumberSkipped: false };
  } catch (e) {
    const msg = String(e?.message || '');
    if (!msg.includes("'page_number' column") && !msg.includes('page_number')) throw e;
    console.warn('[drawings import] page_number column missing; retrying without page_number. Run supabase_drawings_add_page_number.sql to preserve PAGE NO.');
    await _dbInsert('drawing_sheets', _drwSheetInsertRows(setId, meta, sheets, false));
    return { pageNumberSkipped: true };
  }
}

async function _drwConfirmImport() {
  const meta = _drwUploadMeta;
  if (!meta) return;
  const toImport = _drwParsedSheets.filter(s => s.included);
  if (!toImport.length) { toast('Select at least one sheet to import.', 'error'); return; }

  document.querySelector('#modal-overlay .modal-body').innerHTML = `
    <div style="text-align:center;padding:40px 20px;">
      <div class="spinner" style="margin:0 auto 16px;"></div>
      <p id="drw-confirm-status" style="color:var(--gray-500);">Creating drawing set record…</p>
    </div>`;
  document.querySelector('#modal-overlay .modal-footer').innerHTML = '';

  try {
    const inserted = await _dbInsert('drawing_sets', {
      title: meta.title, location: meta.location,
      import_date: meta.import_date || null, revision_date: meta.revision_date || null,
      release_date: meta.release_date || null,
      uploaded_by: currentRoleUser?.name || 'Admin',
      status: 'processing', total_sheets: toImport.length,
    });
    const setId = inserted[0]?.id;
    if (!setId) throw new Error('Failed to create drawing set record.');

    document.getElementById('drw-confirm-status').textContent = 'Uploading PDF to storage…';
    const storagePath = `${setId}/full.pdf`;
    await _drawStorage.upload(storagePath, meta.file);
    await _dbUpdate('drawing_sets', { storage_path: storagePath }, { id: setId });

    document.getElementById('drw-confirm-status').textContent = 'Checking for existing revisions…';
    const newNums = toImport.map(s => s.sheetNumber).filter(Boolean);
    const toSupersede = DRAWING_SHEETS.filter(s => s.location === meta.location && s.is_current && newNums.includes(s.sheet_number));
    if (toSupersede.length) await Promise.all(toSupersede.map(s => _dbUpdate('drawing_sheets', { is_current: false }, { id: s.id })));

    document.getElementById('drw-confirm-status').textContent = 'Saving sheet records…';
    const insertResult = await _drwInsertSheetRows(setId, meta, toImport);

    const confirmedDisciplines = toImport.map(s => s.discipline).filter(Boolean);
    let addedDisciplines = [];
    try {
      addedDisciplines = await _fscEnsureOptions('drawing_discipline', confirmedDisciplines);
    } catch (cfgErr) {
      console.warn('[drawings import] discipline config update failed:', cfgErr.message);
    }
    await _dbUpdate('drawing_sets', { status: 'ready' }, { id: setId });

    await loadDrawingsData();
    _drwCloseUpload();
    renderDrawingsPage();
    const skipped = _drwParsedSheets.length - toImport.length;
    toast(`Drawing set imported: ${toImport.length} sheets${skipped ? `, ${skipped} skipped` : ''}${toSupersede.length ? `, ${toSupersede.length} auto-upreved` : ''}${addedDisciplines.length ? `, ${addedDisciplines.length} discipline${addedDisciplines.length===1?'':'s'} added` : ''}${insertResult.pageNumberSkipped ? ', page numbers skipped until DB migration is run' : ''}`, 'success');
  } catch(e) {
    document.querySelector('#modal-overlay .modal-body').innerHTML = `<p style="color:var(--bad);padding:20px;">Import failed: ${escapeHtml(e.message)}</p>`;
    document.querySelector('#modal-overlay .modal-footer').innerHTML = `<button class="admin-action-btn-secondary" onclick="_drwCloseUpload()">Close</button>`;
  }
}

// ── Sheet Viewer ───────────────────────────────────────────────────────────
let _drwPdfDoc    = null;
let _drwCurSheet  = null;
let _drwMarkupShapes = [];
let _drwSavedMarkupId = null;
let _drwMarkupDirty   = false;
let _drwTool      = { name: 'pen', color: '#dc2626', width: 3 };
let _drwIsDrawing = false;
let _drwStartX    = 0;
let _drwStartY    = 0;
let _drwCurPath   = [];
let _drwPageIndex = 0;
let _drwZoomMode  = 'fit';
let _drwZoomScale = 1;
let _drwSelectedShape = -1;
let _drwDragState = null;
let _drwTextEditor = null;

async function _drwOpenSheet(sheetId, setId, pageIndex) {
  const sheet = DRAWING_SHEETS.find(s => s.id === sheetId);
  const set   = DRAWING_SETS.find(s => s.id === setId);
  if (!sheet || !set) return;

  _drwCurSheet     = sheet;
  _drwMarkupShapes = [];
  _drwSavedMarkupId = null;
  _drwMarkupDirty   = false;
  _drwSelectedShape = -1;
  _drwDragState = null;
  _drwPageIndex = pageIndex;
  _drwZoomMode = 'fit';

  const ov = document.getElementById('drw-viewer-overlay');
  ov.style.display = 'flex';
  _drwEnsureEditorChrome();

  document.getElementById('drw-viewer-sheet-num').textContent = sheet.sheet_number || '—';
  document.getElementById('drw-viewer-title').textContent     = sheet.sheet_title || '';
  document.getElementById('drw-viewer-rev').textContent       = sheet.revision ? `Rev ${sheet.revision}` : '';
  document.getElementById('drw-viewer-loading').style.display = 'flex';
  document.getElementById('drw-pdf-canvas').style.display     = 'none';
  document.getElementById('drw-markup-canvas').style.display  = 'none';
  document.getElementById('drw-markup-status').textContent    = '';

  // Load existing markup for this user
  const myMarkup = DRAWING_MARKUPS.find(m => m.sheet_id === sheetId
    && m.created_by === currentRoleUser?.id && !m.is_published);
  if (myMarkup) {
    _drwSavedMarkupId = myMarkup.id;
    _drwMarkupShapes  = Array.isArray(myMarkup.markup_data) ? myMarkup.markup_data : [];
  }
  const pubMarkups = DRAWING_MARKUPS.filter(m => m.sheet_id === sheetId && m.is_published);
  document.getElementById('drw-published-markups').textContent =
    pubMarkups.length ? `${pubMarkups.length} published markup${pubMarkups.length>1?'s':''}` : '';

  // Load PDF and render page
  try {
    if (typeof pdfjsLib === 'undefined') throw new Error('PDF.js not loaded');
    if (!pdfjsLib.GlobalWorkerOptions.workerSrc) {
      pdfjsLib.GlobalWorkerOptions.workerSrc =
        'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/legacy/build/pdf.worker.min.js';
    }
    const bytes   = await _drawStorage.downloadBytes(set.storage_path);
    _drwPdfDoc    = await pdfjsLib.getDocument({ data: bytes }).promise;
    await _drwRenderPage(pageIndex);
  } catch(e) {
    document.getElementById('drw-viewer-loading').textContent = `Failed to load: ${e.message}`;
  }

  _drwSetTool('select');
  _drwSetColor(_drwTool.color);
}

function _drwEnsureEditorChrome() {
  const ov = document.getElementById('drw-viewer-overlay');
  const head = document.getElementById('drw-viewer-header');
  const body = document.getElementById('drw-viewer-body');
  const wrap = document.getElementById('drw-canvas-wrap');
  const footer = document.getElementById('drw-viewer-footer');
  const toolbar = document.getElementById('drw-markup-toolbar');
  if (ov) ov.classList.add('drw-editor-overlay');
  if (head) head.classList.add('drw-editor-header');
  if (body) body.classList.add('drw-editor-body');
  if (wrap) wrap.classList.add('drw-canvas-wrap');
  if (footer) footer.classList.add('drw-editor-footer');
  if (toolbar && !toolbar.dataset.modernized) {
    toolbar.dataset.modernized = 'true';
    toolbar.className = 'drw-markup-toolbar';
    toolbar.innerHTML = `
      <button class="drw-tool-btn" id="drw-tool-select" onclick="_drwSetTool('select')" title="Select, move, resize, edit">Select</button>
      <button class="drw-tool-btn" id="drw-tool-pen" onclick="_drwSetTool('pen')" title="Freehand pen">Pen</button>
      <button class="drw-tool-btn" id="drw-tool-rect" onclick="_drwSetTool('rect')" title="Rectangle">Rect</button>
      <button class="drw-tool-btn" id="drw-tool-arrow" onclick="_drwSetTool('arrow')" title="Arrow">Arrow</button>
      <button class="drw-tool-btn" id="drw-tool-text" onclick="_drwSetTool('text')" title="Inline text box">Text</button>
      <select id="drw-width-select" class="drw-editor-select" onchange="_drwSetWidth(this.value)" title="Line width">
        <option value="2">2px</option><option value="3" selected>3px</option><option value="5">5px</option><option value="8">8px</option>
      </select>
      <button class="drw-color-btn" data-color="#dc2626" onclick="_drwSetColor('#dc2626')" title="Red" style="background:#dc2626;"></button>
      <button class="drw-color-btn" data-color="#f59e0b" onclick="_drwSetColor('#f59e0b')" title="Amber" style="background:#f59e0b;"></button>
      <button class="drw-color-btn" data-color="#10b981" onclick="_drwSetColor('#10b981')" title="Green" style="background:#10b981;"></button>
      <button class="drw-color-btn" data-color="#2563eb" onclick="_drwSetColor('#2563eb')" title="Blue" style="background:#2563eb;"></button>
      <span class="drw-toolbar-divider"></span>
      <button class="drw-tool-btn" onclick="_drwZoomOut()" title="Zoom out">-</button>
      <button class="drw-tool-btn" onclick="_drwFitPage()" title="Fit whole page">Fit</button>
      <button class="drw-tool-btn" onclick="_drwZoomIn()" title="Zoom in">+</button>
      <span id="drw-zoom-label" class="drw-zoom-label">Fit</span>
      <span class="drw-toolbar-divider"></span>
      <button class="drw-tool-btn drw-danger-btn" onclick="_drwDeleteSelected()" title="Delete selected markup">Delete</button>
      <button class="drw-tool-btn drw-danger-btn" onclick="_drwClearMarkup()" title="Clear all your draft markups">Clear</button>
      <button class="drw-save-btn" onclick="_drwSaveMarkup()">Save Draft</button>
      <button class="drw-publish-btn" onclick="_drwPublishMarkup()">Publish</button>`;
  }
  const hint = footer?.querySelector('.drw-editor-hint');
  if (footer && !hint) {
    const span = document.createElement('span');
    span.className = 'drw-editor-hint';
    span.textContent = 'Select markups to move, resize, edit, or delete. Double-click text to edit.';
    footer.insertBefore(span, document.getElementById('drw-published-markups'));
  }
}

function _drwComputeFitScale(page) {
  const body = document.getElementById('drw-viewer-body');
  const vp = page.getViewport({ scale: 1 });
  const maxW = Math.max(320, (body?.clientWidth || window.innerWidth) - 56);
  const maxH = Math.max(320, (body?.clientHeight || window.innerHeight) - 56);
  return Math.min(maxW / vp.width, maxH / vp.height);
}

async function _drwRenderPage(pageIndex, opts = {}) {
  const pdfCanvas    = document.getElementById('drw-pdf-canvas');
  const markupCanvas = document.getElementById('drw-markup-canvas');
  const loading      = document.getElementById('drw-viewer-loading');

  const page     = await _drwPdfDoc.getPage(pageIndex + 1);
  _drwPageIndex = pageIndex;
  if (_drwZoomMode === 'fit' || opts.fit) {
    _drwZoomMode = 'fit';
    _drwZoomScale = _drwComputeFitScale(page);
  }
  const viewport = page.getViewport({ scale: _drwZoomScale });

  pdfCanvas.width  = viewport.width;
  pdfCanvas.height = viewport.height;
  markupCanvas.width  = viewport.width;
  markupCanvas.height = viewport.height;
  pdfCanvas.style.width = viewport.width + 'px';
  pdfCanvas.style.height = viewport.height + 'px';
  markupCanvas.style.width = viewport.width + 'px';
  markupCanvas.style.height = viewport.height + 'px';

  const ctx = pdfCanvas.getContext('2d');
  await page.render({ canvasContext: ctx, viewport }).promise;

  loading.style.display        = 'none';
  pdfCanvas.style.display      = 'block';
  markupCanvas.style.display   = 'block';

  _drwInitMarkupCanvas(markupCanvas);
  _drwUpdateZoomLabel();
  _drwRedraw();
}

function _drwCloseViewer() {
  if (_drwMarkupDirty) {
    if (!confirm('You have unsaved markup changes. Close anyway?')) return;
  }
  document.getElementById('drw-viewer-overlay').style.display = 'none';
  _drwPdfDoc    = null;
  _drwCurSheet  = null;
  _drwMarkupShapes = [];
  _drwSelectedShape = -1;
  _drwRemoveTextEditor(false);
}

function _drwUpdateZoomLabel() {
  const el = document.getElementById('drw-zoom-label');
  if (el) el.textContent = _drwZoomMode === 'fit' ? 'Fit' : `${Math.round(_drwZoomScale * 100)}%`;
}

async function _drwFitPage() {
  if (!_drwPdfDoc) return;
  await _drwRenderPage(_drwPageIndex, { fit: true });
}

async function _drwZoomBy(mult) {
  if (!_drwPdfDoc) return;
  _drwZoomMode = 'manual';
  _drwZoomScale = Math.max(0.25, Math.min(4, _drwZoomScale * mult));
  await _drwRenderPage(_drwPageIndex);
}

function _drwZoomIn() { _drwZoomBy(1.2); }
function _drwZoomOut() { _drwZoomBy(1 / 1.2); }

// ── Markup canvas ──────────────────────────────────────────────────────────
function _drwInitMarkupCanvas(canvas) {
  // Remove old listeners by cloning
  const fresh = canvas.cloneNode(true);
  canvas.parentNode.replaceChild(fresh, canvas);

  fresh.addEventListener('pointerdown', _drwPointerDown);
  fresh.addEventListener('pointermove', _drwPointerMove);
  fresh.addEventListener('pointerup',   _drwPointerUp);
  fresh.addEventListener('pointerleave',_drwPointerUp);
  fresh.addEventListener('dblclick', _drwCanvasDblClick);
  fresh.addEventListener('keydown', _drwCanvasKeyDown);
  fresh.tabIndex = 0;
  _drwUpdateCursor();
}

function _drwCanvasXY(e) {
  const canvas = document.getElementById('drw-markup-canvas');
  const rect = canvas.getBoundingClientRect();
  return {
    fx: (e.clientX - rect.left) / rect.width,
    fy: (e.clientY - rect.top)  / rect.height,
  };
}

function _drwPointerDown(e) {
  _drwRemoveTextEditor(true);
  const canvas = document.getElementById('drw-markup-canvas');
  canvas?.focus();
  const { fx, fy } = _drwCanvasXY(e);
  if (_drwTool.name === 'select') {
    const handle = _drwSelectedShape >= 0 ? _drwHitHandle(_drwMarkupShapes[_drwSelectedShape], fx, fy) : null;
    if (handle) {
      _drwDragState = { mode: 'resize', idx: _drwSelectedShape, handle, startX: fx, startY: fy, before: _drwCloneShape(_drwMarkupShapes[_drwSelectedShape]) };
      canvas?.setPointerCapture(e.pointerId);
      return;
    }
    const hit = _drwHitShape(fx, fy);
    _drwSelectedShape = hit;
    if (hit >= 0) {
      _drwDragState = { mode: 'move', idx: hit, startX: fx, startY: fy, before: _drwCloneShape(_drwMarkupShapes[hit]) };
      canvas?.setPointerCapture(e.pointerId);
    }
    _drwRedraw();
    return;
  }
  _drwIsDrawing = true;
  _drwStartX = fx; _drwStartY = fy;
  _drwCurPath = [[fx, fy]];
  document.getElementById('drw-markup-canvas').setPointerCapture(e.pointerId);
}

function _drwPointerMove(e) {
  const { fx, fy } = _drwCanvasXY(e);
  if (_drwDragState) {
    _drwApplyDrag(fx, fy, e.shiftKey);
    _drwMarkupDirty = true;
    _drwRedraw();
    return;
  }
  if (!_drwIsDrawing) return;
  if (_drwTool.name === 'pen') _drwCurPath.push([fx, fy]);
  _drwRedraw({ preview: { type: _drwTool.name, startX: _drwStartX, startY: _drwStartY, endX: fx, endY: fy, path: _drwCurPath } });
}

function _drwPointerUp(e) {
  if (_drwDragState) {
    _drwDragState = null;
    _drwRedraw();
    return;
  }
  if (!_drwIsDrawing) return;
  _drwIsDrawing = false;
  const { fx, fy } = _drwCanvasXY(e);
  let shape = null;
  if (_drwTool.name === 'pen' && _drwCurPath.length > 1) {
    shape = { type: 'pen', points: [..._drwCurPath], color: _drwTool.color, width: _drwTool.width };
  } else if (_drwTool.name === 'rect') {
    shape = { type: 'rect', x: _drwStartX, y: _drwStartY, w: fx - _drwStartX, h: fy - _drwStartY, color: _drwTool.color, width: _drwTool.width };
  } else if (_drwTool.name === 'arrow') {
    shape = { type: 'arrow', x1: _drwStartX, y1: _drwStartY, x2: fx, y2: fy, color: _drwTool.color, width: _drwTool.width };
  } else if (_drwTool.name === 'text') {
    const r = _drwNormRect(_drwStartX, _drwStartY, fx - _drwStartX, fy - _drwStartY);
    shape = {
      type: 'text',
      x: r.x,
      y: r.y,
      w: Math.max(0.14, r.w),
      h: Math.max(0.045, r.h),
      text: '',
      color: _drwTool.color,
      size: 15,
    };
  }
  if (shape) {
    _drwMarkupShapes.push(shape);
    _drwSelectedShape = _drwMarkupShapes.length - 1;
    _drwMarkupDirty = true;
  }
  _drwCurPath = [];
  _drwRedraw();
  if (shape?.type === 'text') _drwOpenTextEditor(_drwSelectedShape);
}

function _drwPlaceText(e) {
  const { fx, fy } = _drwCanvasXY(e);
  const shape = { type: 'text', x: fx, y: fy, w: 0.22, h: 0.055, text: '', color: _drwTool.color, size: 15 };
  _drwMarkupShapes.push(shape);
  _drwSelectedShape = _drwMarkupShapes.length - 1;
  _drwMarkupDirty = true;
  _drwRedraw();
  _drwOpenTextEditor(_drwSelectedShape);
}

function _drwRedraw(opts = {}) {
  const canvas = document.getElementById('drw-markup-canvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  ctx.clearRect(0, 0, W, H);

  // Draw published markups (semi-transparent)
  const pubMarkups = DRAWING_MARKUPS.filter(m => _drwCurSheet && m.sheet_id === _drwCurSheet.id && m.is_published);
  pubMarkups.forEach(m => {
    const shapes = Array.isArray(m.markup_data) ? m.markup_data : [];
    ctx.globalAlpha = 0.5;
    shapes.forEach(s => _drwDrawShape(ctx, s, W, H));
    ctx.globalAlpha = 1;
  });

  // Draw current user's shapes
  _drwMarkupShapes.forEach((s, i) => _drwDrawShape(ctx, s, W, H, i === _drwSelectedShape));

  // Draw preview
  if (opts.preview) {
    const p = opts.preview;
    ctx.strokeStyle = _drwTool.color;
    ctx.lineWidth   = _drwTool.width;
    ctx.setLineDash([4, 4]);
    if (p.type === 'pen' && p.path.length > 1) {
      ctx.beginPath(); ctx.moveTo(p.path[0][0]*W, p.path[0][1]*H);
      p.path.slice(1).forEach(pt => ctx.lineTo(pt[0]*W, pt[1]*H));
      ctx.stroke();
    } else if (p.type === 'rect' || p.type === 'text') {
      ctx.strokeRect(p.startX*W, p.startY*H, (p.endX-p.startX)*W, (p.endY-p.startY)*H);
    } else if (p.type === 'arrow') {
      _drwArrow(ctx, p.startX*W, p.startY*H, p.endX*W, p.endY*H);
    }
    ctx.setLineDash([]);
  }
}

function _drwDrawShape(ctx, s, W, H, selected = false) {
  ctx.strokeStyle = s.color || '#dc2626';
  ctx.fillStyle   = s.color || '#dc2626';
  ctx.lineWidth   = s.width || 2;
  ctx.lineCap     = 'round';
  ctx.lineJoin    = 'round';
  if (s.type === 'pen' && s.points?.length > 1) {
    ctx.beginPath(); ctx.moveTo(s.points[0][0]*W, s.points[0][1]*H);
    s.points.slice(1).forEach(pt => ctx.lineTo(pt[0]*W, pt[1]*H));
    ctx.stroke();
  } else if (s.type === 'rect') {
    ctx.strokeRect(s.x*W, s.y*H, s.w*W, s.h*H);
  } else if (s.type === 'arrow') {
    _drwArrow(ctx, s.x1*W, s.y1*H, s.x2*W, s.y2*H);
  } else if (s.type === 'text') {
    const b = _drwShapeBounds(s);
    const px = b.x * W, py = b.y * H, pw = b.w * W, ph = b.h * H;
    ctx.font = `600 ${Math.max(10, (s.size || 15) * _drwZoomScale)}px sans-serif`;
    ctx.textBaseline = 'top';
    _drwDrawTextLines(ctx, s.text || '', px + 4, py + 4, Math.max(10, pw - 8), Math.max(12, (s.size || 15) * _drwZoomScale * 1.25));
    if (!s.text) {
      ctx.globalAlpha = 0.35;
      ctx.strokeStyle = s.color || '#dc2626';
      ctx.strokeRect(px, py, pw, ph);
      ctx.globalAlpha = 1;
    }
  }
  if (selected) _drwDrawSelection(ctx, s, W, H);
}

function _drwArrow(ctx, x1, y1, x2, y2) {
  const angle = Math.atan2(y2-y1, x2-x1);
  const len = 12;
  ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - len*Math.cos(angle-Math.PI/6), y2 - len*Math.sin(angle-Math.PI/6));
  ctx.lineTo(x2 - len*Math.cos(angle+Math.PI/6), y2 - len*Math.sin(angle+Math.PI/6));
  ctx.closePath(); ctx.fill();
}

function _drwDrawTextLines(ctx, text, x, y, maxWidth, lineHeight) {
  const lines = String(text || '').split(/\n/);
  let yy = y;
  for (const line of lines) {
    const words = line.split(/\s+/);
    let cur = '';
    for (const word of words) {
      const test = cur ? `${cur} ${word}` : word;
      if (ctx.measureText(test).width > maxWidth && cur) {
        ctx.fillText(cur, x, yy);
        yy += lineHeight;
        cur = word;
      } else {
        cur = test;
      }
    }
    if (cur) ctx.fillText(cur, x, yy);
    yy += lineHeight;
  }
}

function _drwCloneShape(s) {
  return JSON.parse(JSON.stringify(s || {}));
}

function _drwNormRect(x, y, w, h) {
  const nx = w < 0 ? x + w : x;
  const ny = h < 0 ? y + h : y;
  return { x: nx, y: ny, w: Math.abs(w), h: Math.abs(h) };
}

function _drwShapeBounds(s) {
  if (!s) return { x: 0, y: 0, w: 0, h: 0 };
  if (s.type === 'rect') return _drwNormRect(s.x || 0, s.y || 0, s.w || 0, s.h || 0);
  if (s.type === 'text') return { x: s.x || 0, y: s.y || 0, w: s.w || 0.22, h: s.h || 0.055 };
  if (s.type === 'arrow') {
    const x = Math.min(s.x1 || 0, s.x2 || 0), y = Math.min(s.y1 || 0, s.y2 || 0);
    return { x, y, w: Math.abs((s.x2 || 0) - (s.x1 || 0)), h: Math.abs((s.y2 || 0) - (s.y1 || 0)) };
  }
  if (s.type === 'pen' && s.points?.length) {
    const xs = s.points.map(p => p[0]), ys = s.points.map(p => p[1]);
    const x = Math.min(...xs), y = Math.min(...ys);
    return { x, y, w: Math.max(0.006, Math.max(...xs) - x), h: Math.max(0.006, Math.max(...ys) - y) };
  }
  return { x: 0, y: 0, w: 0, h: 0 };
}

function _drwDrawSelection(ctx, s, W, H) {
  const b = _drwShapeBounds(s);
  const x = b.x * W, y = b.y * H, w = b.w * W, h = b.h * H;
  ctx.save();
  ctx.strokeStyle = '#2563eb';
  ctx.lineWidth = 1.5;
  ctx.setLineDash([5, 4]);
  ctx.strokeRect(x, y, w, h);
  ctx.setLineDash([]);
  for (const hnd of _drwSelectionHandles(s)) {
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = '#2563eb';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.rect(hnd.x * W - 4, hnd.y * H - 4, 8, 8);
    ctx.fill();
    ctx.stroke();
  }
  ctx.restore();
}

function _drwSelectionHandles(s) {
  if (s?.type === 'arrow') return [{ id: 'start', x: s.x1, y: s.y1 }, { id: 'end', x: s.x2, y: s.y2 }];
  const b = _drwShapeBounds(s);
  return [
    { id: 'nw', x: b.x, y: b.y },
    { id: 'ne', x: b.x + b.w, y: b.y },
    { id: 'sw', x: b.x, y: b.y + b.h },
    { id: 'se', x: b.x + b.w, y: b.y + b.h },
  ];
}

function _drwDistToSegment(px, py, x1, y1, x2, y2) {
  const dx = x2 - x1, dy = y2 - y1;
  if (!dx && !dy) return Math.hypot(px - x1, py - y1);
  const t = Math.max(0, Math.min(1, ((px - x1) * dx + (py - y1) * dy) / (dx * dx + dy * dy)));
  return Math.hypot(px - (x1 + t * dx), py - (y1 + t * dy));
}

function _drwHitHandle(s, fx, fy) {
  const tol = 9 / Math.max(1, document.getElementById('drw-markup-canvas')?.width || 1);
  return _drwSelectionHandles(s).find(h => Math.hypot(fx - h.x, fy - h.y) < tol)?.id || null;
}

function _drwHitShape(fx, fy) {
  const tol = 8 / Math.max(1, document.getElementById('drw-markup-canvas')?.width || 1);
  for (let i = _drwMarkupShapes.length - 1; i >= 0; i--) {
    const s = _drwMarkupShapes[i];
    const b = _drwShapeBounds(s);
    if (s.type === 'rect' || s.type === 'text') {
      const inside = fx >= b.x - tol && fx <= b.x + b.w + tol && fy >= b.y - tol && fy <= b.y + b.h + tol;
      if (inside) return i;
    } else if (s.type === 'arrow') {
      if (_drwDistToSegment(fx, fy, s.x1, s.y1, s.x2, s.y2) < tol) return i;
    } else if (s.type === 'pen' && s.points?.length > 1) {
      for (let p = 1; p < s.points.length; p++) {
        if (_drwDistToSegment(fx, fy, s.points[p-1][0], s.points[p-1][1], s.points[p][0], s.points[p][1]) < tol) return i;
      }
    }
  }
  return -1;
}

function _drwMoveShape(s, dx, dy) {
  if (s.type === 'rect' || s.type === 'text') { s.x += dx; s.y += dy; }
  else if (s.type === 'arrow') { s.x1 += dx; s.y1 += dy; s.x2 += dx; s.y2 += dy; }
  else if (s.type === 'pen') s.points = (s.points || []).map(p => [p[0] + dx, p[1] + dy]);
}

function _drwResizeShape(s, before, handle, dx, dy, lockRatio) {
  if (s.type === 'arrow') {
    if (handle === 'start') { s.x1 = before.x1 + dx; s.y1 = before.y1 + dy; }
    if (handle === 'end') { s.x2 = before.x2 + dx; s.y2 = before.y2 + dy; }
    return;
  }
  const b = _drwShapeBounds(before);
  let left = b.x, top = b.y, right = b.x + b.w, bottom = b.y + b.h;
  if (handle.includes('w')) left += dx;
  if (handle.includes('e')) right += dx;
  if (handle.includes('n')) top += dy;
  if (handle.includes('s')) bottom += dy;
  if (lockRatio && b.w > 0 && b.h > 0) {
    const ratio = b.w / b.h;
    const nw = Math.max(0.01, Math.abs(right - left));
    const nh = nw / ratio;
    if (handle.includes('n')) top = bottom - nh; else bottom = top + nh;
  }
  const nb = { x: Math.min(left, right), y: Math.min(top, bottom), w: Math.max(0.008, Math.abs(right - left)), h: Math.max(0.008, Math.abs(bottom - top)) };
  if (s.type === 'rect' || s.type === 'text') {
    s.x = nb.x; s.y = nb.y; s.w = nb.w; s.h = nb.h;
  } else if (s.type === 'pen') {
    const sx = nb.w / Math.max(0.0001, b.w), sy = nb.h / Math.max(0.0001, b.h);
    s.points = (before.points || []).map(p => [nb.x + (p[0] - b.x) * sx, nb.y + (p[1] - b.y) * sy]);
  }
}

function _drwApplyDrag(fx, fy, lockRatio) {
  const d = _drwDragState;
  if (!d) return;
  const s = _drwMarkupShapes[d.idx];
  Object.assign(s, _drwCloneShape(d.before));
  const dx = fx - d.startX, dy = fy - d.startY;
  if (d.mode === 'move') _drwMoveShape(s, dx, dy);
  else _drwResizeShape(s, d.before, d.handle, dx, dy, lockRatio);
}

function _drwOpenTextEditor(idx) {
  _drwRemoveTextEditor(true);
  const s = _drwMarkupShapes[idx];
  if (!s || s.type !== 'text') return;
  const wrap = document.getElementById('drw-canvas-wrap');
  const canvas = document.getElementById('drw-markup-canvas');
  if (!wrap || !canvas) return;
  const b = _drwShapeBounds(s);
  const editor = document.createElement('textarea');
  editor.className = 'drw-inline-text-editor';
  editor.value = s.text || '';
  editor.style.left = `${b.x * canvas.width}px`;
  editor.style.top = `${b.y * canvas.height}px`;
  editor.style.width = `${Math.max(80, b.w * canvas.width)}px`;
  editor.style.height = `${Math.max(34, b.h * canvas.height)}px`;
  editor.style.color = s.color || _drwTool.color;
  editor.style.fontSize = `${Math.max(12, (s.size || 15) * _drwZoomScale)}px`;
  editor.oninput = () => {
    s.text = editor.value;
    _drwMarkupDirty = true;
    _drwRedraw();
  };
  editor.onkeydown = (ev) => {
    if (ev.key === 'Escape') _drwRemoveTextEditor(false);
    if ((ev.ctrlKey || ev.metaKey) && ev.key === 'Enter') _drwRemoveTextEditor(true);
  };
  editor.onblur = () => _drwRemoveTextEditor(true);
  wrap.appendChild(editor);
  _drwTextEditor = { el: editor, idx };
  setTimeout(() => { editor.focus(); editor.select(); }, 0);
}

function _drwRemoveTextEditor(commit = true) {
  if (!_drwTextEditor) return;
  const { el, idx } = _drwTextEditor;
  if (commit && _drwMarkupShapes[idx]?.type === 'text') {
    _drwMarkupShapes[idx].text = el.value.trim();
    if (!_drwMarkupShapes[idx].text) _drwMarkupShapes.splice(idx, 1);
  }
  el.remove();
  _drwTextEditor = null;
  _drwRedraw();
}

function _drwCanvasDblClick(e) {
  const { fx, fy } = _drwCanvasXY(e);
  const hit = _drwHitShape(fx, fy);
  if (hit >= 0) {
    _drwSelectedShape = hit;
    _drwRedraw();
    if (_drwMarkupShapes[hit].type === 'text') _drwOpenTextEditor(hit);
  }
}

function _drwCanvasKeyDown(e) {
  if (e.key === 'Delete' || e.key === 'Backspace') {
    e.preventDefault();
    _drwDeleteSelected();
  }
  if (e.key === 'Escape') {
    _drwSelectedShape = -1;
    _drwRemoveTextEditor(false);
    _drwRedraw();
  }
}

function _drwDeleteSelected() {
  if (_drwSelectedShape < 0) return;
  _drwMarkupShapes.splice(_drwSelectedShape, 1);
  _drwSelectedShape = -1;
  _drwMarkupDirty = true;
  _drwRemoveTextEditor(false);
  _drwRedraw();
}

function _drwSetTool(name) {
  _drwTool.name = name;
  document.querySelectorAll('.drw-tool-btn').forEach(b => b.classList.remove('active'));
  document.getElementById(`drw-tool-${name}`)?.classList.add('active');
  _drwUpdateCursor();
}

function _drwSetColor(color) {
  _drwTool.color = color;
  if (_drwSelectedShape >= 0 && _drwMarkupShapes[_drwSelectedShape]) {
    _drwMarkupShapes[_drwSelectedShape].color = color;
    _drwMarkupDirty = true;
    _drwRedraw();
  }
  document.querySelectorAll('.drw-color-btn').forEach(b => b.style.outline='none');
  document.querySelector(`.drw-color-btn[data-color="${color}"]`)?.style.setProperty('outline','2px solid white');
}

function _drwSetWidth(width) {
  _drwTool.width = Number(width) || 3;
  if (_drwSelectedShape >= 0 && _drwMarkupShapes[_drwSelectedShape]) {
    const s = _drwMarkupShapes[_drwSelectedShape];
    if (s.type === 'text') s.size = Math.max(10, _drwTool.width * 5);
    else s.width = _drwTool.width;
    _drwMarkupDirty = true;
    _drwRedraw();
  }
}

function _drwUpdateCursor() {
  const canvas = document.getElementById('drw-markup-canvas');
  if (!canvas) return;
  canvas.style.cursor = _drwTool.name === 'select' ? 'default' : _drwTool.name === 'text' ? 'text' : 'crosshair';
}

function _drwClearMarkup() {
  if (!_drwMarkupShapes.length) return;
  if (!confirm('Clear all your markup on this sheet?')) return;
  _drwMarkupShapes = [];
  _drwSelectedShape = -1;
  _drwMarkupDirty  = true;
  _drwRemoveTextEditor(false);
  _drwRedraw();
}

async function _drwSaveMarkup() {
  if (!_drwCurSheet) return;
  const sheetId = _drwCurSheet.id;
  try {
    _drwRemoveTextEditor(true);
    const data = { markup_data: _drwMarkupShapes, updated_at: new Date().toISOString() };
    if (_drwSavedMarkupId) {
      await _dbUpdate('drawing_markups', data, { id: _drwSavedMarkupId });
    } else {
      const rows = await _dbInsert('drawing_markups', {
        sheet_id: sheetId, created_by: currentRoleUser?.id,
        creator_name: currentRoleUser?.name, markup_data: _drwMarkupShapes,
      });
      _drwSavedMarkupId = rows[0]?.id;
    }
    _drwMarkupDirty = false;
    await loadDrawingsData();
    document.getElementById('drw-markup-status').textContent = 'Draft saved';
    setTimeout(() => { const el=document.getElementById('drw-markup-status'); if(el)el.textContent=''; }, 3000);
  } catch(e) { toast(`Save failed: ${e.message}`, 'error'); }
}

async function _drwPublishMarkup() {
  if (!_drwCurSheet) return;
  if (!confirm('Publish your markup? It will be visible to all team members.')) return;
  try {
    await _drwSaveMarkup();
    if (!_drwSavedMarkupId) return;
    await _dbUpdate('drawing_markups', {
      is_published: true,
      published_at: new Date().toISOString(),
      published_by: currentRoleUser?.id,
    }, { id: _drwSavedMarkupId });
    await loadDrawingsData();
    _drwRedraw();
    document.getElementById('drw-markup-status').textContent = 'Published!';
    const pubCount = DRAWING_MARKUPS.filter(m => m.sheet_id === _drwCurSheet.id && m.is_published).length;
    document.getElementById('drw-published-markups').textContent =
      `${pubCount} published markup${pubCount>1?'s':''}`;
    toast('Markup published to team', 'success');
  } catch(e) { toast(`Publish failed: ${e.message}`, 'error'); }
}
